select t.id, 'ca', '[{"n":"1","title":"Administració pública i forces i cossos de seguretat (arts. 103 i 104)"},{"n":"2","title":"Control judicial de l''Administració i policia judicial (arts. 106 i 126)"},{"n":"3","title":"Estats d''alarma, excepció i setge (art. 116)"},{"n":"4","title":"Ministeri Fiscal (art. 124)"},{"n":"5","title":"Organització territorial: municipis, províncies i comunitats (arts. 137, 140 i 141)"},{"n":"6","title":"Hisendes locals (art. 142)"},{"n":"7","title":"Competències de les comunitats autònomes i de l''Estat en seguretat (arts. 148.1.22 i 149.1.29)"},{"n":"8","title":"Control de les comunitats autònomes (arts. 153 i 155)"}]'::jsonb, '["Art. 104 CE: «1. Las Fuerzas y Cuerpos de seguridad, bajo la dependencia del Gobierno, tendrán como misión proteger el libre ejercicio de los derechos y libertades y garantizar la seguridad ciudadana.»","Art. 104.2 CE: «2. Una ley orgánica determinará las funciones, principios básicos de actuación y estatutos de las Fuerzas y Cuerpos de seguridad.»","Art. 126 CE: «La policía judicial depende de los Jueces, de los Tribunales y del Ministerio Fiscal en sus funciones de averiguación del delito y descubrimiento y aseguramiento del delincuente»","Art. 103.1 CE: «actúa de acuerdo con los principios de eficacia, jerarquía, descentralización, desconcentración y coordinación, con sometimiento pleno a la ley y al Derecho.»","Art. 103.3 CE: «el acceso a la función pública de acuerdo con los principios de mérito y capacidad»","Art. 106.2 CE: «salvo en los casos de fuerza mayor, siempre que la lesión sea consecuencia del funcionamiento de los servicios públicos.»","Art. 116.2 CE: «2. El estado de alarma será declarado por el Gobierno mediante decreto acordado en Consejo de Ministros por un plazo máximo de quince días, dando cuenta al Congreso de los Diputados»","Art. 116.3 CE: «su duración, que no podrá exceder de treinta días, prorrogables por otro plazo igual, con los mismos requisitos.»","Art. 124 CE: «conforme a los principios de unidad de actuación y dependencia jerárquica y con sujeción, en todo caso, a los de legalidad e imparcialidad.»","Art. 137 CE: «El Estado se organiza territorialmente en municipios, en provincias y en las Comunidades Autónomas que se constituyan.»","Art. 140 CE: «Los Concejales serán elegidos por los vecinos del municipio mediante sufragio universal, igual, libre, directo y secreto, en la forma establecida por la ley.»","Art. 141 CE: «Cualquier alteración de los límites provinciales habrá de ser aprobada por las Cortes Generales mediante ley orgánica.»","Art. 142 CE: «se nutrirán fundamentalmente de tributos propios y de participación en los del Estado y de las Comunidades Autónomas.»","Art. 145 CE: «1. En ningún caso se admitirá la federación de Comunidades Autónomas.»","Art. 148.1.22 CE: «22.ª La vigilancia y protección de sus edificios e instalaciones. La coordinación y demás facultades en relación con las policías locales en los términos que establezca una ley orgánica.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[{"n":"1","title":"Administració pública i forces i cossos de seguretat (arts. 103 i 104)","blocks":[{"text":"L''Administració pública serveix amb objectivitat els interessos generals i actua d''acord amb els principis d''eficàcia, jerarquia, descentralització, desconcentració i coordinació, amb submissió plena a la llei i al dret (art. 103.1 CE). Són cinc principis que cal saber de memòria; a l''examen s''hi solen colar intrusos com «autonomia», «solidaritat» o «economia», que no figuren en aquest article. Els òrgans de l''Administració de l''Estat són creats, regits i coordinats d''acord amb la llei (art. 103.2).","refs":[{"ref":"Art. 103.1 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"La Administración Pública sirve con objetividad los intereses generales y actúa de acuerdo con los principios de eficacia, jerarquía, descentralización, desconcentración y coordinación, con sometimiento pleno a la ley y al Derecho."},{"ref":"Art. 103.2 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"Los órganos de la Administración del Estado son creados, regidos y coordinados de acuerdo con la ley."}]},{"text":"L''article 103.3 remet a la llei la regulació de l''estatut dels funcionaris públics, l''accés a la funció pública d''acord amb els principis de mèrit i capacitat, les peculiaritats de l''exercici del seu dret a sindicació, el sistema d''incompatibilitats i les garanties per a la imparcialitat en l''exercici de les seves funcions. Aquest precepte és el fonament constitucional dels processos selectius com el d''agent de policia local.","refs":[{"ref":"Art. 103.3 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"La ley regulará el estatuto de los funcionarios públicos, el acceso a la función pública de acuerdo con los principios de mérito y capacidad, las peculiaridades del ejercicio de su derecho a sindicación, el sistema de incompatibilidades y las garantías para la imparcialidad en el ejercicio de sus funciones."}]},{"text":"L''article 104.1 encomana a les forces i cossos de seguretat, sota la dependència del Govern, la missió de protegir el lliure exercici dels drets i llibertats i garantir la seguretat ciutadana. Segons l''article 104.2, una llei orgànica ha de determinar-ne les funcions, els principis bàsics d''actuació i els estatuts. Aquesta llei és la Llei orgànica 2/1986, de forces i cossos de seguretat, que inclou entre aquestes forces els cossos de policia dependents de les corporacions locals (art. 2 LOFCS) i preveu que les corporacions locals participin en el manteniment de la seguretat pública (art. 1.3 LOFCS).","refs":[{"ref":"Art. 104 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"1. Las Fuerzas y Cuerpos de seguridad, bajo la dependencia del Gobierno, tendrán como misión proteger el libre ejercicio de los derechos y libertades y garantizar la seguridad ciudadana. 2. Una ley orgánica determinará las funciones, principios básicos de actuación y estatutos de las Fuerzas y Cuerpos de seguridad."},{"ref":"Art. 2 LOFCS","law":"LO 2/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859","quote":"Son Fuerzas y Cuerpos de Seguridad: a) Las Fuerzas y Cuerpos de Seguridad del Estado dependientes del Gobierno de la Nación. b) Los Cuerpos de Policía dependientes de las Comunidades Autónomas. c) Los Cuerpos de Policía dependientes de las Corporaciones Locales."},{"ref":"Art. 1.3 LOFCS","law":"LO 2/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859","quote":"Las Corporaciones Locales participarán en el mantenimiento de la seguridad pública en los términos establecidos en la Ley Reguladora de las Bases de Régimen Local y en el marco de esta Ley."}]}]},{"n":"2","title":"Control judicial de l''Administració i policia judicial (arts. 106 i 126)","blocks":[{"text":"Els tribunals controlen la potestat reglamentària i la legalitat de l''actuació administrativa, i també que aquesta se sotmeti a les finalitats que la justifiquen (art. 106.1 CE). L''article 106.2 consagra la responsabilitat patrimonial de l''Administració: els particulars, en els termes que estableixi la llei, tenen dret a ser indemnitzats per tota lesió que pateixin en qualsevol dels seus béns i drets, excepte en els casos de força major, sempre que la lesió sigui conseqüència del funcionament dels serveis públics. L''única excepció que esmenta la Constitució és la força major.","refs":[{"ref":"Art. 106 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"1. Los Tribunales controlan la potestad reglamentaria y la legalidad de la actuación administrativa, así como el sometimiento de ésta a los fines que la justifican. 2. Los particulares, en los términos establecidos por la ley, tendrán derecho a ser indemnizados por toda lesión que sufran en cualquiera de sus bienes y derechos, salvo en los casos de fuerza mayor, siempre que la lesión sea consecuencia del funcionamiento de los servicios públicos."}]},{"text":"La policia judicial depèn dels jutges, dels tribunals i del Ministeri Fiscal en les seves funcions d''averiguació del delicte i de descobriment i assegurament del delinqüent, en els termes que estableixi la llei (art. 126 CE). És a dir, la dependència funcional en la investigació penal és respecte de l''autoritat judicial i fiscal, i no del Govern, del qual depenen orgànicament les forces i cossos de seguretat segons l''article 104.","refs":[{"ref":"Art. 126 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"La policía judicial depende de los Jueces, de los Tribunales y del Ministerio Fiscal en sus funciones de averiguación del delito y descubrimiento y aseguramiento del delincuente, en los términos que la ley establezca."}]}]},{"n":"3","title":"Estats d''alarma, excepció i setge (art. 116)","blocks":[{"text":"Una llei orgànica regula els estats d''alarma, d''excepció i de setge, amb les competències i limitacions corresponents (art. 116.1 CE). L''estat d''alarma el declara el Govern mitjançant decret acordat en Consell de Ministres per un termini màxim de quinze dies, donant-ne compte al Congrés dels Diputats, que es reuneix immediatament i sense l''autorització del qual no es pot prorrogar el termini; el decret determina l''àmbit territorial (art. 116.2).","refs":[{"ref":"Art. 116.1 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"Una ley orgánica regulará los estados de alarma, de excepción y de sitio, y las competencias y limitaciones correspondientes."},{"ref":"Art. 116.2 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"El estado de alarma será declarado por el Gobierno mediante decreto acordado en Consejo de Ministros por un plazo máximo de quince días, dando cuenta al Congreso de los Diputados, reunido inmediatamente al efecto y sin cuya autorización no podrá ser prorrogado dicho plazo."}]},{"text":"L''estat d''excepció també el declara el Govern per decret acordat en Consell de Ministres, però amb autorització prèvia del Congrés. L''autorització n''ha de determinar els efectes, l''àmbit territorial i la durada, que no pot excedir de trenta dies, prorrogables per un altre termini igual amb els mateixos requisits (art. 116.3). L''estat de setge el declara el Congrés per majoria absoluta, a proposta exclusiva del Govern, i el Congrés en fixa l''àmbit, la durada i les condicions (art. 116.4).","refs":[{"ref":"Art. 116.3 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"El estado de excepción será declarado por el Gobierno mediante decreto acordado en Consejo de Ministros, previa autorización del Congreso de los Diputados. La autorización y proclamación del estado de excepción deberá determinar expresamente los efectos del mismo, el ámbito territorial a que se extiende y su duración, que no podrá exceder de treinta días, prorrogables por otro plazo igual, con los mismos requisitos."},{"ref":"Art. 116.4 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"El estado de sitio será declarado por la mayoría absoluta del Congreso de los Diputados, a propuesta exclusiva del Gobierno. El Congreso determinará su ámbito territorial, duración y condiciones."}]},{"text":"Mentre estigui declarat algun d''aquests estats no es pot dissoldre el Congrés, i el funcionament de les cambres i dels altres poders constitucionals no es pot interrompre (art. 116.5). La declaració no modifica el principi de responsabilitat del Govern i dels seus agents (art. 116.6).","refs":[{"ref":"Art. 116.5 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"No podrá procederse a la disolución del Congreso mientras estén declarados algunos de los estados comprendidos en el presente artículo"},{"ref":"Art. 116.6 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"La declaración de los estados de alarma, de excepción y de sitio no modificarán el principio de responsabilidad del Gobierno y de sus agentes reconocidos en la Constitución y en las leyes."}]}]},{"n":"4","title":"Ministeri Fiscal (art. 124)","blocks":[{"text":"El Ministeri Fiscal té per missió promoure l''acció de la justícia en defensa de la legalitat, dels drets dels ciutadans i de l''interès públic tutelat per la llei, d''ofici o a petició dels interessats, i també vetllar per la independència dels tribunals (art. 124.1 CE). Exerceix les funcions per mitjà d''òrgans propis d''acord amb els principis d''unitat d''actuació i dependència jeràrquica, i amb subjecció, en tot cas, als de legalitat i imparcialitat (art. 124.2). El Fiscal General de l''Estat el nomena el Rei, a proposta del Govern, un cop escoltat el Consell General del Poder Judicial (art. 124.4).","refs":[{"ref":"Art. 124.1 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"tiene por misión promover la acción de la justicia en defensa de la legalidad, de los derechos de los ciudadanos y del interés público tutelado por la ley, de oficio o a petición de los interesados, así como velar por la independencia de los Tribunales"},{"ref":"Art. 124.2 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"El Ministerio Fiscal ejerce sus funciones por medio de órganos propios conforme a los principios de unidad de actuación y dependencia jerárquica y con sujeción, en todo caso, a los de legalidad e imparcialidad."},{"ref":"Art. 124.4 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"El Fiscal General del Estado será nombrado por el Rey, a propuesta del Gobierno, oído el Consejo General del Poder Judicial."}]}]},{"n":"5","title":"Organització territorial: municipis, províncies i comunitats (arts. 137, 140 i 141)","blocks":[{"text":"L''Estat s''organitza territorialment en municipis, en províncies i en les comunitats autònomes que es constitueixin, i totes aquestes entitats gaudeixen d''autonomia per a la gestió dels seus interessos respectius (art. 137 CE). L''Estat garanteix el principi de solidaritat (art. 138.1), les diferències entre estatuts no poden implicar privilegis econòmics o socials (art. 138.2) i tots els espanyols tenen els mateixos drets i obligacions en qualsevol part del territori (art. 139.1).","refs":[{"ref":"Art. 137 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"El Estado se organiza territorialmente en municipios, en provincias y en las Comunidades Autónomas que se constituyan. Todas estas entidades gozan de autonomía para la gestión de sus respectivos intereses."},{"ref":"Arts. 138.2 i 139.1 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"Las diferencias entre los Estatutos de las distintas Comunidades Autónomas no podrán implicar, en ningún caso, privilegios económicos o sociales. […] Todos los españoles tienen los mismos derechos y obligaciones en cualquier parte del territorio del Estado."}]},{"text":"La Constitució garanteix l''autonomia dels municipis, que tenen personalitat jurídica plena (art. 140). El seu govern i administració corresponen als ajuntaments, integrats pels alcaldes i els regidors. Els regidors són elegits pels veïns del municipi per sufragi universal, igual, lliure, directe i secret, i els alcaldes són elegits pels regidors o pels veïns. La llei regula les condicions del règim de concejo abierto (consell obert).","refs":[{"ref":"Art. 140 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"La Constitución garantiza la autonomía de los municipios. Estos gozarán de personalidad jurídica plena. Su gobierno y administración corresponde a sus respectivos Ayuntamientos, integrados por los Alcaldes y los Concejales. Los Concejales serán elegidos por los vecinos del municipio mediante sufragio universal, igual, libre, directo y secreto, en la forma establecida por la ley. Los Alcaldes serán elegidos por los Concejales o por los vecinos."}]},{"text":"La província és una entitat local amb personalitat jurídica pròpia, determinada per l''agrupació de municipis i divisió territorial per complir les activitats de l''Estat; qualsevol alteració dels límits provincials l''han d''aprovar les Corts Generals mitjançant llei orgànica (art. 141.1). El govern i l''administració autònoma de les províncies corresponen a diputacions o altres corporacions de caràcter representatiu (art. 141.2). Es poden crear agrupacions de municipis diferents de la província (art. 141.3) i, als arxipèlags, les illes tenen administració pròpia en forma de cabildos o consells (art. 141.4).","refs":[{"ref":"Art. 141.1 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"La provincia es una entidad local con personalidad jurídica propia, determinada por la agrupación de municipios y división territorial para el cumplimiento de las actividades del Estado. Cualquier alteración de los límites provinciales habrá de ser aprobada por las Cortes Generales mediante ley orgánica."},{"ref":"Art. 141.2 a 141.4 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"2. El gobierno y la administración autónoma de las provincias estarán encomendados a Diputaciones u otras Corporaciones de carácter representativo. 3. Se podrán crear agrupaciones de municipios diferentes de la provincia. 4. En los archipiélagos, las islas tendrán además su administración propia en forma de Cabildos o Consejos."}]}]},{"n":"6","title":"Hisendes locals (art. 142)","blocks":[{"text":"Les hisendes locals han de disposar dels mitjans suficients per exercir les funcions que la llei atribueix a les corporacions respectives, i s''han de nodrir fonamentalment de dues fonts: els tributs propis i la participació en els tributs de l''Estat i de les comunitats autònomes (art. 142 CE). És el principi de suficiència financera, complement necessari de l''autonomia local garantida a l''article 140.","refs":[{"ref":"Art. 142 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"Las Haciendas locales deberán disponer de los medios suficientes para el desempeño de las funciones que la ley atribuye a las Corporaciones respectivas y se nutrirán fundamentalmente de tributos propios y de participación en los del Estado y de las Comunidades Autónomas."}]}]},{"n":"7","title":"Comunitats autònomes i competències en seguretat (arts. 145, 147, 148.1.22 i 149.1.29)","blocks":[{"text":"En cap cas no s''admet la federació de comunitats autònomes (art. 145.1 CE); els estatuts poden preveure convenis entre comunitats per a la gestió i prestació de serveis propis, amb comunicació a les Corts Generals, i els altres acords de cooperació necessiten autorització de les Corts (art. 145.2). Els estatuts són la norma institucional bàsica de cada comunitat, i l''Estat els reconeix i empara com a part del seu ordenament (art. 147.1); la seva reforma requereix sempre l''aprovació de les Corts Generals mitjançant llei orgànica (art. 147.3).","refs":[{"ref":"Art. 145 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"1. En ningún caso se admitirá la federación de Comunidades Autónomas. 2. Los Estatutos podrán prever los supuestos, requisitos y términos en que las Comunidades Autónomas podrán celebrar convenios entre sí para la gestión y prestación de servicios propios de las mismas"},{"ref":"Art. 147 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"los Estatutos serán la norma institucional básica de cada Comunidad Autónoma y el Estado los reconocerá y amparará como parte integrante de su ordenamiento jurídico. […] requerirá, en todo caso, la aprobación por las Cortes Generales, mediante ley orgánica."}]},{"text":"Entre les matèries que les comunitats autònomes poden assumir, l''article 148.1.22a inclou la vigilància i protecció dels seus edificis i instal·lacions, i la coordinació i altres facultats en relació amb les policies locals en els termes que estableixi una llei orgànica. Aquest és el fonament constitucional de la coordinació de les policies locals per la Generalitat.","refs":[{"ref":"Art. 148.1.22 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"22.ª La vigilancia y protección de sus edificios e instalaciones. La coordinación y demás facultades en relación con las policías locales en los términos que establezca una ley orgánica."}]},{"text":"Per la seva banda, la seguretat pública és competència exclusiva de l''Estat (art. 149.1.29a), sens perjudici de la possibilitat que les comunitats autònomes creïn policies en la forma que estableixin els seus estatuts, en el marc del que disposi una llei orgànica. La LOFCS ho reprodueix: la seguretat pública és competència exclusiva de l''Estat i el seu manteniment correspon al Govern; les comunitats autònomes hi participen en els termes dels estatuts i de la llei (art. 1 LOFCS). Les matèries no atribuïdes expressament a l''Estat poden correspondre a les comunitats en virtut dels estatuts, i el dret estatal és sempre supletori (art. 149.3 CE).","refs":[{"ref":"Art. 149.1.29 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"29.ª Seguridad pública, sin perjuicio de la posibilidad de creación de policías por las Comunidades Autónomas en la forma que se establezca en los respectivos Estatutos en el marco de lo que disponga una ley orgánica."},{"ref":"Art. 1 LOFCS","law":"LO 2/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859","quote":"1. La Seguridad Pública es competencia exclusiva del Estado. Su mantenimiento corresponde al Gobierno de la Nación. 2. Las Comunidades Autónomas participarán en el mantenimiento de la Seguridad Pública en los términos que establezcan los respectivos Estatutos y en el marco de esta Ley."},{"ref":"Art. 149.3 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"Las materias no atribuidas expresamente al Estado por esta Constitución podrán corresponder a las Comunidades Autónomas, en virtud de sus respectivos Estatutos. […] El derecho estatal será, en todo caso, supletorio del derecho de las Comunidades Autónomas."}]}]},{"n":"8","title":"Control de les comunitats autònomes (arts. 153, 154 i 155)","blocks":[{"text":"L''article 153 CE reparteix el control de l''activitat dels òrgans de les comunitats autònomes: el Tribunal Constitucional controla la constitucionalitat de les seves disposicions normatives amb força de llei; el Govern, amb dictamen previ del Consell d''Estat, l''exercici de funcions delegades de l''article 150.2; la jurisdicció contenciosa administrativa, l''administració autonòmica i les seves normes reglamentàries, i el Tribunal de Comptes, el control econòmic i pressupostari. Un delegat nomenat pel Govern dirigeix l''Administració de l''Estat al territori de la comunitat (art. 154).","refs":[{"ref":"Art. 153 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"a) Por el Tribunal Constitucional, el relativo a la constitucionalidad de sus disposiciones normativas con fuerza de ley. b) Por el Gobierno, previo dictamen del Consejo de Estado, el del ejercicio de funciones delegadas a que se refiere el apartado 2 del artículo 150. c) Por la jurisdicción contencioso-administrativa, el de la administración autónoma y sus normas reglamentarias. d) Por el Tribunal de Cuentas, el económico y presupuestario."},{"ref":"Art. 154 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"Un Delegado nombrado por el Gobierno dirigirá la Administración del Estado en el territorio de la Comunidad Autónoma"}]},{"text":"L''article 155 regula el control extraordinari. Si una comunitat no compleix les obligacions que li imposen la Constitució o les lleis, o actua de manera que atempta greument contra l''interès general d''Espanya, el Govern, amb requeriment previ al president de la comunitat i, si no és atès, amb l''aprovació per majoria absoluta del Senat, pot adoptar les mesures necessàries per obligar-la al compliment forçós de les obligacions o per protegir aquell interès general. Per executar-les, el Govern pot donar instruccions a totes les autoritats de la comunitat (art. 155.2). Fixa''t que l''aprovació correspon al Senat, no al Congrés.","refs":[{"ref":"Art. 155 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"el Gobierno, previo requerimiento al Presidente de la Comunidad Autónoma y, en el caso de no ser atendido, con la aprobación por mayoría absoluta del Senado, podrá adoptar las medidas necesarias para obligar a aquélla al cumplimiento forzoso de dichas obligaciones o para la protección del mencionado interés general. 2. Para la ejecución de las medidas previstas en el apartado anterior, el Gobierno podrá dar instrucciones a todas las autoridades de las Comunidades Autónomas."}]}]},{"n":"R","title":"Recorda per a l''examen","blocks":[{"text":"Principis de l''article 103.1: eficàcia, jerarquia, descentralització, desconcentració i coordinació (no «autonomia»). Accés a la funció pública: mèrit i capacitat (art. 103.3).","refs":[{"ref":"Art. 103.1 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"eficacia, jerarquía, descentralización, desconcentración y coordinación"}]},{"text":"Missió de les forces i cossos de seguretat: protegir el lliure exercici dels drets i llibertats i garantir la seguretat ciutadana; funcions i estatuts, per llei orgànica (art. 104).","refs":[{"ref":"Art. 104.1 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"tendrán como misión proteger el libre ejercicio de los derechos y libertades y garantizar la seguridad ciudadana."}]},{"text":"La policia judicial depèn dels jutges, dels tribunals i del Ministeri Fiscal (art. 126).","refs":[{"ref":"Art. 126 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"La policía judicial depende de los Jueces, de los Tribunales y del Ministerio Fiscal"}]},{"text":"Responsabilitat patrimonial: indemnització per tota lesió derivada dels serveis públics, excepte força major (art. 106.2).","refs":[{"ref":"Art. 106.2 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"salvo en los casos de fuerza mayor"}]},{"text":"Alarma: Govern, màxim quinze dies, donant compte al Congrés. Excepció: Govern amb autorització prèvia del Congrés, màxim trenta dies prorrogables per un termini igual. Setge: majoria absoluta del Congrés.","refs":[{"ref":"Art. 116 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"por un plazo máximo de quince días […] que no podrá exceder de treinta días, prorrogables por otro plazo igual […] El estado de sitio será declarado por la mayoría absoluta del Congreso de los Diputados"}]},{"text":"Ministeri Fiscal: unitat d''actuació i dependència jeràrquica, amb subjecció a la legalitat i la imparcialitat (art. 124.2).","refs":[{"ref":"Art. 124.2 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"conforme a los principios de unidad de actuación y dependencia jerárquica y con sujeción, en todo caso, a los de legalidad e imparcialidad."}]},{"text":"Regidors: elegits pels veïns per sufragi universal, igual, lliure, directe i secret. Alcaldes: elegits pels regidors o pels veïns (art. 140).","refs":[{"ref":"Art. 140 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"Los Alcaldes serán elegidos por los Concejales o por los vecinos."}]},{"text":"Límits provincials: Corts Generals per llei orgànica; govern de la província: diputacions o altres corporacions representatives (art. 141).","refs":[{"ref":"Art. 141 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"habrá de ser aprobada por las Cortes Generales mediante ley orgánica. 2. El gobierno y la administración autónoma de las provincias estarán encomendados a Diputaciones u otras Corporaciones de carácter representativo."}]},{"text":"Hisendes locals: tributs propis i participació en els de l''Estat i de les comunitats autònomes (art. 142). La federació de comunitats no s''admet mai (art. 145.1).","refs":[{"ref":"Art. 142 i 145.1 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"se nutrirán fundamentalmente de tributos propios y de participación en los del Estado y de las Comunidades Autónomas. […] En ningún caso se admitirá la federación de Comunidades Autónomas."}]},{"text":"Article 155: requeriment previ al president de la comunitat i, si no és atès, aprovació per majoria absoluta del Senat. Lleis autonòmiques: control de constitucionalitat pel Tribunal Constitucional (art. 153.a).","refs":[{"ref":"Art. 155.1 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"previo requerimiento al Presidente de la Comunidad Autónoma y, en el caso de no ser atendido, con la aprobación por mayoría absoluta del Senado"}]}]}]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229'), 'https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229', null, null, null, null
  from public.topics t where t.slug = 'plcat-t02-constitucio-organitzacio-territorial'
