       is distinct from (excluded.outline, excluded.key_ideas, excluded.glossary, excluded.amendments, excluded.lessons);
insert into public.sources (title, url, kind, publisher, published_on) values ('Ley Orgánica 6/2006, de 19 de julio, de reforma del Estatuto de Autonomía de Cataluña (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-2006-13087', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('plcat-t03-estatut-autonomia', 'Tema 3. L''Estatut d''autonomia de Catalunya: drets, deures i principis rectors, govern local i seguretat pública') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('policia-local') and t.slug = 'plcat-t03-estatut-autonomia' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, lessons, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"Catalunya com a nacionalitat i l''autogovern (arts. 1 i 2)"},{"n":"2","title":"Llengua pròpia i símbols (arts. 6 i 8)"},{"n":"3","title":"Drets de les persones i drets lingüístics (arts. 15, 32 i 33)"},{"n":"4","title":"Govern local: municipi, organització i competències (arts. 83, 84 i 86)"},{"n":"5","title":"Ordenació territorial (art. 91)"},{"n":"6","title":"Competències en règim local i seguretat pública (arts. 160 i 164)"}]'::jsonb, '["Art. 1 EAC: «Cataluña, como nacionalidad, ejerce su autogobierno constituida en Comunidad Autónoma de acuerdo con la Constitución y con el presente Estatuto, que es su norma institucional básica.»","Art. 2.2 EAC: «2. La Generalitat está integrada por el Parlamento, la Presidencia de la Generalitat, el Gobierno y las demás instituciones que establece el Capítulo V, del Título II.»","Art. 2.3 EAC: «también integran el sistema institucional de la Generalitat, como entes en los que ésta se organiza territorialmente, sin perjuicio de su autonomía.»","Art. 6.2 EAC: «Todas las personas tienen derecho a utilizar las dos lenguas oficiales y los ciudadanos de Cataluña el derecho y el deber de conocerlas.»","Art. 8 EAC: «3. La fiesta de Cataluña es el Día Once de Septiembre.»","Art. 8.2 EAC: «2. La bandera de Cataluña es la tradicional de cuatro barras rojas en fondo amarillo y debe estar presente en los edificios públicos y en los actos oficiales que tengan lugar en Cataluña.»","Art. 15.2 EAC: «2. Todas las personas tienen derecho a vivir con dignidad, seguridad y autonomía, libres de explotación, de malos tratos y de todo tipo de discriminación»","Art. 32 EAC: «Los actos jurídicos realizados en cualquiera de las dos lenguas oficiales tienen, en cuanto a la lengua, plena validez y eficacia.»","Art. 33.1 EAC: «En las relaciones con las instituciones, las organizaciones y las Administraciones públicas en Cataluña, todas las personas tienen derecho a utilizar la lengua oficial que elijan.»","Art. 50.5 EAC: «También deben utilizarlo en las comunicaciones y las notificaciones dirigidas a personas físicas o jurídicas residentes en Cataluña, sin perjuicio del derecho de los ciudadanos a recibirlas en castellano si lo piden.»","Art. 83 EAC: «1. Cataluña estructura su organización territorial básica en municipios y veguerías.»","Art. 84.2.e EAC: «e) La regulación de las condiciones de seguridad en las actividades organizadas en espacios públicos y en los locales de concurrencia pública. La coordinación mediante la Junta de Seguridad de los distintos cuerpos y fuerzas presentes en el municipio.»","Art. 86.1 EAC: «1. El municipio es el ente local básico de la organización territorial de Cataluña y el medio esencial de participación de la comunidad local en los asuntos públicos.»","Art. 86.4 EAC: «4. Los actos y acuerdos adoptados por los municipios no pueden ser objeto de control de oportunidad por ninguna otra administración.»","Art. 91.3 EAC: «3. Los Consejos de veguería sustituyen a las Diputaciones.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[{"n":"1","title":"Catalunya com a nacionalitat i l''autogovern (arts. 1 a 4)","blocks":[{"text":"L''Estatut d''autonomia de Catalunya vigent és el que aprova la Llei orgànica 6/2006, de 19 de juliol, de reforma de l''Estatut. El seu article 1 diu que Catalunya, com a nacionalitat, exerceix el seu autogovern constituïda en comunitat autònoma d''acord amb la Constitució i amb l''Estatut, que és la seva norma institucional bàsica. Aquesta qualificació encaixa amb l''article 147.1 de la Constitució, que defineix els estatuts com la norma institucional bàsica de cada comunitat. El text que s''estudia aquí és la versió consolidada del BOE, en castellà; la versió oficial catalana no és a la carpeta de fonts.","refs":[{"ref":"Art. 1 EAC","law":"EAC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2006-13087","quote":"Cataluña, como nacionalidad, ejerce su autogobierno constituida en Comunidad Autónoma de acuerdo con la Constitución y con el presente Estatuto, que es su norma institucional básica."},{"ref":"Títol EAC","law":"EAC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2006-13087","quote":"Ley Orgánica 6/2006, de 19 de julio, de reforma del Estatuto de Autonomía de Cataluña"}]},{"text":"La Generalitat és el sistema institucional en què s''organitza políticament l''autogovern de Catalunya (art. 2.1). La integren el Parlament, la Presidència de la Generalitat, el Govern i les altres institucions que estableix el capítol V del títol II (art. 2.2). A més, els municipis, les vegueries, les comarques i els altres ens locals que determinin les lleis també integren el sistema institucional de la Generalitat, com a ens en què aquesta s''organitza territorialment, sens perjudici de la seva autonomia (art. 2.3). Els poders de la Generalitat emanen del poble de Catalunya (art. 2.4).","refs":[{"ref":"Art. 2 EAC","law":"EAC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2006-13087","quote":"1. La Generalitat es el sistema institucional en que se organiza políticamente el autogobierno de Cataluña. 2. La Generalitat está integrada por el Parlamento, la Presidencia de la Generalitat, el Gobierno y las demás instituciones que establece el Capítulo V, del Título II. 3. Los municipios, las veguerías, las comarcas y los demás entes locales que las leyes determinen, también integran el sistema institucional de la Generalitat, como entes en los que ésta se organiza territorialmente, sin perjuicio de su autonomía."}]},{"text":"Les relacions de la Generalitat amb l''Estat es fonamenten en el principi de lleialtat institucional mútua i es regeixen pels principis d''autonomia, bilateralitat i multilateralitat (art. 3.1). Els poders públics de Catalunya han de promoure el ple exercici de les llibertats i els drets que reconeixen l''Estatut, la Constitució, la Unió Europea, la Declaració Universal de Drets Humans, el Conveni Europeu de Drets Humans i els altres tractats subscrits per Espanya (art. 4.1), i han de promoure, entre d''altres, els valors de la llibertat, la democràcia, la igualtat, el pluralisme, la pau, la justícia, la solidaritat, la cohesió social, l''equitat de gènere i el desenvolupament sostenible (art. 4.3).","refs":[{"ref":"Art. 3.1 EAC","law":"EAC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2006-13087","quote":"Las relaciones de la Generalitat con el Estado se fundamentan en el principio de la lealtad institucional mutua y se rigen por el principio general según el cual la Generalitat es Estado, por el principio de autonomía, por el de bilateralidad y también por el de multilateralidad."},{"ref":"Art. 4.3 EAC","law":"EAC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2006-13087","quote":"Los poderes públicos de Cataluña deben promover los valores de la libertad, la democracia, la igualdad, el pluralismo, la paz, la justicia, la solidaridad, la cohesión social, la equidad de género y el desarrollo sostenible."}]}]},{"n":"2","title":"Llengua pròpia i símbols (arts. 6 i 8)","blocks":[{"text":"La llengua pròpia de Catalunya és el català, que és la llengua d''ús normal de les administracions públiques i dels mitjans de comunicació públics de Catalunya, i també la llengua normalment utilitzada com a vehicular i d''aprenentatge en l''ensenyament (art. 6.1). Atenció a la vigència: el text del BOE encara conté l''incís «y preferente» (ús normal «i preferent»), però la nota del mateix BOE indica que la Sentència del Tribunal Constitucional 31/2010 en va declarar la inconstitucionalitat i nul·litat; per tant, aquest incís no és vigent.","refs":[{"ref":"Art. 6.1 EAC","law":"EAC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2006-13087","quote":"La lengua propia de Cataluña es el catalán. Como tal, el catalán es la lengua de uso normal […] de las Administraciones públicas y de los medios de comunicación públicos de Cataluña, y es también la lengua normalmente utilizada como vehicular y de aprendizaje en la enseñanza."},{"ref":"Nota BOE a l''art. 6 EAC","law":"EAC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2006-13087","quote":"y preferente […] Se declara la inconstitucionalidad y nulidad del inciso destacado del apartado 1 y que el apartado 2 no es inconstitucional, siempre que se interprete en los términos establecidos en el fundamento jurídico 114.b), por Sentencia del TC 31/2010, de 28 de junio."}]},{"text":"El català és la llengua oficial de Catalunya, i també ho és el castellà, llengua oficial de l''Estat (art. 6.2). Totes les persones tenen dret a utilitzar les dues llengües oficials, i els ciutadans de Catalunya tenen el dret i el deure de conèixer-les; no hi pot haver discriminació per l''ús d''una o altra llengua. La llengua occitana, denominada aranès a l''Aran, és la llengua pròpia d''aquest territori i és oficial a Catalunya (art. 6.5).","refs":[{"ref":"Art. 6.2 EAC","law":"EAC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2006-13087","quote":"El catalán es la lengua oficial de Cataluña. También lo es el castellano, que es la lengua oficial del Estado español. Todas las personas tienen derecho a utilizar las dos lenguas oficiales y los ciudadanos de Cataluña el derecho y el deber de conocerlas."},{"ref":"Art. 6.5 EAC","law":"EAC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2006-13087","quote":"La lengua occitana, denominada aranés en Arán, es la lengua propia de este territorio y es oficial en Cataluña"}]},{"text":"Catalunya té com a símbols nacionals la bandera, la festa i l''himne (art. 8.1). La bandera és la tradicional de quatre barres vermelles en fons groc i ha de ser present als edificis públics i als actes oficials que tinguin lloc a Catalunya (art. 8.2); la festa és el dia Onze de Setembre (art. 8.3), i l''himne, «Els segadors» (art. 8.4). Els símbols de Catalunya tenen la mateixa protecció jurídica que els altres símbols de l''Estat (art. 8.6). Gaudeixen de la condició política de catalans els ciutadans espanyols que tenen veïnatge administratiu a Catalunya (art. 7.1).","refs":[{"ref":"Art. 8 EAC","law":"EAC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2006-13087","quote":"2. La bandera de Cataluña es la tradicional de cuatro barras rojas en fondo amarillo y debe estar presente en los edificios públicos y en los actos oficiales que tengan lugar en Cataluña. 3. La fiesta de Cataluña es el Día Once de Septiembre. 4. El himno de Cataluña es «Els segadors»."},{"ref":"Art. 8.6 EAC","law":"EAC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2006-13087","quote":"La protección jurídica de los símbolos de Cataluña es la que corresponde a los demás símbolos del Estado."},{"ref":"Art. 7.1 EAC","law":"EAC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2006-13087","quote":"Gozan de la condición política de catalanes o ciudadanos de Cataluña los ciudadanos españoles que tienen vecindad administrativa en Cataluña."}]}]},{"n":"3","title":"Drets de les persones (títol I, capítol I: art. 15)","blocks":[{"text":"El títol I es titula «Drets, deures i principis rectors» i s''estructura en cinc capítols: drets i deures de l''àmbit civil i social (capítol I), drets en l''àmbit polític i de l''Administració (capítol II), drets i deures lingüístics (capítol III), garanties dels drets estatutaris (capítol IV) i principis rectors (capítol V).","refs":[{"ref":"Títol I EAC","law":"EAC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2006-13087","quote":"TÍTULO I. Derechos, deberes y principios rectores CAPÍTULO I. Derechos y deberes del ámbito civil y social"},{"ref":"Títol I EAC","law":"EAC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2006-13087","quote":"CAPÍTULO II. De los derechos en el ámbito político y de la Administración […] CAPÍTULO III. Derechos y deberes lingüísticos […] CAPÍTULO IV. Garantías de los derechos estatutarios […] CAPÍTULO V. Principios rectores"}]},{"text":"L''article 15 obre el capítol I. Els ciutadans de Catalunya són titulars dels drets i deures reconeguts per les normes de l''article 4.1 (art. 15.1). Totes les persones tenen dret a viure amb dignitat, seguretat i autonomia, lliures d''explotació, de maltractaments i de tota mena de discriminació, i tenen dret al lliure desenvolupament de la seva personalitat i capacitat personal (art. 15.2). Els drets que l''Estatut reconeix als ciutadans de Catalunya es poden estendre a altres persones en els termes que estableixin les lleis (art. 15.3). El capítol continua amb drets en l''àmbit de les famílies, dels menors, de les persones grans i de les dones, entre d''altres (arts. 16 a 28).","refs":[{"ref":"Art. 15 EAC","law":"EAC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2006-13087","quote":"2. Todas las personas tienen derecho a vivir con dignidad, seguridad y autonomía, libres de explotación, de malos tratos y de todo tipo de discriminación, y tienen derecho al libre desarrollo de su personalidad y capacidad personal. 3. Los derechos que el presente Estatuto reconoce a los ciudadanos de Cataluña pueden extenderse a otras personas, en los términos que establecen las leyes."},{"ref":"Arts. 16 a 19 EAC","law":"EAC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2006-13087","quote":"Artículo 16. Derechos en el ámbito de las familias. […] Artículo 17. Derechos de los menores. […] Artículo 18. Derechos de las personas mayores. […] Artículo 19. Derechos de las mujeres."}]}]},{"n":"4","title":"Drets en l''àmbit polític i de l''Administració (arts. 29 a 31)","blocks":[{"text":"Els ciutadans de Catalunya tenen dret a participar en condicions d''igualtat en els afers públics, directament o per mitjà de representants (art. 29.1). Totes les persones tenen dret a adreçar peticions i plantejar queixes a les institucions i l''Administració de la Generalitat i als ens locals de Catalunya, en matèries de les seves competències (art. 29.5). També tenen dret a ser tractades pels poders públics de Catalunya de manera imparcial i objectiva, i que l''actuació dels poders públics sigui proporcionada a les finalitats que la justifiquen (art. 30.2), un principi que afecta directament l''actuació policial.","refs":[{"ref":"Art. 29.5 EAC","law":"EAC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2006-13087","quote":"Todas las personas tienen derecho a dirigir peticiones y a plantear quejas, en la forma y con los efectos que establecen las leyes, a las instituciones y la Administración de la Generalitat, así como a los entes locales de Cataluña, en materias de las respectivas competencias."},{"ref":"Art. 30.2 EAC","law":"EAC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2006-13087","quote":"Todas las personas tienen derecho a ser tratadas por los poderes públicos de Cataluña, en los asuntos que les afectan, de forma imparcial y objetiva, y a que la actuación de los poderes públicos sea proporcionada a las finalidades que la justifican."}]},{"text":"L''article 31 reconeix el dret a la protecció de les dades personals contingudes en els fitxers que són competència de la Generalitat, i el dret d''accedir-hi, examinar-les i obtenir-ne la correcció. Una autoritat independent, designada pel Parlament, ha de vetllar pel respecte d''aquests drets.","refs":[{"ref":"Art. 31 EAC","law":"EAC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2006-13087","quote":"Todas las personas tienen derecho a la protección de los datos personales contenidos en los ficheros que son competencia de la Generalitat y el derecho a acceder a los mismos, a su examen y a obtener su corrección. Una autoridad independiente, designada por el Parlamento, debe velar por el respeto de estos derechos en los términos que establecen las leyes."}]}]},{"n":"5","title":"Drets i deures lingüístics (arts. 32, 33 i 50)","blocks":[{"text":"Totes les persones tenen dret a no ser discriminades per raons lingüístiques, i els actes jurídics fets en qualsevol de les dues llengües oficials tenen, pel que fa a la llengua, plena validesa i eficàcia (art. 32). Els ciutadans tenen el dret d''opció lingüística: en les relacions amb les institucions, les organitzacions i les administracions públiques a Catalunya, totes les persones tenen dret a utilitzar la llengua oficial que triïn (art. 33.1). Aquest dret obliga també l''Administració electoral i les entitats privades que en depenen quan exerceixen funcions públiques. Per a un agent de policia local, això vol dir atendre el ciutadà en la llengua oficial que aquest triï.","refs":[{"ref":"Art. 32 EAC","law":"EAC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2006-13087","quote":"Todas las personas tienen derecho a no ser discriminadas por razones lingüísticas. Los actos jurídicos realizados en cualquiera de las dos lenguas oficiales tienen, en cuanto a la lengua, plena validez y eficacia."},{"ref":"Art. 33.1 EAC","law":"EAC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2006-13087","quote":"Los ciudadanos tienen el derecho de opción lingüística. En las relaciones con las instituciones, las organizaciones y las Administraciones públicas en Cataluña, todas las personas tienen derecho a utilizar la lengua oficial que elijan."}]},{"text":"Dins dels principis rectors, l''article 50.5 estableix que la Generalitat, l''Administració local i les altres corporacions públiques de Catalunya, les institucions i empreses que en depenen i els concessionaris dels seus serveis han d''utilitzar el català en les actuacions internes i en la relació entre ells. També l''han d''utilitzar en les comunicacions i notificacions adreçades a persones físiques o jurídiques residents a Catalunya, sens perjudici del dret dels ciutadans a rebre-les en castellà si ho demanen. Segons la nota del BOE, la STC 31/2010 declara que aquest apartat no és inconstitucional sempre que s''interpreti en els termes del seu fonament jurídic 23.","refs":[{"ref":"Art. 50.5 EAC","law":"EAC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2006-13087","quote":"La Generalitat, la Administración local y las demás corporaciones públicas de Cataluña, las instituciones y las empresas que dependen de las mismas y los concesionarios de sus servicios deben utilizar el catalán en sus actuaciones internas y en la relación entre ellos. También deben utilizarlo en las comunicaciones y las notificaciones dirigidas a personas físicas o jurídicas residentes en Cataluña, sin perjuicio del derecho de los ciudadanos a recibirlas en castellano si lo piden."},{"ref":"Nota BOE a l''art. 50 EAC","law":"EAC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2006-13087","quote":"Se declara que el apartado 5 no es inconstitucional, siempre que se interprete en los términos establecidos en el fundamento jurídico 23, por Sentencia del TC 31/2010, de 28 de junio."}]}]},{"n":"6","title":"Garanties dels drets i principis rectors (arts. 37 a 39 i 48)","blocks":[{"text":"Els drets dels capítols I, II i III del títol I vinculen tots els poders públics de Catalunya i, segons la naturalesa de cada dret, els particulars; les disposicions s''han d''interpretar i aplicar en el sentit més favorable a la seva plena efectivitat (art. 37.1). Els drets lingüístics dels articles 32 i 33 vinculen també l''Administració General de l''Estat a Catalunya. Aquests drets no alteren el repartiment de competències ni poden reduir els drets fonamentals reconeguts per la Constitució (art. 37.4). Els actes que els vulnerin són objecte de recurs davant el Tribunal Superior de Justícia de Catalunya, i els tutela també el Consell de Garanties Estatutàries (art. 38).","refs":[{"ref":"Art. 37.1 EAC","law":"EAC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2006-13087","quote":"Los derechos reconocidos por los capítulos I, II y III del presente Título vinculan a todos los poderes públicos de Cataluña y, de acuerdo con la naturaleza de cada derecho, a los particulares. […] Los derechos reconocidos en los artículos 32 y 33 vinculan también a la Administración General del Estado en Cataluña."},{"ref":"Art. 37.4 EAC","law":"EAC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2006-13087","quote":"Ninguna de las disposiciones de este Título puede ser desarrollada, aplicada o interpretada de forma que reduzca o limite los derechos fundamentales reconocidos por la Constitución"},{"ref":"Art. 38 EAC","law":"EAC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2006-13087","quote":"son tutelados por el Consejo de Garantías Estatutarias […] serán objeto de recurso ante el Tribunal Superior de Justicia de Cataluña"}]},{"text":"Els principis rectors orienten les polítiques públiques; informen la legislació, la pràctica judicial i l''actuació dels poders públics, i són exigibles davant la jurisdicció d''acord amb les lleis que els despleguen (art. 39). Un exemple rellevant per a la policia local és l''article 48.2: els poders públics han d''impulsar de manera prioritària les mesures per incrementar la seguretat viària i disminuir els accidents de trànsit, amb especial incidència en la prevenció, l''educació viària i l''atenció a les víctimes.","refs":[{"ref":"Art. 39 EAC","law":"EAC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2006-13087","quote":"2. El reconocimiento, el respeto y la protección de los principios rectores informan la legislación positiva, la práctica judicial y la actuación de los poderes públicos. 3. Los principios rectores son exigibles ante la jurisdicción, de acuerdo con lo que determinan las leyes y las demás disposiciones que los desarrollan."},{"ref":"Art. 48.2 EAC","law":"EAC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2006-13087","quote":"Los poderes públicos deben impulsar, de forma prioritaria, las medidas destinadas al incremento de la seguridad vial y la disminución de los accidentes de tráfico, con especial incidencia en la prevención, la educación vial y la atención a las víctimas."}]}]},{"n":"7","title":"Govern local: organització i competències (arts. 83 i 84)","blocks":[{"text":"Catalunya estructura la seva organització territorial bàsica en municipis i vegueries (art. 83.1). L''àmbit supramunicipal el constitueixen, en tot cas, les comarques, que ha de regular una llei del Parlament (art. 83.2), i els altres ens supramunicipals que creï la Generalitat es fonamenten en la voluntat de col·laboració i associació dels municipis (art. 83.3).","refs":[{"ref":"Art. 83 EAC","law":"EAC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2006-13087","quote":"1. Cataluña estructura su organización territorial básica en municipios y veguerías. 2. El ámbito supramunicipal está constituido, en todo caso, por las comarcas, que debe regular una ley del Parlamento. 3. Los demás entes supramunicipales que cree la Generalitat se fundamentan en la voluntad de colaboración y asociación de los municipios."}]},{"text":"L''Estatut garanteix als municipis un nucli de competències pròpies que han d''exercir amb plena autonomia, subjecta només a control de constitucionalitat i de legalitat (art. 84.1). Entre les matèries de competència pròpia dels governs locals (art. 84.2) en destaquen, per a la policia local: la regulació de les condicions de seguretat en les activitats organitzades en espais públics i en els locals de concurrència pública, i la coordinació mitjançant la junta de seguretat dels diferents cossos i forces presents al municipi (lletra e); la protecció civil i la prevenció d''incendis (lletra f), i la circulació i els serveis de mobilitat i la gestió del transport de viatgers municipal (lletra h).","refs":[{"ref":"Art. 84.1 EAC","law":"EAC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2006-13087","quote":"El presente Estatuto garantiza a los municipios un núcleo de competencias propias que deben ser ejercidas por dichas entidades con plena autonomía, sujeta sólo a control de constitucionalidad y de legalidad."},{"ref":"Art. 84.2 EAC","law":"EAC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2006-13087","quote":"e) La regulación de las condiciones de seguridad en las actividades organizadas en espacios públicos y en los locales de concurrencia pública. La coordinación mediante la Junta de Seguridad de los distintos cuerpos y fuerzas presentes en el municipio. f) La protección civil y la prevención de incendios."},{"ref":"Art. 84.2.h EAC","law":"EAC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2006-13087","quote":"h) La circulación y los servicios de movilidad y la gestión del transporte de viajeros municipal."}]}]},{"n":"8","title":"El municipi i l''autonomia municipal (arts. 86 i 87)","blocks":[{"text":"El municipi és l''ens local bàsic de l''organització territorial de Catalunya i el mitjà essencial de participació de la comunitat local en els afers públics (art. 86.1). El govern i l''administració municipals corresponen a l''ajuntament, format per l''alcalde o alcaldessa i els regidors (art. 86.2), i els regidors són elegits pels veïns per sufragi universal, igual, lliure, directe i secret (art. 86.6).","refs":[{"ref":"Art. 86 EAC","law":"EAC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2006-13087","quote":"1. El municipio es el ente local básico de la organización territorial de Cataluña y el medio esencial de participación de la comunidad local en los asuntos públicos. 2. El gobierno y la administración municipales corresponden al Ayuntamiento, formado por el Alcalde o Alcaldesa y los Concejales."},{"ref":"Art. 86.6 EAC","law":"EAC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2006-13087","quote":"Los concejales son elegidos por los vecinos de los municipios mediante sufragio universal, igual, libre, directo y secreto."}]},{"text":"Els actes i acords dels municipis no poden ser objecte de control d''oportunitat per cap altra administració (art. 86.4). El que sí que correspon a la Generalitat és el control de legalitat, és a dir, de l''adequació dels actes i acords a l''ordenament jurídic i, si escau, la impugnació davant la jurisdicció contenciosa administrativa, sens perjudici de les accions de l''Estat en defensa de les seves competències (art. 86.5). Els municipis tenen plena capacitat d''autoorganització dins el marc legal (art. 87.1) i potestat normativa en l''àmbit de les seves competències (art. 87.3), que és la base de les ordenances municipals.","refs":[{"ref":"Art. 86.4 i 86.5 EAC","law":"EAC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2006-13087","quote":"4. Los actos y acuerdos adoptados por los municipios no pueden ser objeto de control de oportunidad por ninguna otra administración. 5. Corresponde a la Generalitat el control de la adecuación al ordenamiento jurídico de los actos y acuerdos adoptados por los municipios y, si procede, la impugnación correspondiente ante la jurisdicción contenciosa administrativa"},{"ref":"Art. 87 EAC","law":"EAC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2006-13087","quote":"Los municipios disponen de plena capacidad de autoorganización dentro del marco de las disposiciones generales establecidas por ley en materia de organización y funcionamiento municipal. […] 3. Los municipios tienen potestad normativa, como expresión del principio democrático en que se fundamentan, en el ámbito de sus competencias y en los otros sobre los que se proyecta su autonomía."}]}]},{"n":"9","title":"Ordenació territorial: la vegueria (arts. 90 i 91)","blocks":[{"text":"La vegueria és l''àmbit territorial específic per a l''exercici del govern intermunicipal de cooperació local i té personalitat jurídica pròpia; és també la divisió territorial adoptada per la Generalitat per organitzar els seus serveis (art. 90.1). El govern i l''administració autònoma de la vegueria corresponen al consell de vegueria, format pel president o presidenta i els consellers de vegueria (art. 91.1); el president l''escullen els consellers d''entre els seus membres (art. 91.2).","refs":[{"ref":"Art. 90.1 EAC","law":"EAC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2006-13087","quote":"La veguería es el ámbito territorial específico para el ejercicio del gobierno intermunicipal de cooperación local y tiene personalidad jurídica propia. La veguería también es la división territorial adoptada por la Generalitat para la organización territorial de sus servicios."},{"ref":"Art. 91.1 i 91.2 EAC","law":"EAC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2006-13087","quote":"El gobierno y la administración autónoma de la veguería corresponden al Consejo de veguería, formado por el Presidente o Presidenta y por los Consejeros de veguería. 2. El Presidente o Presidenta de veguería es escogido por los Consejeros de veguería de entre sus miembros."}]},{"text":"Segons l''article 91.3, els consells de vegueria substitueixen les diputacions. La creació, la modificació i la supressió de les vegueries es regulen per llei del Parlament, i l''alteració dels límits provincials s''ha de fer d''acord amb l''article 141.1 de la Constitució, és a dir, per llei orgànica de les Corts Generals (art. 91.4). La nota del BOE recorda que la STC 31/2010 declara que els apartats 3 i 4 no són inconstitucionals sempre que s''interpretin en els termes del seu fonament jurídic 41.","refs":[{"ref":"Art. 91.3 i 91.4 EAC","law":"EAC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2006-13087","quote":"3. Los Consejos de veguería sustituyen a las Diputaciones. 4. La creación, modificación y supresión, así como el desarrollo del régimen jurídico de las veguerías, se regulan por ley del Parlamento. La alteración, en su caso, de los límites provinciales se llevará a cabo conforme a lo previsto en el artículo 141.1 de la Constitución."},{"ref":"Nota BOE a l''art. 91 EAC","law":"EAC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2006-13087","quote":"Se declara que los apartados 3 y 4 no son inconstitucionales, siempre que se interpreten en los términos establecidos en el fundamento jurídico 41, por Sentencia del TC 31/2010, de 28 de junio."}]}]},{"n":"10","title":"Competències en règim local i seguretat pública (arts. 160 i 164)","blocks":[{"text":"En matèria de règim local, respectant el principi d''autonomia local, la Generalitat té competència exclusiva sobre les matèries que enumera l''article 160.1: entre d''altres, les relacions entre la Generalitat i els ens locals, la determinació de les competències i potestats pròpies dels municipis en els àmbits de l''article 84, i el règim dels béns de domini públic, comunals i patrimonials. En tot el que no estableix l''apartat 1, la competència és compartida (art. 160.2).","refs":[{"ref":"Art. 160.1 EAC","law":"EAC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2006-13087","quote":"Corresponde a la Generalitat la competencia exclusiva en materia de régimen local que, respetando el principio de autonomía local, incluye:"},{"ref":"Art. 160.1.b i 160.2 EAC","law":"EAC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2006-13087","quote":"b) La determinación de las competencias y de las potestades propias de los municipios y de los demás entes locales, en los ámbitos especificados por el artículo 84. […] 2. Corresponde a la Generalitat la competencia compartida en todo lo no establecido por el apartado 1."}]},{"text":"En seguretat pública, i d''acord amb la legislació estatal, corresponen a la Generalitat la planificació i regulació del sistema de seguretat pública de Catalunya i l''ordenació de les policies locals; la creació i organització de la Policia de la Generalitat-Mossos d''Esquadra, i el control i la vigilància del trànsit (art. 164.1). També li corresponen el comandament suprem dels Mossos d''Esquadra i la coordinació de l''actuació de les policies locals (art. 164.2), i, entre les facultats executives, les funcions governatives sobre l''exercici dels drets de reunió i manifestació (art. 164.3.a).","refs":[{"ref":"Art. 164.1 EAC","law":"EAC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2006-13087","quote":"a) La planificación y regulación del sistema de seguridad pública de Cataluña y la ordenación de las policías locales. b) La creación y la organización de la Policía de la Generalitat-Mossos d´Esquadra. c) El control y la vigilancia del tráfico."},{"ref":"Art. 164.2 EAC","law":"EAC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2006-13087","quote":"Corresponde a la Generalitat el mando supremo de la Policía de la Generalitat-Mossos d´Esquadra y la coordinación de la actuación de las policías locales."},{"ref":"Art. 164.3.a EAC","law":"EAC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2006-13087","quote":"a) Las funciones gubernativas sobre el ejercicio de los derechos de reunión y manifestación."}]},{"text":"La Generalitat participa, mitjançant una Junta de Seguretat de composició paritària entre la Generalitat i l''Estat i presidida pel president de la Generalitat, en la coordinació de les polítiques de seguretat i de l''activitat dels cossos policials de l''Estat i de Catalunya (art. 164.4). La Policia de la Generalitat-Mossos d''Esquadra té com a àmbit d''actuació el conjunt del territori de Catalunya i exerceix totes les funcions pròpies d''un cos de policia en els àmbits de la seguretat ciutadana i l''ordre públic, la policia administrativa i la policia judicial i investigació criminal (art. 164.5).","refs":[{"ref":"Art. 164.4 EAC","law":"EAC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2006-13087","quote":"La Generalitat participa, mediante una Junta de Seguridad de composición paritaria entre la Generalitat y el Estado y presidida por el Presidente de la Generalitat, en la coordinación de las políticas de seguridad y de la actividad de los cuerpos policiales del Estado y de Cataluña"},{"ref":"Art. 164.5 EAC","law":"EAC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2006-13087","quote":"La Policía de la Generalitat-Mossos d''Esquadra tiene como ámbito de actuación el conjunto del territorio de Cataluña y ejerce todas las funciones propias de un cuerpo de policía, en los siguientes ámbitos: a) La seguridad ciudadana y el orden público. b) La policía administrativa, que incluye la que deriva de la normativa estatal. c) La policía judicial y la investigación criminal"}]}]},{"n":"R","title":"Recorda per a l''examen","blocks":[{"text":"Catalunya exerceix l''autogovern com a nacionalitat, constituïda en comunitat autònoma; l''Estatut és la seva norma institucional bàsica (art. 1).","refs":[{"ref":"Art. 1 EAC","law":"EAC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2006-13087","quote":"Cataluña, como nacionalidad, ejerce su autogobierno constituida en Comunidad Autónoma"}]},{"text":"Municipis, vegueries, comarques i altres ens locals també integren el sistema institucional de la Generalitat (art. 2.3).","refs":[{"ref":"Art. 2.3 EAC","law":"EAC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2006-13087","quote":"también integran el sistema institucional de la Generalitat, como entes en los que ésta se organiza territorialmente, sin perjuicio de su autonomía."}]},{"text":"Dues llengües oficials: tothom té dret a usar-les i els ciutadans de Catalunya tenen el dret i el deure de conèixer-les (art. 6.2). Opció lingüística davant les administracions (art. 33.1).","refs":[{"ref":"Art. 6.2 EAC","law":"EAC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2006-13087","quote":"Todas las personas tienen derecho a utilizar las dos lenguas oficiales y los ciudadanos de Cataluña el derecho y el deber de conocerlas."}]},{"text":"Festa: l''Onze de Setembre. Bandera: quatre barres vermelles en fons groc (art. 8).","refs":[{"ref":"Art. 8.3 EAC","law":"EAC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2006-13087","quote":"La fiesta de Cataluña es el Día Once de Septiembre."}]},{"text":"Comunicacions i notificacions locals a residents: en català, amb dret a rebre-les en castellà si es demana (art. 50.5).","refs":[{"ref":"Art. 50.5 EAC","law":"EAC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2006-13087","quote":"sin perjuicio del derecho de los ciudadanos a recibirlas en castellano si lo piden."}]},{"text":"Organització territorial bàsica: municipis i vegueries (art. 83.1); els consells de vegueria substitueixen les diputacions (art. 91.3).","refs":[{"ref":"Art. 83.1 EAC","law":"EAC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2006-13087","quote":"Cataluña estructura su organización territorial básica en municipios y veguerías."}]},{"text":"Actes municipals: cap control d''oportunitat per una altra administració; només control de legalitat (art. 86.4 i 86.5).","refs":[{"ref":"Art. 86.4 EAC","law":"EAC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2006-13087","quote":"no pueden ser objeto de control de oportunidad por ninguna otra administración."}]},{"text":"Règim local: competència exclusiva de la Generalitat en les matèries de l''article 160.1 i compartida en la resta (art. 160.2).","refs":[{"ref":"Art. 160.2 EAC","law":"EAC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2006-13087","quote":"Corresponde a la Generalitat la competencia compartida en todo lo no establecido por el apartado 1."}]},{"text":"Seguretat pública: ordenació de les policies locals (art. 164.1.a) i coordinació de la seva actuació (art. 164.2). Junta de Seguretat paritària presidida pel president de la Generalitat (art. 164.4).","refs":[{"ref":"Art. 164.2 EAC","law":"EAC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2006-13087","quote":"la coordinación de la actuación de las policías locales."}]},{"text":"Els Mossos d''Esquadra actuen en el conjunt del territori de Catalunya (art. 164.5).","refs":[{"ref":"Art. 164.5 EAC","law":"EAC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2006-13087","quote":"tiene como ámbito de actuación el conjunto del territorio de Cataluña"}]}]}]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2006-13087'), 'https://www.boe.es/buscar/act.php?id=BOE-A-2006-13087', null, null, null, null
  from public.topics t where t.slug = 'plcat-t03-estatut-autonomia'
