   set outline = excluded.outline, key_ideas = excluded.key_ideas, glossary = excluded.glossary,
       amendments = excluded.amendments, lessons = excluded.lessons, source_id = excluded.source_id, source_url = excluded.source_url,
       page_from = excluded.page_from, page_to = excluded.page_to, key_ideas_page = excluded.key_ideas_page
 where (n.outline, n.key_ideas, n.glossary, n.amendments, n.lessons)
       is distinct from (excluded.outline, excluded.key_ideas, excluded.glossary, excluded.amendments, excluded.lessons);
insert into public.sources (title, url, kind, publisher, published_on) values ('Ley 7/1985, de 2 de abril, Reguladora de las Bases del Régimen Local (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-5392', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('plcat-t04-regim-local', 'Tema 4. Règim local: el municipi, l''organització municipal i les ordenances (Llei 7/1985)') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('policia-local') and t.slug = 'plcat-t04-regim-local' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, lessons, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"Entitats locals i municipi (arts. 3 i 11)"},{"n":"2","title":"Territori, població i padró (arts. 12 i 15)"},{"n":"3","title":"Organització municipal: òrgans necessaris (art. 20)"},{"n":"4","title":"L''alcalde i les seves atribucions, també en policia (art. 21)"},{"n":"5","title":"El Ple i la Junta de Govern Local (arts. 22 i 23)"},{"n":"6","title":"Competències pròpies i serveis mínims (arts. 25 i 26)"},{"n":"7","title":"Ordenances: procediment d''aprovació (art. 49)"},{"n":"8","title":"Infraccions i sancions de les ordenances (arts. 139-141)"}]'::jsonb, '["Art. 3 LBRL: «1. Son Entidades Locales territoriales: a) El Municipio. b) La Provincia. c) La Isla en los archipiélagos balear y canario.»","Art. 11.2 LBRL: «2. Son elementos del Municipio el territorio, la población y la organización.»","Art. 12 LBRL: «1. El término municipal es el territorio en que el ayuntamiento ejerce sus competencias. 2. Cada municipio pertenecerá a una sola provincia.»","Art. 15 LBRL: «Quien viva en varios municipios deberá inscribirse únicamente en el que habite durante más tiempo al año.»","Art. 20 LBRL: «a) El Alcalde, los Tenientes de Alcalde y el Pleno existen en todos los ayuntamientos.»","Art. 21.1.i LBRL: «i) Ejercer la jefatura de la Policía Municipal.»","Art. 21.3 LBRL: «3. El Alcalde puede delegar el ejercicio de sus atribuciones, salvo las de convocar y presidir las sesiones del Pleno y de la Junta de Gobierno Local»","Art. 21.1.m LBRL: «m) Adoptar personalmente, y bajo su responsabilidad, en caso de catástrofe o de infortunios públicos o grave riesgo de los mismos, las medidas necesarias y adecuadas dando cuenta inmediata al Pleno.»","Art. 21.1.e LBRL: «e) Dictar bandos.»","Art. 22.2.d LBRL: «d) La aprobación del reglamento orgánico y de las ordenanzas.»","Art. 23 LBRL: «1. La Junta de Gobierno Local se integra por el Alcalde y un número de Concejales no superior al tercio del número legal de los mismos, nombrados y separados libremente por aquél, dando cuenta al Pleno.»","Art. 23.3 LBRL: «3. Los Tenientes de Alcalde sustituyen, por el orden de su nombramiento y en los casos de vacante, ausencia o enfermedad, al Alcalde»","Art. 25.2.f LBRL: «f) Policía local, protección civil, prevención y extinción de incendios.»","Art. 26.1 LBRL: «c) En los Municipios con población superior a 20.000 habitantes, además: protección civil»","Art. 26.1.d LBRL: «d) En los Municipios con población superior a 50.000 habitantes, además: transporte colectivo urbano de viajeros y medio ambiente urbano.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[{"n":"1","title":"Entitats locals i municipi (arts. 1, 3 i 11)","blocks":[{"text":"La Llei 7/1985, de 2 d''abril, reguladora de les bases del règim local (LBRL), és la norma bàsica estatal sobre els ens locals. Els municipis són entitats bàsiques de l''organització territorial de l''Estat i canals immediats de participació ciutadana en els afers públics, que gestionen amb autonomia els interessos propis de les seves col·lectivitats (art. 1.1). A Catalunya aquesta llei bàsica conviu amb la legislació catalana de règim local, que no és entre les fonts de la carpeta; per això aquests apunts se cenyeixen a la LBRL.","refs":[{"ref":"Títol LBRL","law":"LBRL","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-5392","quote":"Ley 7/1985, de 2 de abril, Reguladora de las Bases del Régimen Local"},{"ref":"Art. 1.1 LBRL","law":"LBRL","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-5392","quote":"Los Municipios son entidades básicas de la organización territorial del Estado y cauces inmediatos de participación ciudadana en los asuntos públicos, que institucionalizan y gestionan con autonomía los intereses propios de las correspondientes colectividades."}]},{"text":"Són entitats locals territorials el municipi, la província i l''illa als arxipèlags balear i canari (art. 3.1). També tenen la condició d''entitats locals, però no territorials, les comarques o altres entitats que agrupin diversos municipis instituïdes per les comunitats autònomes, les àrees metropolitanes i les mancomunitats de municipis (art. 3.2).","refs":[{"ref":"Art. 3 LBRL","law":"LBRL","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-5392","quote":"1. Son Entidades Locales territoriales: a) El Municipio. b) La Provincia. c) La Isla en los archipiélagos balear y canario. 2. Gozan, asimismo, de la condición de Entidades Locales: a) Las Comarcas u otras entidades que agrupen varios Municipios, instituidas por las Comunidades Autónomas de conformidad con esta Ley y los correspondientes Estatutos de Autonomía. b) Las Áreas Metropolitanas. c) Las Mancomunidades de Municipios."}]},{"text":"El municipi és l''entitat local bàsica, amb personalitat jurídica i plena capacitat per complir les seves finalitats (art. 11.1), i els seus elements són tres: el territori, la població i l''organització (art. 11.2). Com a administració territorial, li corresponen, entre d''altres, les potestats reglamentària i d''autoorganització, tributària i financera, d''execució forçosa i sancionadora, i la presumpció de legitimitat i l''executivitat dels seus actes (art. 4.1).","refs":[{"ref":"Art. 11 LBRL","law":"LBRL","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-5392","quote":"1. El Municipio es la entidad local básica de la organización territorial del Estado. Tiene personalidad jurídica y plena capacidad para el cumplimiento de sus fines. 2. Son elementos del Municipio el territorio, la población y la organización."},{"ref":"Art. 4.1 LBRL","law":"LBRL","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-5392","quote":"a) Las potestades reglamentaria y de autoorganización. b) Las potestades tributaria y financiera. […] e) La presunción de legitimidad y la ejecutividad de sus actos. f) Las potestades de ejecución forzosa y sancionadora."}]}]},{"n":"2","title":"Territori, població i padró (arts. 12 a 18)","blocks":[{"text":"El terme municipal és el territori en què l''ajuntament exerceix les seves competències, i cada municipi pertany a una sola província (art. 12). La creació o supressió de municipis i l''alteració de termes es regulen per la legislació autonòmica de règim local, i l''alteració de termes no pot suposar mai una modificació dels límits provincials (art. 13.1). Els nous municipis només es poden crear sobre nuclis de població territorialment diferenciats d''almenys 4.000 habitants i financerament sostenibles (art. 13.2).","refs":[{"ref":"Art. 12 LBRL","law":"LBRL","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-5392","quote":"1. El término municipal es el territorio en que el ayuntamiento ejerce sus competencias. 2. Cada municipio pertenecerá a una sola provincia."},{"ref":"Art. 13 LBRL","law":"LBRL","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-5392","quote":"se regularán por la legislación de las Comunidades Autónomas sobre régimen local, sin que la alteración de términos municipales pueda suponer, en ningún caso, modificación de los límites provinciales. […] de al menos 4.000 habitantes y siempre que los municipios resultantes sean financieramente sostenibles"}]},{"text":"Tota persona que viu a Espanya està obligada a inscriure''s en el padró del municipi on resideix habitualment; qui viu en diversos municipis s''ha d''inscriure únicament en aquell on habiti més temps a l''any (art. 15). El conjunt d''inscrits forma la població del municipi, els inscrits són els veïns, i la condició de veí s''adquireix en el mateix moment de la inscripció en el padró.","refs":[{"ref":"Art. 15 LBRL","law":"LBRL","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-5392","quote":"Toda persona que viva en España está obligada a inscribirse en el Padrón del municipio en el que resida habitualmente. Quien viva en varios municipios deberá inscribirse únicamente en el que habite durante más tiempo al año. El conjunto de personas inscritas en el Padrón municipal constituye la población del municipio. Los inscritos en el Padrón municipal son los vecinos del municipio. La condición de vecino se adquiere en el mismo momento de su inscripción en el Padrón."}]},{"text":"El padró municipal és el registre administratiu on consten els veïns; les seves dades són prova de la residència i del domicili habitual, i les certificacions que se n''expedeixen són document públic i fefaent a tots els efectes administratius (art. 16.1). La inscripció dels estrangers en el padró no constitueix prova de la seva residència legal a Espanya ni els atribueix cap dret que no els confereixi la legislació vigent (art. 18.2). Entre els drets i deures dels veïns hi ha ser elector i elegible, utilitzar els serveis públics municipals i contribuir a les competències municipals (art. 18.1).","refs":[{"ref":"Art. 16.1 LBRL","law":"LBRL","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-5392","quote":"El Padrón municipal es el registro administrativo donde constan los vecinos de un municipio. Sus datos constituyen prueba de la residencia en el municipio y del domicilio habitual en el mismo. Las certificaciones que de dichos datos se expidan tendrán carácter de documento público y fehaciente para todos los efectos administrativos."},{"ref":"Art. 18 LBRL","law":"LBRL","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-5392","quote":"a) Ser elector y elegible de acuerdo con lo dispuesto en la legislación electoral. […] c) Utilizar, de acuerdo con su naturaleza, los servicios públicos municipales […] 2. La inscripción de los extranjeros en el padrón municipal no constituirá prueba de su residencia legal en España ni les atribuirá ningún derecho que no les confiera la legislación vigente"}]}]},{"n":"3","title":"Organització municipal: òrgans necessaris (arts. 19 i 20)","blocks":[{"text":"El govern i l''administració municipal corresponen a l''ajuntament, integrat per l''alcalde i els regidors, excepte en els municipis que funcionen en règim de concejo abierto (consell obert) (art. 19.1). Els regidors són elegits per sufragi universal, igual, lliure, directe i secret, i l''alcalde és elegit pels regidors o pels veïns (art. 19.2).","refs":[{"ref":"Art. 19 LBRL","law":"LBRL","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-5392","quote":"1. El Gobierno y la administración municipal, salvo en aquellos municipios que legalmente funcionen en régimen de Concejo Abierto, corresponde al ayuntamiento, integrado por el Alcalde y los Concejales. 2. Los Concejales son elegidos mediante sufragio universal, igual, libre, directo y secreto, y el Alcalde es elegido por los Concejales o por los vecinos"}]},{"text":"L''article 20.1 fixa els òrgans. L''alcalde, els tinents d''alcalde i el Ple existeixen en tots els ajuntaments. La Junta de Govern Local existeix en tots els municipis de més de 5.000 habitants i, en els de menys, quan ho disposi el reglament orgànic o ho acordi el Ple. La Comissió Especial de Comptes existeix en tots els municipis. Les lleis autonòmiques i els reglaments orgànics poden afegir-hi òrgans complementaris (art. 20.2 i 20.3).","refs":[{"ref":"Art. 20.1 LBRL","law":"LBRL","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-5392","quote":"a) El Alcalde, los Tenientes de Alcalde y el Pleno existen en todos los ayuntamientos. b) La Junta de Gobierno Local existe en todos los municipios con población superior a 5.000 habitantes y en los de menos, cuando así lo disponga su reglamento orgánico o así lo acuerde el Pleno de su ayuntamiento."},{"ref":"Art. 20.1.e LBRL","law":"LBRL","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-5392","quote":"e) La Comisión Especial de Cuentas existe en todos los municipios, de acuerdo con la estructura prevista en el artículo 116."}]}]},{"n":"4","title":"L''alcalde i les seves atribucions, també en policia (art. 21)","blocks":[{"text":"L''alcalde és el president de la corporació (art. 21.1). Entre les seves atribucions hi ha dirigir el govern i l''administració municipal (a), representar l''ajuntament (b), convocar i presidir les sessions del Ple i de la Junta de Govern Local i decidir els empats amb vot de qualitat (c), dictar bans (e), exercir la prefectura superior de tot el personal (h) i, molt important per a aquest temari, exercir la prefectura de la Policia Municipal (i). També li correspon sancionar les faltes de desobediència a la seva autoritat o per infracció de les ordenances municipals, llevat que aquesta facultat estigui atribuïda a altres òrgans (n), i nomenar els tinents d''alcalde (art. 21.2).","refs":[{"ref":"Art. 21.1 LBRL","law":"LBRL","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-5392","quote":"1. El Alcalde es el Presidente de la Corporación y ostenta las siguientes atribuciones: a) Dirigir el gobierno y la administración municipal. b) Representar al ayuntamiento."},{"ref":"Art. 21.1.e, h, i LBRL","law":"LBRL","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-5392","quote":"e) Dictar bandos. […] h) Desempeñar la jefatura superior de todo el personal […] i) Ejercer la jefatura de la Policía Municipal."},{"ref":"Art. 21.1.n i 21.2 LBRL","law":"LBRL","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-5392","quote":"n) Sancionar las faltas de desobediencia a su autoridad o por infracción de las ordenanzas municipales, salvo en los casos en que tal facultad esté atribuida a otros órganos. […] 2. Corresponde asimismo al Alcalde el nombramiento de los Tenientes de Alcalde."}]},{"text":"En cas de catàstrofe o d''infortunis públics o de risc greu que es produeixin, l''alcalde pot adoptar personalment, i sota la seva responsabilitat, les mesures necessàries i adequades, donant-ne compte immediat al Ple (art. 21.1.m). És la base de moltes actuacions d''emergència en què intervé la policia local.","refs":[{"ref":"Art. 21.1.m LBRL","law":"LBRL","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-5392","quote":"m) Adoptar personalmente, y bajo su responsabilidad, en caso de catástrofe o de infortunios públicos o grave riesgo de los mismos, las medidas necesarias y adecuadas dando cuenta inmediata al Pleno."}]},{"text":"L''alcalde pot delegar les seves atribucions, excepte les que enumera l''article 21.3: convocar i presidir les sessions del Ple i de la Junta de Govern Local, decidir els empats amb vot de qualitat, concertar operacions de crèdit, la prefectura superior de tot el personal, la separació del servei dels funcionaris i l''acomiadament del personal laboral, i les de les lletres a), e), j), k), l) i m) de l''apartat 1. Per tant, dictar bans (e) i les mesures d''emergència (m) són indelegables; en canvi, la prefectura de la Policia Municipal (lletra i) no és a la llista d''exclusions i, per tant, és delegable.","refs":[{"ref":"Art. 21.3 LBRL","law":"LBRL","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-5392","quote":"El Alcalde puede delegar el ejercicio de sus atribuciones, salvo las de convocar y presidir las sesiones del Pleno y de la Junta de Gobierno Local, decidir los empates con el voto de calidad, la concertación de operaciones de crédito, la jefatura superior de todo el personal, la separación del servicio de los funcionarios y el despido del personal laboral, y las enunciadas en los párrafos a), e), j), k), l) y m) del apartado 1 de este artículo."}]}]},{"n":"5","title":"El Ple i la Junta de Govern Local (arts. 22 i 23)","blocks":[{"text":"El Ple, integrat per tots els regidors, el presideix l''alcalde (art. 22.1). Li corresponen, entre altres atribucions, el control i la fiscalització dels òrgans de govern (a), l''aprovació del reglament orgànic i de les ordenances (d), la determinació dels recursos propis de caràcter tributari i l''aprovació dels pressupostos (e), i l''aprovació de la plantilla de personal i de la relació de llocs de treball (i). També vota la moció de censura a l''alcalde i la qüestió de confiança (art. 22.3). L''aprovació de les ordenances no es pot delegar (art. 22.4).","refs":[{"ref":"Art. 22.1 i 22.2 LBRL","law":"LBRL","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-5392","quote":"1. El Pleno, integrado por todos los Concejales, es presidido por el Alcalde. […] a) El control y la fiscalización de los órganos de gobierno. […] d) La aprobación del reglamento orgánico y de las ordenanzas."},{"ref":"Art. 22.3 LBRL","law":"LBRL","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-5392","quote":"Corresponde, igualmente, al Pleno la votación sobre la moción de censura al Alcalde y sobre la cuestión de confianza planteada por el mismo"},{"ref":"Art. 22.4 LBRL","law":"LBRL","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-5392","quote":"El Pleno puede delegar el ejercicio de sus atribuciones en el Alcalde y en la Junta de Gobierno Local, salvo las enunciadas en el apartado 2, párrafos a), b), c), d), e), f), g), h), i), l) y p), y en el apartado 3 de este artículo."}]},{"text":"La Junta de Govern Local s''integra per l''alcalde i un nombre de regidors no superior al terç del nombre legal de regidors, nomenats i separats lliurement per l''alcalde, que n''ha de donar compte al Ple (art. 23.1). Li correspon assistir l''alcalde en l''exercici de les seves atribucions i exercir les que li deleguin o li atribueixin les lleis (art. 23.2).","refs":[{"ref":"Art. 23.1 i 23.2 LBRL","law":"LBRL","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-5392","quote":"1. La Junta de Gobierno Local se integra por el Alcalde y un número de Concejales no superior al tercio del número legal de los mismos, nombrados y separados libremente por aquél, dando cuenta al Pleno. 2. Corresponde a la Junta de Gobierno Local: a) La asistencia al Alcalde en el ejercicio de sus atribuciones."}]},{"text":"Els tinents d''alcalde substitueixen l''alcalde, per l''ordre del seu nomenament, en els casos de vacant, absència o malaltia. L''alcalde els designa i remou lliurement d''entre els membres de la Junta de Govern Local i, on aquesta no existeixi, d''entre els regidors (art. 23.3).","refs":[{"ref":"Art. 23.3 LBRL","law":"LBRL","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-5392","quote":"3. Los Tenientes de Alcalde sustituyen, por el orden de su nombramiento y en los casos de vacante, ausencia o enfermedad, al Alcalde, siendo libremente designados y removidos por éste de entre los miembros de la Junta de Gobierno Local y, donde ésta no exista, de entre los Concejales."}]}]},{"n":"6","title":"Competències pròpies (art. 25)","blocks":[{"text":"El municipi, per gestionar els seus interessos i en l''àmbit de les seves competències, pot promoure activitats i prestar serveis públics que satisfacin les necessitats de la comunitat veïnal (art. 25.1). L''article 25.2 enumera les matèries en què exerceix en tot cas competències pròpies, en els termes de la legislació estatal i autonòmica. Per a la policia local destaquen: policia local, protecció civil, prevenció i extinció d''incendis (lletra f); trànsit, estacionament de vehicles i mobilitat, i transport col·lectiu urbà (lletra g); medi ambient urbà, inclosa la protecció contra la contaminació acústica (lletra b), i les actuacions de promoció de la igualtat entre homes i dones i contra la violència de gènere (lletra o).","refs":[{"ref":"Art. 25.2.b LBRL","law":"LBRL","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-5392","quote":"b) Medio ambiente urbano: en particular, parques y jardines públicos, gestión de los residuos sólidos urbanos y protección contra la contaminación acústica, lumínica y atmosférica en las zonas urbanas."},{"ref":"Art. 25.2.f i g LBRL","law":"LBRL","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-5392","quote":"f) Policía local, protección civil, prevención y extinción de incendios. g) Tráfico, estacionamiento de vehículos y movilidad. Transporte colectivo urbano."},{"ref":"Art. 25.2.o LBRL","law":"LBRL","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-5392","quote":"o) Actuaciones en la promoción de la igualdad entre hombres y mujeres así como contra la violencia de género."}]},{"text":"La disposició addicional desena de la LBRL preveu que, en el marc de les lleis orgàniques del Poder Judicial, de forces i cossos de seguretat i de seguretat ciutadana, es potenciï la participació dels cossos de policia local en el manteniment de la seguretat ciutadana, com a policia de proximitat, i en l''exercici de funcions de policia judicial. Cal advertir que el text cita la Llei orgànica 1/1992, de seguretat ciutadana, que avui ha estat substituïda per la Llei orgànica 4/2015 (tema de seguretat ciutadana); la disposició no s''ha actualitzat en aquest punt.","refs":[{"ref":"DA 10a LBRL","law":"LBRL","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-5392","quote":"1/1992, de 21 de febrero, sobre Protección de la Seguridad Ciudadana, y en las disposiciones legales reguladoras del régimen local, se potenciará la participación de los Cuerpos de policía local en el mantenimiento de la seguridad ciudadana, como policía de proximidad, así como en el ejercicio de las funciones de policía judicial"},{"ref":"Disposició derogatòria única LOPSC","law":"LO 4/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442","quote":"1. Queda derogada la Ley Orgánica 1/1992, de 21 de febrero, sobre Protección de la Seguridad Ciudadana."}]}]},{"n":"7","title":"Serveis mínims obligatoris (art. 26)","blocks":[{"text":"L''article 26.1 fixa els serveis que els municipis han de prestar en tot cas, de manera acumulativa segons la població. En tots els municipis: enllumenat públic, cementiri, recollida de residus, neteja viària, abastament domiciliari d''aigua potable, clavegueram, accés als nuclis de població i pavimentació de les vies públiques. En els de més de 5.000 habitants, a més: parc públic, biblioteca pública i tractament de residus.","refs":[{"ref":"Art. 26.1.a i b LBRL","law":"LBRL","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-5392","quote":"a) En todos los Municipios: alumbrado público, cementerio, recogida de residuos, limpieza viaria, abastecimiento domiciliario de agua potable, alcantarillado, acceso a los núcleos de población y pavimentación de las vías públicas. b) En los Municipios con población superior a 5.000 habitantes, además: parque público, biblioteca pública y tratamiento de residuos."}]},{"text":"En els municipis de més de 20.000 habitants, a més: protecció civil, avaluació i informació de situacions de necessitat social i atenció immediata a persones en risc d''exclusió social, prevenció i extinció d''incendis i instal·lacions esportives d''ús públic. En els de més de 50.000 habitants, a més: transport col·lectiu urbà de viatgers i medi ambient urbà. Retén les xifres 5.000, 20.000 i 50.000.","refs":[{"ref":"Art. 26.1.c i d LBRL","law":"LBRL","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-5392","quote":"c) En los Municipios con población superior a 20.000 habitantes, además: protección civil, evaluación e información de situaciones de necesidad social y la atención inmediata a personas en situación o riesgo de exclusión social, prevención y extinción de incendios e instalaciones deportivas de uso público. d) En los Municipios con población superior a 50.000 habitantes, además: transporte colectivo urbano de viajeros y medio ambiente urbano."}]}]},{"n":"8","title":"Ordenances: procediment d''aprovació (art. 49)","blocks":[{"text":"Les ordenances locals s''aproven en tres fases (art. 49): aprovació inicial pel Ple; informació pública i audiència als interessats per un termini mínim de trenta dies per presentar reclamacions i suggeriments; i resolució de totes les reclamacions i suggeriments presentats dins el termini i aprovació definitiva pel Ple. Si no s''ha presentat cap reclamació ni suggeriment, l''acord fins aleshores provisional s''entén definitivament adoptat, sense necessitat d''un nou acord. Recorda que l''aprovació és sempre del Ple, mentre que els bans els dicta l''alcalde.","refs":[{"ref":"Art. 49 LBRL","law":"LBRL","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-5392","quote":"a) Aprobación inicial por el Pleno. b) Información pública y audiencia a los interesados por el plazo mínimo de treinta días para la presentación de reclamaciones y sugerencias. c) Resolución de todas las reclamaciones y sugerencias presentadas dentro del plazo y aprobación definitiva por el Pleno. En el caso de que no se hubiera presentado ninguna reclamación o sugerencia, se entenderá definitivamente adoptado el acuerdo hasta entonces provisional."}]}]},{"n":"9","title":"Infraccions i sancions de les ordenances (arts. 139 a 141)","blocks":[{"text":"Per ordenar adequadament les relacions de convivència d''interès local i l''ús dels serveis, equipaments, infraestructures, instal·lacions i espais públics, els ens locals poden, en defecte de normativa sectorial específica, establir els tipus de les infraccions i imposar sancions per l''incompliment dels deures, prohibicions o limitacions de les ordenances (art. 139). La potestat sancionadora municipal és, doncs, subsidiària de la legislació sectorial.","refs":[{"ref":"Art. 139 LBRL","law":"LBRL","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-5392","quote":"Para la adecuada ordenación de las relaciones de convivencia de interés local y del uso de sus servicios, equipamientos, infraestructuras, instalaciones y espacios públicos, los entes locales podrán, en defecto de normativa sectorial específica, establecer los tipos de las infracciones e imponer sanciones por el incumplimiento de deberes, prohibiciones o limitaciones contenidos en las correspondientes ordenanzas"}]},{"text":"Les infraccions es classifiquen en molt greus, greus i lleus (art. 140.1). Són molt greus, entre d''altres: una pertorbació rellevant de la convivència que afecti de manera greu, immediata i directa la tranquil·litat o l''exercici de drets legítims d''altres persones; impedir l''ús d''un servei públic o d''un espai públic a altres persones amb dret a utilitzar-lo; impedir o obstruir greument el funcionament normal d''un servei públic, i els actes de deteriorament greu i rellevant d''equipaments o espais públics. Les altres es classifiquen en greus i lleus segons la intensitat de la pertorbació o dels danys (art. 140.2). Fixa''t que la lletra a) es remet al capítol IV de la LO 1/1992, de seguretat ciutadana, avui derogada per la LO 4/2015.","refs":[{"ref":"Art. 140.1 LBRL","law":"LBRL","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-5392","quote":"Las infracciones a las ordenanzas locales a que se refiere el artículo anterior se clasificarán en muy graves, graves y leves. Serán muy graves las infracciones que supongan: a) Una perturbación relevante de la convivencia que afecte de manera grave, inmediata y directa a la tranquilidad o al ejercicio de derechos legítimos de otras personas"},{"ref":"Art. 140.1.b, c, e LBRL","law":"LBRL","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-5392","quote":"b) El impedimento del uso de un servicio público por otra u otras personas con derecho a su utilización. c) El impedimento o la grave y relevante obstrucción al normal funcionamiento de un servicio público. […] e) El impedimento del uso de un espacio público por otra u otras personas con derecho a su utilización."},{"ref":"Art. 140.2 LBRL","law":"LBRL","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-5392","quote":"Las demás infracciones se clasificarán en graves y leves, de acuerdo con los siguientes criterios: a) La intensidad de la perturbación ocasionada en la tranquilidad o en el pacífico ejercicio de los derechos de otras personas o actividades."}]},{"text":"Llevat de previsió legal diferent, les multes per infracció d''ordenances locals han de respectar aquests límits (art. 141): infraccions molt greus, fins a 3.000 euros; greus, fins a 1.500 euros, i lleus, fins a 750 euros. Cada import és el doble de l''anterior, cosa que ajuda a recordar-los.","refs":[{"ref":"Art. 141 LBRL","law":"LBRL","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-5392","quote":"Salvo previsión legal distinta, las multas por infracción de Ordenanzas locales deberán respetar las siguientes cuantías: Infracciones muy graves: hasta 3.000 euros. Infracciones graves: hasta 1.500 euros. Infracciones leves: hasta 750 euros."}]}]},{"n":"R","title":"Recorda per a l''examen","blocks":[{"text":"Entitats locals territorials: municipi, província i illa (art. 3.1). Elements del municipi: territori, població i organització (art. 11.2).","refs":[{"ref":"Art. 11.2 LBRL","law":"LBRL","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-5392","quote":"Son elementos del Municipio el territorio, la población y la organización."}]},{"text":"Qui viu en diversos municipis s''empadrona només on habita més temps a l''any; la condició de veí s''adquireix en inscriure''s (art. 15).","refs":[{"ref":"Art. 15 LBRL","law":"LBRL","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-5392","quote":"La condición de vecino se adquiere en el mismo momento de su inscripción en el Padrón."}]},{"text":"Òrgans de tots els ajuntaments: alcalde, tinents d''alcalde i Ple; Junta de Govern Local obligatòria a partir de 5.000 habitants (art. 20.1).","refs":[{"ref":"Art. 20.1.a LBRL","law":"LBRL","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-5392","quote":"El Alcalde, los Tenientes de Alcalde y el Pleno existen en todos los ayuntamientos."}]},{"text":"L''alcalde exerceix la prefectura de la Policia Municipal (art. 21.1.i), i aquesta atribució és delegable; dictar bans (e) i les mesures en catàstrofes (m) no ho són (art. 21.3).","refs":[{"ref":"Art. 21.3 LBRL","law":"LBRL","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-5392","quote":"y las enunciadas en los párrafos a), e), j), k), l) y m) del apartado 1 de este artículo."}]},{"text":"Ordenances i reglament orgànic: les aprova el Ple (art. 22.2.d), amb informació pública mínima de trenta dies (art. 49.b).","refs":[{"ref":"Art. 49.b LBRL","law":"LBRL","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-5392","quote":"por el plazo mínimo de treinta días"}]},{"text":"Junta de Govern Local: alcalde i regidors fins a un terç del nombre legal. Els tinents d''alcalde substitueixen l''alcalde per l''ordre de nomenament (art. 23).","refs":[{"ref":"Art. 23 LBRL","law":"LBRL","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-5392","quote":"un número de Concejales no superior al tercio del número legal de los mismos"}]},{"text":"Serveis obligatoris: protecció civil i extinció d''incendis, a partir de 20.000 habitants; transport col·lectiu urbà i medi ambient urbà, a partir de 50.000 (art. 26.1).","refs":[{"ref":"Art. 26.1.d LBRL","law":"LBRL","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-5392","quote":"En los Municipios con población superior a 50.000 habitantes, además: transporte colectivo urbano de viajeros y medio ambiente urbano."}]},{"text":"Impedir a altres persones l''ús d''un servei públic o d''un espai públic és infracció molt greu (art. 140.1).","refs":[{"ref":"Art. 140.1.b LBRL","law":"LBRL","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-5392","quote":"b) El impedimento del uso de un servicio público por otra u otras personas con derecho a su utilización."}]},{"text":"Multes d''ordenances: molt greus fins a 3.000 euros, greus fins a 1.500 i lleus fins a 750 (art. 141).","refs":[{"ref":"Art. 141 LBRL","law":"LBRL","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-5392","quote":"Infracciones graves: hasta 1.500 euros."}]}]}]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-5392'), 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-5392', null, null, null, null
  from public.topics t where t.slug = 'plcat-t04-regim-local'
