insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, lessons, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"Interessats i capacitat d''obrar (art. 4)"},{"n":"2","title":"Relació electrònica amb l''Administració (art. 14)"},{"n":"3","title":"Obligació de resoldre i silenci administratiu (arts. 21 i 24)"},{"n":"4","title":"Còmput de terminis (art. 30)"},{"n":"5","title":"Eficàcia i validesa dels actes: nul·litat i anul·labilitat (arts. 39, 47 i 48)"},{"n":"6","title":"Drets de l''interessat en el procediment (art. 53)"},{"n":"7","title":"Esmena de la sol·licitud i terminació (arts. 68 i 85)"},{"n":"8","title":"Recursos administratius: alçada i reposició (arts. 112, 122 i 124)"}]'::jsonb, '["Art. 4 Llei 39/2015: «a) Quienes lo promuevan como titulares de derechos o intereses legítimos individuales o colectivos.»","Art. 14.1 Llei 39/2015: «1. Las personas físicas podrán elegir en todo momento si se comunican con las Administraciones Públicas para el ejercicio de sus derechos y obligaciones a través de medios electrónicos o no»","Art. 14.2 Llei 39/2015: «a) Las personas jurídicas.»","Art. 21.1 Llei 39/2015: «1. La Administración está obligada a dictar resolución expresa y a notificarla en todos los procedimientos cualquiera que sea su forma de iniciación.»","Art. 21.3 Llei 39/2015: «3. Cuando las normas reguladoras de los procedimientos no fijen el plazo máximo, éste será de tres meses.»","Art. 21.2 Llei 39/2015: «Este plazo no podrá exceder de seis meses salvo que una norma con rango de Ley establezca uno mayor»","Art. 24.1 Llei 39/2015: «legitima al interesado o interesados para entenderla estimada por silencio administrativo»","Art. 30.2 Llei 39/2015: «cuando los plazos se señalen por días, se entiende que éstos son hábiles, excluyéndose del cómputo los sábados, los domingos y los declarados festivos.»","Art. 30.1 Llei 39/2015: «no podrán tener una duración superior a veinticuatro horas, en cuyo caso se expresarán en días.»","Art. 39.1 Llei 39/2015: «1. Los actos de las Administraciones Públicas sujetos al Derecho Administrativo se presumirán válidos y producirán efectos desde la fecha en que se dicten, salvo que en ellos se disponga otra cosa.»","Art. 47 Llei 39/2015: «b) Los dictados por órgano manifiestamente incompetente por razón de la materia o del territorio.»","Art. 48 Llei 39/2015: «1. Son anulables los actos de la Administración que incurran en cualquier infracción del ordenamiento jurídico, incluso la desviación de poder.»","Art. 53 Llei 39/2015: «a) A conocer, en cualquier momento, el estado de la tramitación de los procedimientos en los que tengan la condición de interesados»","Art. 68 Llei 39/2015: «se requerirá al interesado para que, en un plazo de diez días, subsane la falta o acompañe los documentos preceptivos, con indicación de que, si así no lo hiciera, se le tendrá por desistido de su petición»","Art. 85.3 Llei 39/2015: «el órgano competente para resolver el procedimiento aplicará reducciones de, al menos, el 20 % sobre el importe de la sanción propuesta, siendo éstos acumulables entre sí.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[{"n":"1","title":"Objecte i àmbit de la Llei 39/2015 (títol preliminar)","blocks":[{"text":"La Llei 39/2015, d''1 d''octubre, del procediment administratiu comú de les administracions públiques (LPAC), regula tres grans blocs: els requisits de validesa i eficàcia dels actes administratius, el procediment administratiu comú a totes les administracions (inclosos el sancionador i el de reclamació de responsabilitat patrimonial) i els principis que han de guiar la iniciativa legislativa i la potestat reglamentària (art. 1.1 LPAC). Només una llei, de manera motivada, pot afegir-hi tràmits addicionals o diferents (art. 1.2 LPAC).","refs":[{"ref":"Art. 1.1 LPAC","law":"Llei 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"La presente Ley tiene por objeto regular los requisitos de validez y eficacia de los actos administrativos, el procedimiento administrativo común a todas las Administraciones Públicas, incluyendo el sancionador y el de reclamación de responsabilidad de las Administraciones Públicas, así como los principios a los que se ha de ajustar el ejercicio de la iniciativa legislativa y la potestad reglamentaria."},{"ref":"Art. 1.2 LPAC","law":"Llei 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"Solo mediante ley, cuando resulte eficaz, proporcionado y necesario para la consecución de los fines propios del procedimiento, y de manera motivada, podrán incluirse trámites adicionales o distintos a los contemplados en esta Ley."}]},{"text":"La Llei s''aplica a tot el sector públic: l''Administració General de l''Estat, les administracions autonòmiques, les entitats que integren l''Administració local i el sector públic institucional (art. 2.1 LPAC). Per tant, un ajuntament també hi està sotmès quan tramita un expedient.","refs":[{"ref":"Art. 2.1 LPAC","law":"Llei 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"a) La Administración General del Estado. b) Las Administraciones de las Comunidades Autónomas. c) Las Entidades que integran la Administración Local. d) El sector público institucional."}]}]},{"n":"2","title":"Els interessats: capacitat d''obrar i concepte d''interessat (arts. 3 i 4)","blocks":[{"text":"Tenen capacitat d''obrar davant les administracions les persones físiques o jurídiques que la tinguin segons les normes civils; els menors d''edat, per exercir i defensar els drets i interessos que l''ordenament els permet exercir sense l''assistència de qui en tingui la pàtria potestat, tutela o curatela; i, quan una llei ho declari expressament, els grups d''afectats, les unions i entitats sense personalitat jurídica i els patrimonis independents o autònoms (art. 3 LPAC).","refs":[{"ref":"Art. 3 LPAC","law":"Llei 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"a) Las personas físicas o jurídicas que ostenten capacidad de obrar con arreglo a las normas civiles. b) Los menores de edad para el ejercicio y defensa de aquellos de sus derechos e intereses cuya actuación esté permitida por el ordenamiento jurídico sin la asistencia de la persona que ejerza la patria potestad, tutela o curatela."},{"ref":"Art. 3.c LPAC","law":"Llei 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"c) Cuando la Ley así lo declare expresamente, los grupos de afectados, las uniones y entidades sin personalidad jurídica y los patrimonios independientes o autónomos."}]},{"text":"L''article 4.1 LPAC defineix tres classes d''interessats: qui promou el procediment com a titular de drets o interessos legítims, individuals o col·lectius; qui, sense haver-lo iniciat, té drets que poden resultar afectats per la decisió; i qui té interessos legítims que poden resultar afectats per la resolució i es persona en el procediment mentre no hi hagi resolució definitiva. En queda fora, doncs, qui només té un interès genèric en la legalitat sense cap dret ni interès legítim afectat. Les associacions representatives d''interessos econòmics i socials són titulars d''interessos legítims col·lectius en els termes que reconegui la llei, i si la condició d''interessat deriva d''una relació jurídica transmissible, el drethavent hi succeeix sigui quin sigui l''estat del procediment (art. 4.2 i 4.3 LPAC).","refs":[{"ref":"Art. 4.1 LPAC","law":"Llei 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"a) Quienes lo promuevan como titulares de derechos o intereses legítimos individuales o colectivos. b) Los que, sin haber iniciado el procedimiento, tengan derechos que puedan resultar afectados por la decisión que en el mismo se adopte. c) Aquellos cuyos intereses legítimos, individuales o colectivos, puedan resultar afectados por la resolución y se personen en el procedimiento en tanto no haya recaído resolución definitiva."},{"ref":"Art. 4.2 i 4.3 LPAC","law":"Llei 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"Las asociaciones y organizaciones representativas de intereses económicos y sociales serán titulares de intereses legítimos colectivos en los términos que la Ley reconozca. […] Cuando la condición de interesado derivase de alguna relación jurídica transmisible, el derecho-habiente sucederá en tal condición cualquiera que sea el estado del procedimiento."}]}]},{"n":"3","title":"Activitat de les administracions: drets de les persones i relació electrònica (arts. 13, 14 i 18)","blocks":[{"text":"Tothom qui té capacitat d''obrar és titular, en les seves relacions amb l''Administració, d''una sèrie de drets (art. 13 LPAC): comunicar-se per un Punt d''Accés General electrònic, ser assistit en l''ús de mitjans electrònics, utilitzar les llengües oficials de la seva comunitat autònoma i ser tractat amb respecte i deferència, entre d''altres.","refs":[{"ref":"Art. 13 LPAC","law":"Llei 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"a) A comunicarse con las Administraciones Públicas a través de un Punto de Acceso General electrónico de la Administración. b) A ser asistidos en el uso de medios electrónicos en sus relaciones con las Administraciones Públicas. c) A utilizar las lenguas oficiales en el territorio de su Comunidad Autónoma"},{"ref":"Art. 13.e LPAC","law":"Llei 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"e) A ser tratados con respeto y deferencia por las autoridades y empleados públicos, que habrán de facilitarles el ejercicio de sus derechos y el cumplimiento de sus obligaciones."}]},{"text":"Les persones físiques poden triar en tot moment si es comuniquen amb l''Administració per mitjans electrònics o no, llevat que hi estiguin obligades, i poden canviar el mitjà triat en qualsevol moment (art. 14.1 LPAC). Estan obligats, en canvi, a relacionar-se electrònicament per a qualsevol tràmit, com a mínim, les persones jurídiques, les entitats sense personalitat jurídica, els professionals amb col·legiació obligatòria en l''exercici de la professió, els representants d''un interessat obligat i els empleats públics per als tràmits que facin per raó de la seva condició (art. 14.2 LPAC). Per reglament es pot estendre l''obligació a determinats col·lectius de persones físiques que tinguin accés acreditat als mitjans electrònics (art. 14.3 LPAC).","refs":[{"ref":"Art. 14.1 LPAC","law":"Llei 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"Las personas físicas podrán elegir en todo momento si se comunican con las Administraciones Públicas para el ejercicio de sus derechos y obligaciones a través de medios electrónicos o no, salvo que estén obligadas a relacionarse a través de medios electrónicos con las Administraciones Públicas. El medio elegido por la persona para comunicarse con las Administraciones Públicas podrá ser modificado por aquella en cualquier momento."},{"ref":"Art. 14.2 LPAC","law":"Llei 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"a) Las personas jurídicas. b) Las entidades sin personalidad jurídica. c) Quienes ejerzan una actividad profesional para la que se requiera colegiación obligatoria"},{"ref":"Art. 14.2.e LPAC","law":"Llei 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"e) Los empleados de las Administraciones Públicas para los trámites y actuaciones que realicen con ellas por razón de su condición de empleado público"}]},{"text":"Les persones han de col·laborar amb l''Administració i, si no hi ha previsió expressa, li han de facilitar els informes i les inspeccions que necessiti, excepte si atempten contra l''honor o la intimitat personal o familiar (art. 18.1 LPAC).","refs":[{"ref":"Art. 18.1 LPAC","law":"Llei 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"Las personas colaborarán con la Administración en los términos previstos en la Ley que en cada caso resulte aplicable, y a falta de previsión expresa, facilitarán a la Administración los informes, inspecciones y otros actos de investigación que requieran para el ejercicio de sus competencias, salvo que la revelación de la información solicitada por la Administración atentara contra el honor, la intimidad personal o familiar"}]}]},{"n":"4","title":"Obligació de resoldre i terminis màxims (art. 21)","blocks":[{"text":"L''Administració està obligada a dictar resolució expressa i a notificar-la en tots els procediments, sigui quina sigui la forma d''iniciació (art. 21.1 LPAC). Només se n''exceptuen la terminació per pacte o conveni i els procediments subjectes únicament a declaració responsable o comunicació.","refs":[{"ref":"Art. 21.1 LPAC","law":"Llei 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"1. La Administración está obligada a dictar resolución expresa y a notificarla en todos los procedimientos cualquiera que sea su forma de iniciación."},{"ref":"Art. 21.1 LPAC","law":"Llei 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"Se exceptúan de la obligación a que se refiere el párrafo primero, los supuestos de terminación del procedimiento por pacto o convenio, así como los procedimientos relativos al ejercicio de derechos sometidos únicamente al deber de declaración responsable o comunicación a la Administración."}]},{"text":"El termini màxim per notificar la resolució és el que fixi la norma reguladora de cada procediment, però no pot superar els sis mesos, llevat que una norma amb rang de llei n''estableixi un de més llarg o ho prevegi el dret de la Unió Europea (art. 21.2 LPAC). Si la norma reguladora no fixa cap termini, és de tres mesos (art. 21.3 LPAC). Es compta des de l''acord d''iniciació (d''ofici) o des de l''entrada de la sol·licitud al registre electrònic (a instància de part).","refs":[{"ref":"Art. 21.2 LPAC","law":"Llei 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"El plazo máximo en el que debe notificarse la resolución expresa será el fijado por la norma reguladora del correspondiente procedimiento. Este plazo no podrá exceder de seis meses salvo que una norma con rango de Ley establezca uno mayor o así venga previsto en el Derecho de la Unión Europea."},{"ref":"Art. 21.3 LPAC","law":"Llei 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"3. Cuando las normas reguladoras de los procedimientos no fijen el plazo máximo, éste será de tres meses. Este plazo y los previstos en el apartado anterior se contarán: a) En los procedimientos iniciados de oficio, desde la fecha del acuerdo de iniciación. b) En los iniciados a solicitud del interesado, desde la fecha en que la solicitud haya tenido entrada en el registro electrónico de la Administración u Organismo competente para su tramitación."}]}]},{"n":"5","title":"El silenci administratiu (arts. 24 i 25)","blocks":[{"text":"En els procediments iniciats a sol·licitud de l''interessat, si venç el termini màxim sense resolució expressa notificada, la regla general és el silenci positiu: l''interessat pot entendre estimada la sol·licitud, excepte si una norma amb rang de llei, una norma de dret de la Unió Europea o de dret internacional aplicable a Espanya disposen el contrari (art. 24.1 LPAC). El silenci és, en canvi, desestimatori en els procediments sobre el dret de petició de l''article 29 de la Constitució, en els que transfereixen facultats sobre el domini públic o el servei públic, en els que impliquen activitats que puguin danyar el medi ambient, en els de responsabilitat patrimonial i en els d''impugnació d''actes i disposicions i de revisió d''ofici a instància de part.","refs":[{"ref":"Art. 24.1 LPAC","law":"Llei 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"el vencimiento del plazo máximo sin haberse notificado resolución expresa, legitima al interesado o interesados para entenderla estimada por silencio administrativo, excepto en los supuestos en los que una norma con rango de ley o una norma de Derecho de la Unión Europea o de Derecho internacional aplicable en España establezcan lo contrario."},{"ref":"Art. 24.1 LPAC","law":"Llei 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"El silencio tendrá efecto desestimatorio en los procedimientos relativos al ejercicio del derecho de petición, a que se refiere el artículo 29 de la Constitución, aquellos cuya estimación tuviera como consecuencia que se transfirieran al solicitante o a terceros facultades relativas al dominio público o al servicio público, impliquen el ejercicio de actividades que puedan dañar el medio ambiente y en los procedimientos de responsabilidad patrimonial de las Administraciones Públicas."}]},{"text":"Hi ha una excepció important dins dels recursos: si s''ha interposat un recurs d''alçada contra una desestimació per silenci i l''òrgan no resol ni notifica dins de termini, el recurs s''entén estimat, sempre que no es tracti de les matèries de silenci negatiu (art. 24.1, tercer paràgraf, LPAC). L''estimació per silenci és un acte administratiu que posa fi al procediment, mentre que la desestimació per silenci només serveix per poder interposar el recurs que pertoqui (art. 24.2 LPAC). Si després de l''estimació per silenci es dicta resolució expressa, només pot ser confirmatòria (art. 24.3.a LPAC).","refs":[{"ref":"Art. 24.1 LPAC","law":"Llei 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"No obstante, cuando el recurso de alzada se haya interpuesto contra la desestimación por silencio administrativo de una solicitud por el transcurso del plazo, se entenderá estimado el mismo si, llegado el plazo de resolución, el órgano administrativo competente no dictase y notificase resolución expresa, siempre que no se refiera a las materias enumeradas en el párrafo anterior de este apartado."},{"ref":"Art. 24.2 i 24.3.a LPAC","law":"Llei 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"La estimación por silencio administrativo tiene a todos los efectos la consideración de acto administrativo finalizador del procedimiento. La desestimación por silencio administrativo tiene los solos efectos de permitir a los interesados la interposición del recurso administrativo o contencioso-administrativo que resulte procedente. […] a) En los casos de estimación por silencio administrativo, la resolución expresa posterior a la producción del acto sólo podrá dictarse de ser confirmatoria del mismo."}]},{"text":"En els procediments iniciats d''ofici, el venciment del termini no eximeix de resoldre: si se''n podien derivar drets o situacions favorables, els interessats compareguts poden entendre desestimades les pretensions; si l''Administració exercia potestats sancionadores o d''intervenció desfavorables, es produeix la caducitat i s''arxiven les actuacions (art. 25.1 LPAC).","refs":[{"ref":"Art. 25.1 LPAC","law":"Llei 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"b) En los procedimientos en que la Administración ejercite potestades sancionadoras o, en general, de intervención, susceptibles de producir efectos desfavorables o de gravamen, se producirá la caducidad. En estos casos, la resolución que declare la caducidad ordenará el archivo de las actuaciones"},{"ref":"Art. 25.1.a LPAC","law":"Llei 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"a) En el caso de procedimientos de los que pudiera derivarse el reconocimiento o, en su caso, la constitución de derechos u otras situaciones jurídicas favorables, los interesados que hubieren comparecido podrán entender desestimadas sus pretensiones por silencio administrativo."}]}]},{"n":"6","title":"Còmput de terminis (art. 30)","blocks":[{"text":"Si la llei o el dret de la Unió Europea no diuen una altra cosa, els terminis per hores són d''hores hàbils, es compten d''hora en hora i de minut en minut des de la notificació o publicació, i no poden durar més de vint-i-quatre hores; si cal més temps, s''han d''expressar en dies (art. 30.1 LPAC). Els terminis per dies s''entenen de dies hàbils, i s''exclouen del còmput els dissabtes, els diumenges i els festius (art. 30.2 LPAC); si una llei els fixa en dies naturals, s''ha de fer constar a la notificació.","refs":[{"ref":"Art. 30.1 LPAC","law":"Llei 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"Los plazos expresados por horas se contarán de hora en hora y de minuto en minuto desde la hora y minuto en que tenga lugar la notificación o publicación del acto de que se trate y no podrán tener una duración superior a veinticuatro horas, en cuyo caso se expresarán en días."},{"ref":"Art. 30.2 LPAC","law":"Llei 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"cuando los plazos se señalen por días, se entiende que éstos son hábiles, excluyéndose del cómputo los sábados, los domingos y los declarados festivos."}]},{"text":"Els terminis en dies es compten a partir de l''endemà de la notificació, la publicació o el silenci (art. 30.3 LPAC). Els fixats en mesos o anys també comencen l''endemà, però acaben el mateix dia del mes o any de venciment en què es va produir la notificació; si aquest dia no existeix, el termini expira l''últim dia del mes (art. 30.4 LPAC). Si l''últim dia és inhàbil, es prorroga al primer dia hàbil següent (art. 30.5 LPAC), i un dia que sigui hàbil al municipi de residència de l''interessat i inhàbil a la seu de l''òrgan, o a l''inrevés, es considera inhàbil en tot cas (art. 30.6 LPAC).","refs":[{"ref":"Art. 30.4 LPAC","law":"Llei 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"El plazo concluirá el mismo día en que se produjo la notificación, publicación o silencio administrativo en el mes o el año de vencimiento. Si en el mes de vencimiento no hubiera día equivalente a aquel en que comienza el cómputo, se entenderá que el plazo expira el último día del mes."},{"ref":"Art. 30.5 i 30.6 LPAC","law":"Llei 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"5. Cuando el último día del plazo sea inhábil, se entenderá prorrogado al primer día hábil siguiente. 6. Cuando un día fuese hábil en el municipio o Comunidad Autónoma en que residiese el interesado, e inhábil en la sede del órgano administrativo, o a la inversa, se considerará inhábil en todo caso."}]}]},{"n":"7","title":"Els actes administratius: producció, motivació i eficàcia (arts. 34, 35 i 39)","blocks":[{"text":"Els actes administratius, d''ofici o a instància de part, els ha de dictar l''òrgan competent seguint els requisits i el procediment establerts, i el seu contingut ha de ser conforme a l''ordenament, determinat i adequat a les finalitats de l''acte (art. 34 LPAC). Cal motivar-los, amb una referència succinta de fets i fonaments de dret, entre d''altres casos, quan limiten drets subjectius o interessos legítims, quan resolen recursos, quan se separen del criteri seguit en actuacions anteriors, quan resolen procediments sancionadors i quan es dicten en exercici de potestats discrecionals (art. 35.1 LPAC).","refs":[{"ref":"Art. 34 LPAC","law":"Llei 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"1. Los actos administrativos que dicten las Administraciones Públicas, bien de oficio o a instancia del interesado, se producirán por el órgano competente ajustándose a los requisitos y al procedimiento establecido. 2. El contenido de los actos se ajustará a lo dispuesto por el ordenamiento jurídico y será determinado y adecuado a los fines de aquéllos."},{"ref":"Art. 35.1 LPAC","law":"Llei 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"Serán motivados, con sucinta referencia de hechos y fundamentos de derecho: a) Los actos que limiten derechos subjetivos o intereses legítimos."},{"ref":"Art. 35.1.h i 35.1.i LPAC","law":"Llei 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"h) Las propuestas de resolución en los procedimientos de carácter sancionador, así como los actos que resuelvan procedimientos de carácter sancionador o de responsabilidad patrimonial. i) Los actos que se dicten en el ejercicio de potestades discrecionales"}]},{"text":"Els actes subjectes al dret administratiu es presumeixen vàlids i produeixen efectes des de la data en què es dicten, llevat que s''hi disposi una altra cosa (art. 39.1 LPAC). L''eficàcia queda ajornada quan està supeditada a la notificació, la publicació o l''aprovació superior, i excepcionalment pot ser retroactiva si l''acte substitueix un d''anul·lat o és favorable a l''interessat (art. 39.2 i 39.3).","refs":[{"ref":"Art. 39.1 LPAC","law":"Llei 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"1. Los actos de las Administraciones Públicas sujetos al Derecho Administrativo se presumirán válidos y producirán efectos desde la fecha en que se dicten, salvo que en ellos se disponga otra cosa."},{"ref":"Art. 39.2 i 39.3 LPAC","law":"Llei 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"La eficacia quedará demorada cuando así lo exija el contenido del acto o esté supeditada a su notificación, publicación o aprobación superior. 3. Excepcionalmente, podrá otorgarse eficacia retroactiva a los actos cuando se dicten en sustitución de actos anulados, así como cuando produzcan efectos favorables al interesado"}]}]},{"n":"8","title":"Invalidesa: nul·litat de ple dret i anul·labilitat (arts. 47 i 48)","blocks":[{"text":"La nul·litat de ple dret és el vici més greu i només es dona en els casos taxats de l''article 47.1 LPAC: actes que lesionen drets i llibertats susceptibles d''empara constitucional; dictats per un òrgan manifestament incompetent per raó de la matèria o del territori; de contingut impossible; constitutius d''infracció penal o dictats com a conseqüència d''aquesta; dictats prescindint total i absolutament del procediment o de les regles essencials de formació de la voluntat dels òrgans col·legiats; actes contraris a l''ordenament pels quals s''adquireixen facultats o drets sense els requisits essencials; i qualsevol altre que estableixi una norma amb rang de llei.","refs":[{"ref":"Art. 47.1 LPAC","law":"Llei 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"a) Los que lesionen los derechos y libertades susceptibles de amparo constitucional. b) Los dictados por órgano manifiestamente incompetente por razón de la materia o del territorio. c) Los que tengan un contenido imposible. d) Los que sean constitutivos de infracción penal o se dicten como consecuencia de ésta."},{"ref":"Art. 47.1.e LPAC","law":"Llei 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"e) Los dictados prescindiendo total y absolutamente del procedimiento legalmente establecido o de las normas que contienen las reglas esenciales para la formación de la voluntad de los órganos colegiados."}]},{"text":"L''anul·labilitat és la regla general: són anul·lables els actes que incorren en qualsevol infracció de l''ordenament jurídic, fins i tot la desviació de poder (art. 48.1 LPAC). Ara bé, el defecte de forma només anul·la l''acte si li falten els requisits formals indispensables per assolir la seva finalitat o si provoca indefensió, i l''actuació fora de termini només l''anul·la quan ho imposa la naturalesa del termini (art. 48.2 i 48.3 LPAC).","refs":[{"ref":"Art. 48 LPAC","law":"Llei 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"1. Son anulables los actos de la Administración que incurran en cualquier infracción del ordenamiento jurídico, incluso la desviación de poder. 2. No obstante, el defecto de forma sólo determinará la anulabilidad cuando el acto carezca de los requisitos formales indispensables para alcanzar su fin o dé lugar a la indefensión de los interesados."},{"ref":"Art. 48.3 LPAC","law":"Llei 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"La realización de actuaciones administrativas fuera del tiempo establecido para ellas sólo implicará la anulabilidad del acto cuando así lo imponga la naturaleza del término o plazo."}]}]},{"n":"9","title":"Drets de l''interessat en el procediment (art. 53)","blocks":[{"text":"A més dels drets generals de l''article 13, els interessats en un procediment tenen dret, entre d''altres, a conèixer en qualsevol moment l''estat de la tramitació, el sentit del silenci si no es resol en termini, l''òrgan competent per instruir i resoldre i els actes de tràmit dictats, i a obtenir còpia dels documents (art. 53.1.a LPAC); a formular al·legacions i aportar documents en qualsevol fase anterior al tràmit d''audiència; i a actuar assistits d''assessor (art. 53.1 LPAC).","refs":[{"ref":"Art. 53.1.a LPAC","law":"Llei 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"a) A conocer, en cualquier momento, el estado de la tramitación de los procedimientos en los que tengan la condición de interesados; el sentido del silencio administrativo que corresponda, en caso de que la Administración no dicte ni notifique resolución expresa en plazo; el órgano competente para su instrucción, en su caso, y resolución; y los actos de trámite dictados."},{"ref":"Art. 53.1.e i 53.1.g LPAC","law":"Llei 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"e) A formular alegaciones, utilizar los medios de defensa admitidos por el Ordenamiento Jurídico, y a aportar documentos en cualquier fase del procedimiento anterior al trámite de audiencia […] g) A actuar asistidos de asesor cuando lo consideren conveniente en defensa de sus intereses."}]},{"text":"En els procediments sancionadors, el presumpte responsable té, a més, dret a ser notificat dels fets imputats, de les infraccions i sancions possibles, de la identitat de l''instructor i de l''autoritat competent, i a la presumpció de no-existència de responsabilitat administrativa mentre no es demostri el contrari (art. 53.2 LPAC).","refs":[{"ref":"Art. 53.2 LPAC","law":"Llei 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"a) A ser notificado de los hechos que se le imputen, de las infracciones que tales hechos puedan constituir y de las sanciones que, en su caso, se les pudieran imponer, así como de la identidad del instructor, de la autoridad competente para imponer la sanción y de la norma que atribuya tal competencia. b) A la presunción de no existencia de responsabilidad administrativa mientras no se demuestre lo contrario."}]}]},{"n":"10","title":"Esmena de la sol·licitud i terminació del procediment (arts. 68, 84 i 85)","blocks":[{"text":"Si una sol·licitud no reuneix els requisits exigits, s''ha de requerir l''interessat perquè l''esmeni o hi adjunti els documents preceptius en un termini de deu dies, advertint-lo que, si no ho fa, se''l tindrà per desistit de la petició, prèvia resolució (art. 68.1 LPAC). Fora dels procediments selectius o de concurrència competitiva, el termini es pot ampliar fins a cinc dies més quan aportar els documents sigui especialment difícil (art. 68.2 LPAC).","refs":[{"ref":"Art. 68.1 LPAC","law":"Llei 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"se requerirá al interesado para que, en un plazo de diez días, subsane la falta o acompañe los documentos preceptivos, con indicación de que, si así no lo hiciera, se le tendrá por desistido de su petición, previa resolución que deberá ser dictada en los términos previstos en el artículo 21."},{"ref":"Art. 68.2 LPAC","law":"Llei 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"Siempre que no se trate de procedimientos selectivos o de concurrencia competitiva, este plazo podrá ser ampliado prudencialmente, hasta cinco días, a petición del interesado o a iniciativa del órgano, cuando la aportación de los documentos requeridos presente dificultades especiales."}]},{"text":"Posen fi al procediment la resolució, el desistiment, la renúncia al dret (si no està prohibida), la declaració de caducitat i la impossibilitat material de continuar-lo per causes sobrevingudes (art. 84 LPAC). En el procediment sancionador, si l''infractor reconeix la responsabilitat es pot resoldre imposant la sanció; i si la sanció és només pecuniària, el pagament voluntari abans de la resolució també posa fi al procediment (art. 85.1 i 85.2 LPAC). En tots dos casos, amb sanció únicament pecuniària, s''apliquen reduccions d''almenys el 20 % sobre l''import proposat, acumulables entre si, que han de constar a la notificació d''inici i que queden condicionades al desistiment o la renúncia de qualsevol acció o recurs en via administrativa (art. 85.3 LPAC).","refs":[{"ref":"Art. 84.1 LPAC","law":"Llei 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"Pondrán fin al procedimiento la resolución, el desistimiento, la renuncia al derecho en que se funde la solicitud, cuando tal renuncia no esté prohibida por el ordenamiento jurídico, y la declaración de caducidad."},{"ref":"Art. 85.1 LPAC","law":"Llei 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"Iniciado un procedimiento sancionador, si el infractor reconoce su responsabilidad, se podrá resolver el procedimiento con la imposición de la sanción que proceda."},{"ref":"Art. 85.3 LPAC","law":"Llei 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"el órgano competente para resolver el procedimiento aplicará reducciones de, al menos, el 20 % sobre el importe de la sanción propuesta, siendo éstos acumulables entre sí. Las citadas reducciones, deberán estar determinadas en la notificación de iniciación del procedimiento y su efectividad estará condicionada al desistimiento o renuncia de cualquier acción o recurso en vía administrativa contra la sanción."}]}]},{"n":"11","title":"Recursos administratius: alçada i reposició (arts. 112 i 121-124)","blocks":[{"text":"Es poden recórrer en alçada o en reposició potestativa les resolucions i també els actes de tràmit qualificats, és a dir, els que decideixen directament o indirectament el fons de l''assumpte, impedeixen continuar el procediment o produeixen indefensió o perjudici irreparable; el recurs es pot fundar en qualsevol causa de nul·litat o anul·labilitat (art. 112.1 LPAC).","refs":[{"ref":"Art. 112.1 LPAC","law":"Llei 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"Contra las resoluciones y los actos de trámite, si estos últimos deciden directa o indirectamente el fondo del asunto, determinan la imposibilidad de continuar el procedimiento, producen indefensión o perjuicio irreparable a derechos e intereses legítimos, podrán interponerse por los interesados los recursos de alzada y potestativo de reposición"}]},{"text":"El recurs d''alçada procedeix contra els actes que no posen fi a la via administrativa i es resol per l''òrgan superior jeràrquic del que els va dictar; es pot presentar davant de l''un o de l''altre (art. 121 LPAC). El termini per interposar-lo és d''un mes si l''acte és exprés; passat aquest termini, la resolució és ferma; si l''acte no és exprés, es pot interposar en qualsevol moment a partir de l''endemà que es produeixin els efectes del silenci (art. 122.1 LPAC). El termini màxim per resoldre i notificar és de tres mesos; transcorregut aquest termini, el recurs es pot entendre desestimat, llevat del supòsit del tercer paràgraf de l''article 24.1, i contra la resolució de l''alçada només hi cap el recurs extraordinari de revisió (art. 122.2 i 122.3 LPAC).","refs":[{"ref":"Art. 121.1 LPAC","law":"Llei 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"Las resoluciones y actos a que se refiere el artículo 112.1, cuando no pongan fin a la vía administrativa, podrán ser recurridos en alzada ante el órgano superior jerárquico del que los dictó."},{"ref":"Art. 122 LPAC","law":"Llei 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"1. El plazo para la interposición del recurso de alzada será de un mes, si el acto fuera expreso. Transcurrido dicho plazo sin haberse interpuesto el recurso, la resolución será firme a todos los efectos. […] 2. El plazo máximo para dictar y notificar la resolución será de tres meses. Transcurrido este plazo sin que recaiga resolución, se podrá entender desestimado el recurso, salvo en el supuesto previsto en el artículo 24.1, tercer párrafo. 3. Contra la resolución de un recurso de alzada no cabrá ningún otro recurso administrativo, salvo el recurso extraordinario de revisión"}]},{"text":"El recurs de reposició és potestatiu: els actes que posen fi a la via administrativa es poden recórrer en reposició davant el mateix òrgan que els va dictar o impugnar directament davant la jurisdicció contenciosa administrativa, però si s''opta per la reposició no es pot anar al contenciós fins que es resolgui o es desestimi per silenci (art. 123 LPAC). El termini d''interposició és d''un mes si l''acte és exprés i el de resolució també és d''un mes, i contra la resolució d''un recurs de reposició no se''n pot tornar a interposar un altre (art. 124 LPAC).","refs":[{"ref":"Art. 123 LPAC","law":"Llei 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"1. Los actos administrativos que pongan fin a la vía administrativa podrán ser recurridos potestativamente en reposición ante el mismo órgano que los hubiera dictado o ser impugnados directamente ante el orden jurisdiccional contencioso-administrativo. 2. No se podrá interponer recurso contencioso-administrativo hasta que sea resuelto expresamente o se haya producido la desestimación presunta del recurso de reposición interpuesto."},{"ref":"Art. 124 LPAC","law":"Llei 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"1. El plazo para la interposición del recurso de reposición será de un mes, si el acto fuera expreso. […] 2. El plazo máximo para dictar y notificar la resolución del recurso será de un mes. 3. Contra la resolución de un recurso de reposición no podrá interponerse de nuevo dicho recurso."}]}]},{"n":"R","title":"Recorda per a l''examen","blocks":[{"text":"Les persones jurídiques sempre estan obligades a relacionar-se electrònicament; les físiques poden triar i canviar de mitjà.","refs":[{"ref":"Art. 14.2.a LPAC","law":"Llei 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"estarán obligados a relacionarse a través de medios electrónicos con las Administraciones Públicas para la realización de cualquier trámite de un procedimiento administrativo, al menos, los siguientes sujetos: a) Las personas jurídicas."}]},{"text":"Termini màxim per resoldre: el de la norma reguladora, sense passar de sis mesos (llevat de llei o dret UE); si no se''n fixa cap, tres mesos.","refs":[{"ref":"Art. 21.3 LPAC","law":"Llei 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"Cuando las normas reguladoras de los procedimientos no fijen el plazo máximo, éste será de tres meses."}]},{"text":"Silenci a instància de part: positiu com a regla general; negatiu en el dret de petició (art. 29 CE), domini o servei públic, medi ambient i responsabilitat patrimonial.","refs":[{"ref":"Art. 24.1 LPAC","law":"Llei 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"legitima al interesado o interesados para entenderla estimada por silencio administrativo"}]},{"text":"Terminis en dies: hàbils, sense dissabtes, diumenges ni festius. Terminis en hores: màxim vint-i-quatre.","refs":[{"ref":"Art. 30.2 LPAC","law":"Llei 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"excluyéndose del cómputo los sábados, los domingos y los declarados festivos."}]},{"text":"L''òrgan manifestament incompetent per raó de matèria o territori produeix nul·litat de ple dret; la desviació de poder, anul·labilitat.","refs":[{"ref":"Art. 47.1.b LPAC","law":"Llei 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"b) Los dictados por órgano manifiestamente incompetente por razón de la materia o del territorio."}]},{"text":"Esmena de la sol·licitud: deu dies, amb advertiment de desistiment.","refs":[{"ref":"Art. 68.1 LPAC","law":"Llei 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"en un plazo de diez días, subsane la falta o acompañe los documentos preceptivos"}]},{"text":"Reconeixement de responsabilitat i pagament voluntari: reduccions d''almenys el 20 % cadascuna, acumulables.","refs":[{"ref":"Art. 85.3 LPAC","law":"Llei 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"reducciones de, al menos, el 20 % sobre el importe de la sanción propuesta, siendo éstos acumulables entre sí."}]},{"text":"Alçada: un mes per interposar i tres mesos per resoldre. Reposició: un mes i un mes, i no se''n pot interposar una segona.","refs":[{"ref":"Art. 122.1 LPAC","law":"Llei 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"El plazo para la interposición del recurso de alzada será de un mes, si el acto fuera expreso."}]}]}]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565'), 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565', null, null, null, null
