insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, lessons, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"Forces i cossos de seguretat i competència de l''Estat (arts. 1 i 2)"},{"n":"2","title":"Principis bàsics d''actuació (art. 5)"},{"n":"3","title":"Formació, retribució i règim disciplinari (arts. 6, 7 i 8)"},{"n":"4","title":"Forces i cossos de seguretat de l''Estat (arts. 9 i 11)"},{"n":"5","title":"Policia judicial (art. 29)"},{"n":"6","title":"Policies locals: naturalesa i funcions (arts. 51 i 53)"},{"n":"7","title":"Juntes locals de seguretat (art. 54)"}]'::jsonb, '["Art. 1 LO 2/1986: «1. La Seguridad Pública es competencia exclusiva del Estado. Su mantenimiento corresponde al Gobierno de la Nación.»","Art. 1.3 LO 2/1986: «3. Las Corporaciones Locales participarán en el mantenimiento de la seguridad pública en los términos establecidos en la Ley Reguladora de las Bases de Régimen Local y en el marco de esta Ley.»","Art. 2 LO 2/1986: «Son Fuerzas y Cuerpos de Seguridad: a) Las Fuerzas y Cuerpos de Seguridad del Estado dependientes del Gobierno de la Nación. b) Los Cuerpos de Policía dependientes de las Comunidades Autónomas. c) Los Cuerpos de Policía dependientes de las Corporaciones Locales.»","Art. 5.1 LO 2/1986: «b) Actuar, en el cumplimiento de sus funciones, con absoluta neutralidad política e imparcialidad y, en consecuencia, sin discriminación alguna por razón de raza, religión u opinión.»","Art. 5.2.c LO 2/1986: «rigiéndose al hacerlo por los principios de congruencia, oportunidad y proporcionalidad en la utilización de los medios a su alcance.»","Art. 5.3 LO 2/1986: «a) Los miembros de las Fuerzas y Cuerpos de Seguridad deberán identificarse debidamente como tales en el momento de efectuar una detención.»","Art. 5.4 LO 2/1986: «Deberán llevar a cabo sus funciones con total dedicación, debiendo intervenir siempre, en cualquier tiempo y lugar, se hallaren o no de servicio, en defensa de la Ley y de la seguridad ciudadana.»","Art. 5.5 LO 2/1986: «No estarán obligados a revelar las fuentes de información salvo que el ejercicio de sus funciones o las disposiciones de la Ley les impongan actuar de otra manera.»","Art. 5.6 LO 2/1986: «Son responsables personal y directamente por los actos que en su actuación profesional llevaren a cabo»","Art. 6.3 LO 2/1986: «3. Los miembros de las Fuerzas y Cuerpos de Seguridad deberán jurar o prometer acatamiento a la Constitución como norma fundamental del Estado.»","Art. 7 LO 2/1986: «tendrán al efecto de su protección penal la consideración de autoridad.»","Art. 8 LO 2/1986: «1. La jurisdicción ordinaria será la competente para conocer de los delitos que se cometan contra miembros de las Fuerzas y Cuerpos de Seguridad, así como de los cometidos por éstos en el ejercicio de sus funciones.»","Art. 9 LO 2/1986: «b) La Guardia Civil, que es un Instituto Armado de naturaleza militar»","Art. 11.2 LO 2/1986: «a) Corresponde al Cuerpo Nacional de Policía ejercitar dichas funciones en las capitales de provincia y en los términos municipales y núcleos urbanos que el Gobierno determine.»","Art. 29.2 LO 2/1986: «tendrán carácter colaborador de las Fuerzas y Cuerpos de Seguridad del Estado el personal de Policía de las Comunidades Autónomas y de las Corporaciones Locales.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[{"n":"1","title":"La seguretat pública, competència de l''Estat, i les forces i cossos de seguretat (arts. 1 a 4)","blocks":[{"text":"La Llei orgànica 2/1986, de 13 de març, de forces i cossos de seguretat (LOFCS), parteix d''una idea clau: la seguretat pública és competència exclusiva de l''Estat i el seu manteniment correspon al Govern de la Nació (art. 1.1 LOFCS). Això no exclou les altres administracions: les comunitats autònomes hi participen en els termes dels seus estatuts i en el marc d''aquesta Llei, i les corporacions locals hi participen en els termes de la Llei reguladora de les bases del règim local i també en el marc de la LOFCS (art. 1.2 i 1.3). En tots els casos, el manteniment de la seguretat pública s''exerceix per mitjà de les forces i cossos de seguretat (art. 1.4).","refs":[{"ref":"Art. 1 LOFCS","law":"LO 2/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859","quote":"1. La Seguridad Pública es competencia exclusiva del Estado. Su mantenimiento corresponde al Gobierno de la Nación. 2. Las Comunidades Autónomas participarán en el mantenimiento de la Seguridad Pública en los términos que establezcan los respectivos Estatutos y en el marco de esta Ley. 3. Las Corporaciones Locales participarán en el mantenimiento de la seguridad pública en los términos establecidos en la Ley Reguladora de las Bases de Régimen Local y en el marco de esta Ley."},{"ref":"Art. 1.4 LOFCS","law":"LO 2/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859","quote":"El mantenimiento de la Seguridad Pública se ejercerá por las distintas Administraciones Públicas a través de las Fuerzas y Cuerpos de Seguridad."}]},{"text":"Els membres de les forces i cossos de seguretat s''han de regir pel principi de cooperació recíproca, i la seva coordinació es fa pels òrgans que crea la Llei (art. 3 LOFCS). Al seu torn, tothom té el deure de prestar-los l''auxili necessari en la investigació i persecució dels delictes, i les persones i entitats que fan funcions de vigilància, seguretat o custòdia tenen una obligació especial de col·laborar-hi en tot moment (art. 4 LOFCS).","refs":[{"ref":"Art. 3 LOFCS","law":"LO 2/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859","quote":"Los miembros de las Fuerzas y Cuerpos de Seguridad ajustarán su actuación al principio de cooperación recíproca y su coordinación se efectuará a través de los órganos que a tal efecto establece esta Ley."},{"ref":"Art. 4 LOFCS","law":"LO 2/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859","quote":"1. Todos tienen el deber de prestar a las Fuerzas y Cuerpos de Seguridad el auxilio necesario en la investigación y persecución de los delitos en los términos previstos legalmente. 2. Las personas y entidades que ejerzan funciones de vigilancia, seguridad o custodia referidas a personal y bienes o servicios de titularidad pública o privada tienen especial obligación de auxiliar o colaborar en todo momento con las Fuerzas y Cuerpos de Seguridad."}]},{"text":"L''article 2 LOFCS fa una enumeració tancada de tres grups: les forces i cossos de seguretat de l''Estat, que depenen del Govern de la Nació; els cossos de policia que depenen de les comunitats autònomes (a Catalunya, la Policia de la Generalitat-Mossos d''Esquadra); i els cossos de policia que depenen de les corporacions locals, és a dir, les policies locals. Les Forces Armades no hi són incloses.","refs":[{"ref":"Art. 2 LOFCS","law":"LO 2/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859","quote":"Son Fuerzas y Cuerpos de Seguridad: a) Las Fuerzas y Cuerpos de Seguridad del Estado dependientes del Gobierno de la Nación. b) Los Cuerpos de Policía dependientes de las Comunidades Autónomas. c) Los Cuerpos de Policía dependientes de las Corporaciones Locales."}]}]},{"n":"2","title":"Principis bàsics d''actuació (I): adequació a l''ordenament jurídic (art. 5.1)","blocks":[{"text":"L''article 5 LOFCS conté els principis bàsics d''actuació comuns a tots els cossos, agrupats en sis blocs. El primer és l''adequació a l''ordenament jurídic, que inclou: exercir la funció amb respecte absolut a la Constitució i a la resta de l''ordenament; actuar amb absoluta neutralitat política i imparcialitat, sense cap discriminació per raó de raça, religió o opinió; actuar amb integritat i dignitat, abstenint-se de tot acte de corrupció i oposant-s''hi resoltament; i col·laborar amb l''Administració de justícia i auxiliar-la (art. 5.1 LOFCS).","refs":[{"ref":"Art. 5.1 LOFCS","law":"LO 2/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859","quote":"a) Ejercer su función con absoluto respeto a la Constitución y al resto del ordenamiento jurídico. b) Actuar, en el cumplimiento de sus funciones, con absoluta neutralidad política e imparcialidad y, en consecuencia, sin discriminación alguna por razón de raza, religión u opinión. c) Actuar con integridad y dignidad. En particular, deberán abstenerse de todo acto de corrupción y oponerse a él resueltamente."},{"ref":"Art. 5.1.e LOFCS","law":"LO 2/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859","quote":"e) Colaborar con la Administración de Justicia y auxiliarla en los términos establecidos en la Ley."}]},{"text":"Dins d''aquest mateix bloc hi ha els principis de jerarquia i subordinació, amb un límit essencial: l''obediència deguda no pot emparar mai ordres que comportin executar actes manifestament delictius o contraris a la Constitució o a les lleis (art. 5.1.d LOFCS).","refs":[{"ref":"Art. 5.1.d LOFCS","law":"LO 2/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859","quote":"d) Sujetarse en su actuación profesional, a los principios de jerarquía y subordinación. En ningún caso, la obediencia debida podrá amparar órdenes que entrañen la ejecución de actos que manifiestamente constituyan delito o sean contrarios a la Constitución o a las Leyes."}]}]},{"n":"3","title":"Principis bàsics d''actuació (II): relacions amb la comunitat (art. 5.2)","blocks":[{"text":"En les relacions amb la comunitat, els agents han d''impedir qualsevol pràctica abusiva, arbitrària o discriminatòria que comporti violència física o moral, i han de mantenir un tracte correcte i acurat amb els ciutadans, a qui han d''auxiliar i protegir quan les circumstàncies ho aconsellin o se''ls requereixi, i informar de manera completa sobre les causes i la finalitat de les seves intervencions (art. 5.2.a i 5.2.b LOFCS).","refs":[{"ref":"Art. 5.2.a i 5.2.b LOFCS","law":"LO 2/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859","quote":"a) Impedir, en el ejercicio de su actuación profesional, cualquier práctica abusiva, arbitraria o discriminatoria que entrañe violencia física o moral. b) Observar en todo momento un trato correcto y esmerado en sus relaciones con los ciudadanos, a quienes procurarán auxiliar y proteger, siempre que las circunstancias lo aconsejen o fueren requeridos para ello."}]},{"text":"Quan cal evitar un dany greu, immediat i irreparable, han d''actuar amb la decisió necessària i sense demora, regint-se pels principis de congruència, oportunitat i proporcionalitat en l''ús dels mitjans al seu abast (art. 5.2.c LOFCS). Les armes només es poden fer servir en situacions de risc racionalment greu per a la vida o la integritat física pròpia o de terceres persones, o en circumstàncies que puguin suposar un risc greu per a la seguretat ciutadana, i sempre d''acord amb aquests mateixos principis (art. 5.2.d LOFCS).","refs":[{"ref":"Art. 5.2.c LOFCS","law":"LO 2/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859","quote":"c) En el ejercicio de sus funciones deberán actuar con la decisión necesaria, y sin demora cuando de ello dependa evitar un daño grave, inmediato e irreparable; rigiéndose al hacerlo por los principios de congruencia, oportunidad y proporcionalidad en la utilización de los medios a su alcance."},{"ref":"Art. 5.2.d LOFCS","law":"LO 2/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859","quote":"d) Solamente deberán utilizar las armas en las situaciones en que exista un riesgo racionalmente grave para su vida, su integridad física o las de terceras personas, o en aquellas circunstancias que puedan suponer un grave riesgo para la seguridad ciudadana y de conformidad con los principios a que se refiere el apartado anterior."}]}]},{"n":"4","title":"Principis bàsics d''actuació (III): detinguts, dedicació, secret i responsabilitat (art. 5.3 a 5.6)","blocks":[{"text":"En el tractament de detinguts, els agents s''han d''identificar degudament com a tals en el moment de fer una detenció; han de vetllar per la vida i la integritat física de les persones detingudes o sota custòdia i respectar-ne l''honor i la dignitat; i han de complir amb diligència els tràmits, terminis i requisits que exigeix l''ordenament quan detenen una persona (art. 5.3 LOFCS).","refs":[{"ref":"Art. 5.3 LOFCS","law":"LO 2/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859","quote":"a) Los miembros de las Fuerzas y Cuerpos de Seguridad deberán identificarse debidamente como tales en el momento de efectuar una detención. b) Velarán por la vida e integridad física de las personas a quienes detuvieren o que se encuentren bajo su custodia y respetarán el honor y la dignidad de las personas."}]},{"text":"El principi de dedicació professional obliga a exercir les funcions amb dedicació total i a intervenir sempre, en qualsevol temps i lloc, estiguin o no de servei, en defensa de la llei i de la seguretat ciutadana (art. 5.4 LOFCS). Pel secret professional, han de guardar un secret rigorós sobre la informació que coneguin per raó del càrrec, i no estan obligats a revelar les fonts d''informació, llevat que l''exercici de les funcions o la llei els imposin actuar d''una altra manera (art. 5.5 LOFCS).","refs":[{"ref":"Art. 5.4 LOFCS","law":"LO 2/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859","quote":"Deberán llevar a cabo sus funciones con total dedicación, debiendo intervenir siempre, en cualquier tiempo y lugar, se hallaren o no de servicio, en defensa de la Ley y de la seguridad ciudadana."},{"ref":"Art. 5.5 LOFCS","law":"LO 2/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859","quote":"Deberán guardar riguroso secreto respecto a todas las informaciones que conozcan por razón o con ocasión del desempeño de sus funciones. No estarán obligados a revelar las fuentes de información salvo que el ejercicio de sus funciones o las disposiciones de la Ley les impongan actuar de otra manera."}]},{"text":"Finalment, els agents són responsables personalment i directament dels actes que, en la seva actuació professional, infringeixin les normes legals i reglamentàries o els principis anteriors, sens perjudici de la responsabilitat patrimonial que pugui correspondre a les administracions públiques (art. 5.6 LOFCS).","refs":[{"ref":"Art. 5.6 LOFCS","law":"LO 2/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859","quote":"Son responsables personal y directamente por los actos que en su actuación profesional llevaren a cabo, infringiendo o vulnerando las normas legales, así como las reglamentarias que rijan su profesión y los principios enunciados anteriormente, sin perjuicio de la responsabilidad patrimonial que pueda corresponder a las Administraciones Públicas por las mismas."}]}]},{"n":"5","title":"Formació, jurament, retribució, incompatibilitats i vaga (art. 6)","blocks":[{"text":"Els poders públics han de promoure la promoció professional, social i humana dels agents d''acord amb els principis d''objectivitat, igualtat d''oportunitats, mèrit i capacitat (art. 6.1 LOFCS). La formació s''ha d''adequar als principis de l''article 5 i ha de tenir caràcter professional i permanent (art. 6.2). Tots els membres de les forces i cossos de seguretat han de jurar o prometre acatament a la Constitució com a norma fonamental de l''Estat (art. 6.3).","refs":[{"ref":"Art. 6.2.a LOFCS","law":"LO 2/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859","quote":"La formación y perfeccionamiento de los miembros de las Fuerzas y Cuerpos de Seguridad se adecuará a los principios señalados en el artículo 5.º y se ajustarán a los siguientes criterios: a) Tendrá carácter profesional y permanente."},{"ref":"Art. 6.3 LOFCS","law":"LO 2/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859","quote":"3. Los miembros de las Fuerzas y Cuerpos de Seguridad deberán jurar o prometer acatamiento a la Constitución como norma fundamental del Estado."}]},{"text":"Tenen dret a una remuneració justa que tingui en compte la formació, les incompatibilitats, la mobilitat, la dedicació i el risc de la missió (art. 6.4). La pertinença a un cos és incompatible amb qualsevol altra activitat pública o privada, llevat de les exceptuades per la legislació d''incompatibilitats (art. 6.7), i no poden exercir en cap cas el dret de vaga ni accions substitutives o concertades per alterar el funcionament normal dels serveis (art. 6.8). El règim disciplinari s''ha d''inspirar en l''estructura jerarquitzada i disciplinada dels cossos (art. 6.9).","refs":[{"ref":"Art. 6.7 i 6.8 LOFCS","law":"LO 2/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859","quote":"7. La pertenencia a las fuerzas y Cuerpos de Seguridad es causa de incompatibilidad para el desempeño de cualquier otra actividad pública o privada, salvo aquellas actividades exceptuadas de la legislación sobre incompatibilidades. 8. Los miembros de las Fuerzas y Cuerpos de Seguridad no podrán ejercer en ningún caso el derecho de huelga, ni acciones sustitutivas del mismo o concertadas con el fin de alterar el normal funcionamiento de los servicios."},{"ref":"Art. 6.9 LOFCS","law":"LO 2/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859","quote":"El régimen disciplinario, sin perjuicio de la observancia de las debidas garantías, estará inspirado en unos principios acordes con la misión fundamental que la Constitución les atribuye y con la estructura y organización jerarquizada y disciplinada propias de los mismos."}]}]},{"n":"6","title":"Condició d''agent de l''autoritat i jurisdicció competent (arts. 7 i 8)","blocks":[{"text":"En l''exercici de les funcions, els membres de les forces i cossos de seguretat tenen a tots els efectes legals el caràcter d''agents de l''autoritat (art. 7.1 LOFCS). Excepcionalment, a l''efecte de la seva protecció penal tenen la consideració d''autoritat quan es comet contra ells un delicte d''atemptat amb armes de foc, explosius o altres mitjans d''agressió d''una perillositat anàloga que puguin posar en perill greu la seva integritat física (art. 7.2 LOFCS).","refs":[{"ref":"Art. 7 LOFCS","law":"LO 2/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859","quote":"1. En el ejercicio de sus funciones, los miembros de las Fuerzas y Cuerpos de Seguridad tendrán a todos los efectos legales el carácter de agentes de la autoridad. 2. Cuando se cometa delito de atentado, empleando en su ejecución armas de fuego, explosivos u otros medios de agresión de análoga peligrosidad, que puedan poner en peligro grave la integridad física de los miembros de las Fuerzas y Cuerpos de Seguridad, tendrán al efecto de su protección penal la consideración de autoridad."}]},{"text":"La jurisdicció ordinària és la competent per conèixer dels delictes comesos contra els agents i dels que cometin ells en l''exercici de les funcions, llevat dels supòsits en què sigui competent la jurisdicció militar (art. 8.1 LOFCS). Atenció: el segon paràgraf de l''article 8.1, que atribuïa la instrucció a l''Audiència Provincial, va ser declarat inconstitucional i nul per la STC 55/1990, com adverteix el text consolidat. La presó preventiva i les penes privatives de llibertat dels agents es compleixen en establiments ordinaris, separats de la resta d''interns (art. 8.2), i el procediment penal no impedeix tramitar l''expedient disciplinari pels mateixos fets, tot i que la resolució definitiva ha d''esperar la sentència penal ferma (art. 8.3).","refs":[{"ref":"Art. 8.1 LOFCS","law":"LO 2/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859","quote":"1. La jurisdicción ordinaria será la competente para conocer de los delitos que se cometan contra miembros de las Fuerzas y Cuerpos de Seguridad, así como de los cometidos por éstos en el ejercicio de sus funciones. […] Se exceptúa de lo dispuesto en los párrafos anteriores los supuestos en que sea competente la jurisdicción militar."},{"ref":"Nota del BOE a l''art. 8.1 LOFCS","law":"LO 2/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859","quote":"Téngase en cuenta que se declara inconstitucional y nulo el párrafo segundo del apartado 1"},{"ref":"Art. 8.3 LOFCS","law":"LO 2/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859","quote":"La iniciación de procedimiento penal contra miembros de las Fuerzas y Cuerpos de Seguridad, no impedirá la incoación y tramitación de expedientes gubernativos o disciplinarios por los mismos hechos. No obstante, la resolución definitiva del expediente sólo podrá producirse cuando la sentencia recaída en el ámbito penal sea firme"}]}]},{"n":"7","title":"Les forces i cossos de seguretat de l''Estat (arts. 9 i 11)","blocks":[{"text":"Les forces i cossos de seguretat de l''Estat actuen a tot el territori nacional i les integren el Cos Nacional de Policia, institut armat de naturalesa civil que depèn del ministre de l''Interior, i la Guàrdia Civil, institut armat de naturalesa militar, que depèn del ministre de l''Interior en les funcions que li atribueix la Llei i del ministre de Defensa en les missions de caràcter militar; en temps de guerra i durant l''estat de setge depèn exclusivament de Defensa (art. 9 LOFCS).","refs":[{"ref":"Art. 9 LOFCS","law":"LO 2/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859","quote":"a) El Cuerpo Nacional de Policía, que es un Instituto Armado de naturaleza civil, dependiente del Ministro del Interior. b) La Guardia Civil, que es un Instituto Armado de naturaleza militar, dependiente del Ministro del Interior, en el desempeño de las funciones que esta Ley le atribuye, y del Ministro de Defensa en el cumplimiento de las misiones de carácter militar que éste o el Gobierno le encomienden. En tiempo de guerra y durante el estado de sitio, dependerá exclusivamente del Ministro de Defensa."}]},{"text":"La seva missió és protegir el lliure exercici dels drets i llibertats i garantir la seguretat ciutadana (art. 11.1 LOFCS). Territorialment, el Cos Nacional de Policia actua a les capitals de província i als termes municipals i nuclis urbans que determini el Govern, i la Guàrdia Civil a la resta del territori nacional i al mar territorial (art. 11.2 LOFCS).","refs":[{"ref":"Art. 11.1 LOFCS","law":"LO 2/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859","quote":"Las Fuerzas y Cuerpos de Seguridad del Estado tienen como misión proteger el libre ejercicio de los derechos y libertades y garantizar la seguridad ciudadana"},{"ref":"Art. 11.2 LOFCS","law":"LO 2/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859","quote":"a) Corresponde al Cuerpo Nacional de Policía ejercitar dichas funciones en las capitales de provincia y en los términos municipales y núcleos urbanos que el Gobierno determine. b) La Guardia Civil las ejercerá en el resto del territorio nacional y su mar territorial."}]}]},{"n":"8","title":"La policia judicial (art. 29)","blocks":[{"text":"Les funcions de policia judicial de l''article 126 de la Constitució les exerceixen les forces i cossos de seguretat de l''Estat per mitjà de les seves unitats (art. 29.1 LOFCS). El personal de les policies autonòmiques i de les policies locals hi té caràcter de col·laborador de les forces i cossos de seguretat de l''Estat (art. 29.2 LOFCS).","refs":[{"ref":"Art. 29 LOFCS","law":"LO 2/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859","quote":"1. Las funciones de Policía Judicial que se mencionan en el artículo 126 de la Constitución serán ejercidas por las Fuerzas y Cuerpos de Seguridad del Estado, a través de las Unidades que se regulan en el presente capítulo. 2. Para el cumplimiento de dicha función tendrán carácter colaborador de las Fuerzas y Cuerpos de Seguridad del Estado el personal de Policía de las Comunidades Autónomas y de las Corporaciones Locales."}]}]},{"n":"9","title":"Les policies locals: creació, naturalesa i àmbit (arts. 51 i 52)","blocks":[{"text":"Els municipis poden crear cossos de policia propis d''acord amb la LOFCS, la Llei de bases de règim local i la legislació autonòmica; on no n''hi ha, les seves tasques les fa el personal de custòdia i vigilància de béns, serveis i instal·lacions (guardes, vigilants, agents, agutzils o anàlegs) (art. 51.1 i 51.2 LOFCS). Els cossos de policia local són instituts armats de naturalesa civil amb estructura i organització jerarquitzada (art. 52.1 LOFCS).","refs":[{"ref":"Art. 51.1 i 51.2 LOFCS","law":"LO 2/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859","quote":"1. Los municipios podrán crear cuerpos de policía propios, de acuerdo con lo previsto en la presente ley, en la Ley de Bases de Régimen Local y en la legislación autonómica. 2. En los municipios donde no exista policía municipal, los cometidos de ésta serán ejercidos por el personal que desempeñe funciones de custodia y vigilancia de bienes, servicios e instalaciones, con la denominación de guardas, vigilantes, agentes, alguaciles o análogos."},{"ref":"Art. 52.1 LOFCS","law":"LO 2/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859","quote":"1. Los Cuerpos de Policía Local son Institutos armados, de naturaleza civil con estructura y organización jerarquizada"}]},{"text":"Només poden actuar dins del terme municipal, llevat de situacions d''emergència i amb requeriment previ de les autoritats competents. Quan fan funcions de protecció d''autoritats de les corporacions locals, però, poden actuar fora del terme amb autorització del Ministeri de l''Interior o, si l''actuació es fa íntegrament dins d''una comunitat autònoma amb policia pròpia, de l''autoritat autonòmica corresponent (art. 51.3 LOFCS).","refs":[{"ref":"Art. 51.3 LOFCS","law":"LO 2/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859","quote":"3. Dichos cuerpos sólo podrán actuar en el ámbito territorial del municipio respectivo, salvo en situaciones de emergencia y previo requerimiento de las autoridades competentes. No obstante, cuando ejerzan funciones de protección de autoridades de las corporaciones locales, podrán actuar fuera del término municipal respectivo, con autorización del Ministerio del Interior o de la correspondiente autoridad de la comunidad autónoma que cuente con cuerpo de policía autonómica, cuando desarrollen íntegramente esas actuaciones en el ámbito territorial de dicha comunidad autónoma."}]}]},{"n":"10","title":"Funcions de les policies locals (art. 53)","blocks":[{"text":"L''article 53.1 LOFCS enumera les funcions de les policies locals: protegir les autoritats de les corporacions locals i vigilar-ne els edificis; ordenar, senyalitzar i dirigir el trànsit al casc urbà; instruir atestats per accidents de circulació al casc urbà; policia administrativa (ordenances, bans i disposicions municipals); participar en les funcions de policia judicial segons l''article 29.2; auxiliar en accidents, catàstrofes i calamitats i participar en els plans de protecció civil; fer diligències de prevenció per evitar actes delictius en el marc de les juntes de seguretat; vigilar els espais públics i col·laborar en la protecció de manifestacions i grans concentracions quan se''ls requereixi; i cooperar en la resolució de conflictes privats quan se''ls requereixi. La investigació de la delinqüència organitzada no hi figura.","refs":[{"ref":"Art. 53.1 LOFCS","law":"LO 2/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859","quote":"a) Proteger a las Autoridades de las Corporaciones Locales, y vigilancia o custodia de sus edificios e instalaciones. b) Ordenar, señalizar y dirigir el tráfico en el casco urbano, de acuerdo con lo establecido en las normas de circulación. c) Instruir atestados por accidentes de circulación dentro del casco urbano. d) Policía Administrativa, en lo relativo a las Ordenanzas, Bandos y demás disposiciones municipales dentro del ámbito de su competencia. e) Participar en las funciones de Policía Judicial, en la forma establecida en el artículo 29.2 de esta Ley."},{"ref":"Art. 53.1.g a 53.1.i LOFCS","law":"LO 2/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859","quote":"g) Efectuar diligencias de prevención y cuantas actuaciones tiendan a evitar la comisión de actos delictivos en el marco de colaboración establecido en las Juntas de Seguridad. h) Vigilar los espacios públicos y colaborar con las Fuerzas y Cuerpos de Seguridad del Estado y con la Policía de las Comunidades Autónomas en la protección de las manifestaciones y el mantenimiento del orden en grandes concentraciones humanas, cuando sean requeridos para ello. i) Cooperar en la resolución de los conflictos privados cuando sean requeridos para ello."}]},{"text":"Les actuacions dels atestats de trànsit (lletra c) i de les diligències de prevenció (lletra g) s''han de comunicar a les forces i cossos de seguretat de l''Estat competents (art. 53.2 LOFCS).","refs":[{"ref":"Art. 53.2 LOFCS","law":"LO 2/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859","quote":"2. Las actuaciones que practiquen los Cuerpos de Policía Local en el ejercicio de las funciones previstas en los apartados c) y g) precedentes deberán ser comunicadas a las Fuerzas y Cuerpos de Seguridad del Estado competentes."}]}]},{"n":"11","title":"Les juntes locals de seguretat (art. 54)","blocks":[{"text":"Als municipis amb cos de policia propi es pot constituir una junta local de seguretat, òrgan competent per establir les formes i els procediments de col·laboració entre els membres de les forces i cossos de seguretat al seu territori (art. 54.1 LOFCS). La presideix l''alcalde, llevat que hi assisteixi el governador civil, cas en què la presidència és compartida (art. 54.2 LOFCS). El text consolidat encara parla de «Gobernador civil»: és una denominació històrica i les fonts de la carpeta no recullen la norma que en fixa l''equivalent actual. A Catalunya, els municipis amb policia local que creïn la junta hi poden integrar representants del departament de la Generalitat, i la seva participació és preceptiva on hi ha presència operativa de la policia autonòmica (art. 17 Llei 16/1991).","refs":[{"ref":"Art. 54 LOFCS","law":"LO 2/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859","quote":"1. En los municipios que tengan Cuerpo de Policía propio, podrá constituirse una Junta Local de Seguridad, que será el órgano competente para establecer las formas y procedimientos de colaboración entre los miembros de las Fuerzas y Cuerpos de Seguridad en su ámbito territorial. 2. La constitución de dichas Juntas y su composición se determinará reglamentariamente. La presidencia corresponderá al Alcalde, salvo que concurriera a sus sesiones el Gobernador civil de la provincia, en cuyo caso, la presidencia será compartida con éste."},{"ref":"Art. 17.2 LPL","law":"Llei 16/1991","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343","quote":"La participación de representantes del Departamento de Gobernación en la Junta Local de Seguridad es preceptiva en los Municipios en que haya una presencia operativa de la Policía autonómica."}]}]},{"n":"R","title":"Recorda per a l''examen","blocks":[{"text":"La seguretat pública és competència exclusiva de l''Estat; les corporacions locals hi participen segons la LBRL i en el marc de la LOFCS.","refs":[{"ref":"Art. 1.1 LOFCS","law":"LO 2/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859","quote":"La Seguridad Pública es competencia exclusiva del Estado."}]},{"text":"Neutralitat política i imparcialitat formen part de l''adequació a l''ordenament jurídic.","refs":[{"ref":"Art. 5.1 LOFCS","law":"LO 2/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859","quote":"Adecuación al ordenamiento jurídico, especialmente:"}]},{"text":"Ús de mitjans: congruència, oportunitat i proporcionalitat.","refs":[{"ref":"Art. 5.2.c LOFCS","law":"LO 2/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859","quote":"por los principios de congruencia, oportunidad y proporcionalidad en la utilización de los medios a su alcance."}]},{"text":"Els agents intervenen sempre, de servei o no, i no estan obligats a revelar les fonts d''informació.","refs":[{"ref":"Art. 5.4 LOFCS","law":"LO 2/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859","quote":"debiendo intervenir siempre, en cualquier tiempo y lugar, se hallaren o no de servicio"}]},{"text":"Consideració d''autoritat només a l''efecte de protecció penal, en atemptats amb armes de foc, explosius o mitjans anàlegs.","refs":[{"ref":"Art. 7.2 LOFCS","law":"LO 2/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859","quote":"tendrán al efecto de su protección penal la consideración de autoridad."}]},{"text":"Guàrdia Civil: institut armat de naturalesa militar; Cos Nacional de Policia: de naturalesa civil.","refs":[{"ref":"Art. 9.b LOFCS","law":"LO 2/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859","quote":"La Guardia Civil, que es un Instituto Armado de naturaleza militar"}]},{"text":"Policies locals i autonòmiques, en policia judicial: col·laboradores de les FCSE.","refs":[{"ref":"Art. 29.2 LOFCS","law":"LO 2/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859","quote":"tendrán carácter colaborador de las Fuerzas y Cuerpos de Seguridad del Estado"}]},{"text":"Atestats de trànsit i diligències de prevenció de la policia local es comuniquen a les FCSE competents.","refs":[{"ref":"Art. 53.2 LOFCS","law":"LO 2/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859","quote":"deberán ser comunicadas a las Fuerzas y Cuerpos de Seguridad del Estado competentes."}]},{"text":"Junta local de seguretat: la presideix l''alcalde, i la presidència és compartida si hi assisteix el governador civil.","refs":[{"ref":"Art. 54.2 LOFCS","law":"LO 2/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859","quote":"La presidencia corresponderá al Alcalde, salvo que concurriera a sus sesiones el Gobernador civil de la provincia, en cuyo caso, la presidencia será compartida con éste."}]}]}]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859'), 'https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859', null, null, null, null
