insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, lessons, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"Naturalesa i àmbit de les policies locals (arts. 1-3)"},{"n":"2","title":"Denominació, uniformitat i armes"},{"n":"3","title":"Funcions de les policies locals"},{"n":"4","title":"Vigilants municipals"},{"n":"5","title":"Coordinació: Comissió de Coordinació de les Policies Locals"},{"n":"6","title":"Estructura i escala de comandament"},{"n":"7","title":"Accés i formació a l''Institut de Seguretat Pública (arts. 24, 26 i 29)"}]'::jsonb, '["Art. 2.1 Llei 16/1991: «1. Las Policías locales son institutos armados de naturaleza civil con estructura y organización jerarquizadas.»","Art. 2.3 Llei 16/1991: «pueden recibir también la denominación específica de Policía municipal o de Guardia urbana.»","Art. 3 Llei 16/1991: «2. En los Municipios de menos de 10.000 habitantes puede existir Policía local si acuerda su creación la mayoría absoluta del número legal de miembros de la correspondiente Corporación local y lo autoriza el Consejero de Gobernación, previo informe de la Comisión de Coordinación de las Policías Locales.»","Art. 1.3 Llei 16/1991: «3. El servicio que compete a las Policías locales será prestado directamente por las respectivas Corporaciones locales, que no pueden constituir órganos especiales de gestión ni aprobar la concesión, el arrendamiento ni ninguna otra forma de gestión indirecta del servicio.»","Art. 4 Llei 16/1991: «2. El mando de la Policía local es ejercido por el Alcalde, que puede delegar las correspondientes atribuciones, de acuerdo con la normativa vigente.»","Art. 5 Llei 16/1991: «2. Las Policías locales solamente pueden actuar fuera de su ámbito territorial en situaciones de emergencia y previa autorización de las autoridades competentes. Se dará cuenta de estas actuaciones al Departamento de Gobernación.»","Art. 6 Llei 16/1991: «Antes de tomar posesión del cargo, los Policías locales jurarán o prometerán acatar la Constitución, como norma fundamental del Estado, y respetar y observar el Estatuto de Autonomía, como norma institucional básica de Cataluña.»","Art. 7 Llei 16/1991: «No se consideran agentes de la autoridad, en ningún caso, los vigilantes, alguaciles o similares que actúan de manera complementaria o auxiliar a una policía local municipal existente.»","Art. 8 Llei 16/1991: «2. El Alcalde determinará, de forma motivada, las circunstancias y los servicios en que no se llevarán armas de fuego.»","Art. 10 Llei 16/1991: «d) Utilizar las armas solamente en las situaciones en que exista un riesgo racionalmente grave para su vida o su integridad física o las de terceras personas y en aquellas circunstancias que puedan suponer un grave riesgo para la seguridad ciudadana»","Art. 11 Llei 16/1991: «b) Ordenar, señalizar y dirigir el tráfico en el núcleo urbano, de acuerdo con lo establecido en las normas de circulación.»","Art. 11.c Llei 16/1991: «c) Instruir atestados por accidentes de circulación acaecidos dentro del núcleo urbano, en cuyo caso comunicarán las actuaciones realizadas a las Fuerzas o Cuerpos de Seguridad competentes.»","Art. 11.g-h Llei 16/1991: «h) Cooperar en la resolución de los conflictos privados, cuando sean requeridas para ello.»","Art. 12 Llei 16/1991: «b) Practicar, por iniciativa propia o a requerimiento de la autoridad judicial, del Ministerio Fiscal o de los superiores jerárquicos las primeras diligencias de prevención y custodia de detenidos»","Art. 13 Llei 16/1991: «Los Vigilantes a que se refiere el artículo 1.2 pueden realizar únicamente las actuaciones siguientes:»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[{"n":"1","title":"Naturalesa i àmbit d''aplicació de les policies locals (arts. 1 i 2)","blocks":[{"text":"La Llei 16/1991, de 10 de juliol, de les policies locals (LPL), s''aplica a tots els cossos de policia que depenen dels municipis de Catalunya, anomenats genèricament policies locals (art. 1.1 LPL). Els municipis que no en tenen es poden dotar de guardes, vigilants, agents, agutzils o similars, que reben el nom genèric de vigilants (art. 1.2). El servei l''han de prestar directament les corporacions locals: no poden crear òrgans especials de gestió ni aprovar la concessió, l''arrendament ni cap altra forma de gestió indirecta (art. 1.3 LPL).","refs":[{"ref":"Art. 1.1 LPL","law":"Llei 16/1991","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343","quote":"La presente Ley se aplica a todos los Cuerpos de Policía que dependen de los Municipios de Cataluña, denominados genéricamente Policías locales."},{"ref":"Art. 1.3 LPL","law":"Llei 16/1991","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343","quote":"3. El servicio que compete a las Policías locales será prestado directamente por las respectivas Corporaciones locales, que no pueden constituir órganos especiales de gestión ni aprobar la concesión, el arrendamiento ni ninguna otra forma de gestión indirecta del servicio."}]},{"text":"Les policies locals són instituts armats de naturalesa civil amb estructura i organització jerarquitzades, i són els cossos amb competències de policia i seguretat ciutadana que depenen dels municipis (art. 2.1 i 2.2 LPL). Cal tenir present que el text conserva referències a òrgans antics: el text parla del «Departamento de Gobernación» i del «Consejero de Gobernación», mentre que la Llei 4/2003 es refereix al departament titular de les competències en matèria de seguretat pública.","refs":[{"ref":"Art. 2.1 LPL","law":"Llei 16/1991","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343","quote":"1. Las Policías locales son institutos armados de naturaleza civil con estructura y organización jerarquizadas."},{"ref":"Art. 25.1 LSSP","law":"Llei 4/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-9620","quote":"El Gobierno, por medio del departamento titular de las competencias en materia de seguridad pública, tiene la responsabilidad de hacer efectiva la coordinación de las policías locales"}]}]},{"n":"2","title":"Creació, cos únic, comandament i àmbit territorial (arts. 3 a 6)","blocks":[{"text":"Pot haver-hi policia local als municipis de més de 10.000 habitants (art. 3.1 LPL). En els de menys de 10.000, cal que ho acordi la majoria absoluta del nombre legal de membres de la corporació i que ho autoritzi el conseller competent, amb informe previ de la Comissió de Coordinació de les Policies Locals (art. 3.2 LPL).","refs":[{"ref":"Art. 3 LPL","law":"Llei 16/1991","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343","quote":"1. Puede existir Policía local en los Municipios de más de 10.000 habitantes. 2. En los Municipios de menos de 10.000 habitantes puede existir Policía local si acuerda su creación la mayoría absoluta del número legal de miembros de la correspondiente Corporación local y lo autoriza el Consejero de Gobernación, previo informe de la Comisión de Coordinación de las Policías Locales."}]},{"text":"La policia local de cada municipi s''integra en un cos únic (art. 4.1). El comandament l''exerceix l''alcalde, que en pot delegar les atribucions, i el comandament immediat correspon al cap del cos (art. 4.2 i 4.3 LPL). L''àmbit d''actuació és el terme municipal; fora d''aquest, només en situacions d''emergència i amb autorització prèvia de les autoritats competents, i se n''ha de donar compte al departament (art. 5 LPL). Abans de prendre possessió, els policies locals han de jurar o prometre acatar la Constitució i respectar i observar l''Estatut d''autonomia (art. 6 LPL).","refs":[{"ref":"Art. 4 LPL","law":"Llei 16/1991","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343","quote":"1. La Policía local de cada Municipio se integrará en un Cuerpo único, sin perjuicio de la organización interna que se adopte por Reglamento. 2. El mando de la Policía local es ejercido por el Alcalde, que puede delegar las correspondientes atribuciones, de acuerdo con la normativa vigente. 3. El mando inmediato de la Policía local corresponde al Jefe del Cuerpo."},{"ref":"Art. 5.2 LPL","law":"Llei 16/1991","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343","quote":"Las Policías locales solamente pueden actuar fuera de su ámbito territorial en situaciones de emergencia y previa autorización de las autoridades competentes. Se dará cuenta de estas actuaciones al Departamento de Gobernación."},{"ref":"Art. 6 LPL","law":"Llei 16/1991","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343","quote":"Antes de tomar posesión del cargo, los Policías locales jurarán o prometerán acatar la Constitución, como norma fundamental del Estado, y respetar y observar el Estatuto de Autonomía, como norma institucional básica de Cataluña."}]}]},{"n":"3","title":"Agents de l''autoritat, denominació, armes i uniforme (arts. 2.3, 7, 8 i 9)","blocks":[{"text":"Per tradició històrica i si ho acorda la corporació, les policies locals poden rebre també la denominació específica de Policia municipal o de Guàrdia urbana (art. 2.3 LPL). En l''exercici de les funcions, els policies locals tenen a tots els efectes la condició d''agents de l''autoritat (art. 7.1 LPL).","refs":[{"ref":"Art. 2.3 LPL","law":"Llei 16/1991","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343","quote":"las Policías locales, por razones de tradición histórica, siempre que lo acuerde la respectiva Corporación local, pueden recibir también la denominación específica de Policía municipal o de Guardia urbana."},{"ref":"Art. 7.1 LPL","law":"Llei 16/1991","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343","quote":"Los policías locales gozan a todos los efectos, en el ejercicio de sus funciones, de la condición de agentes de la autoridad."}]},{"text":"Com a integrants d''un institut armat, porten l''armament reglamentari que se''ls assigni i els altres mitjans tècnics necessaris; l''alcalde determina, de forma motivada, les circumstàncies i els serveis en què no es porten armes de foc (art. 8.1 i 8.2 LPL). Estan obligats a portar l''uniforme reglamentari, que només es pot fer servir en el servei; l''alcalde pot autoritzar serveis sense uniforme, i llavors cal portar la documentació acreditativa (art. 9 LPL).","refs":[{"ref":"Art. 8.2 LPL","law":"Llei 16/1991","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343","quote":"2. El Alcalde determinará, de forma motivada, las circunstancias y los servicios en que no se llevarán armas de fuego."},{"ref":"Art. 9 LPL","law":"Llei 16/1991","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343","quote":"1. Los Policías locales están obligados a llevar el uniforme reglamentario, que solamente puede utilizarse para el cumplimiento del servicio. 2. No obstante lo dispuesto en el apartado 1, el Alcalde puede autorizar que determinados servicios se presten sin el uniforme reglamentario"}]},{"text":"Les característiques comunes d''uniformes, insignies, distintius, equip i vehicles les fixa el departament (art. 19 LPL). Avui la Llei 4/2003 també atribueix a la coordinació establir-les, amb informe previ de la Comissió de Policia de Catalunya, sens perjudici que cada municipi hi afegeixi elements propis (art. 25.2.d LSSP).","refs":[{"ref":"Art. 19.1 LPL","law":"Llei 16/1991","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343","quote":"fijará las características comunes de uniformes, insignias, distintivos, equipo, vehículos y demás complementos de las Policías locales que puedan ser uniformados."},{"ref":"Art. 25.2.d LSSP","law":"Llei 4/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-9620","quote":"d) Establecer, previo informe de la Comisión de Policía de Cataluña, las características comunes de los uniformes, insignias, distintivos, equipo, vehículos y demás complementos de las policías locales que puedan ser uniformados"}]}]},{"n":"4","title":"Principis bàsics d''actuació (art. 10)","blocks":[{"text":"L''article 10 LPL reprodueix, adaptats, els principis de la LO 2/1986. En l''adequació a l''ordenament, els policies locals han d''actuar amb respecte absolut a la Constitució, a l''Estatut i a la resta de l''ordenament; amb neutralitat política i imparcialitat, sense discriminació per raó de naixement, raça, sexe, religió, opinió o qualsevol altra condició; amb integritat i dignitat; i sotmesos a la jerarquia i la subordinació, però l''obediència deguda no pot emparar mai ordres que comportin actes manifestament delictius o contraris a la Constitució, a l''Estatut o a les lleis.","refs":[{"ref":"Art. 10.1 LPL","law":"Llei 16/1991","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343","quote":"b) Actuar, en el cumplimiento de sus funciones, con absoluta neutralidad política e imparcialidad y, en consecuencia, sin discriminación alguna por razón de nacimiento, raza, sexo, religión, opinión o cualquier otra condición o circunstancia personal o social."},{"ref":"Art. 10.1 LPL","law":"Llei 16/1991","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343","quote":"d) Atenerse, en su actuación profesional, a los principios de jerarquía y subordinación; no obstante, en ningún caso la obediencia debida podrá amparar órdenes que entrañen la ejecución de actos que manifiestamente constituyan delito o sean contrarios a la Constitución, al Estatuto o a las leyes."}]},{"text":"En les relacions amb la comunitat, només poden utilitzar les armes en situacions de risc racionalment greu per a la seva vida o integritat física o les de terceres persones, i en circumstàncies que puguin suposar un risc greu per a la seguretat ciutadana. També els obliguen els principis sobre detinguts (identificar-se en el moment de la detenció), la dedicació professional (intervenir sempre, de servei o no) i el secret professional. Responen personalment i directament dels seus actes, sens perjudici de la responsabilitat patrimonial de l''Administració (art. 10.2 LPL).","refs":[{"ref":"Art. 10.1 LPL","law":"Llei 16/1991","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343","quote":"d) Utilizar las armas solamente en las situaciones en que exista un riesgo racionalmente grave para su vida o su integridad física o las de terceras personas y en aquellas circunstancias que puedan suponer un grave riesgo para la seguridad ciudadana"},{"ref":"Art. 10.1 LPL","law":"Llei 16/1991","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343","quote":"a) Identificarse debidamente como agentes en el momento de efectuar una detención."},{"ref":"Art. 10.2 LPL","law":"Llei 16/1991","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343","quote":"Los Policías locales son responsables personal y directamente por los actos en que, en el desempeño de su funciones, infrinjan o vulneren, por acción u omisión, las normas legales"}]}]},{"n":"5","title":"Funcions de les policies locals (art. 11)","blocks":[{"text":"L''article 11 LPL enumera les funcions: protegir les autoritats locals i vigilar els edificis municipals; ordenar, senyalitzar i dirigir el trànsit al nucli urbà; instruir atestats per accidents de circulació dins del nucli urbà, comunicant les actuacions als cossos de seguretat competents; exercir de policia administrativa; exercir de policia judicial; fer diligències de prevenció per evitar actes delictius, també amb comunicació als cossos competents; vigilar els espais públics; auxiliar en accidents i catàstrofes i participar en els plans de protecció civil; vetllar per la normativa de medi ambient; garantir la seguretat viària; i qualsevol altra funció que els encomani la legislació.","refs":[{"ref":"Art. 11 LPL","law":"Llei 16/1991","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343","quote":"b) Ordenar, señalizar y dirigir el tráfico en el núcleo urbano, de acuerdo con lo establecido en las normas de circulación. c) Instruir atestados por accidentes de circulación acaecidos dentro del núcleo urbano, en cuyo caso comunicarán las actuaciones realizadas a las Fuerzas o Cuerpos de Seguridad competentes."},{"ref":"Art. 11.f LPL","law":"Llei 16/1991","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343","quote":"f) Realizar diligencias de prevención y actuaciones dirigidas a evitar la comisión de actos delictivos, en cuyo caso, comunicarán las actuaciones realizadas a las Fuerzas o Cuerpos de Seguridad competentes."},{"ref":"Art. 11.i a 11.l LPL","law":"Llei 16/1991","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343","quote":"i) Vigilar los espacios públicos. j) Prestar auxilio en accidentes, catástrofes y calamidades públicas, participando, de acuerdo con lo dispuesto en las leyes, en la ejecución de los planes de protección civil. k) Velar por el cumplimiento de la normativa vigente en materia de medio ambiente y de protección del entorno. l) Realizar actuaciones dirigidas a garantizar la seguridad vial en el Municipio."}]},{"text":"Dues funcions només s''exerceixen quan se''ls requereix: col·laborar amb les forces i cossos de seguretat de l''Estat i amb la policia autonòmica en la protecció de manifestacions i en l''ordre en grans concentracions humanes (lletra g), i cooperar en la resolució dels conflictes privats (lletra h).","refs":[{"ref":"Art. 11.g i 11.h LPL","law":"Llei 16/1991","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343","quote":"g) Colaborar con las Fuerzas o Cuerpos de Seguridad del Estado y con la Policía autonómica en la protección de las manifestaciones y en el mantenimiento del orden en grandes concentraciones humanas, cuando sean requeridas para ello. h) Cooperar en la resolución de los conflictos privados, cuando sean requeridas para ello."}]}]},{"n":"6","title":"Funcions de policia judicial (art. 12)","blocks":[{"text":"Com a policia judicial, les policies locals auxilien jutges, tribunals i Ministeri Fiscal en la investigació dels delictes i en la detenció dels delinqüents quan se''ls requereix, i practiquen, per iniciativa pròpia o a requeriment de l''autoritat judicial, del Ministeri Fiscal o dels superiors jeràrquics, les primeres diligències de prevenció i custòdia de detinguts i d''objectes del delicte, de les quals han de donar compte en els terminis legals (art. 12.1 LPL). Ho fan d''acord amb els principis de cooperació mútua i col·laboració recíproca amb els altres cossos (art. 12.2).","refs":[{"ref":"Art. 12.1 LPL","law":"Llei 16/1991","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343","quote":"b) Practicar, por iniciativa propia o a requerimiento de la autoridad judicial, del Ministerio Fiscal o de los superiores jerárquicos las primeras diligencias de prevención y custodia de detenidos y la prevención y custodia de los objetos provenientes de un delito o relacionados con su ejecución"},{"ref":"Art. 12.2 LPL","law":"Llei 16/1991","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343","quote":"se cumplirán de acuerdo con los principios de cooperación mutua y de colaboración recíproca con las demás Fuerzas y Cuerpos de Seguridad."}]}]},{"n":"7","title":"Els vigilants municipals (arts. 1.2, 7.2, 8.3 i 13)","blocks":[{"text":"Els vigilants només poden custodiar i vigilar béns i instal·lacions municipals; ordenar i regular el trànsit al nucli urbà; participar en l''auxili al ciutadà i en la protecció civil; i vetllar pel compliment de les ordenances i disposicions municipals (art. 13 LPL). No tenen, doncs, funcions de policia judicial, i no poden portar armes de foc (art. 8.3 LPL).","refs":[{"ref":"Art. 13 LPL","law":"Llei 16/1991","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343","quote":"Los Vigilantes a que se refiere el artículo 1.2 pueden realizar únicamente las actuaciones siguientes: a) Custodiar y vigilar bienes, servicios, instalaciones y dependencias municipales. b) Ordenar y regular el tráfico en el núcleo urbano, de acuerdo con las normas de circulación."},{"ref":"Art. 8.3 LPL","law":"Llei 16/1991","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343","quote":"3. Los vigilantes a que se refiere el artículo 1.2 no pueden llevar armas de fuego."}]},{"text":"Són agents de l''autoritat només si actuen identificats, dins de les seves funcions i en un municipi sense policia local. Els vigilants que actuen de manera complementària o auxiliar d''una policia local existent no ho són en cap cas (art. 7.2 LPL, segons la redacció de la Llei 5/2020).","refs":[{"ref":"Art. 7.2 LPL","law":"Llei 16/1991","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343","quote":"a) Actúen debidamente identificados y en ejercicio de las funciones que les son propias tal como están definidas en el artículo 13 y con las limitaciones del artículo 8.3. b) El municipio donde actúen no disponga de policía local, tal y como establece el artículo 1.2. No se consideran agentes de la autoridad, en ningún caso, los vigilantes, alguaciles o similares que actúan de manera complementaria o auxiliar a una policía local municipal existente."}]}]},{"n":"8","title":"Coordinació i Comissió de Policia de Catalunya (arts. 14-23 LPL i 8 Llei 4/2003)","blocks":[{"text":"La coordinació és la determinació dels mitjans i sistemes de relació que fan possible l''acció conjunta de les policies locals, per integrar-ne les actuacions en el sistema de seguretat (art. 14 LPL). S''estén, entre altres funcions, a homogeneïtzar mitjans tècnics i uniformitat, crear un sistema d''informació recíproca, fixar normes d''estructura i d''accés, formació i promoció, i sempre respectant l''autonomia local (art. 15 LPL).","refs":[{"ref":"Art. 14 LPL","law":"Llei 16/1991","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343","quote":"se entiende por coordinación la determinación de los medios y sistemas de relación que posibilitan la acción conjunta de las Policias locales"},{"ref":"Art. 15.2 LPL","law":"Llei 16/1991","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343","quote":"Las funciones especificadas en el apartado 1 se cumplirán respetando en cualquier caso la autonomía local y las competencias de los Municipios en materia de Policía local."}]},{"text":"Important: l''article 16 LPL, que regulava la Comissió de Coordinació de les Policies Locals, està derogat per la Llei 4/2003. Avui l''òrgan és la Comissió de Policia de Catalunya, òrgan consultiu superior de coordinació entre els Mossos d''Esquadra i les policies locals, presidida pel conseller competent i formada per cinc vocals dels ajuntaments i cinc del Govern (art. 8 LSSP). Les referències de la LPL a la Comissió de Coordinació (per exemple, l''art. 3.2) s''han de llegir tenint en compte aquesta substitució.","refs":[{"ref":"Art. 16 LPL","law":"Llei 16/1991","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343","quote":"Se deroga por la disposición derogatoria de la Ley 4/2003, de 7 de abril."},{"ref":"Preàmbul LSSP","law":"Llei 4/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-9620","quote":"la Comisión de Policía de Cataluña, que sustituye la hasta ahora existente Comisión de Coordinación de Policías Locales"},{"ref":"Art. 8.2 LSSP","law":"Llei 4/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-9620","quote":"a) El consejero o consejera del departamento con competencias en materia de seguridad pública, que la preside. b) Cinco vocales en representación de los ayuntamientos. c) Cinco vocales en representación del Gobierno."}]},{"text":"Les corporacions amb policia local o vigilants han d''enviar al departament i fer pública, el primer trimestre de cada any, la memòria de serveis de l''any anterior i la dotació de recursos (art. 20.1 LPL). Els municipis limítrofs, en cas de necessitat i amb autorització del conseller, poden subscriure acords de cooperació entre les seves policies (art. 23.3 LPL).","refs":[{"ref":"Art. 20.1 LPL","law":"Llei 16/1991","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343","quote":"enviarán al Departamento de Gobernación y harán pública, en el primer trimestre de cada año, de acuerdo con los criterios de elaboración determinados por reglamento, la siguiente documentación: a) La Memoria de los servicios prestados el año anterior. b) La dotación de recursos humanos y materiales."},{"ref":"Art. 23.3 LPL","law":"Llei 16/1991","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343","quote":"En casos de necesidad, los Municipios limítrofes, previa autorización del Consejero de Gobernación, pueden suscribir acuerdos de cooperación entre sus Policías."}]}]},{"n":"9","title":"Estructura: escales, categories i grups (arts. 24 i 25)","blocks":[{"text":"Els cossos s''estructuren en quatre escales: superior (superintendent, intendent major i intendent), executiva (inspector), intermèdia (sotsinspector i sergent) i bàsica (caporal i agent) (art. 24.1 LPL). Els grups són: escala superior, A1; executiva, A2; intermèdia, C1; i bàsica, també C1 (art. 24.2 LPL, modificat per la Llei 3/2023). El Decret 233/2002 (text consolidat) continua exigint per a agent i caporal el graduat en ESO o equivalent, de manera que cal comprovar a les bases de cada convocatòria la titulació exigida.","refs":[{"ref":"Art. 24.1 LPL","law":"Llei 16/1991","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343","quote":"a) Escala superior, que comprende las categorías de Superintendente, de Intendente Mayor y de Intendente. b) Escala ejecutiva, que comprende la categoría de Inspector. c) Escala intermedia, que comprende las categorías de Subinspector y de Sargento. d) Escala básica, que comprende las categorías de Cabo y de Agente."},{"ref":"Art. 24.2 LPL","law":"Llei 16/1991","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343","quote":"c) A la escala intermedia, el grupo C, subgrupo C1. d) A la escala básica, el grupo C, subgrupo C1."},{"ref":"Nota del BOE a l''art. 24 LPL","law":"Llei 16/1991","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343","quote":"Se modifica el apartado 2 por el art. 36.1 de la Ley 3/2023, de 16 de marzo."},{"ref":"Art. 11.2.a D233","law":"Decret 233/2002","url":"https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=286781","quote":"a) En les categories d’agent i caporal: títol de graduat o graduada en educació secundària"}]},{"text":"Cada municipi aprova la plantilla (art. 25.1). La categoria de superintendent només es pot crear en municipis de més de 200.000 habitants, i les d''intendent major i intendent, en els de més de 100.000, amb excepcions si el nombre d''agents supera 250 o 100 (art. 25.3 LPL).","refs":[{"ref":"Art. 25.3 LPL","law":"Llei 16/1991","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343","quote":"La categoría de Superintendente solamente puede crearse en los Municipios que tienen más de 200.000 habitantes y las categorías de Intendente Mayor y de Intendente solamente pueden crearse en los Municipios que tienen más de 100.000 habitantes."}]}]},{"n":"10","title":"El cap del cos (arts. 26 i 27)","blocks":[{"text":"El cap del cos, sota el comandament de l''alcalde o de qui aquest delegui, exerceix el comandament immediat (art. 26.1). En la redacció vigent (Llei 2/2021), és cap del cos el membre de la plantilla de més graduació; en cas d''igualtat, el nomena l''alcalde d''acord amb els principis d''objectivitat, mèrit, capacitat i igualtat d''oportunitats (art. 26.2 LPL). Li correspon dirigir i supervisar les operacions, avaluar necessitats, transformar en ordres concretes les directrius de l''alcalde i informar-lo del funcionament del servei (art. 27 LPL).","refs":[{"ref":"Art. 26.2 LPL","law":"Llei 16/1991","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343","quote":"Es jefe del cuerpo el miembro de la plantilla de mayor graduación; en caso de igualdad, corresponde al alcalde realizar el nombramiento, de acuerdo con los principios de objetividad, de mérito, de capacidad y de igualdad de oportunidades."},{"ref":"Art. 27 LPL","law":"Llei 16/1991","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343","quote":"c) Transformar en órdenes concretas las directrices de los objetivos a conseguir, recibidas del Alcalde o del cargo en quien éste delegue. d) Informar al Alcalde, o al cargo en quien éste delegue, del funcionamiento del servicio."}]}]},{"n":"11","title":"Accés i formació a l''Institut de Seguretat Pública (arts. 28 a 32)","blocks":[{"text":"Els policies locals són funcionaris de carrera dels ajuntaments (art. 28 LPL). L''accés a agent és per oposició o concurs oposició lliure; els requisits mínims són la ciutadania espanyola, l''edat que fixin el reglament o la convocatòria, les condicions per exercir les funcions i no estar inhabilitat ni separat del servei (art. 29.1). L''oposició ha d''incloure, com a mínim, proves culturals, físiques, mèdiques i psicotècniques, i cal superar un curs selectiu a l''Escola de Policia de Catalunya (art. 29.2 i 29.3 LPL). Les referències a l''Escola s''entenen fetes avui a l''Institut de Seguretat Pública de Catalunya (Llei 10/2007).","refs":[{"ref":"Art. 29.2 i 29.3 LPL","law":"Llei 16/1991","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343","quote":"2. Se incluirán en la oposición, como mínimo, pruebas culturales, físicas, médicas y psicotécnicas. 3. Es requisito indispensable, en cualquier caso, superar en la oposición un curso selectivo en la Escuela de Policía de Cataluña"},{"ref":"Disposició addicional primera LISPC","law":"Llei 10/2007","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2007-15546","quote":"Las referencias que la legislación vigente hace a la Escuela de Policía de Cataluña y a la Escuela de Bomberos y Seguridad Civil de Cataluña se entienden hechas al Instituto de Seguridad Pública de Cataluña."}]},{"text":"Les categories de caporal, sergent i sotsinspector s''hi accedeix per promoció interna amb dos anys d''antiguitat a la categoria inferior (art. 30.1), i les d''inspector a superintendent per concurs oposició lliure, amb fins a un 50 % de places reservables a promoció interna (art. 31). Els tribunals es componen per terços: membres de la corporació, personal tècnic i representants del departament (art. 32.1 LPL).","refs":[{"ref":"Art. 31 LPL","law":"Llei 16/1991","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343","quote":"Puede reservarse hasta un 50 por 100 de las plazas de cada convocatoria para la promoción interna"},{"ref":"Art. 32.1 LPL","law":"Llei 16/1991","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343","quote":"a) Un tercio será integrado por miembros o funcionarios de la misma Corporación. b) Otro tercio será integrado por personal técnico especializado en la materia."}]}]},{"n":"R","title":"Recorda per a l''examen","blocks":[{"text":"Policies locals: instituts armats de naturalesa civil, jerarquitzats; prestació directa, mai indirecta.","refs":[{"ref":"Art. 2.1 LPL","law":"Llei 16/1991","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343","quote":"institutos armados de naturaleza civil con estructura y organización jerarquizadas."}]},{"text":"Municipis de menys de 10.000 habitants: majoria absoluta del nombre legal de membres i autorització del conseller.","refs":[{"ref":"Art. 3.2 LPL","law":"Llei 16/1991","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343","quote":"la mayoría absoluta del número legal de miembros de la correspondiente Corporación local"}]},{"text":"Comandament: l''alcalde (delegable); comandament immediat: el cap del cos.","refs":[{"ref":"Art. 4.3 LPL","law":"Llei 16/1991","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343","quote":"El mando inmediato de la Policía local corresponde al Jefe del Cuerpo."}]},{"text":"L''alcalde decideix motivadament quan no es porten armes de foc; els vigilants no en poden portar mai.","refs":[{"ref":"Art. 8.2 LPL","law":"Llei 16/1991","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343","quote":"El Alcalde determinará, de forma motivada"}]},{"text":"Només a requeriment: manifestacions i grans concentracions, i conflictes privats.","refs":[{"ref":"Art. 11.h LPL","law":"Llei 16/1991","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343","quote":"Cooperar en la resolución de los conflictos privados, cuando sean requeridas para ello."}]},{"text":"Escala bàsica: caporal i agent, grup C1.","refs":[{"ref":"Art. 24.2.d LPL","law":"Llei 16/1991","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343","quote":"A la escala básica, el grupo C, subgrupo C1."}]},{"text":"Proves mínimes de l''oposició: culturals, físiques, mèdiques i psicotècniques.","refs":[{"ref":"Art. 29.2 LPL","law":"Llei 16/1991","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343","quote":"pruebas culturales, físicas, médicas y psicotécnicas."}]},{"text":"La Comissió de Coordinació ha estat substituïda per la Comissió de Policia de Catalunya.","refs":[{"ref":"Art. 8.1 LSSP","law":"Llei 4/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-9620","quote":"La Comisión de Policía de Cataluña es el órgano colegiado consultivo superior en materia de coordinación"}]}]}]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343'), 'https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343', null, null, null, null
