insert into public.sources (title, url, kind, publisher, published_on) values ('Ley 16/1991, de 10 de julio, de las Policías Locales (Cataluña) (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('plcat-t08-policies-locals-estatut-disciplina', 'Tema 8. La Llei 16/1991 de les policies locals: drets i deures, situacions i règim disciplinari') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('policia-local') and t.slug = 'plcat-t08-policies-locals-estatut-disciplina' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, lessons, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"Drets dels policies locals"},{"n":"2","title":"Deures i incompatibilitats"},{"n":"3","title":"Situacions administratives"},{"n":"4","title":"Règim disciplinari: faltes molt greus, greus i lleus"},{"n":"5","title":"Sancions i prescripció"},{"n":"6","title":"Procediment i suspensió provisional"}]'::jsonb, '["Art. 38 Llei 16/1991: «Los Policías locales no pueden ejercer el derecho de huelga ni participar en acciones sustitutivas de éste o en actuaciones concertadas con la finalidad de alterar el funcionamiento normal de los servicios.»","Art. 35 Llei 16/1991: «3. Corresponde al Pleno de la respectiva Corporación Local la fijación de las retribuciones complementarias»","Art. 37 Llei 16/1991: «La condición de Policía local es incompatible con el ejercicio de ninguna otra actividad pública o privada, excepción hecha de las actividades no incluidas en la legislación reguladora de las incompatibilidades.»","Art. 41 Llei 16/1991: «Las Corporaciones Locales garantizarán la necesaria defensa jurídica a sus Policías locales en las causas judiciales que se sigan contra ellos a consecuencia de actuaciones realizadas en el ejercicio de sus funciones.»","Art. 42 Llei 16/1991: «2. Los miembros de la Policía local dispondrán de una revisión médica anual.»","Art. 43 Llei 16/1991: «por razón de edad, que en ningún caso será inferior a cincuenta y siete años»","Art. 43.3 Llei 16/1991: «3. El paso a la situación de segunda actividad no representará una disminución de las retribuciones básicas ni del grado personal de los afectados.»","Art. 44 Llei 16/1991: «se compondrá de tres Médicos, uno designado por el Ayuntamiento, uno designado por el interesado y uno escogido por sorteo entre los facultativos del Servicio Catalán de la Salud»","Art. 47 Llei 16/1991: «Las faltas cometidas por los Policías locales en el ejercicio de sus funciones pueden ser muy graves, graves y leves.»","Art. 48 Llei 16/1991: «g) El abandono del servicio.»","Art. 48-49 Llei 16/1991: «n) La pérdida de las armas, así como permitir su sustracción por negligencia simple.»","Art. 49 Llei 16/1991: «m) La reincidencia en la comisión de faltas leves.»","Art. 50 Llei 16/1991: «c) El descuido en la presentación personal.»","Art. 51 Llei 16/1991: «2. Los Policías locales que encubren las faltas muy graves y graves consumadas incurren en una falta de un grado inferior.»","Art. 52 Llei 16/1991: «a) La suspensión de funciones, por más de quince días y menos de un año, con pérdida de las retribuciones.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[{"n":"1","title":"Règim estatutari: normativa aplicable i jornada (arts. 28 i 34)","blocks":[{"text":"Els policies locals són funcionaris de carrera del seu ajuntament i es regeixen per la LO 2/1986 de forces i cossos de seguretat, per la Llei 16/1991 (LPL) i les normes que la despleguen, pels reglaments específics i altres normes municipals, i per la legislació de règim local i de funció pública de Catalunya (art. 28 LPL). L''Estatut bàsic de l''empleat públic també s''hi aplica, juntament amb la legislació autonòmica, excepte en allò que estableix per a ells la LO 2/1986 (art. 3.2 TREBEP).","refs":[{"ref":"Art. 28 LPL","law":"Llei 16/1991","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343","quote":"Los Policías locales son funcionarios de carrera de los Ayuntamientos respectivos y se rigen por la Ley Orgánica 2/1986, de 13 de marzo, de Fuerzas y Cuerpos de Seguridad; por la presente Ley y las disposiciones que la desplieguen"},{"ref":"Art. 3.2 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"Los Cuerpos de Policía Local se rigen también por este Estatuto y por la legislación de las comunidades autónomas, excepto en lo establecido para ellos en la Ley Orgánica 2/1986, de 13 de marzo, de Fuerzas y Cuerpos de Seguridad."}]},{"text":"Cada ens local fixa el règim de jornada, horari, vacances i permisos, adaptat a les especificitats del servei (art. 34 LPL). Cal advertir que el text consolidat de la LPL que recull el BOE conserva denominacions antigues (per exemple, «Departamento de Gobernación» o «Escuela de Policía de Cataluña»), que s''han de llegir d''acord amb les lleis posteriors.","refs":[{"ref":"Art. 34 LPL","law":"Llei 16/1991","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343","quote":"Cada Entidad local, de acuerdo con las disposiciones reglamentarias que se determinen, fijará el régimen de jornada, horario, vacaciones y permisos para los miembros de la Policía local, que se adaptará a las especificidades del servicio del Cuerpo."},{"ref":"Disposició addicional primera LISPC","law":"Llei 10/2007","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2007-15546","quote":"Las referencias que la legislación vigente hace a la Escuela de Policía de Cataluña y a la Escuela de Bomberos y Seguridad Civil de Cataluña se entienden hechas al Instituto de Seguridad Pública de Cataluña."}]}]},{"n":"2","title":"Drets dels policies locals: retribucions, protecció i recompenses (arts. 35, 39, 40, 41 i 45)","blocks":[{"text":"Tenen dret a una remuneració justa que valori la formació, les incompatibilitats, la dedicació, el risc de la professió, els horaris i l''estructura del cos, i que es compon, com a mínim, de retribucions bàsiques i complementàries (art. 35.1 LPL). Les bàsiques tenen la mateixa estructura i quantia que per a la resta de la funció pública, i les complementàries les fixa el Ple de la corporació, dins dels límits de la legislació vigent (art. 35.2 i 35.3 LPL).","refs":[{"ref":"Art. 35.1 LPL","law":"Llei 16/1991","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343","quote":"Los Policías locales tienen derecho a una remuneración justa en la que se valore el nivel de formación, el régimen de incompatibilidades, la dedicación y el riesgo que entraña la profesión"},{"ref":"Art. 35.3 LPL","law":"Llei 16/1991","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343","quote":"3. Corresponde al Pleno de la respectiva Corporación Local la fijación de las retribuciones complementarias, teniendo en cuenta los conceptos expuestos en el apartado 1, dentro de los límites fijados en la legislación vigente."}]},{"text":"Tenen el mateix règim de previsió social que els altres funcionaris de la corporació (art. 39). Durant el curs selectiu, la corporació els assegura els ingressos de funcionari en pràctiques i la cotització a la Seguretat Social, i la Generalitat regula un sistema de beques (art. 40). Les corporacions han de garantir-los la defensa jurídica necessària en les causes judicials que se segueixin contra ells per actuacions fetes en l''exercici de les funcions (art. 41 LPL). En drets sindicals s''aplica la Llei 9/1987 (disposició addicional primera LPL).","refs":[{"ref":"Art. 39 LPL","law":"Llei 16/1991","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343","quote":"Los Policías locales están acogidos al mismo régimen de previsión social que los demás funcionarios de la Corporación local a la que pertenecen."},{"ref":"Art. 41 LPL","law":"Llei 16/1991","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343","quote":"Las Corporaciones Locales garantizarán la necesaria defensa jurídica a sus Policías locales en las causas judiciales que se sigan contra ellos a consecuencia de actuaciones realizadas en el ejercicio de sus funciones."},{"ref":"Disposició addicional primera LPL","law":"Llei 16/1991","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343","quote":"Se aplica a las Policías locales, en cuanto se refiere al ejercicio de los derechos sindicales, la Ley 9/1987, de 12 de junio"}]},{"text":"Els reglaments dels cossos poden establir distincions i recompenses, que consten a l''expedient personal i es poden valorar com a mèrit en els concursos de provisió (art. 45 LPL).","refs":[{"ref":"Art. 45.2 LPL","law":"Llei 16/1991","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343","quote":"Las distinciones y recompensas constarán en el expediente personal del funcionario y podrán ser valoradas como mérito en los concursos de provisión de puestos de trabajo."}]}]},{"n":"3","title":"Seguretat i higiene en el treball (art. 42)","blocks":[{"text":"Les policies locals han de disposar de mitjans i instal·lacions adequats, els seus membres tenen dret a una revisió mèdica anual i les corporacions han d''adoptar mesures per prevenir malalties contagioses (art. 42 LPL).","refs":[{"ref":"Art. 42 LPL","law":"Llei 16/1991","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343","quote":"1. Las Policías locales dispondrán de medios e instalaciones adecuados para el desarrollo de su función. 2. Los miembros de la Policía local dispondrán de una revisión médica anual. 3. Las Corporaciones Locales adoptarán las medidas necesarias para la prevención de enfermedades contagiosas."}]}]},{"n":"4","title":"Deures: incompatibilitats, prohibició de vaga i uniforme (arts. 6, 9, 37 i 38)","blocks":[{"text":"La condició de policia local és incompatible amb qualsevol altra activitat pública o privada, llevat de les activitats no incloses en la legislació d''incompatibilitats (art. 37 LPL). Incomplir les normes d''incompatibilitats és falta molt greu (art. 48.1.n LPL).","refs":[{"ref":"Art. 37 LPL","law":"Llei 16/1991","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343","quote":"La condición de Policía local es incompatible con el ejercicio de ninguna otra actividad pública o privada, excepción hecha de las actividades no incluidas en la legislación reguladora de las incompatibilidades."},{"ref":"Art. 48.1.n LPL","law":"Llei 16/1991","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343","quote":"n) El incumplimiento de las normas sobre incompatibilidades."}]},{"text":"Els policies locals no poden exercir el dret de vaga ni participar en accions substitutives o en actuacions concertades per alterar el funcionament normal dels serveis (art. 38 LPL); fer-ho és també falta molt greu (art. 48.1.k). Altres deures són jurar o prometre la Constitució i l''Estatut abans de prendre possessió (art. 6) i portar l''uniforme reglamentari, que només es pot fer servir en el servei (art. 9.1 LPL), a més dels principis d''actuació de l''article 10.","refs":[{"ref":"Art. 38 LPL","law":"Llei 16/1991","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343","quote":"Los Policías locales no pueden ejercer el derecho de huelga ni participar en acciones sustitutivas de éste o en actuaciones concertadas con la finalidad de alterar el funcionamiento normal de los servicios."},{"ref":"Art. 9.1 LPL","law":"Llei 16/1991","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343","quote":"Los Policías locales están obligados a llevar el uniforme reglamentario, que solamente puede utilizarse para el cumplimiento del servicio."}]}]},{"n":"5","title":"Situacions administratives i segona activitat (arts. 36, 43 i 44)","blocks":[{"text":"Les situacions administratives es regulen per la normativa dels funcionaris locals, tenint en compte les peculiaritats del cos (art. 36 LPL). Amb caràcter bàsic, els funcionaris de carrera poden estar en servei actiu, serveis especials, servei en altres administracions, excedència o suspensió de funcions (art. 85.1 TREBEP).","refs":[{"ref":"Art. 36 LPL","law":"Llei 16/1991","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343","quote":"Las situaciones administrativas de los Policías locales se regulan de acuerdo con la normativa aplicable a los funcionarios locales, teniendo siempre en cuenta las peculiaridades del Cuerpo a que pertenecen."},{"ref":"Art. 85.1 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"a) Servicio activo. b) Servicios especiales. c) Servicio en otras Administraciones Públicas. d) Excedencia. e) Suspensión de funciones."}]},{"text":"Passen a segona activitat els policies amb capacitat disminuïda per al servei ordinari, segons dictamen mèdic o per raó d''edat, que en cap cas pot ser inferior als cinquanta-set anys (art. 43.1). Normalment la segona activitat es fa al mateix cos amb altres funcions; si no és possible, en altres llocs de la corporació (art. 43.2). No comporta disminució de les retribucions bàsiques ni del grau personal (art. 43.3 LPL).","refs":[{"ref":"Art. 43.1 LPL","law":"Llei 16/1991","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343","quote":"Los Policías locales que según dictamen médico o por razón de edad, que en ningún caso será inferior a cincuenta y siete años, tienen disminuida su capacidad para cumplir el servicio ordinario pasan a la situación de segunda actividad"},{"ref":"Art. 43.3 LPL","law":"Llei 16/1991","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343","quote":"3. El paso a la situación de segunda actividad no representará una disminución de las retribuciones básicas ni del grado personal de los afectados."}]},{"text":"El dictamen mèdic l''emet un tribunal de tres metges: un designat per l''ajuntament, un per l''interessat i un escollit per sorteig entre facultatius del Servei Català de la Salut; poden ser recusats, i el tribunal decideix per majoria (art. 44 LPL).","refs":[{"ref":"Art. 44.1 LPL","law":"Llei 16/1991","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343","quote":"se compondrá de tres Médicos, uno designado por el Ayuntamiento, uno designado por el interesado y uno escogido por sorteo entre los facultativos del Servicio Catalán de la Salud"},{"ref":"Art. 44.3 LPL","law":"Llei 16/1991","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343","quote":"El Tribunal emitirá el dictamen médico por mayoría"}]}]},{"n":"6","title":"Règim disciplinari i faltes molt greus (arts. 46 a 48)","blocks":[{"text":"El règim disciplinari és el de la LPL, sens perjudici de les responsabilitats civils o penals (art. 46). Les faltes comeses en l''exercici de les funcions poden ser molt greus, greus i lleus (art. 47 LPL).","refs":[{"ref":"Art. 46 LPL","law":"Llei 16/1991","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343","quote":"El régimen disciplinario aplicable a los Policías locales es el establecido en la presente Ley, sin perjuicio de las responsabilidades civiles o criminales en que puedan incurrir."},{"ref":"Art. 47 LPL","law":"Llei 16/1991","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343","quote":"Las faltas cometidas por los Policías locales en el ejercicio de sus funciones pueden ser muy graves, graves y leves."}]},{"text":"Entre les faltes molt greus (art. 48.1 LPL) hi ha: incomplir el deure de fidelitat a la Constitució o a l''Estatut; qualsevol discriminació; infligir tortures o maltractaments; qualsevol conducta constitutiva de delicte dolós; la prevaricació o el suborn; l''abandonament del servei; la insubordinació; la denegació d''auxili; la pèrdua de les armes o permetre''n la sostracció per negligència inexcusable; la participació en vagues; la violació del secret professional; embriagar-se o consumir drogues durant el servei; i la reincidència en faltes greus. També ho són determinades conductes sobre gravacions de videocàmeres (art. 48.2).","refs":[{"ref":"Art. 48.1 LPL","law":"Llei 16/1991","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343","quote":"e) Cualquier conducta o actuación constitutiva de delito doloso. f) Cualquier acto de prevaricación o soborno, así como no evitarlo o no denunciarlo. g) El abandono del servicio."},{"ref":"Art. 48.1.j LPL","law":"Llei 16/1991","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343","quote":"j) La pérdida de las armas, así como permitir su sustracción por negligencia inexcusable."},{"ref":"Art. 48.1.u LPL","law":"Llei 16/1991","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343","quote":"u) La reincidencia en la comisión de faltas graves."}]}]},{"n":"7","title":"Faltes greus, lleus i participació en la falta (arts. 49 a 51)","blocks":[{"text":"Són faltes greus (art. 49 LPL), entre d''altres: la desobediència als superiors; les faltes de respecte greus i manifestes; els actes que atempten contra el decor o la imatge del cos; l''incompliment del deure de reserva; el consum d''alcohol durant el servei; la pèrdua de les credencials per negligència inexcusable; la falta d''assistència sense causa; la reincidència en faltes lleus; i la pèrdua de les armes o permetre''n la sostracció per negligència simple. Compareu: amb negligència inexcusable, la pèrdua de l''arma és molt greu; amb negligència simple, greu.","refs":[{"ref":"Art. 49 LPL","law":"Llei 16/1991","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343","quote":"m) La reincidencia en la comisión de faltas leves. n) La pérdida de las armas, así como permitir su sustracción por negligencia simple."},{"ref":"Art. 49.j LPL","law":"Llei 16/1991","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343","quote":"j) El consumo de bebidas alcohólicas durante el servicio, así como negarse a las pertinentes comprobaciones técnicas."}]},{"text":"Són faltes lleus (art. 50 LPL): la incorrecció amb superiors, companys, subordinats o ciutadans; la demora, la negligència o l''oblit en el compliment de les funcions; el descuit en la presentació personal; el descuit en la conservació de locals i material; l''incompliment de la jornada sense causa; prescindir del conducte reglamentari; i les faltes repetides de puntualitat en un mateix mes.","refs":[{"ref":"Art. 50 LPL","law":"Llei 16/1991","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343","quote":"a) La incorrección para con los superiores, los compañeros, los subordinados o los ciudadanos. b) La demora, la negligencia y el olvido en el cumplimiento de las funciones o de las órdenes recibidas. c) El descuido en la presentación personal."}]},{"text":"Qui indueix un altre a cometre una falta incorre en la mateixa responsabilitat, igual que els comandaments que la toleren; qui encobreix faltes molt greus o greus consumades incorre en una falta d''un grau inferior (art. 51 LPL).","refs":[{"ref":"Art. 51 LPL","law":"Llei 16/1991","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343","quote":"1. Los Policías locales que induzcan a otros a cometer actos o tener conductas constitutivos de falta disciplinaria incurren en la misma responsabilidad; también incurren en ella los mandos que las toleran. 2. Los Policías locales que encubren las faltas muy graves y graves consumadas incurren en una falta de un grado inferior."}]}]},{"n":"8","title":"Sancions i graduació (arts. 52 i 53)","blocks":[{"text":"Les sancions possibles són la separació del servei, la suspensió de funcions amb pèrdua de retribucions, el trasllat a un altre lloc, la deducció proporcional de retribucions per faltes de puntualitat i assistència i l''amonestació (art. 52.1). Per falta molt greu: separació del servei o suspensió de més d''un any i menys de sis. Per falta greu: suspensió de més de quinze dies i menys d''un any, o trasllat. Per falta lleu: suspensió d''un a quinze dies, trasllat, deducció proporcional o amonestació (art. 52.2 a 52.4 LPL).","refs":[{"ref":"Art. 52.2 LPL","law":"Llei 16/1991","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343","quote":"a) La separación del servicio. b) La suspensión de funciones, por más de un año y menos de seis, con pérdida de las retribuciones."},{"ref":"Art. 52.3 LPL","law":"Llei 16/1991","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343","quote":"a) La suspensión de funciones, por más de quince días y menos de un año, con pérdida de las retribuciones. b) El traslado a otro puesto de trabajo."},{"ref":"Art. 52.4 LPL","law":"Llei 16/1991","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343","quote":"a) La suspensión de funciones, por un período de uno a quince días, con pérdida de las retribuciones."}]},{"text":"Per graduar la sanció, d''acord amb el principi de proporcionalitat, es tenen en compte la intencionalitat, la pertorbació dels serveis, els danys i perjudicis, la reincidència, el grau de participació i la transcendència per a la seguretat pública (art. 53 LPL).","refs":[{"ref":"Art. 53 LPL","law":"Llei 16/1991","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343","quote":"a) La intencionalidad. b) La perturbación de los servicios. c) Los daños y perjuicios producidos a la Administración o a los administrados. d) La reincidencia en la comisión de faltas. e) El grado de participación en la comisión u omisión. f) La trascendencia para la seguridad pública."}]}]},{"n":"9","title":"Procediment disciplinari i òrgans competents (art. 54)","blocks":[{"text":"Les sancions per faltes greus o molt greus exigeixen un expedient, regit per la sumarietat i la celeritat, però sense causar mai indefensió; les lleus es poden imposar sense cap altre tràmit que l''audiència a l''interessat (art. 54.1). La incoació i el nomenament d''instructor i secretari corresponen a l''alcalde o a qui delegui (art. 54.2). Imposa les sancions l''alcalde, llevat de la separació del servei, que és competència del Ple de la corporació (art. 54.3 LPL).","refs":[{"ref":"Art. 54.1 LPL","law":"Llei 16/1991","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343","quote":"No pueden imponerse sanciones por faltas graves o muy graves si no es en virtud de un expediente instruido al efecto; la tramitación del expediente se regirá por los principios de sumariedad y celeridad, pero en ningún caso podrá causarse indefensión. La sanción por faltas leves puede ser impuesta sin más trámite que el de audiencia al interesado."},{"ref":"Art. 54.3 LPL","law":"Llei 16/1991","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343","quote":"La imposición de las sanciones por faltas muy graves corresponde al Alcalde, salvo en el caso de la separación del servicio, que es competencia del Pleno de la Corporación"}]},{"text":"Alguns temaris (Mataró) inclouen el Decret 179/2015, del procediment disciplinari de les policies locals, però aquest decret no és a les fonts de la carpeta i no se''n pot fer el resum. Sí que hi ha la regla de la LO 2/1986: el procediment penal no impedeix tramitar l''expedient disciplinari pels mateixos fets, però la resolució definitiva ha d''esperar la sentència ferma, i els fets provats vinculen l''Administració (art. 8.3 LOFCS).","refs":[{"ref":"Art. 8.3 LOFCS","law":"LO 2/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859","quote":"La iniciación de procedimiento penal contra miembros de las Fuerzas y Cuerpos de Seguridad, no impedirá la incoación y tramitación de expedientes gubernativos o disciplinarios por los mismos hechos. No obstante, la resolución definitiva del expediente sólo podrá producirse cuando la sentencia recaída en el ámbito penal sea firme, y la declaración de hechos probados vinculará a la administración."}]}]},{"n":"10","title":"Mesures preventives i suspensió provisional (arts. 55 a 57)","blocks":[{"text":"En iniciar un procediment judicial o disciplinari, o durant la tramitació, l''òrgan competent per incoar-lo pot acordar com a mesures preventives la suspensió provisional, el trasllat o l''adscripció a un lloc intern sense uniforme, arma ni credencial, per resolució motivada (art. 55 LPL).","refs":[{"ref":"Art. 55 LPL","law":"Llei 16/1991","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343","quote":"el órgano competente para incoarlo en la vía administrativa puede acordar como medidas preventivas la suspensión provisional, el traslado o la adscripción a un puesto de trabajo interno, sin uniforme, sin arma ni credencial del Policía expedientado o procesado."}]},{"text":"La suspensió provisional s''acorda inicialment per un mes i es pot prorrogar mes a mes fins a un màxim de sis, llevat que l''expedient s''allargui per causa imputable a l''expedientat o fins que hi hagi resolució en un procediment penal (art. 56.1). Mentre dura, es perden el complement específic i les gratificacions per serveis extraordinaris, i el temps es computa per complir la sanció de suspensió (art. 56.2). El trasllat preventiu no pot durar més que l''expedient (art. 56.3).","refs":[{"ref":"Art. 56.1 LPL","law":"Llei 16/1991","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343","quote":"La suspensión provisional solamente puede acordarse inicialmente por un plazo de un mes; acabado el cual, puede prorrogarse por otro mes, y así sucesivamente hasta un plazo máximo de seis meses"},{"ref":"Art. 56.2 LPL","law":"Llei 16/1991","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343","quote":"La suspensión provisional implica, mientras dura, la pérdida de las retribuciones correspondientes al complemento específico y a las gratificaciones por servicios extraordinarios."}]},{"text":"Tant si és sanció com mesura preventiva, la suspensió de funcions comporta la privació temporal de les funcions, la retirada temporal de l''arma i la credencial, la prohibició d''usar l''uniforme i la d''entrar a les dependències policials sense autorització (art. 57 LPL). No comporta, en canvi, la pèrdua definitiva de la condició de funcionari.","refs":[{"ref":"Art. 57 LPL","law":"Llei 16/1991","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343","quote":"además de la privación temporal del ejercicio de las funciones, conlleva la retirada temporal del arma y la credencial reglamentarias, la prohibición del uso del uniforme, en su caso, y la prohibición de entrar en las dependencias de la Policía local sin autorización."}]}]},{"n":"11","title":"Extinció de la responsabilitat i prescripció (art. 58)","blocks":[{"text":"La responsabilitat disciplinària s''extingeix per compliment de la sanció, mort, indult, amnistia i prescripció de la falta o de la sanció (art. 58.1). Les faltes molt greus prescriuen als sis anys, les greus als dos anys i les lleus al cap d''un mes, comptats des de la data de comissió (art. 58.2). Les sancions prescriuen en els mateixos terminis, comptats des de la notificació (art. 58.3 LPL).","refs":[{"ref":"Art. 58.1 LPL","law":"Llei 16/1991","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343","quote":"La responsabilidad disciplinaria se extingue por el cumplimiento de la sanción, muerte, indulto, amnistía y prescripción de la falta o sanción."},{"ref":"Art. 58.2 LPL","law":"Llei 16/1991","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343","quote":"Las faltas muy graves prescriben al cabo de seis años, las graves al cabo de dos años y las leves al cabo de un mes, desde la fecha de comisión de la falta."},{"ref":"Art. 58.3 LPL","law":"Llei 16/1991","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343","quote":"Las sanciones impuestas por faltas muy graves prescriben al cabo de seis años, las impuestas por faltas graves al cabo de dos años y las impuestas por faltas leves al cabo de un mes, desde la fecha de notificación de las sanciones."}]}]},{"n":"R","title":"Recorda per a l''examen","blocks":[{"text":"Retribucions complementàries: les fixa el Ple de la corporació.","refs":[{"ref":"Art. 35.3 LPL","law":"Llei 16/1991","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343","quote":"Corresponde al Pleno de la respectiva Corporación Local la fijación de las retribuciones complementarias"}]},{"text":"Revisió mèdica: anual.","refs":[{"ref":"Art. 42.2 LPL","law":"Llei 16/1991","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343","quote":"dispondrán de una revisión médica anual."}]},{"text":"Segona activitat per edat: mai abans dels cinquanta-set anys, i sense reduir retribucions bàsiques ni grau.","refs":[{"ref":"Art. 43.1 LPL","law":"Llei 16/1991","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343","quote":"que en ningún caso será inferior a cincuenta y siete años"}]},{"text":"Abandonament del servei: molt greu. Reincidència en faltes lleus: greu.","refs":[{"ref":"Art. 48.1.g LPL","law":"Llei 16/1991","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343","quote":"g) El abandono del servicio."}]},{"text":"Pèrdua d''armes per negligència simple: greu; per negligència inexcusable: molt greu.","refs":[{"ref":"Art. 49.n LPL","law":"Llei 16/1991","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343","quote":"n) La pérdida de las armas, así como permitir su sustracción por negligencia simple."}]},{"text":"Encobrir faltes greus o molt greus consumades: falta d''un grau inferior.","refs":[{"ref":"Art. 51.2 LPL","law":"Llei 16/1991","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343","quote":"incurren en una falta de un grado inferior."}]},{"text":"Separació del servei: la imposa el Ple; la resta de sancions, l''alcalde.","refs":[{"ref":"Art. 54.3 LPL","law":"Llei 16/1991","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343","quote":"que es competencia del Pleno de la Corporación"}]},{"text":"Suspensió provisional: un mes, prorrogable mes a mes fins a sis.","refs":[{"ref":"Art. 56.1 LPL","law":"Llei 16/1991","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343","quote":"hasta un plazo máximo de seis meses"}]},{"text":"Prescripció: molt greus sis anys, greus dos anys, lleus un mes.","refs":[{"ref":"Art. 58.2 LPL","law":"Llei 16/1991","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343","quote":"las graves al cabo de dos años"}]}]}]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343'), 'https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343', null, null, null, null
  from public.topics t where t.slug = 'plcat-t08-policies-locals-estatut-disciplina'
on conflict (topic_id, locale) do update
   set outline = excluded.outline, key_ideas = excluded.key_ideas, glossary = excluded.glossary,
       amendments = excluded.amendments, lessons = excluded.lessons, source_id = excluded.source_id, source_url = excluded.source_url,
       page_from = excluded.page_from, page_to = excluded.page_to, key_ideas_page = excluded.key_ideas_page
 where (n.outline, n.key_ideas, n.glossary, n.amendments, n.lessons)
       is distinct from (excluded.outline, excluded.key_ideas, excluded.glossary, excluded.amendments, excluded.lessons);
insert into public.sources (title, url, kind, publisher, published_on) values ('Ley 4/2003, de 7 de abril, de Ordenación del Sistema de Seguridad Pública de Cataluña (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-2003-9620', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('plcat-t09-sistema-seguretat-catalunya', 'Tema 9. La Llei 4/2003 d''ordenació del sistema de seguretat pública de Catalunya i l''Institut de Seguretat Pública') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('policia-local') and t.slug = 'plcat-t09-sistema-seguretat-catalunya' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, lessons, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"Sistema de seguretat pública de Catalunya: objecte i principis (Llei 4/2003)"},{"n":"2","title":"Competències de la Generalitat i dels municipis"},{"n":"3","title":"Juntes locals de seguretat i plans de seguretat"},{"n":"4","title":"Institut de Seguretat Pública de Catalunya: naturalesa i funcions (Llei 10/2007)"},{"n":"5","title":"Formació bàsica i promoció a l''ISPC"}]'::jsonb, '["Art. 3.1 Llei 4/2003: «a) Las autoridades de seguridad. b) Los cuerpos policiales y demás servicios, públicos o privados, de seguridad. c) Los órganos de coordinación y participación en materia de seguridad.»","Art. 2 Llei 4/2003: «c) Proximidad a los ciudadanos y descentralización de los servicios públicos.»","Art. 4.1 Llei 4/2003: «En el ámbito local, los alcaldes son también autoridades superiores en materia de seguridad, en el marco de sus competencias.»","Art. 5.1 Llei 4/2003: «1. La Policía de la Generalidad-Mossos d''Esquadra y las policías de los ayuntamientos, con la denominación de policía local, policía municipal, guardia urbana o cualquier otra denominación tradicional, constituyen la policía de las instituciones propias de Cataluña.»","Art. 5.4 Llei 4/2003: «en particular, por los de complementariedad, coordinación, colaboración, cooperación y auxilio mutuo, especialmente en el seno de las juntas locales de seguridad.»","Art. 6 Llei 4/2003: «1. El Consejo de Seguridad de Cataluña es el órgano consultivo y de participación superior en Cataluña en materia de seguridad»","Art. 3.3 Llei 4/2003: «3. La Junta de Seguridad de Cataluña es el órgano superior de coordinación entre la Policía de la Generalidad y las fuerzas y cuerpos de seguridad del Estado»","Art. 8 Llei 4/2003: «a) El consejero o consejera del departamento con competencias en materia de seguridad pública, que la preside. b) Cinco vocales en representación de los ayuntamientos. c) Cinco vocales en representación del Gobierno.»","Art. 9.1 Llei 4/2003: «1. En los municipios que tengan policía local debe existir una junta local de seguridad»","Art. 9.2 Llei 4/2003: «2. La junta local de seguridad está integrada por el alcalde o la alcalde, que la preside, con voz y voto»","Art. 10 Llei 4/2003: «b) Elaborar y aprobar el plan de seguridad local y los planes de actuación específicos que sean procedentes en el ámbito respectivo»","Art. 11 Llei 4/2003: «1. Las juntas locales de seguridad deben crear una mesa de coordinación operativa, como órgano permanente y estable de coordinación y cooperación de los diversos cuerpos y servicios de seguridad en el municipio.»","Art. 1 Llei 10/2007: «1. Se crea el Instituto de Seguridad Pública de Cataluña como entidad autónoma de carácter administrativo adscrita al departamento competente en materia de seguridad pública.»","Art. 7 Llei 10/2007: «1. El presidente o presidenta del Instituto de Seguridad Pública de Cataluña es el consejero o consejera del departamento competente en materia de seguridad pública.»","Art. 3.3 Llei 10/2007: «a) Los miembros de los cuerpos de policía de Cataluña, los vigilantes y auxiliares de la policía local»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[{"n":"1","title":"Objecte, àmbit i finalitat del sistema de seguretat pública","blocks":[{"text":"La Llei 4/2003, d''ordenació del sistema de seguretat pública de Catalunya, ordena les competències de la Generalitat en seguretat pública, sobretot les de policia, i les integra amb les de protecció civil, trànsit, joc i espectacles i seguretat privada en un sistema general propi de Catalunya, en què participen també les altres administracions competents (art. 1.1). En formen part les autoritats competents, els serveis que en depenen i els òrgans de coordinació i participació ciutadana (art. 1.2).","refs":[{"ref":"Art. 1.1 Llei 4/2003","law":"Llei 4/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-9620","quote":"El objeto de la presente Ley es la ordenación de las competencias de la Generalidad en materia de seguridad pública, especialmente las de policía, y su integración con las de protección civil, tráfico, juego y espectáculos y seguridad privada, en un sistema general de seguridad propio de Cataluña, participado por las otras administraciones con competencias en esta materia."},{"ref":"Art. 1.2 Llei 4/2003","law":"Llei 4/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-9620","quote":"Integran el sistema de seguridad pública de Cataluña las autoridades con competencias en la materia y los servicios dependientes de las administraciones respectivas, así como los órganos de coordinación y participación ciudadana."}]},{"text":"La finalitat del sistema és contribuir a unes polítiques de prevenció i protecció eficaces per assegurar els drets i les llibertats, preservar la convivència i fomentar la cohesió social (art. 1.3). Com que és un sistema integral, ha de garantir als ciutadans una prestació homogènia dels serveis de seguretat a qualsevol lloc de Catalunya (art. 1.4).","refs":[{"ref":"Art. 1.3 i 1.4 Llei 4/2003","law":"Llei 4/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-9620","quote":"tiene por objeto contribuir al desarrollo de políticas públicas de prevención y protección eficaces en el aseguramiento de los derechos y libertades de los ciudadanos, la preservación de la convivencia y el fomento de la cohesión social. […] debe garantizar el derecho de los ciudadanos a una prestación homogénea de los servicios de seguridad en cualquier parte de Cataluña."}]},{"text":"Avís de vigència: el text consolidat del BOE que fem servir apareix com a «Desactualizado» i incorpora modificacions fins al 2017. A més, conserva referències antigues: la disposició addicional primera remet a la Llei orgànica 1/1992 de seguretat ciutadana, que avui ha estat substituïda per la LO 4/2015 (tema 11), i l''article 3.3 remet a l''article 13 de l''Estatut de 1979, quan la Junta de Seguretat ara és a l''article 164.4 de l''Estatut del 2006.","refs":[{"ref":"Disposició addicional primera Llei 4/2003","law":"Llei 4/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-9620","quote":"a) Las determinadas por la Ley orgánica 1/1992, de 21 de febrero, de protección de la seguridad ciudadana."},{"ref":"Art. 164.4 EAC","law":"EAC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2006-13087","quote":"La Generalitat participa, mediante una Junta de Seguridad de composición paritaria entre la Generalitat y el Estado y presidida por el Presidente de la Generalitat, en la coordinación de las políticas de seguridad y de la actividad de los cuerpos policiales del Estado y de Cataluña"}]}]},{"n":"2","title":"Principis generals del sistema","blocks":[{"text":"L''article 2 enumera nou principis que inspiren el sistema: a) prevenció dels riscos i de les amenaces; b) adequació del servei públic a la demanda social; c) proximitat als ciutadans i descentralització dels serveis públics; d) eficàcia de l''acció pública i eficiència en l''assignació de recursos; e) planificació i avaluació de les actuacions; f) proporcionalitat de la intervenció pública; g) corresponsabilitat i complementarietat d''autoritats i administracions; h) coordinació i cooperació, i i) transparència i informació als ciutadans. Atenció a les preguntes trampa: la llei parla de descentralització, mai de centralització.","refs":[{"ref":"Art. 2 Llei 4/2003","law":"Llei 4/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-9620","quote":"a) Prevención de los riesgos y de las amenazas. b) Adecuación del servicio público a la demanda social. c) Proximidad a los ciudadanos y descentralización de los servicios públicos. d) Eficacia de la acción pública y eficiencia en la asignación de recursos y medios. e) Planificación y evaluación de las actuaciones. f) Proporcionalidad de la intervención pública. g) Corresponsabilidad y complementariedad de autoridades y administraciones. h) Coordinación y cooperación entre autoridades, administraciones y servicios. i) Transparencia e información a los ciudadanos."}]}]},{"n":"3","title":"Estructura del sistema i autoritats de seguretat","blocks":[{"text":"El sistema de seguretat de Catalunya està integrat per tres elements (art. 3.1): les autoritats de seguretat; els cossos policials i altres serveis de seguretat, públics o privats, i els òrgans de coordinació i participació. El Govern, per mitjà del departament competent, protegeix el lliure exercici dels drets i llibertats i garanteix la seguretat ciutadana (art. 3.2).","refs":[{"ref":"Art. 3.1 Llei 4/2003","law":"Llei 4/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-9620","quote":"a) Las autoridades de seguridad. b) Los cuerpos policiales y demás servicios, públicos o privados, de seguridad. c) Los órganos de coordinación y participación en materia de seguridad."}]},{"text":"Pel que fa a les autoritats (art. 4.1), el Govern és l''òrgan col·legiat superior de Catalunya en seguretat; el conseller del departament competent és l''autoritat que dirigeix la política de seguretat, d''acord amb el Govern, i en l''àmbit local ho són també els alcaldes. També són autoritats de seguretat els delegats territorials del Govern i els titulars d''òrgans del departament o dels ajuntaments que exerceixin aquestes funcions per atribució legal o per delegació expressa (art. 4.2).","refs":[{"ref":"Art. 4.1 Llei 4/2003","law":"Llei 4/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-9620","quote":"El Gobierno es el órgano colegiado superior de Cataluña en materia de seguridad. El consejero o consejera del departamento con competencias en materia de seguridad pública es la autoridad de la Generalidad que dirige la política de seguridad de Cataluña, de acuerdo con el Gobierno y sin perjuicio de las funciones que corresponden a las autoridades del Estado. En el ámbito local, los alcaldes son también autoridades superiores en materia de seguridad, en el marco de sus competencias."},{"ref":"Art. 4.2 Llei 4/2003","law":"Llei 4/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-9620","quote":"Tienen asimismo la condición de autoridades de seguridad los delegados territoriales del Gobierno"}]}]},{"n":"4","title":"Competències del conseller i dels alcaldes","blocks":[{"text":"Al conseller li corresponen, entre altres funcions (art. 4.3), dirigir la política de seguretat del Govern, exercir el comandament superior dels Mossos d''Esquadra, coordinar les policies locals de Catalunya, presidir el Consell de Seguretat de Catalunya, elaborar el Pla general de seguretat i sotmetre''l al Govern, i presentar al Govern un informe anual sobre la seguretat que, un cop aprovat, s''eleva al Parlament.","refs":[{"ref":"Art. 4.3 Llei 4/2003","law":"Llei 4/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-9620","quote":"a) Dirigir la política de seguridad del Gobierno. […] c) Ejercer el mando superior de la Policía de la Generalidad-Mossos d''Esquadra. d) Coordinar las policías locales de Cataluña. e) Presidir el Consejo de Seguridad de Cataluña. f) Elaborar y someter a la aprobación del Gobierno el Plan general de seguridad de Cataluña."},{"ref":"Art. 4.3.i Llei 4/2003","law":"Llei 4/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-9620","quote":"i) Someter a la aprobación del Gobierno un informe anual sobre la seguridad en Cataluña que, una vez aprobado por éste, debe elevarse al Parlamento."}]},{"text":"L''alcalde, en canvi, dirigeix la política de seguretat del seu municipi dins el marc del Pla general de seguretat, presideix la junta local de seguretat i vetlla pel compliment dels seus acords, exerceix el comandament superior de la policia local i informa el ple de l''ajuntament sobre el pla local de seguretat i, cada any, sobre la seva aplicació (art. 4.4). També té potestat sancionadora en els termes de la legislació vigent.","refs":[{"ref":"Art. 4.4 Llei 4/2003","law":"Llei 4/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-9620","quote":"a) Dirigir la política de seguridad en su municipio, de acuerdo con las competencias respectivas y en el marco de las determinaciones del Plan general de seguridad de Cataluña que establece el artículo 15. b) Presidir la junta local de seguridad, si existe, y velar por el cumplimiento de sus acuerdos. c) Ordenar y dirigir las actuaciones municipales en materia de seguridad, de acuerdo con el ordenamiento vigente. d) Ejercer el mando superior de la policía local."},{"ref":"Art. 4.4 Llei 4/2003","law":"Llei 4/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-9620","quote":"g) Informar anualmente al pleno del ayuntamiento sobre la aplicación e incidencias del plan local de seguridad. h) Ejercer la potestad sancionadora, en los términos que les atribuye la legislación vigente."}]}]},{"n":"5","title":"Els cossos policials de Catalunya","blocks":[{"text":"La Policia de la Generalitat-Mossos d''Esquadra i les policies dels ajuntaments (amb el nom de policia local, policia municipal, guàrdia urbana o una altra denominació tradicional) constitueixen la policia de les institucions pròpies de Catalunya (art. 5.1). La policia local de cada municipi s''integra en un sol cos i actua dins el terme municipal; només en pot sortir en situacions d''emergència i en les condicions dels convenis de col·laboració o dels plans de coordinació aprovats pel departament (art. 5.2).","refs":[{"ref":"Art. 5.1 Llei 4/2003","law":"Llei 4/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-9620","quote":"1. La Policía de la Generalidad-Mossos d''Esquadra y las policías de los ayuntamientos, con la denominación de policía local, policía municipal, guardia urbana o cualquier otra denominación tradicional, constituyen la policía de las instituciones propias de Cataluña."},{"ref":"Art. 5.2 Llei 4/2003","law":"Llei 4/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-9620","quote":"La policía local de cada municipio debe integrarse en un solo cuerpo y su ámbito de actuación es el del término municipal correspondiente. Sólo pueden actuar fuera de este ámbito en situaciones de emergencia y en las condiciones que establezcan los convenios de colaboración o los planes de coordinación aprobados por el departamento titular de las competencias en materia de seguridad pública."}]},{"text":"Les relacions entre aquests cossos es regeixen, en particular, pels principis de complementarietat, coordinació, col·laboració, cooperació i auxili mutu, especialment en el si de les juntes locals de seguretat; els convenis entre el departament i els ajuntaments els adapten a cada municipi (art. 5.4). La coordinació superior dels Mossos amb les forces i cossos de seguretat de l''Estat es fa per mitjà de la Junta de Seguretat de Catalunya, que és l''òrgan superior de coordinació entre tots dos (art. 3.3 i 5.6).","refs":[{"ref":"Art. 5.4 Llei 4/2003","law":"Llei 4/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-9620","quote":"en particular, por los de complementariedad, coordinación, colaboración, cooperación y auxilio mutuo, especialmente en el seno de las juntas locales de seguridad."},{"ref":"Art. 3.3 Llei 4/2003","law":"Llei 4/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-9620","quote":"3. La Junta de Seguridad de Cataluña es el órgano superior de coordinación entre la Policía de la Generalidad y las fuerzas y cuerpos de seguridad del Estado"}]}]},{"n":"6","title":"Òrgans superiors de coordinació i participació","blocks":[{"text":"El Consell de Seguretat de Catalunya és l''òrgan consultiu i de participació superior en seguretat (art. 6.1). El presideix el conseller i hi ha representants d''entitats ciutadanes, administracions locals, Generalitat i, si l''Estat ho acorda, de l''Administració de l''Estat, la judicatura i la fiscalia (art. 6.2). Emet un informe anual sobre l''evolució de la seguretat (art. 6.4.a).","refs":[{"ref":"Art. 6.1 Llei 4/2003","law":"Llei 4/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-9620","quote":"1. El Consejo de Seguridad de Cataluña es el órgano consultivo y de participación superior en Cataluña en materia de seguridad"},{"ref":"Art. 6.2 i 6.4.a Llei 4/2003","law":"Llei 4/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-9620","quote":"El Consejo de Seguridad de Cataluña es presidido por el consejero o consejera del departamento con competencias en materia de seguridad pública […] a) Analizar, estudiar y evaluar la situación de la seguridad en Cataluña a partir de los datos y estudios que determina el apartado 5, y emitir un informe anual sobre su evolución"}]},{"text":"La Comissió del Govern per a la Seguretat la presideix el president de la Generalitat (o el conseller primer) i l''integren els consellers de les matèries que afecten la seguretat; coordina els departaments, coneix el Pla general de seguretat i se''n fa el seguiment, i s''ha de reunir com a mínim un cop cada trimestre (art. 7).","refs":[{"ref":"Art. 7.1 i 7.2 Llei 4/2003","law":"Llei 4/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-9620","quote":"La Comisión del Gobierno para la Seguridad está integrada por el presidente o presidenta de la Generalidad o, en su caso, por el consejero o consejera jefe, que la preside […] La Comisión debe reunirse, como mínimo, una vez cada trimestre."}]},{"text":"La Comissió de Policia de Catalunya és l''òrgan col·legiat consultiu superior de coordinació entre els Mossos d''Esquadra i les policies locals (art. 8.1). La presideix el conseller i té cinc vocals dels ajuntaments i cinc del Govern (art. 8.2). Emet, entre altres, informes preceptius no vinculants sobre organització, accés, formació i promoció i sobre uniformitat de les policies locals (art. 8.3). Substitueix l''antiga Comissió de Coordinació de les Policies Locals (disposició derogatòria).","refs":[{"ref":"Art. 8.1 Llei 4/2003","law":"Llei 4/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-9620","quote":"1. La Comisión de Policía de Cataluña es el órgano colegiado consultivo superior en materia de coordinación entre la Policía de la Generalidad-Mossos d''Esquadra y las policías locales en Cataluña."},{"ref":"Art. 8.2 Llei 4/2003","law":"Llei 4/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-9620","quote":"a) El consejero o consejera del departamento con competencias en materia de seguridad pública, que la preside. b) Cinco vocales en representación de los ayuntamientos. c) Cinco vocales en representación del Gobierno."},{"ref":"Disposició derogatòria 2 Llei 4/2003","law":"Llei 4/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-9620","quote":"Las referencias que hace la legislación vigente a la Comisión de Coordinación de las Policías Locales se entienden hechas a la Comisión de Policía de Cataluña."}]}]},{"n":"7","title":"Juntes locals de seguretat i mesa de coordinació operativa","blocks":[{"text":"En els municipis que tenen policia local hi ha d''haver una junta local de seguretat, òrgan col·legiat de col·laboració i coordinació dels cossos i serveis de seguretat i de participació ciutadana (art. 9.1). La presideix l''alcalde, amb veu i vot, i són vocals permanents, també amb veu i vot, el delegat territorial del Govern, el regidor de seguretat ciutadana, el cap de la comissaria dels Mossos i el cap de la policia local; si l''Estat ho acorda, també els caps de la Guàrdia Civil i del Cos Nacional de Policia (art. 9.2).","refs":[{"ref":"Art. 9.1 Llei 4/2003","law":"Llei 4/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-9620","quote":"1. En los municipios que tengan policía local debe existir una junta local de seguridad, como órgano colegiado de colaboración y coordinación general de los diversos cuerpos de policía y demás servicios de seguridad que operan en su territorio y de participación ciudadana en el sistema de seguridad."},{"ref":"Art. 9.2 Llei 4/2003","law":"Llei 4/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-9620","quote":"2. La junta local de seguridad está integrada por el alcalde o la alcalde, que la preside, con voz y voto, y los vocales permanentes siguientes, también con voz y voto:"}]},{"text":"La junta es reuneix en sessió ordinària cada trimestre i una de les sessions anuals ha de ser plenària; els acords s''adopten per unanimitat i són executius (art. 9.7 i 9.8). Entre les seves funcions destaca elaborar i aprovar el pla de seguretat local i els plans específics i fer-ne el seguiment amb un informe anual (art. 10.b).","refs":[{"ref":"Art. 9.7 i 9.8 Llei 4/2003","law":"Llei 4/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-9620","quote":"La junta local de seguridad debe reunirse en sesión ordinaria, convocada por el presidente o presidenta, con carácter trimestral. Una de las sesiones anuales debe ser plenaria […] Los acuerdos de la junta local de seguridad deben adoptarse por unanimidad y tienen carácter ejecutivo."},{"ref":"Art. 10.b Llei 4/2003","law":"Llei 4/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-9620","quote":"b) Elaborar y aprobar el plan de seguridad local y los planes de actuación específicos que sean procedentes en el ámbito respectivo, de acuerdo con lo dispuesto por los artículos 15.2 y 27, y hacer el seguimiento y evaluación de los mismos mediante un informe anual."}]},{"text":"Cada junta local ha de crear una mesa de coordinació operativa, òrgan permanent i estable de coordinació i cooperació dels cossos i serveis de seguretat del municipi (art. 11.1), integrada pels caps dels Mossos i de la policia local membres de la junta (art. 11.2). Executa els acords de la junta i assegura l''intercanvi d''informació i la coordinació operativa; en tot cas, els cossos actuen sota les ordres immediates dels seus comandaments orgànics (art. 11.4). Els municipis d''una mateixa regió policial s''integren, a més, en una comissió regional de seguretat que presideix el conseller (art. 12).","refs":[{"ref":"Art. 11.1 Llei 4/2003","law":"Llei 4/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-9620","quote":"1. Las juntas locales de seguridad deben crear una mesa de coordinación operativa, como órgano permanente y estable de coordinación y cooperación de los diversos cuerpos y servicios de seguridad en el municipio."},{"ref":"Art. 11.4 i 12.1 Llei 4/2003","law":"Llei 4/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-9620","quote":"En todo caso, las fuerzas y cuerpos de seguridad deben actuar bajo las órdenes inmediatas de los mandos orgánicos respectivos. […] Los municipios de una misma región policial deben integrarse en una comisión regional de seguridad."}]}]},{"n":"8","title":"Plans de seguretat","blocks":[{"text":"El Govern aprova el Pla general de seguretat de Catalunya, a proposta del conseller i amb coneixement previ de la Comissió del Govern per a la Seguretat i del Consell de Seguretat (art. 15.1). Té periodicitat quadriennal, llevat que s''hagi de modificar abans per urgència o necessitat, fixa les directrius per als plans locals i regionals i s''ha de presentar al Parlament (art. 15.3 a 15.5).","refs":[{"ref":"Art. 15.3 i 15.5 Llei 4/2003","law":"Llei 4/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-9620","quote":"El Plan de seguridad de Cataluña tiene periodicidad cuatrienal, sin perjuicio de que, por razones de urgencia o de necesidad, deba modificarse antes de haber transcurrido dicho plazo. […] El Plan general de seguridad de Cataluña debe presentarse al Parlamento."}]},{"text":"Els plans de seguretat poden ser municipals, supramunicipals o regionals, i de caràcter general, sectorial, estacional i específic (art. 31.1). Les juntes locals aproven el pla general de seguretat del municipi i l''envien al conseller; els plans supramunicipals i regionals els aprova el conseller (art. 31.4, 31.6 i 31.7).","refs":[{"ref":"Art. 31.1 Llei 4/2003","law":"Llei 4/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-9620","quote":"1. Los planes de seguridad pueden ser municipales, supramunicipales o regionales, de carácter general, sectorial, estacional y específico."},{"ref":"Art. 31.7 Llei 4/2003","law":"Llei 4/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-9620","quote":"La aprobación de planes de seguridad de ámbito supramunicipal o regional corresponde al consejero o consejera del departamento con competencias en materia de seguridad pública, salvo el Plan general de seguridad de Cataluña, que corresponde al Gobierno"}]}]},{"n":"9","title":"Mapa policial: àrees bàsiques i regions policials","blocks":[{"text":"El Govern aprova per decret el mapa policial de Catalunya, que organitza el territori en àrees bàsiques policials i en regions policials (art. 18). L''àrea bàsica policial és la unitat mínima, geogràfica i poblacional, amb serveis bàsics d''atenció primària en prevenció, seguretat ciutadana, control del trànsit i investigació de primer nivell (art. 19.1). L''agrupació de diverses àrees bàsiques forma una regió policial, amb una comissaria regional (art. 20.1).","refs":[{"ref":"Art. 18 Llei 4/2003","law":"Llei 4/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-9620","quote":"El Gobierno debe aprobar por decreto el mapa policial de Cataluña, de acuerdo con las disposiciones del Plan territorial general de Cataluña. El mapa policial organiza el territorio de Cataluña en áreas básicas policiales y en regiones policiales"},{"ref":"Art. 19.1 Llei 4/2003","law":"Llei 4/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-9620","quote":"1. El área básica policial es la unidad mínima, geográfica y poblacional, dotada de unos servicios básicos para la atención primaria de las demandas de prevención, seguridad ciudadana, control del tráfico e investigación de primer nivel."},{"ref":"Art. 20.1 Llei 4/2003","law":"Llei 4/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-9620","quote":"La agrupación de varias áreas básicas policiales, de acuerdo con criterios del Plan territorial general de Cataluña, forma una región policial."}]}]},{"n":"10","title":"Relacions entre administracions: coordinació, assistència i convenis","blocks":[{"text":"El Govern, per mitjà del departament, fa efectiva la coordinació de les policies locals (art. 25.1), que inclou homogeneïtzar mitjans i uniformitat, fixar normes bàsiques d''estructura i d''accés, formació i promoció, i determinar per reglament, amb informe previ de la Comissió de Policia, els tipus d''armes, els dipòsits i les mesures de seguretat (art. 25.2). La llei crea també el Registre de les policies locals (art. 25 bis) i obliga cada agent a portar un document d''acreditació professional amb el municipi, la categoria i el número de registre individual (art. 25 ter).","refs":[{"ref":"Art. 25.2.c Llei 4/2003","law":"Llei 4/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-9620","quote":"c) Determinar por reglamento, previo informe de la Comisión de Policía de Cataluña, los tipos de armas que deben utilizar las policías locales"},{"ref":"Art. 25 bis.1 Llei 4/2003","law":"Llei 4/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-9620","quote":"Se crea el Registro de las policías locales de Cataluña"},{"ref":"Art. 25 ter Llei 4/2003","law":"Llei 4/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-9620","quote":"En este documento debe figurar, como mínimo, el municipio de pertenencia, la identificación de la categoría profesional y el número de registro individual."}]},{"text":"Els Mossos i les policies locals s''han de prestar l''assistència mútua que requereixi l''exercici eficaç de les seves funcions (art. 26.2); el conveni només en concreta l''abast i les modalitats, per exemple el suport dels Mossos als municipis sense policia local (art. 26.3). Els convenis entre el departament i els ajuntaments els signen el conseller i l''alcalde i s''han de publicar al DOGC en el termini d''un mes (art. 27.6 i 27.7).","refs":[{"ref":"Art. 26.2 Llei 4/2003","law":"Llei 4/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-9620","quote":"2. La Policía de la Generalidad-Mossos d''Esquadra y las policías locales deben prestarse la asistencia mutua que el ejercicio eficaz de las funciones respectivas requiera."},{"ref":"Art. 27.7 Llei 4/2003","law":"Llei 4/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-9620","quote":"Los convenios deben publicarse en el Diari Oficial de la Generalitat de Catalunya en el plazo de un mes a contar del momento en que se firmen."}]},{"text":"L''article 28 delimita serveis. Són funcions pròpies de les policies locals, entre altres, protegir les autoritats municipals i vigilar-ne els edificis, la policia de trànsit urbà, la policia administrativa municipal (sobretot mediambiental), la policia comunitària i la de policia judicial, especialment en trànsit; els Mossos tenen la de trànsit interurbà. Són compartides la policia de proximitat, la resolució amistosa de conflictes privats i la vigilància d''espais públics (art. 28.4).","refs":[{"ref":"Art. 28.3 Llei 4/2003","law":"Llei 4/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-9620","quote":"b) Las de policía de tráfico urbano. c) Las de policía administrativa en el ámbito de las competencias municipales y, especialmente, las relacionadas con la normativa medioambiental."},{"ref":"Art. 28.2.e Llei 4/2003","law":"Llei 4/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-9620","quote":"e) Las de policía de tráfico interurbano."},{"ref":"Art. 28.4 Llei 4/2003","law":"Llei 4/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-9620","quote":"a) Las de policía de proximidad y el auxilio y asistencia a los ciudadanos. b) La intervención en la resolución amistosa de conflictos privados, si son requeridas para ello. c) La vigilancia de espacios públicos."}]},{"text":"La Generalitat ha de tenir un centre integrat i permanent d''atenció d''emergències, protecció civil, policia i urgències sanitàries, i el telèfon unificat 112 ha de ser d''accés universal i gratuït a tot Catalunya (art. 30). Els ajuntaments amb policia local han d''enviar al departament i fer pública, dins el primer trimestre de cada any, la memòria de serveis, les dades registrals i les dotacions (art. 24.6).","refs":[{"ref":"Art. 30.2 Llei 4/2003","law":"Llei 4/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-9620","quote":"2. El número de teléfono unificado 112, de acuerdo con la normativa de la comunidad europea, debe ser de acceso universal y gratuito para el conjunto del territorio y de la población de Cataluña."},{"ref":"Art. 24.6 Llei 4/2003","law":"Llei 4/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-9620","quote":"Las corporaciones locales que dispongan de policía local deben enviar al departamento titular de las competencias en materia de seguridad pública y hacer pública, dentro del primer trimestre de cada año"}]}]},{"n":"11","title":"Relacions amb els ciutadans","blocks":[{"text":"El capítol V reconeix el dret dels ciutadans a participar en la seguretat pública per mitjà de les entitats representades al Consell de Seguretat, a les juntes locals i a les comissions regionals (art. 32.1), i el dret a ser informats de les situacions d''especial risc i de les mesures preventives (art. 33.1). Poden adreçar queixes i peticions a les autoritats de seguretat sobre els serveis i l''actuació dels agents (art. 34.1). La Generalitat ha d''establir, amb informe previ del Consell de Seguretat, la Carta de serveis públics de seguretat (art. 36).","refs":[{"ref":"Art. 32.1 Llei 4/2003","law":"Llei 4/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-9620","quote":"Los ciudadanos tienen derecho a participar en las tareas de seguridad pública mediante las asociaciones y entidades que tienen representación en el Consejo de Seguridad de Cataluña, las juntas locales y las comisiones regionales de seguridad."},{"ref":"Art. 34.1 Llei 4/2003","law":"Llei 4/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-9620","quote":"Los ciudadanos pueden dirigir a las autoridades de seguridad las quejas y peticiones que crean oportunas sobre la prestación de los diversos servicios de seguridad y la actuación de los agentes."},{"ref":"Art. 36 Llei 4/2003","law":"Llei 4/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-9620","quote":"La Generalidad debe establecer, previo informe del Consejo de Seguridad de Cataluña, la Carta de servicios públicos de seguridad"}]}]},{"n":"12","title":"L''Institut de Seguretat Pública de Catalunya: naturalesa, òrgans, funcions i formació","blocks":[{"text":"La Llei 10/2007 crea l''Institut de Seguretat Pública de Catalunya (ISPC) com a entitat autònoma de caràcter administratiu adscrita al departament competent en seguretat pública, amb personalitat jurídica pròpia (art. 1). Succeeix l''Escola de Policia de Catalunya, i les referències legals a l''Escola s''entenen fetes a l''Institut, que pot continuar usant aquesta denominació en la formació policial (disposicions addicionals primera i cinquena). On la Llei 4/2003 (art. 14) o la Llei 16/1991 diuen «Escola de Policia», avui cal llegir ISPC.","refs":[{"ref":"Art. 1.1 i 1.2 Llei 10/2007","law":"Llei 10/2007","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2007-15546","quote":"1. Se crea el Instituto de Seguridad Pública de Cataluña como entidad autónoma de carácter administrativo adscrita al departamento competente en materia de seguridad pública. 2. El Instituto de Seguridad Pública de Cataluña tiene personalidad jurídica propia y plena capacidad de obrar para el cumplimiento de sus finalidades."},{"ref":"Disposició addicional primera Llei 10/2007","law":"Llei 10/2007","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2007-15546","quote":"Las referencias que la legislación vigente hace a la Escuela de Policía de Cataluña y a la Escuela de Bomberos y Seguridad Civil de Cataluña se entienden hechas al Instituto de Seguridad Pública de Cataluña."}]},{"text":"La seva finalitat principal és formar els membres dels serveis de seguretat, de bombers, d''emergències, de protecció civil i de protecció ambiental, i promoure''n l''estudi i la recerca (art. 2). L''àmbit d''actuació inclou els membres dels cossos de policia de Catalunya, els vigilants i els auxiliars de la policia local i, també, protecció civil, bombers, agents rurals i altres col·lectius (art. 3.3). Programa la formació bàsica, la de promoció i comandament, l''especialització i la formació contínua (art. 4.1.j) i avalua les condicions psicològiques per portar arma de foc (art. 4.1.c).","refs":[{"ref":"Art. 3.3.a Llei 10/2007","law":"Llei 10/2007","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2007-15546","quote":"a) Los miembros de los cuerpos de policía de Cataluña, los vigilantes y auxiliares de la policía local"},{"ref":"Art. 4.1.c i j Llei 10/2007","law":"Llei 10/2007","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2007-15546","quote":"c) Estudiar, identificar y definir los protocolos de evaluación para llevar un arma de fuego, coordinar su aplicación y evaluar las condiciones psicológicas que deben cumplir los miembros de los cuerpos de policía de Cataluña para llevar un arma de fuego. […] j) Programar, organizar y desarrollar la formación básica, la formación para la promoción y el mando, la formación para la especialización y la formación continua"}]},{"text":"Els òrgans de govern són el president, els vicepresidents, el Consell de Direcció i el director (art. 6). El president és el conseller competent en seguretat pública (art. 7.1), i el director el nomena i el cessa el Govern a proposta del conseller, amb rang de director general (art. 11).","refs":[{"ref":"Art. 7.1 Llei 10/2007","law":"Llei 10/2007","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2007-15546","quote":"1. El presidente o presidenta del Instituto de Seguridad Pública de Cataluña es el consejero o consejera del departamento competente en materia de seguridad pública."},{"ref":"Art. 11 Llei 10/2007","law":"Llei 10/2007","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2007-15546","quote":"El Gobierno, a propuesta del consejero o consejera del departamento competente en materia de seguridad pública, nombra y cesa al director o directora del Instituto de Seguridad Pública de Cataluña."}]},{"text":"Per accedir a la categoria d''agent cal superar un curs selectiu a l''Escola (avui ISPC), del qual queden exempts els aspirants que ja tinguin el diploma del curs bàsic (art. 29.3 Llei 16/1991). La qualificació del curs és d''apte o no apte (art. 28.3 Decret 233/2002), i durant el curs els aspirants a agent cobren les retribucions bàsiques del subgrup C1. Les promocions internes a caporal, sergent i sotsinspector exigeixen dos anys d''antiguitat i el curs específic corresponent (art. 30.1 Llei 16/1991).","refs":[{"ref":"Art. 29.3 Llei 16/1991","law":"Llei 16/1991","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343","quote":"3. Es requisito indispensable, en cualquier caso, superar en la oposición un curso selectivo en la Escuela de Policía de Cataluña, del cual quedan exentos los aspirantes que en la fase de admisión aporten un diploma acreditativo de haber superado el curso básico de la Escuela de Policía de Cataluña."},{"ref":"Art. 28.3 Decret 233/2002","law":"Decret 233/2002","url":"https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=286781","quote":"28.3 La qualificació dels cursos selectius serà d’apte/a o no apte/a"},{"ref":"Disposició addicional setena 4 Llei 16/1991","law":"Llei 16/1991","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343","quote":"Los aspirantes a la categoría de agente deben percibir, durante la realización del curso selectivo en el Instituto de Seguridad Pública de Cataluña, las retribuciones básicas correspondientes al subgrupo C1."},{"ref":"Art. 30.1 Llei 16/1991","law":"Llei 16/1991","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343","quote":"El acceso a las categorías de Cabo, de Sargento y de Subinspector se realiza por promoción interna, mediante concurso-oposición, entre los miembros del Cuerpo que tengan un mínimo de dos años de antigüedad en la categoría inmediatamente inferior respectiva"}]}]},{"n":"R","title":"Recorda per a l''examen","blocks":[{"text":"El sistema el formen autoritats, cossos i serveis de seguretat (públics o privats) i òrgans de coordinació i participació.","refs":[{"ref":"Art. 3.1 Llei 4/2003","law":"Llei 4/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-9620","quote":"b) Los cuerpos policiales y demás servicios, públicos o privados, de seguridad."}]},{"text":"En l''àmbit local, l''alcalde és autoritat superior de seguretat i exerceix el comandament superior de la policia local.","refs":[{"ref":"Art. 4.4.d Llei 4/2003","law":"Llei 4/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-9620","quote":"d) Ejercer el mando superior de la policía local."}]},{"text":"Junta de Seguretat: coordinació Mossos-Estat. Comissió de Policia: coordinació Mossos-policies locals (conseller + 5 + 5). Consell de Seguretat: òrgan consultiu i de participació superior.","refs":[{"ref":"Art. 8.1 Llei 4/2003","law":"Llei 4/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-9620","quote":"órgano colegiado consultivo superior en materia de coordinación entre la Policía de la Generalidad-Mossos d''Esquadra y las policías locales en Cataluña."}]},{"text":"Junta local: obligatòria si hi ha policia local, la presideix l''alcalde amb veu i vot, es reuneix cada trimestre i acorda per unanimitat.","refs":[{"ref":"Art. 9.8 Llei 4/2003","law":"Llei 4/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-9620","quote":"Los acuerdos de la junta local de seguridad deben adoptarse por unanimidad y tienen carácter ejecutivo."}]},{"text":"La mesa de coordinació operativa és l''òrgan permanent i estable de coordinació que crea la junta local.","refs":[{"ref":"Art. 11.1 Llei 4/2003","law":"Llei 4/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-9620","quote":"como órgano permanente y estable de coordinación y cooperación de los diversos cuerpos y servicios de seguridad en el municipio."}]},{"text":"El mapa policial l''aprova el Govern per decret; la unitat mínima és l''àrea bàsica policial.","refs":[{"ref":"Art. 18 Llei 4/2003","law":"Llei 4/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-9620","quote":"El Gobierno debe aprobar por decreto el mapa policial de Cataluña"}]},{"text":"El Pla general de seguretat és quadriennal i es presenta al Parlament.","refs":[{"ref":"Art. 15.3 Llei 4/2003","law":"Llei 4/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-9620","quote":"El Plan de seguridad de Cataluña tiene periodicidad cuatrienal"}]},{"text":"Telèfon unificat d''emergències: 112, universal i gratuït.","refs":[{"ref":"Art. 30.2 Llei 4/2003","law":"Llei 4/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-9620","quote":"debe ser de acceso universal y gratuito para el conjunto del territorio y de la población de Cataluña."}]},{"text":"L''ISPC és una entitat autònoma administrativa; el presideix el conseller i substitueix l''Escola de Policia de Catalunya.","refs":[{"ref":"Art. 1.1 Llei 10/2007","law":"Llei 10/2007","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2007-15546","quote":"como entidad autónoma de carácter administrativo adscrita al departamento competente en materia de seguridad pública."}]}]}]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2003-9620'), 'https://www.boe.es/buscar/act.php?id=BOE-A-2003-9620', null, null, null, 'Otras normas citadas: Llei 10/2007 (https://www.boe.es/buscar/act.php?id=BOE-A-2007-15546)'
  from public.topics t where t.slug = 'plcat-t09-sistema-seguretat-catalunya'
