insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('policia-local') and t.slug = 'plcat-t11-seguretat-ciutadana-1' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, lessons, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"Objecte i finalitats de la LO 4/2015 (arts. 1-3)"},{"n":"2","title":"Autoritats i competències (arts. 4-7)"},{"n":"3","title":"Documentació: el DNI i el passaport (arts. 8-13)"},{"n":"4","title":"Actuacions per al manteniment i restabliment de la seguretat (art. 14)"},{"n":"5","title":"Entrada en domicilis i edificis d''organismes oficials (art. 15)"},{"n":"6","title":"Identificació de persones (art. 16)"},{"n":"7","title":"Restricció del trànsit, controls i zones de seguretat (arts. 17-19)"},{"n":"8","title":"Escorcolls externs (art. 20)"}]'::jsonb, '["Art. 1.1 LO 4/2015: «y su salvaguarda, como bien jurídico de carácter colectivo, es función del Estado, con sujeción a la Constitución y a las Leyes.»","Art. 2.2 LO 4/2015: «2. En particular, quedan fuera del ámbito de aplicación de esta Ley las prescripciones que tienen por objeto velar por el buen orden de los espectáculos y la protección de las personas y bienes a través de una acción administrativa ordinaria»","Art. 4.1 LO 4/2015: «se regirá por los principios de legalidad, igualdad de trato y no discriminación, oportunidad, proporcionalidad, eficacia, eficiencia y responsabilidad, y se someterá al control administrativo y jurisdiccional.»","Art. 5.3 LO 4/2015: «3. Serán autoridades y órganos competentes, a los efectos de esta Ley, los correspondientes de las comunidades autónomas que hayan asumido competencias para la protección de personas y bienes y para el mantenimiento de la seguridad ciudadana y cuenten con un cuerpo de policía propio.»","Art. 7.2 LO 4/2015: «especialmente en los casos de grave calamidad pública o catástrofe extraordinaria, siempre que ello no implique riesgo personal para los mismos.»","Art. 8.1 LO 4/2015: «Es el único documento con suficiente valor por sí solo para la acreditación, a todos los efectos, de la identidad y los datos personales de su titular.»","Art. 9.1 LO 4/2015: «1. El Documento Nacional de Identidad es obligatorio a partir de los catorce años.»","Art. 8.2 LO 4/2015: «sin que en ningún caso, puedan ser relativos a la raza, etnia, religión, creencias, opinión, ideología, discapacidad, orientación o identidad sexual, o afiliación política o sindical.»","Art. 9.2 LO 4/2015: «De su sustracción o extravío deberá darse cuenta tan pronto como sea posible a la comisaría de Policía o puesto de las Fuerzas y Cuerpos de Seguridad más próximo.»","Art. 15.2 LO 4/2015: «2. Será causa legítima suficiente para la entrada en domicilio la necesidad de evitar daños inminentes y graves a las personas y a las cosas, en supuestos de catástrofe, calamidad, ruina inminente u otros semejantes de extrema y urgente necesidad.»","Art. 15.3 LO 4/2015: «3. Para la entrada en edificios ocupados por organismos oficiales o entidades públicas, no será preciso el consentimiento de la autoridad o funcionario que los tuviere a su cargo.»","Art. 16.1 LO 4/2015: «a) Cuando existan indicios de que han podido participar en la comisión de una infracción.»","Art. 16.2 LO 4/2015: «a los solos efectos de su identificación y por el tiempo estrictamente necesario, que en ningún caso podrá superar las seis horas.»","Art. 16.3 LO 4/2015: «Los asientos de este libro-registro se cancelarán de oficio a los tres años.»","Art. 16.4 LO 4/2015: «se les deberá expedir a su salida un volante acreditativo del tiempo de permanencia en ellas, la causa y la identidad de los agentes actuantes.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[{"n":"1","title":"Objecte de la Llei orgànica 4/2015","blocks":[{"text":"La LO 4/2015, de protecció de la seguretat ciutadana, parteix d''una idea: la seguretat ciutadana és un requisit indispensable per exercir plenament els drets fonamentals i les llibertats públiques, i la seva salvaguarda, com a bé jurídic de caràcter col·lectiu, és funció de l''Estat, amb subjecció a la Constitució i a les lleis (art. 1.1). L''objecte de la llei és regular un conjunt plural d''actuacions per tutelar la seguretat ciutadana mitjançant la protecció de persones i béns i el manteniment de la tranquil·litat dels ciutadans (art. 1.2).","refs":[{"ref":"Art. 1.1 LO 4/2015","law":"LO 4/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442","quote":"1. La seguridad ciudadana es un requisito indispensable para el pleno ejercicio de los derechos fundamentales y las libertades públicas, y su salvaguarda, como bien jurídico de carácter colectivo, es función del Estado, con sujeción a la Constitución y a las Leyes."},{"ref":"Art. 1.2 LO 4/2015","law":"LO 4/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442","quote":"mediante la protección de personas y bienes y el mantenimiento de la tranquilidad de los ciudadanos."}]},{"text":"Avís de vigència: el text consolidat del BOE inclou les sentències del Tribunal Constitucional 172/2020 i 13/2021, que van anul·lar o interpretar alguns preceptes del capítol V (es veuen al tema 12). A més, l''article 6 encara remet a la Llei 30/1992, que va ser derogada expressament per la Llei 39/2015.","refs":[{"ref":"Art. 6 LO 4/2015","law":"LO 4/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442","quote":"de conformidad con lo dispuesto en la Ley Orgánica 2/1986, de 13 de marzo, y en la Ley 30/1992, de 26 de noviembre, de Régimen Jurídico de las Administraciones Públicas y del Procedimiento Administrativo Común."},{"ref":"Disposició derogatòria única 2.a Llei 39/2015","law":"Llei 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"2. Quedan derogadas expresamente las siguientes disposiciones: a) Ley 30/1992, de 26 de noviembre, de Régimen Jurídico de las Administraciones Públicas y del Procedimiento Administrativo Común."}]}]},{"n":"2","title":"Àmbit d''aplicació","blocks":[{"text":"La llei s''aplica a tot el territori de l''Estat, sense perjudici de les competències que hagin assumit les comunitats autònomes (art. 2.1). En queden fora, en particular, les prescripcions que vetllen pel bon ordre dels espectacles i la protecció de persones i béns mitjançant una acció administrativa ordinària, encara que hi intervinguin les forces i cossos de seguretat, sempre que aquesta intervenció formi part del sistema preventiu habitual del control de l''espectacle (art. 2.2). Tampoc no desplaça els règims de seguretat aèria, marítima, ferroviària, viària o dels transports, ni la regulació dels estats d''alarma, excepció i setge (art. 2.3).","refs":[{"ref":"Art. 2.2 LO 4/2015","law":"LO 4/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442","quote":"2. En particular, quedan fuera del ámbito de aplicación de esta Ley las prescripciones que tienen por objeto velar por el buen orden de los espectáculos y la protección de las personas y bienes a través de una acción administrativa ordinaria, aun cuando la misma pueda conllevar la intervención de las Fuerzas y Cuerpos de Seguridad, siempre que ésta se conciba como elemento integrante del sistema preventivo habitual del control del espectáculo."},{"ref":"Art. 2.3 LO 4/2015","law":"LO 4/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442","quote":"como la seguridad aérea, marítima, ferroviaria, vial o en los transportes, quedando, en todo caso, salvaguardadas las disposiciones referentes a la defensa nacional y la regulación de los estados de alarma, excepción y sitio."}]}]},{"n":"3","title":"Fins de la llei","blocks":[{"text":"L''article 3 enumera nou fins. Entre ells: protegir el lliure exercici dels drets fonamentals i les llibertats públiques; garantir el funcionament normal de les institucions; preservar la seguretat i la convivència ciutadanes; protegir persones i béns, amb atenció especial als menors i a les persones amb discapacitat; assegurar la utilització pacífica de les vies i espais públics; garantir la normalitat dels serveis bàsics; prevenir delictes i infraccions i sancionar les de la llei, i la transparència dels poders públics.","refs":[{"ref":"Art. 3 LO 4/2015","law":"LO 4/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442","quote":"a) La protección del libre ejercicio de los derechos fundamentales y las libertades públicas y los demás derechos reconocidos y amparados por el ordenamiento jurídico. b) La garantía del normal funcionamiento de las instituciones. c) La preservación de la seguridad y la convivencia ciudadanas."},{"ref":"Art. 3 LO 4/2015","law":"LO 4/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442","quote":"e) La protección de las personas y bienes, con especial atención a los menores y a las personas con discapacidad necesitadas de especial protección. f) La pacífica utilización de vías y demás bienes demaniales"},{"ref":"Art. 3.i LO 4/2015","law":"LO 4/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442","quote":"i) La transparencia en la actuación de los poderes públicos en materia de seguridad ciudadana."}]}]},{"n":"4","title":"Principis rectors de l''actuació","blocks":[{"text":"L''exercici de les potestats de la llei es regeix per set principis: legalitat, igualtat de tracte i no-discriminació, oportunitat, proporcionalitat, eficàcia, eficiència i responsabilitat, i se sotmet al control administratiu i jurisdiccional (art. 4.1). La discrecionalitat no hi figura. Els capítols III i V s''han d''interpretar de la manera més favorable a l''efectivitat dels drets fonamentals, sobretot els de reunió i manifestació, les llibertats d''expressió i informació, la llibertat sindical i el dret de vaga.","refs":[{"ref":"Art. 4.1 LO 4/2015","law":"LO 4/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442","quote":"se regirá por los principios de legalidad, igualdad de trato y no discriminación, oportunidad, proporcionalidad, eficacia, eficiencia y responsabilidad, y se someterá al control administrativo y jurisdiccional."},{"ref":"Art. 4.1 LO 4/2015","law":"LO 4/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442","quote":"En particular, las disposiciones de los capítulos III y V deberán interpretarse y aplicarse del modo más favorable a la plena efectividad de los derechos fundamentales y libertades públicas, singularmente de los derechos de reunión y manifestación, las libertades de expresión e información, la libertad sindical y el derecho de huelga."}]},{"text":"Els agents estan subjectes als principis bàsics d''actuació de l''article 5 de la LO 2/1986 (art. 4.2). La intervenció es justifica per una amenaça concreta o un comportament objectivament perillós que, raonablement, pugui causar un perjudici real per a la seguretat ciutadana (art. 4.3).","refs":[{"ref":"Art. 4.2 i 4.3 LO 4/2015","law":"LO 4/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442","quote":"la actuación de los miembros de las Fuerzas y Cuerpos de Seguridad está sujeta a los principios básicos de actuación regulados en el artículo 5 de la Ley Orgánica 2/1986 […] La actividad de intervención se justifica por la existencia de una amenaza concreta o de un comportamiento objetivamente peligroso que, razonablemente, sea susceptible de provocar un perjuicio real para la seguridad ciudadana"}]}]},{"n":"5","title":"Autoritats i òrgans competents i cooperació","blocks":[{"text":"Al Govern, per mitjà del Ministeri de l''Interior, li correspon la preparació, la direcció i l''execució de la política de seguretat ciutadana (art. 5.1). En l''Administració de l''Estat són autoritats el ministre de l''Interior, el secretari d''Estat de Seguretat, els titulars d''òrgans directius de l''Interior, els delegats del Govern a les comunitats autònomes i els subdelegats (art. 5.2).","refs":[{"ref":"Art. 5.2 LO 4/2015","law":"LO 4/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442","quote":"a) El Ministro del Interior. b) El Secretario de Estado de Seguridad. c) Los titulares de los órganos directivos del Ministerio del Interior que tengan atribuida tal condición, en virtud de disposiciones legales o reglamentarias. d) Los Delegados del Gobierno en las comunidades autónomas y en las Ciudades de Ceuta y Melilla. e) Los Subdelegados del Gobierno en las provincias y los Directores Insulares."}]},{"text":"També són autoritats competents les de les comunitats autònomes que han assumit competències de protecció de persones i béns i de manteniment de la seguretat ciutadana i tenen cos de policia propi (art. 5.3), com Catalunya. Les autoritats locals exerceixen les facultats que els donen la LO 2/1986 i la legislació de règim local, espectacles i activitats (art. 5.4). Les administracions es relacionen segons els principis de cooperació i lleialtat institucional (art. 6).","refs":[{"ref":"Art. 5.3 LO 4/2015","law":"LO 4/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442","quote":"3. Serán autoridades y órganos competentes, a los efectos de esta Ley, los correspondientes de las comunidades autónomas que hayan asumido competencias para la protección de personas y bienes y para el mantenimiento de la seguridad ciudadana y cuenten con un cuerpo de policía propio."},{"ref":"Art. 5.4 LO 4/2015","law":"LO 4/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442","quote":"las autoridades locales ejercerán las facultades que les corresponden, de acuerdo con la Ley Orgánica 2/1986, de 13 de marzo, y la legislación de régimen local, espectáculos públicos, actividades recreativas y actividades clasificadas."},{"ref":"Art. 6 LO 4/2015","law":"LO 4/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442","quote":"se regirán, en sus relaciones, por los principios de cooperación y lealtad institucional"}]}]},{"n":"6","title":"Deure de col·laboració","blocks":[{"text":"Totes les autoritats i funcionaris han de col·laborar amb les autoritats de seguretat i, si per raó del càrrec coneixen fets que pertorbin greument la seguretat ciutadana, els han de comunicar immediatament a l''autoritat competent (art. 7.1). Les autoritats i els agents poden demanar ajuda i col·laboració als particulars en la mesura necessària, especialment en casos de calamitat pública greu o catàstrofe extraordinària, sempre que no impliqui risc personal per a ells; qui en pateixi danys ha de ser indemnitzat (art. 7.2). La seguretat privada té un deure especial d''auxiliar les forces i cossos de seguretat (art. 7.3).","refs":[{"ref":"Art. 7.1 LO 4/2015","law":"LO 4/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442","quote":"estarán obligados a ponerlo inmediatamente en conocimiento de la autoridad competente."},{"ref":"Art. 7.2 LO 4/2015","law":"LO 4/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442","quote":"2. Las autoridades y órganos competentes y los miembros de las Fuerzas y Cuerpos de Seguridad podrán recabar de los particulares su ayuda y colaboración en la medida necesaria para el cumplimiento de los fines previstos en esta Ley, especialmente en los casos de grave calamidad pública o catástrofe extraordinaria, siempre que ello no implique riesgo personal para los mismos. Quienes sufran daños y perjuicios por estas causas serán indemnizados de acuerdo con las leyes."},{"ref":"Art. 7.3 LO 4/2015","law":"LO 4/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442","quote":"tienen un especial deber de auxiliar a las Fuerzas y Cuerpos de Seguridad en el ejercicio de sus funciones"}]}]},{"n":"7","title":"El document nacional d''identitat","blocks":[{"text":"Els espanyols tenen dret que se''ls expedeixi el DNI, que és un document públic i oficial i l''únic amb valor suficient per si sol per acreditar, a tots els efectes, la identitat i les dades personals del titular (art. 8.1). Hi figuren la fotografia, la signatura i les dades que fixi el reglament, però mai dades relatives a raça, ètnia, religió, creences, opinió, ideologia, discapacitat, orientació o identitat sexual, o afiliació política o sindical (art. 8.2). També permet la identificació i la signatura electròniques als majors d''edat amb plena capacitat i als menors emancipats (art. 8.3).","refs":[{"ref":"Art. 8.1 LO 4/2015","law":"LO 4/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442","quote":"El Documento Nacional de Identidad es un documento público y oficial y tendrá la protección que a estos otorgan las leyes. Es el único documento con suficiente valor por sí solo para la acreditación, a todos los efectos, de la identidad y los datos personales de su titular."},{"ref":"Art. 8.2 LO 4/2015","law":"LO 4/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442","quote":"sin que en ningún caso, puedan ser relativos a la raza, etnia, religión, creencias, opinión, ideología, discapacidad, orientación o identidad sexual, o afiliación política o sindical."}]},{"text":"El DNI és obligatori a partir dels catorze anys; és personal i intransferible, i el titular l''ha de mantenir vigent i custodiar-lo amb diligència; no se''n pot ser privat, ni temporalment, llevat que la llei prevegi substituir-lo per un altre document (art. 9.1). Qui està obligat a tenir-lo també ho està a exhibir-lo quan ho requereixin els agents per als fins de l''article 16.1, i en cas de sostracció o pèrdua n''ha de donar compte com més aviat millor a la comissaria o lloc de les forces i cossos de seguretat més pròxim (art. 9.2). L''expedeix la Direcció General de la Policia i està subjecte a taxa (art. 10).","refs":[{"ref":"Art. 9.1 LO 4/2015","law":"LO 4/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442","quote":"1. El Documento Nacional de Identidad es obligatorio a partir de los catorce años. Dicho documento es personal e intransferible, debiendo su titular mantenerlo en vigor y conservarlo y custodiarlo con la debida diligencia."},{"ref":"Art. 9.2 LO 4/2015","law":"LO 4/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442","quote":"De su sustracción o extravío deberá darse cuenta tan pronto como sea posible a la comisaría de Policía o puesto de las Fuerzas y Cuerpos de Seguridad más próximo."},{"ref":"Art. 10.2 i 10.3 LO 4/2015","law":"LO 4/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442","quote":"La competencia a que se refiere el apartado anterior será ejercida por la Dirección General de la Policía […] Su expedición está sujeta al pago de una tasa."}]}]},{"n":"8","title":"El passaport i la identitat dels estrangers","blocks":[{"text":"El passaport és un document públic, personal, individual i intransferible que acredita la identitat i la nacionalitat dels espanyols fora d''Espanya, i dins del territori la dels espanyols no residents (art. 11.1). Se''n pot denegar l''expedició, entre altres casos, als condemnats a penes privatives de llibertat no extingides sense autorització judicial o quan el jutge n''hagi acordat la retirada (art. 11.2). En cas de sostracció o pèrdua, s''ha de comunicar de manera immediata (art. 11.4). L''expedeix la Direcció General de la Policia a Espanya i les representacions diplomàtiques i consulars a l''estranger (art. 12.1).","refs":[{"ref":"Art. 11.1 LO 4/2015","law":"LO 4/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442","quote":"1. El pasaporte español es un documento público, personal, individual e intransferible que, salvo prueba en contrario, acredita la identidad y nacionalidad de los ciudadanos españoles fuera de España, y dentro del territorio nacional, las mismas circunstancias de los españoles no residentes."},{"ref":"Art. 11.4 LO 4/2015","law":"LO 4/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442","quote":"De su sustracción o extravío deberá darse cuenta de manera inmediata a las Fuerzas y Cuerpos de Seguridad"},{"ref":"Art. 12.1 LO 4/2015","law":"LO 4/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442","quote":"a) En el territorio nacional, a la Dirección General de la Policía. b) En el extranjero, a las Representaciones Diplomáticas y Consulares de España."}]},{"text":"Els estrangers tenen el dret i l''obligació de portar la documentació d''identitat del seu país i la que acrediti la seva situació regular a Espanya (art. 13.1). No se''ls en pot privar, llevat d''investigacions judicials penals (art. 13.2), i l''han d''exhibir quan els agents ho requereixin, sense perjudici de poder demostrar la identitat per altres mitjans (art. 13.3).","refs":[{"ref":"Art. 13.1 i 13.2 LO 4/2015","law":"LO 4/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442","quote":"tienen el derecho y la obligación de conservar y portar consigo la documentación que acredite su identidad expedida por las autoridades competentes del país de origen o de procedencia, así como la que acredite su situación regular en España. 2. Los extranjeros no podrán ser privados de su documentación de origen, salvo en el curso de investigaciones judiciales de carácter penal."}]}]},{"n":"9","title":"Ordres i prohibicions i entrada en domicili i edificis oficials","blocks":[{"text":"El capítol III (secció 1a, potestats generals de policia de seguretat) comença permetent a les autoritats dictar ordres i prohibicions i disposar les actuacions policials estrictament necessàries per als fins de la llei, per resolució degudament motivada (art. 14).","refs":[{"ref":"Art. 14 LO 4/2015","law":"LO 4/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442","quote":"podrán dictar las órdenes y prohibiciones y disponer las actuaciones policiales estrictamente necesarias para asegurar la consecución de los fines previstos en esta Ley, mediante resolución debidamente motivada."}]},{"text":"Els agents només poden entrar i registrar un domicili en els casos permesos per la Constitució i les lleis (art. 15.1). És causa legítima suficient la necessitat d''evitar danys imminents i greus a persones i coses en supòsits de catàstrofe, calamitat, ruïna imminent o altres d''extrema i urgent necessitat (art. 15.2); en aquest cas s''ha de remetre sense dilació l''acta o l''atestat a l''autoritat judicial (art. 15.4). Per entrar en edificis ocupats per organismes oficials o entitats públiques no cal el consentiment de l''autoritat o funcionari que els tingui al seu càrrec (art. 15.3).","refs":[{"ref":"Art. 15.2 LO 4/2015","law":"LO 4/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442","quote":"2. Será causa legítima suficiente para la entrada en domicilio la necesidad de evitar daños inminentes y graves a las personas y a las cosas, en supuestos de catástrofe, calamidad, ruina inminente u otros semejantes de extrema y urgente necesidad."},{"ref":"Art. 15.3 LO 4/2015","law":"LO 4/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442","quote":"3. Para la entrada en edificios ocupados por organismos oficiales o entidades públicas, no será preciso el consentimiento de la autoridad o funcionario que los tuviere a su cargo."},{"ref":"Art. 15.4 LO 4/2015","law":"LO 4/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442","quote":"remitirán sin dilación el acta o atestado que instruyan a la autoridad judicial competente."}]}]},{"n":"10","title":"Identificació de persones","blocks":[{"text":"Els agents poden requerir la identificació en dos supòsits (art. 16.1): quan hi ha indicis que la persona ha pogut participar en la comissió d''una infracció, i quan, per les circumstàncies, es considera raonablement necessari que acrediti la identitat per prevenir un delicte. Poden fer les comprovacions a la via pública, fins i tot identificar persones amb el rostre cobert, i han de respectar estrictament la proporcionalitat, la igualtat de tracte i la no-discriminació.","refs":[{"ref":"Art. 16.1 LO 4/2015","law":"LO 4/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442","quote":"a) Cuando existan indicios de que han podido participar en la comisión de una infracción. b) Cuando, en atención a las circunstancias concurrentes, se considere razonablemente necesario que acrediten su identidad para prevenir la comisión de un delito."},{"ref":"Art. 16.1 LO 4/2015","law":"LO 4/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442","quote":"En la práctica de la identificación se respetarán estrictamente los principios de proporcionalidad, igualdad de trato y no discriminación"}]},{"text":"Si no és possible identificar la persona per cap mitjà, ni telemàtic ni telefònic, o si es nega a identificar-se, els agents poden requerir-la perquè els acompanyi a les dependències policials més pròximes, només per identificar-la i pel temps estrictament necessari, que mai no pot superar les sis hores (art. 16.2). Se l''ha d''informar de manera immediata i comprensible del motiu.","refs":[{"ref":"Art. 16.2 LO 4/2015","law":"LO 4/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442","quote":"a los solos efectos de su identificación y por el tiempo estrictamente necesario, que en ningún caso podrá superar las seis horas."},{"ref":"Art. 16.2 LO 4/2015","law":"LO 4/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442","quote":"La persona a la que se solicite que se identifique será informada de modo inmediato y comprensible de las razones de dicha solicitud"}]},{"text":"A les dependències hi ha un llibre registre de les diligències d''identificació, amb els motius i la durada, les dades del qual només es comuniquen a l''autoritat judicial i al Ministeri Fiscal; cada mes s''envia al fiscal un extracte de les diligències, i els assentaments es cancel·len d''ofici als tres anys (art. 16.3). En sortir, la persona rep un volant que acredita el temps de permanència, la causa i la identitat dels agents (art. 16.4). La resistència o la negativa es regeix pel Codi penal, la LECrim i la mateixa llei (art. 16.5).","refs":[{"ref":"Art. 16.3 LO 4/2015","law":"LO 4/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442","quote":"El órgano competente de la Administración remitirá mensualmente al Ministerio Fiscal extracto de las diligencias de identificación con expresión del tiempo utilizado en cada una. Los asientos de este libro-registro se cancelarán de oficio a los tres años."},{"ref":"Art. 16.4 LO 4/2015","law":"LO 4/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442","quote":"se les deberá expedir a su salida un volante acreditativo del tiempo de permanencia en ellas, la causa y la identidad de los agentes actuantes."}]}]},{"n":"11","title":"Restricció del trànsit, controls, comprovacions i disposicions comunes","blocks":[{"text":"Els agents poden limitar o restringir la circulació o la permanència en vies o llocs públics i establir zones de seguretat si hi ha alteració de la seguretat o de la convivència, o indicis racionals que es pugui produir, pel temps imprescindible (art. 17.1). Per prevenir delictes d''especial gravetat o generadors d''alarma social, i per descobrir i detenir-ne els autors, es poden establir controls a vies, llocs o establiments públics quan sigui indispensable identificar persones, registrar vehicles o controlar superficialment efectes personals (art. 17.2).","refs":[{"ref":"Art. 17.1 LO 4/2015","law":"LO 4/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442","quote":"podrán limitar o restringir la circulación o permanencia en vías o lugares públicos y establecer zonas de seguridad en supuestos de alteración de la seguridad ciudadana o de la pacífica convivencia"},{"ref":"Art. 17.2 LO 4/2015","law":"LO 4/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442","quote":"2. Para la prevención de delitos de especial gravedad o generadores de alarma social, así como para el descubrimiento y detención de quienes hubieran participado en su comisión y proceder a la recogida de los instrumentos, efectos o pruebas, se podrán establecer controles en las vías, lugares o establecimientos públicos"}]},{"text":"També poden fer comprovacions en persones, béns i vehicles per impedir que es portin o utilitzin il·legalment armes, explosius o objectes perillosos, i ocupar temporalment mitjans d''agressió, fins i tot armes amb llicència (art. 18). Les diligències d''identificació, registre i comprovació no estan subjectes a les mateixes formalitats que la detenció (art. 19.1). Si s''aprehenen armes o drogues, es fa constar en una acta que ha de signar l''interessat; si s''hi nega, es deixa constància de la negativa, i l''acta gaudeix de presumpció de veracitat llevat de prova en contra (art. 19.2).","refs":[{"ref":"Art. 18.2 LO 4/2015","law":"LO 4/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442","quote":"podrán proceder a la ocupación temporal de cualesquiera objetos, instrumentos o medios de agresión, incluso de las armas que se porten con licencia, permiso o autorización si se estima necesario"},{"ref":"Art. 19.1 LO 4/2015","law":"LO 4/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442","quote":"no estarán sujetas a las mismas formalidades que la detención."},{"ref":"Art. 19.2 LO 4/2015","law":"LO 4/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442","quote":"si éste se negara a firmarla, se dejará constancia expresa de su negativa. El acta que se extienda gozará de presunción de veracidad de los hechos en ella consignados, salvo prueba en contrario."}]}]},{"n":"12","title":"Registres corporals externs","blocks":[{"text":"Es pot fer un registre corporal extern i superficial quan hi hagi indicis racionals que pot conduir a trobar instruments, efectes o altres objectes rellevants per a les funcions d''indagació i prevenció (art. 20.1). Llevat d''urgència per risc greu i imminent per als agents, l''ha de fer un agent del mateix sexe que la persona registrada, i si cal deixar a la vista parts del cos normalment cobertes, s''ha de fer en un lloc reservat i fora de la vista de tercers, amb constància escrita (art. 20.2).","refs":[{"ref":"Art. 20.1 LO 4/2015","law":"LO 4/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442","quote":"1. Podrá practicarse el registro corporal externo y superficial de la persona cuando existan indicios racionales para suponer que puede conducir al hallazgo de instrumentos, efectos u otros objetos relevantes"},{"ref":"Art. 20.2 LO 4/2015","law":"LO 4/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442","quote":"a) El registro se realizará por un agente del mismo sexo que la persona sobre la que se practique esta diligencia. b) Y si exigiera dejar a la vista partes del cuerpo normalmente cubiertas por ropa, se efectuará en un lugar reservado y fuera de la vista de terceros."}]},{"text":"El registre ha de respectar els principis de l''article 16.1 i el d''injerència mínima, causant el menor perjudici a la intimitat i la dignitat, i la persona ha de ser informada de les raons (art. 20.3). Es pot fer contra la voluntat de l''afectat, amb les mesures de compulsió indispensables, d''acord amb els principis d''idoneïtat, necessitat i proporcionalitat (art. 20.4).","refs":[{"ref":"Art. 20.3 LO 4/2015","law":"LO 4/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442","quote":"así como el de injerencia mínima, y se realizarán del modo que cause el menor perjuicio a la intimidad y dignidad de la persona afectada"},{"ref":"Art. 20.4 LO 4/2015","law":"LO 4/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442","quote":"podrán llevarse a cabo contra la voluntad del afectado, adoptando las medidas de compulsión indispensables, conforme a los principios de idoneidad, necesidad y proporcionalidad."}]}]},{"n":"R","title":"Recorda per a l''examen","blocks":[{"text":"La salvaguarda de la seguretat ciutadana és funció de l''Estat.","refs":[{"ref":"Art. 1.1 LO 4/2015","law":"LO 4/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442","quote":"como bien jurídico de carácter colectivo, es función del Estado"}]},{"text":"Principis de l''art. 4.1: legalitat, igualtat de tracte i no-discriminació, oportunitat, proporcionalitat, eficàcia, eficiència i responsabilitat.","refs":[{"ref":"Art. 4.1 LO 4/2015","law":"LO 4/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442","quote":"legalidad, igualdad de trato y no discriminación, oportunidad, proporcionalidad, eficacia, eficiencia y responsabilidad"}]},{"text":"El DNI és obligatori des dels catorze anys i és l''únic document que per si sol acredita la identitat.","refs":[{"ref":"Art. 9.1 LO 4/2015","law":"LO 4/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442","quote":"es obligatorio a partir de los catorce años."}]},{"text":"Entrada en domicili sense autorització: danys imminents i greus per catàstrofe, calamitat, ruïna imminent o similars.","refs":[{"ref":"Art. 15.2 LO 4/2015","law":"LO 4/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442","quote":"en supuestos de catástrofe, calamidad, ruina inminente u otros semejantes de extrema y urgente necesidad."}]},{"text":"Trasllat per identificar: màxim sis hores; volant a la sortida.","refs":[{"ref":"Art. 16.2 LO 4/2015","law":"LO 4/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442","quote":"que en ningún caso podrá superar las seis horas."}]},{"text":"Llibre registre: extracte mensual al fiscal i cancel·lació d''ofici als tres anys.","refs":[{"ref":"Art. 16.3 LO 4/2015","law":"LO 4/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442","quote":"Los asientos de este libro-registro se cancelarán de oficio a los tres años."}]},{"text":"Identificació i registres no tenen les formalitats de la detenció; l''acta té presumpció de veracitat.","refs":[{"ref":"Art. 19.2 LO 4/2015","law":"LO 4/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442","quote":"gozará de presunción de veracidad de los hechos en ella consignados, salvo prueba en contrario."}]},{"text":"Escorcoll extern: agent del mateix sexe, llevat d''urgència per risc greu i imminent.","refs":[{"ref":"Art. 20.2 LO 4/2015","law":"LO 4/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442","quote":"Salvo que exista una situación de urgencia por riesgo grave e inminente para los agentes:"}]}]}]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442'), 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442', null, null, null, null
