insert into public.sources (title, url, kind, publisher, published_on) values ('Ley Orgánica 4/2015, de 30 de marzo, de protección de la seguridad ciudadana (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('plcat-t12-seguretat-ciutadana-2', 'Tema 12. La Llei orgànica 4/2015 (II): potestats de policia de seguretat, reunions i manifestacions i règim sancionador') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('policia-local') and t.slug = 'plcat-t12-seguretat-ciutadana-2' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, lessons, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"Principis de les potestats especials de policia (art. 21)"},{"n":"2","title":"Reunions i manifestacions: dissolució (art. 23)"},{"n":"3","title":"Règim sancionador: subjectes responsables (art. 30)"},{"n":"4","title":"Òrgans competents (art. 32)"},{"n":"5","title":"Graduació de les sancions (art. 33)"},{"n":"6","title":"Infraccions molt greus, greus i lleus (arts. 35-37)"},{"n":"7","title":"Prescripció de les infraccions i sancions (arts. 38 i 39)"}]'::jsonb, '["Art. 21 LO 4/2015: «Dichas medidas podrán adoptarse por los agentes de la autoridad si la urgencia de la situación lo hiciera imprescindible, incluso mediante órdenes verbales.»","Art. 23.2 LO 4/2015: «La disolución de reuniones y manifestaciones constituirá el último recurso.»","Art. 23.3 LO 4/2015: «deberán avisar de tales medidas a las personas afectadas, pudiendo hacerlo de manera verbal si la urgencia de la situación lo hiciera imprescindible.»","Art. 30.2 LO 4/2015: «2. Estarán exentos de responsabilidad por las infracciones cometidas los menores de catorce años.»","Art. 32.3 LO 4/2015: «3. Los alcaldes podrán imponer las sanciones y adoptar las medidas previstas en esta Ley cuando las infracciones se cometieran en espacios públicos municipales o afecten a bienes de titularidad local»","Art. 33.2 LO 4/2015: «c) La ejecución de los hechos usando cualquier tipo de prenda u objeto que cubra el rostro, impidiendo o dificultando la identificación.»","Art. 35 LO 4/2015: «4. La proyección de haces de luz, mediante cualquier tipo de dispositivo, sobre los pilotos o conductores de medios de transporte que puedan deslumbrarles o distraer su atención y provocar accidentes.»","Art. 36.6 LO 4/2015: «así como la negativa a identificarse a requerimiento de la autoridad o de sus agentes o la alegación de datos falsos o inexactos en los procesos de identificación.»","Art. 36.16 LO 4/2015: «16. El consumo o la tenencia ilícitos de drogas tóxicas, estupefacientes o sustancias psicotrópicas, aunque no estuvieran destinadas al tráfico, en lugares, vías, establecimientos públicos o transportes colectivos»","Art. 36.14 LO 4/2015: «14. El uso público e indebido de uniformes, insignias o condecoraciones oficiales, o réplicas de los mismos»","Art. 37.4 LO 4/2015: «4. Las faltas de respeto y consideración cuyo destinatario sea un miembro de las Fuerzas y Cuerpos de Seguridad en el ejercicio de sus funciones de protección de la seguridad, cuando estas conductas no sean constitutivas de infracción penal.»","Art. 37.11 LO 4/2015: «considerándose como tal la tercera y posteriores pérdidas o extravíos en el plazo de un año.»","Art. 37.13 LO 4/2015: «13. Los daños o el deslucimiento de bienes muebles o inmuebles de uso o servicio público, así como de bienes muebles o inmuebles privados en la vía pública, cuando no constituyan infracción penal.»","Art. 37.16 LO 4/2015: «16. Dejar sueltos o en condiciones de causar daños animales feroces o dañinos, así como abandonar animales domésticos en condiciones en que pueda peligrar su vida.»","Art. 38.1 LO 4/2015: «1. Las infracciones administrativas tipificadas en esta Ley prescribirán a los seis meses, al año o a los dos años de haberse cometido, según sean leves, graves o muy graves, respectivamente.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[{"n":"1","title":"Mesures de seguretat extraordinàries i videocàmeres","blocks":[{"text":"Dins les potestats generals de policia de seguretat, les autoritats competents poden acordar mesures de seguretat extraordinàries: el tancament o desallotjament de locals o establiments, la prohibició del pas, l''evacuació d''immobles o espais públics acotats i el dipòsit d''explosius o substàncies semblants (art. 21). Només es poden adoptar en situacions d''emergència que les facin imprescindibles i pel temps estrictament necessari. Els agents de l''autoritat també les poden adoptar si la urgència ho fa imprescindible, fins i tot mitjançant ordres verbals.","refs":[{"ref":"Art. 21 LO 4/2015","law":"LO 4/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442","quote":"el cierre o desalojo de locales o establecimientos, la prohibición del paso, la evacuación de inmuebles o espacios públicos debidamente acotados, o el depósito de explosivos u otras sustancias susceptibles de ser empleadas como tales, en situaciones de emergencia que las hagan imprescindibles y durante el tiempo estrictamente necesario para garantizar la seguridad ciudadana. Dichas medidas podrán adoptarse por los agentes de la autoridad si la urgencia de la situación lo hiciera imprescindible, incluso mediante órdenes verbales."}]},{"text":"La llei defineix l''emergència com la situació de risc sobrevinguda per un esdeveniment que posa en perill imminent persones o béns i exigeix una actuació ràpida de l''autoritat o dels agents per evitar-la o mitigar-ne els efectes (art. 21, segon paràgraf). A més, l''autoritat governativa i les forces i cossos de seguretat poden gravar persones, llocs o objectes amb càmeres de videovigilància fixes o mòbils legalment autoritzades (art. 22).","refs":[{"ref":"Art. 21 LO 4/2015","law":"LO 4/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442","quote":"se entiende por emergencia aquella situación de riesgo sobrevenida por un evento que pone en peligro inminente a personas o bienes y exige una actuación rápida por parte de la autoridad o de sus agentes para evitarla o mitigar sus efectos."},{"ref":"Art. 22 LO 4/2015","law":"LO 4/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442","quote":"podrán proceder a la grabación de personas, lugares u objetos mediante cámaras de videovigilancia fijas o móviles legalmente autorizadas"}]}]},{"n":"2","title":"Reunions i manifestacions: protecció i dissolució","blocks":[{"text":"La secció 2a del capítol III tracta el manteniment i el restabliment de la seguretat en reunions i manifestacions. La primera obligació de les autoritats és protegir-ne la celebració i impedir que es pertorbi la seguretat ciutadana (art. 23.1). Poden acordar la dissolució de reunions en llocs de trànsit públic i de manifestacions en els supòsits de l''article 5 de la LO 9/1983, reguladora del dret de reunió. També poden dissoldre les concentracions de vehicles a les vies públiques i retirar-los, com qualsevol altre obstacle, quan impedeixin, posin en perill o dificultin la circulació.","refs":[{"ref":"Art. 23.1 LO 4/2015","law":"LO 4/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442","quote":"adoptarán las medidas necesarias para proteger la celebración de reuniones y manifestaciones, impidiendo que se perturbe la seguridad ciudadana. Asimismo podrán acordar la disolución de reuniones en lugares de tránsito público y manifestaciones en los supuestos previstos en el artículo 5 de la Ley Orgánica 9/1983, de 15 de julio, reguladora del derecho de reunión."},{"ref":"Art. 23.1 LO 4/2015","law":"LO 4/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442","quote":"También podrán disolver las concentraciones de vehículos en las vías públicas y retirar aquéllos o cualesquiera otra clase de obstáculos cuando impidieran, pusieran en peligro o dificultaran la circulación por dichas vías."}]},{"text":"Avís de fonts: la LO 9/1983, a la qual remet l''article 23, no és a la carpeta de fonts oficials d''aquest temari; per això aquí no se''n detallen els supòsits de dissolució de l''article 5.","refs":[{"ref":"Art. 23.1 LO 4/2015","law":"LO 4/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442","quote":"en los supuestos previstos en el artículo 5 de la Ley Orgánica 9/1983"}]}]},{"n":"3","title":"Gradualitat, avís previ i col·laboració policial","blocks":[{"text":"Les mesures d''intervenció en reunions i manifestacions han de ser graduals i proporcionades a les circumstàncies, i la dissolució és sempre l''últim recurs (art. 23.2). Abans d''actuar, les unitats han d''avisar-ne les persones afectades, i ho poden fer de manera verbal si la urgència ho fa imprescindible (art. 23.3). Només si hi ha una alteració de la seguretat amb armes, artefactes explosius o objectes contundents o perillosos poden dissoldre la reunió o retirar vehicles i obstacles sense avís previ. En aquests casos, les forces i cossos de seguretat col·laboren mútuament segons la LO 2/1986 (art. 24).","refs":[{"ref":"Art. 23.2 LO 4/2015","law":"LO 4/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442","quote":"serán graduales y proporcionadas a las circunstancias. La disolución de reuniones y manifestaciones constituirá el último recurso."},{"ref":"Art. 23.3 LO 4/2015","law":"LO 4/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442","quote":"deberán avisar de tales medidas a las personas afectadas, pudiendo hacerlo de manera verbal si la urgencia de la situación lo hiciera imprescindible."},{"ref":"Art. 23.3 LO 4/2015","law":"LO 4/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442","quote":"En caso de que se produzca una alteración de la seguridad ciudadana con armas, artefactos explosivos u objetos contundentes o de cualquier otro modo peligrosos, las Fuerzas y Cuerpos de Seguridad podrán disolver la reunión o manifestación o retirar los vehículos y obstáculos sin necesidad de previo aviso."},{"ref":"Art. 24 LO 4/2015","law":"LO 4/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442","quote":"las Fuerzas y Cuerpos de Seguridad colaborarán mutuamente en los términos previstos en su Ley orgánica reguladora."}]}]},{"n":"4","title":"Potestats especials de policia administrativa de seguretat","blocks":[{"text":"El capítol IV imposa obligacions de registre documental a activitats rellevants per a la seguretat, com l''hostalatge, el transport de persones, la compravenda d''objectes usats o de joies i metalls, el desballestament de vehicles o la serralleria de seguretat (art. 25.1). Les autoritats poden prohibir i, si ja s''estan celebrant, suspendre espectacles i activitats recreatives quan hi hagi un perill cert per a persones i béns o alteracions greus de la seguretat (art. 27.2). La intervenció d''armes i explosius correspon al Ministeri de l''Interior, que l''exerceix per mitjà de la Direcció General de la Guàrdia Civil (art. 28.2).","refs":[{"ref":"Art. 25.1 LO 4/2015","law":"LO 4/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442","quote":"como las de hospedaje, transporte de personas, acceso comercial a servicios telefónicos o telemáticos de uso público mediante establecimientos abiertos al público, comercio o reparación de objetos usados, alquiler o desguace de vehículos de motor, compraventa de joyas y metales"},{"ref":"Art. 27.2 LO 4/2015","law":"LO 4/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442","quote":"podrán prohibir y, en caso de estar celebrándose, suspender los espectáculos y actividades recreativas cuando exista un peligro cierto para personas y bienes, o acaecieran o se previeran graves alteraciones de la seguridad ciudadana."},{"ref":"Art. 28.2 LO 4/2015","law":"LO 4/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442","quote":"La intervención de armas, explosivos, cartuchería y artículos pirotécnicos corresponde al Ministerio del Interior, que la ejerce a través de la Dirección General de la Guardia Civil"}]}]},{"n":"5","title":"Règim sancionador: subjectes responsables i normes concursals","blocks":[{"text":"La responsabilitat recau directament en l''autor del fet (art. 30.1). Els menors de catorze anys n''estan exempts; si un menor d''aquesta edat comet una infracció, l''autoritat ho posa en coneixement del Ministeri Fiscal (art. 30.2). Es consideren organitzadors o promotors d''una reunió o manifestació els qui han signat la comunicació preceptiva i, encara que no l''hagin signada, els qui de fet la presideixin o dirigeixin (art. 30.3).","refs":[{"ref":"Art. 30.1 i 30.2 LO 4/2015","law":"LO 4/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442","quote":"1. La responsabilidad por las infracciones cometidas recaerá directamente en el autor del hecho en que consista la infracción. 2. Estarán exentos de responsabilidad por las infracciones cometidas los menores de catorce años."},{"ref":"Art. 30.2 LO 4/2015","law":"LO 4/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442","quote":"la autoridad competente lo pondrá en conocimiento del Ministerio Fiscal para que inicie, en su caso, las actuaciones oportunas."}]},{"text":"Quan un fet encaixa en més d''un precepte, s''aplica el precepte especial abans que el general, el més ampli absorbeix el consumit i, si no, el més greu exclou els que preveuen una sanció menor (art. 31.1). Si un sol fet constitueix diverses infraccions, o una és mitjà necessari per cometre l''altra, se sanciona per la que té la sanció més gran (art. 31.2).","refs":[{"ref":"Art. 31.1 LO 4/2015","law":"LO 4/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442","quote":"a) El precepto especial se aplicará con preferencia al general. b) El precepto más amplio o complejo absorberá el que sancione las infracciones consumidas en aquel. c) En defecto de los criterios anteriores, el precepto más grave excluirá los que sancionen el hecho con una sanción menor."},{"ref":"Art. 31.2 LO 4/2015","law":"LO 4/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442","quote":"la conducta será sancionada por aquella infracción que aplique una mayor sanción."}]}]},{"n":"6","title":"Òrgans competents per sancionar","blocks":[{"text":"En l''Administració de l''Estat, el ministre de l''Interior sanciona les infraccions molt greus en grau màxim; el secretari d''Estat de Seguretat, les molt greus en grau mitjà i mínim, i els delegats del Govern, les greus i les lleus (art. 32.1). També són competents les autoritats de la comunitat autònoma en l''àmbit de les seves competències de seguretat ciutadana (art. 32.2).","refs":[{"ref":"Art. 32.1 LO 4/2015","law":"LO 4/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442","quote":"a) El Ministro del Interior, para la sanción de las infracciones muy graves en grado máximo. b) El Secretario de Estado de Seguridad, para la sanción de infracciones muy graves en grado medio y en grado mínimo. c) Los Delegados del Gobierno en las comunidades autónomas y en las Ciudades de Ceuta y Melilla, para la sanción de las infracciones graves y leves."},{"ref":"Art. 32.2 LO 4/2015","law":"LO 4/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442","quote":"Serán competentes para imponer las sanciones tipificadas en esta Ley las autoridades correspondientes de la Comunidad Autónoma en el ámbito de sus competencias en materia de seguridad ciudadana."}]},{"text":"Els alcaldes poden imposar les sancions i adoptar les mesures de la llei quan les infraccions es cometen en espais públics municipals o afecten béns de titularitat local, sempre que tinguin competència en la matèria d''acord amb la legislació específica; les ordenances municipals poden introduir especificacions o graduacions del quadre d''infraccions (art. 32.3). A Catalunya, la Llei 4/2003 atribueix als alcaldes la imposició de sancions de seguretat ciutadana amb audiència prèvia de la junta local de seguretat (disposició addicional segona), però la seva disposició addicional primera encara remet a la derogada LO 1/1992 i no s''ha pogut contrastar amb una versió actualitzada.","refs":[{"ref":"Art. 32.3 LO 4/2015","law":"LO 4/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442","quote":"3. Los alcaldes podrán imponer las sanciones y adoptar las medidas previstas en esta Ley cuando las infracciones se cometieran en espacios públicos municipales o afecten a bienes de titularidad local, siempre que ostenten competencia sobre la materia de acuerdo con la legislación específica."},{"ref":"Disposició addicional segona Llei 4/2003","law":"Llei 4/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-9620","quote":"los alcaldes tienen competencias, previa audiencia de la junta local de seguridad, para imponer las sanciones de suspensión de las autorizaciones o permisos que hubieran concedido los municipios y de multa"},{"ref":"Disposició addicional primera Llei 4/2003","law":"Llei 4/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-9620","quote":"a) Las determinadas por la Ley orgánica 1/1992, de 21 de febrero, de protección de la seguridad ciudadana."}]}]},{"n":"7","title":"Graduació de les sancions","blocks":[{"text":"Les sancions es regeixen pel principi de proporcionalitat (art. 33.1). Les multes per infraccions molt greus i greus es divideixen en tres trams iguals: grau mínim, mitjà i màxim. Per regla general, la infracció comporta la multa en grau mínim. Es passa al grau mitjà si concorre almenys una d''aquestes circumstàncies: reincidència (més d''una infracció de la mateixa naturalesa en dos anys, declarada per resolució ferma), violència, amenaça o intimidació, fer els fets amb el rostre cobert per impedir o dificultar la identificació, o utilitzar menors o persones vulnerables (art. 33.2).","refs":[{"ref":"Art. 33.2 LO 4/2015","law":"LO 4/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442","quote":"La comisión de una infracción determinará la imposición de la multa correspondiente en grado mínimo. La infracción se sancionará con multa en grado medio cuando se acredite la concurrencia, al menos, de una de las siguientes circunstancias:"},{"ref":"Art. 33.2 LO 4/2015","law":"LO 4/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442","quote":"a) La reincidencia, por la comisión en el término de dos años de más de una infracción de la misma naturaleza, cuando así haya sido declarado por resolución firme en vía administrativa. b) La realización de los hechos interviniendo violencia, amenaza o intimidación. c) La ejecución de los hechos usando cualquier tipo de prenda u objeto que cubra el rostro, impidiendo o dificultando la identificación."}]},{"text":"Dins de cada grau, la multa s''individualitza segons el risc produït, la quantia i la transcendència del perjudici, l''alteració dels serveis públics, el grau de culpabilitat, el benefici obtingut i la capacitat econòmica de l''infractor. El grau màxim només s''aplica quan els fets són d''especial gravetat. Les multes lleus es fixen directament segons aquests criteris (art. 33.3).","refs":[{"ref":"Art. 33.2 LO 4/2015","law":"LO 4/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442","quote":"Las infracciones sólo se sancionarán con multa en grado máximo cuando los hechos revistan especial gravedad"},{"ref":"Art. 33.3 LO 4/2015","law":"LO 4/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442","quote":"3. La multa por la comisión de infracciones leves se determinará directamente atendiendo a las circunstancias y los criterios del apartado anterior."}]}]},{"n":"8","title":"Infraccions molt greus","blocks":[{"text":"Les infraccions es classifiquen en molt greus, greus i lleus (art. 34). Són molt greus només quatre conductes (art. 35): les reunions o manifestacions no comunicades o prohibides en infraestructures de serveis bàsics, o la intrusió en aquestes (inclòs el sobrevol), quan generin risc per a la vida o la integritat; les irregularitats amb armes reglamentàries, explosius, cartutxeria o pirotècnia que causin perjudicis molt greus; celebrar espectacles trencant una prohibició o suspensió per raons de seguretat, i projectar feixos de llum sobre pilots o conductors de mitjans de transport que els puguin enlluernar o distreure i provocar accidents.","refs":[{"ref":"Art. 35.3 i 35.4 LO 4/2015","law":"LO 4/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442","quote":"3. La celebración de espectáculos públicos o actividades recreativas quebrantando la prohibición o suspensión ordenada por la autoridad correspondiente por razones de seguridad pública. 4. La proyección de haces de luz, mediante cualquier tipo de dispositivo, sobre los pilotos o conductores de medios de transporte que puedan deslumbrarles o distraer su atención y provocar accidentes."}]},{"text":"Compte amb la diferència: si els feixos de llum es projecten sobre agents de les forces i cossos de seguretat per impedir-los o dificultar-los les funcions, la infracció és lleu (art. 37.6).","refs":[{"ref":"Art. 37.6 LO 4/2015","law":"LO 4/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442","quote":"6. La proyección de haces de luz, mediante cualquier tipo de dispositivo, sobre miembros de las Fuerzas y Cuerpos de Seguridad para impedir o dificultar el ejercicio de sus funciones."}]}]},{"n":"9","title":"Infraccions greus","blocks":[{"text":"L''article 36 tipifica 23 infraccions greus. Algunes de les més rellevants per a la policia local: la desobediència o la resistència a l''autoritat o als agents quan no són delicte, i també la negativa a identificar-se o donar dades falses (36.6); la negativa a dissoldre una reunió o manifestació ordenada per l''autoritat (36.7); portar, exhibir o usar armes prohibides o fer-ho de manera negligent o intimidatòria (36.10); l''ús públic i indegut d''uniformes, insígnies o equipament policial que pugui generar engany (36.14), i la manca de col·laboració amb els agents en els supòsits de l''article 7 (36.15).","refs":[{"ref":"Art. 36.6 LO 4/2015","law":"LO 4/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442","quote":"6. La desobediencia o la resistencia a la autoridad o a sus agentes en el ejercicio de sus funciones, cuando no sean constitutivas de delito, así como la negativa a identificarse a requerimiento de la autoridad o de sus agentes o la alegación de datos falsos o inexactos en los procesos de identificación."},{"ref":"Art. 36.14 LO 4/2015","law":"LO 4/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442","quote":"14. El uso público e indebido de uniformes, insignias o condecoraciones oficiales, o réplicas de los mismos, así como otros elementos del equipamiento de los cuerpos policiales o de los servicios de emergencia que puedan generar engaño acerca de la condición de quien los use, cuando no sea constitutivo de infracción penal."}]},{"text":"També són greus el consum o la tinença il·lícits de drogues en llocs, vies, establiments o transports públics, encara que no siguin per al tràfic, i l''abandonament dels estris emprats (36.16); el cultiu de drogues en llocs visibles al públic (36.18), i tolerar el consum o el tràfic de drogues en locals públics (36.19). Avís de vigència: el Tribunal Constitucional (STC 172/2020) va declarar nul l''incís «no autorizado» de l''apartat 23, sobre l''ús d''imatges d''agents, i en va fixar una interpretació conforme per a la resta.","refs":[{"ref":"Art. 36.16 LO 4/2015","law":"LO 4/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442","quote":"16. El consumo o la tenencia ilícitos de drogas tóxicas, estupefacientes o sustancias psicotrópicas, aunque no estuvieran destinadas al tráfico, en lugares, vías, establecimientos públicos o transportes colectivos, así como el abandono de los instrumentos u otros efectos empleados para ello en los citados lugares."},{"ref":"Nota a l''art. 36.23 LO 4/2015","law":"LO 4/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442","quote":"se declara la inconstitucionalidad y nulidad del inciso destacado del apartado 23 y la no inconstitucionalidad del resto del apartado siempre que se interprete en el sentido establecido en el FJ 7 C), por la Sentencia del TC 172/2020, de 19 de noviembre."}]}]},{"n":"10","title":"Infraccions lleus","blocks":[{"text":"Entre les 17 infraccions lleus de l''article 37 destaquen: les faltes de respecte i consideració a un membre de les forces i cossos de seguretat en l''exercici de funcions de protecció de la seguretat, quan no són delicte (37.4); l''ocupació d''immobles aliens contra la voluntat del titular i l''ocupació indeguda de la via pública, inclosa la venda ambulant no autoritzada (37.7), i els danys o el deslluïment de béns d''ús o servei públic, o de béns privats a la via pública, si no són delicte (37.13).","refs":[{"ref":"Art. 37.4 LO 4/2015","law":"LO 4/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442","quote":"4. Las faltas de respeto y consideración cuyo destinatario sea un miembro de las Fuerzas y Cuerpos de Seguridad en el ejercicio de sus funciones de protección de la seguridad, cuando estas conductas no sean constitutivas de infracción penal."},{"ref":"Art. 37.13 LO 4/2015","law":"LO 4/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442","quote":"13. Los daños o el deslucimiento de bienes muebles o inmuebles de uso o servicio público, así como de bienes muebles o inmuebles privados en la vía pública, cuando no constituyan infracción penal."}]},{"text":"Pel que fa a la documentació, és lleu no obtenir la documentació personal obligatòria o no denunciar-ne per negligència la pèrdua (37.10), i la negligència en la custòdia, que la llei concreta en la tercera pèrdua i les posteriors dins d''un any (37.11). També són lleus deixar sense control animals ferotges o perillosos, o abandonar animals domèstics en perill (37.16), i el consum d''alcohol en llocs públics quan pertorbi greument la tranquil·litat ciutadana (37.17).","refs":[{"ref":"Art. 37.11 LO 4/2015","law":"LO 4/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442","quote":"11. La negligencia en la custodia y conservación de la documentación personal legalmente exigida, considerándose como tal la tercera y posteriores pérdidas o extravíos en el plazo de un año."},{"ref":"Art. 37.16 i 37.17 LO 4/2015","law":"LO 4/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442","quote":"16. Dejar sueltos o en condiciones de causar daños animales feroces o dañinos, así como abandonar animales domésticos en condiciones en que pueda peligrar su vida. 17. El consumo de bebidas alcohólicas en lugares, vías, establecimientos o transportes públicos cuando perturbe gravemente la tranquilidad ciudadana."}]}]},{"n":"11","title":"Sancions i prescripció","blocks":[{"text":"Les multes són (art. 39.1): molt greus, de 30.001 a 600.000 euros; greus, de 601 a 30.000 euros, i lleus, de 100 a 600 euros. Els graus de les greus són: mínim de 601 a 10.400; mitjà de 10.401 a 20.200, i màxim de 20.201 a 30.000 euros. Els de les molt greus són: mínim de 30.001 a 220.000; mitjà de 220.001 a 410.000, i màxim de 410.001 a 600.000 euros. Hi pot haver sancions accessòries, com la retirada d''armes i llicències, el comís o la clausura d''establiments (art. 39.2).","refs":[{"ref":"Art. 39.1 LO 4/2015","law":"LO 4/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442","quote":"1. Las infracciones muy graves se sancionarán con multa de 30.001 a 600.000 euros; las graves, con multa de 601 a 30.000 euros, y las leves, con multa de 100 a 600 euros."},{"ref":"Art. 39.1.a i b LO 4/2015","law":"LO 4/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442","quote":"a) Para las infracciones muy graves, el grado mínimo comprenderá la multa de 30.001 a 220.000 euros; el grado medio, de 220.001 a 410.000 euros, y el grado máximo, de 410.001 a 600.000 euros. b) Para las infracciones graves, el grado mínimo comprenderá la multa de 601 a 10.400; el grado medio, de 10.401 a 20.200 euros, y el grado máximo, de 20.201 a 30.000 euros."}]},{"text":"Les infraccions prescriuen als sis mesos (lleus), a l''any (greus) i als dos anys (molt greus) de la comissió (art. 38.1). El termini es compta des del dia de la infracció; en les continuades, des de l''última, i en les d''efectes permanents, des que s''elimina la situació il·lícita (art. 38.2). Les sancions prescriuen a l''any (lleus), als dos anys (greus) i als tres anys (molt greus), a comptar de l''endemà de la fermesa en via administrativa (art. 40.1).","refs":[{"ref":"Art. 38.1 LO 4/2015","law":"LO 4/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442","quote":"1. Las infracciones administrativas tipificadas en esta Ley prescribirán a los seis meses, al año o a los dos años de haberse cometido, según sean leves, graves o muy graves, respectivamente."},{"ref":"Art. 38.2 LO 4/2015","law":"LO 4/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442","quote":"en los casos de infracciones continuadas y de infracciones de efectos permanentes, los plazos se computarán, respectivamente, desde el día en que se realizó la última infracción y desde que se eliminó la situación ilícita."},{"ref":"Art. 40.1 LO 4/2015","law":"LO 4/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442","quote":"Las sanciones impuestas por infracciones muy graves prescribirán a los tres años, las impuestas por infracciones graves, a los dos años, y las impuestas por infracciones leves al año"}]}]},{"n":"12","title":"Procediment: valor de les denúncies dels agents i procediment abreujat","blocks":[{"text":"Les denúncies, atestats o actes dels agents que han presenciat els fets, ratificats si el denunciat els nega, són base suficient per resoldre, llevat de prova en contra (art. 52). En les infraccions greus i lleus, l''interessat té quinze dies des de la notificació de la incoació per pagar voluntàriament o presentar al·legacions (art. 54.1). Si paga, la multa es redueix un 50 %, renuncia a al·legar i el procediment s''acaba el dia del pagament (art. 54.3). El procediment abreujat no s''aplica a les molt greus (art. 54.2).","refs":[{"ref":"Art. 52 LO 4/2015","law":"LO 4/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442","quote":"previa ratificación en el caso de haber sido negados por los denunciados, constituirán base suficiente para adoptar la resolución que proceda, salvo prueba en contrario"},{"ref":"Art. 54.2 i 54.3 LO 4/2015","law":"LO 4/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442","quote":"2. El procedimiento sancionador abreviado no será de aplicación a las infracciones muy graves. […] a) La reducción del 50 por ciento del importe de la sanción de multa."}]}]},{"n":"R","title":"Recorda per a l''examen","blocks":[{"text":"Mesures extraordinàries (art. 21): els agents les poden adoptar per urgència, fins i tot amb ordres verbals.","refs":[{"ref":"Art. 21 LO 4/2015","law":"LO 4/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442","quote":"incluso mediante órdenes verbales."}]},{"text":"La dissolució de reunions i manifestacions és l''últim recurs; cal avís previ, llevat d''alteració amb armes o objectes perillosos.","refs":[{"ref":"Art. 23.2 LO 4/2015","law":"LO 4/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442","quote":"La disolución de reuniones y manifestaciones constituirá el último recurso."}]},{"text":"Menors de catorze anys: exempts de responsabilitat.","refs":[{"ref":"Art. 30.2 LO 4/2015","law":"LO 4/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442","quote":"Estarán exentos de responsabilidad por las infracciones cometidas los menores de catorce años."}]},{"text":"Rostre cobert, violència o reincidència: multa en grau mitjà.","refs":[{"ref":"Art. 33.2 LO 4/2015","law":"LO 4/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442","quote":"La infracción se sancionará con multa en grado medio"}]},{"text":"Negativa a identificar-se, drogues en llocs públics i ús indegut d''uniformes: greus.","refs":[{"ref":"Art. 36.6 LO 4/2015","law":"LO 4/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442","quote":"la negativa a identificarse a requerimiento de la autoridad o de sus agentes"}]},{"text":"Faltes de respecte a agents, danys al mobiliari públic i tercera pèrdua de la documentació en un any: lleus.","refs":[{"ref":"Art. 37.11 LO 4/2015","law":"LO 4/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442","quote":"la tercera y posteriores pérdidas o extravíos en el plazo de un año."}]},{"text":"Multes: lleus 100-600 €; greus 601-30.000 €; molt greus 30.001-600.000 €.","refs":[{"ref":"Art. 39.1 LO 4/2015","law":"LO 4/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442","quote":"las leves, con multa de 100 a 600 euros."}]},{"text":"Prescripció de les infraccions: 6 mesos, 1 any i 2 anys; de les sancions: 1, 2 i 3 anys.","refs":[{"ref":"Art. 38.1 LO 4/2015","law":"LO 4/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442","quote":"prescribirán a los seis meses, al año o a los dos años de haberse cometido"}]}]}]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442'), 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442', null, null, null, null
