insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, lessons, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"Policia judicial: funcions (art. 282)"},{"n":"2","title":"Atestat i diligències (arts. 284, 292 i 295)"},{"n":"3","title":"Valor de l''atestat (art. 297)"},{"n":"4","title":"La detenció: supòsits i obligats a detenir (arts. 489-493)"},{"n":"5","title":"Forma de practicar la detenció i terminis (arts. 494-496)"},{"n":"6","title":"Drets de la persona detinguda (art. 520)"}]'::jsonb, '["Art. 282 LECrim: «averiguar los delitos públicos que se cometieren en su territorio o demarcación; practicar, según sus atribuciones, las diligencias necesarias para comprobarlos y descubrir a los delincuentes»","Art. 284.2 LECrim: «a) Que se trate de delitos contra la vida, contra la integridad física, contra la libertad e indemnidad sexuales o de delitos relacionados con la corrupción;»","Art. 292 LECrim: «en el cual especificarán con la mayor exactitud los hechos por ellos averiguados, insertando las declaraciones e informes recibidos y anotando todas las circunstancias que hubiesen observado y pudiesen ser prueba o indicio del delito.»","Art. 295 LECrim: «En ningún caso los funcionarios de Policía Judicial podrán dejar transcurrir más de veinticuatro horas sin dar conocimiento a la autoridad judicial o al Ministerio Fiscal de las diligencias que hubieran practicado»","Art. 297 LECrim: «se considerarán denuncias para los efectos legales.»","Art. 489 LECrim: «Ningún español ni extranjero podrá ser detenido sino en los casos y en la forma que las leyes prescriban.»","Art. 490 LECrim: «2.º Al delincuente in fraganti.»","Art. 492 LECrim: «1.ª Que la Autoridad o agente tenga motivos racionalmente bastantes para creer en la existencia de un hecho que presente los caracteres de delito. 2.ª Que los tenga también bastantes para creer que la persona a quien intente detener tuvo participación en él.»","Art. 495 LECrim: «No se podrá detener por la presunta comisión de delitos leves, a no ser que el presunto reo no tuviese domicilio conocido ni diese fianza bastante»","Art. 496 LECrim: «deberá ponerla en libertad o entregarla al Juez más próximo al lugar en que hubiere hecho la detención dentro de las veinticuatro horas siguientes al acto de la misma.»","Art. 520.1 LECrim: «1. La detención y la prisión provisional deberán practicarse en la forma que menos perjudique al detenido o preso en su persona, reputación y patrimonio.»","Art. 520.2 LECrim: «2. Toda persona detenida o presa será informada por escrito, en un lenguaje sencillo y accesible, en una lengua que comprenda y de forma inmediata»","Art. 520.2.e LECrim: «Los extranjeros tendrán derecho a que las circunstancias anteriores se comuniquen a la oficina consular de su país.»","Art. 520.4 LECrim: «4. Si se tratare de un menor, será puesto a disposición de las Secciones de Menores de la Fiscalía y se comunicará el hecho y el lugar de custodia a quienes ejerzan la patria potestad, la tutela o la guarda de hecho del mismo»","Art. 520.5 LECrim: «El abogado designado acudirá al centro de detención con la máxima premura, siempre dentro del plazo máximo de tres horas desde la recepción del encargo.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[{"n":"1","title":"La policia judicial: objecte i funcions (art. 282 LECrim)","blocks":[{"text":"La Llei d''enjudiciament criminal (LECrim) regula la policia judicial al títol III del llibre II. L''article 282 en fixa l''objecte, que alhora és una obligació de tots els seus membres: esbrinar els delictes públics que es cometin al seu territori o demarcació; practicar, segons les seves atribucions, les diligències necessàries per comprovar-los i descobrir-ne els autors; i recollir tots els efectes, instruments o proves del delicte que corrin perill de desaparèixer, posant-los a disposició de l''autoritat judicial.","refs":[{"ref":"Art. 282 LECrim","law":"LECrim","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036","quote":"La Policía Judicial tiene por objeto y será obligación de todos los que la componen, averiguar los delitos públicos que se cometieren en su territorio o demarcación; practicar, según sus atribuciones, las diligencias necesarias para comprobarlos y descubrir a los delincuentes, y recoger todos los efectos, instrumentos o pruebas del delito de cuya desaparición hubiere peligro, poniéndolos a disposición de la autoridad judicial."}]},{"text":"El mateix article incorpora deures envers les víctimes. Quan una víctima entra en contacte amb la policia judicial, aquesta ha de complir els deures d''informació que preveu la legislació vigent i, a més, ha de fer una valoració de les circumstàncies particulars de la víctima per determinar provisionalment quines mesures de protecció cal adoptar. Es tracta d''una valoració provisional: la decisió final correspon al jutge o tribunal.","refs":[{"ref":"Art. 282 LECrim","law":"LECrim","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036","quote":"Cuando las víctimas entren en contacto con la Policía Judicial, cumplirá con los deberes de información que prevé la legislación vigente. Asimismo, llevarán a cabo una valoración de las circunstancias particulares de las víctimas para determinar provisionalmente qué medidas de protección deben ser adoptadas para garantizarles una protección adecuada, sin perjuicio de la decisión final que corresponderá adoptar al Juez o Tribunal."}]},{"text":"Si el delicte només es pot perseguir a instància de part legítima, la policia té la mateixa obligació, però només si se li requereix. Excepcionalment, l''absència de denúncia no impedeix practicar les primeres diligències de prevenció i assegurament en els delictes relatius a la propietat intel·lectual i industrial.","refs":[{"ref":"Art. 282 LECrim","law":"LECrim","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036","quote":"Si el delito fuera de los que sólo pueden perseguirse a instancia de parte legítima, tendrán la misma obligación expresada en el párrafo anterior, si se les requiere al efecto. La ausencia de denuncia no impedirá la práctica de las primeras diligencias de prevención y aseguramiento de los delitos relativos a la propiedad intelectual e industrial."}]}]},{"n":"2","title":"Qui integra la policia judicial i de qui depèn (arts. 283, 287 i 288)","blocks":[{"text":"L''article 283 enumera els qui constitueixen la policia judicial i els qualifica d''auxiliars dels jutges i tribunals competents en matèria penal i del Ministeri Fiscal, obligats a seguir-ne les instruccions per investigar els delictes i perseguir els delinqüents. Entre altres hi figuren les autoritats administratives encarregades de la seguretat pública, els alcaldes i tinents d''alcalde i, de manera expressa, els agents municipals de policia urbana o rural, que és on encaixa la policia local. La redacció és del 1882 i conserva denominacions antigues («Serenos, Celadores»).","refs":[{"ref":"Art. 283 LECrim","law":"LECrim","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036","quote":"Constituirán la Policía judicial y serán auxiliares de los Jueces y Tribunales competentes en materia penal y del Ministerio fiscal, quedando obligados a seguir las instrucciones que de aquellas autoridades reciban a efectos de la investigación de los delitos y persecución de los delincuentes"},{"ref":"Art. 283 LECrim","law":"LECrim","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036","quote":"Tercero. Los Alcaldes, Tenientes de Alcalde y Alcaldes de barrio. […] Quinto. Los Serenos, Celadores y cualesquiera otros Agentes municipales de policía urbana o rural."}]},{"text":"Els funcionaris de policia judicial han de practicar sense dilació les diligències que els encomani el Ministeri Fiscal i les que els encarreguin els jutges durant la causa (art. 287). El fiscal i els jutges es poden adreçar directament a qualsevol funcionari de policia judicial, sigui quina sigui la seva categoria (art. 288).","refs":[{"ref":"Art. 287 LECrim","law":"LECrim","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036","quote":"Los funcionarios que constituyen la Policía judicial practicarán sin dilación, según sus atribuciones respectivas, las diligencias que los funcionarios del Ministerio fiscal les encomienden"},{"ref":"Art. 288 LECrim","law":"LECrim","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036","quote":"El Ministerio fiscal, los Jueces de instrucción y los municipales podrán entenderse directamente con los funcionarios de Policía judicial, cualquiera que sea su categoría"}]}]},{"n":"3","title":"Comunicació del delicte i atestats sense autor conegut (art. 284)","blocks":[{"text":"Tan bon punt la policia judicial té coneixement d''un delicte públic, l''ha de comunicar a l''autoritat judicial o al Ministeri Fiscal, si ho pot fer sense deixar de practicar les diligències de prevenció; si no, ho fa quan les ha acabades (art. 284.1).","refs":[{"ref":"Art. 284.1 LECrim","law":"LECrim","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036","quote":"Inmediatamente que los funcionarios de la Policía judicial tuvieren conocimiento de un delito público o fueren requeridos para prevenir la instrucción de diligencias por razón de algún delito privado, lo participarán a la autoridad judicial o al representante del Ministerio Fiscal, si pudieren hacerlo sin cesar en la práctica de las diligencias de prevención."}]},{"text":"Quan no hi ha autor conegut, la regla general és que la policia conserva l''atestat a disposició del fiscal i del jutge, sense enviar-l''hi (art. 284.2). Cal enviar-lo, però, si es tracta de delictes contra la vida, la integritat física, la llibertat i indemnitat sexuals o relacionats amb la corrupció; si es practica alguna diligència passades setanta-dues hores des de l''obertura de l''atestat i té algun resultat; o si el fiscal o el jutge en demanen la remissió. La policia ha d''advertir el denunciant que, si l''autor no s''identifica en setanta-dues hores, les actuacions no es trametran al jutjat, sens perjudici del seu dret a reiterar la denúncia.","refs":[{"ref":"Art. 284.2 LECrim","law":"LECrim","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036","quote":"cuando no exista autor conocido del delito la Policía Judicial conservará el atestado a disposición del Ministerio Fiscal y de la autoridad judicial, sin enviárselo, salvo que concurra alguna de las siguientes circunstancias: a) Que se trate de delitos contra la vida, contra la integridad física, contra la libertad e indemnidad sexuales o de delitos relacionados con la corrupción; b) Que se practique cualquier diligencia después de transcurridas setenta y dos horas desde la apertura del atestado y éstas hayan tenido algún resultado; o c) Que el Ministerio Fiscal o la autoridad judicial soliciten la remisión."},{"ref":"Art. 284.2 LECrim","law":"LECrim","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036","quote":"la Policía Judicial comunicará al denunciante que en caso de no ser identificado el autor en el plazo de setenta y dos horas, las actuaciones no se remitirán a la autoridad judicial"}]},{"text":"Si es recullen armes, instruments o efectes relacionats amb el delicte, s''estén una diligència que expressi el lloc, el temps i l''ocasió de la troballa, amb una descripció minuciosa que es pot substituir per un reportatge gràfic (art. 284.3).","refs":[{"ref":"Art. 284.3 LECrim","law":"LECrim","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036","quote":"extenderán diligencia expresiva del lugar, tiempo y ocasión en que se encontraren, que incluirá una descripción minuciosa para que se pueda formar idea cabal de los mismos y de las circunstancias de su hallazgo, que podrá ser sustituida por un reportaje gráfico."}]}]},{"n":"4","title":"L''atestat: contingut i signatura (arts. 292-294)","blocks":[{"text":"L''atestat és el document on la policia judicial recull les diligències que practica. S''hi han d''especificar amb la màxima exactitud els fets esbrinats, inserint-hi les declaracions i els informes rebuts i anotant totes les circumstàncies observades que puguin ser prova o indici del delicte (art. 292). Amb l''atestat s''ha de trametre un informe de les detencions anteriors i de les requisitòries de crida i cerca que constin a les bases de dades policials.","refs":[{"ref":"Art. 292 LECrim","law":"LECrim","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036","quote":"un atestado de las diligencias que practiquen, en el cual especificarán con la mayor exactitud los hechos por ellos averiguados, insertando las declaraciones e informes recibidos y anotando todas las circunstancias que hubiesen observado y pudiesen ser prueba o indicio del delito."},{"ref":"Art. 292 LECrim","law":"LECrim","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036","quote":"La Policía Judicial remitirá con el atestado un informe dando cuenta de las detenciones anteriores y de la existencia de requisitorias para su llamamiento y busca cuando así conste en sus bases de datos."}]},{"text":"L''atestat el signa qui l''ha estès. Les persones presents, els pèrits i els testimonis que hi han intervingut són convidats a signar-lo en la part que els afecta i, si no ho fan, se n''ha d''expressar la raó (art. 293). Si el funcionari no el pot redactar, se substitueix per una relació verbal circumstanciada que el fiscal o el jutge redueixen a escrit (art. 294).","refs":[{"ref":"Art. 293 LECrim","law":"LECrim","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036","quote":"El atestado será firmado por el que lo haya extendido, y si usare sello lo estampará con su rúbrica en todas las hojas. Las personas presentes, peritos y testigos que hubieren intervenido en las diligencias relacionadas en el atestado serán invitadas a firmarlo en la parte a ellos referente. Si no lo hicieren, se expresará la razón."},{"ref":"Art. 294 LECrim","law":"LECrim","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036","quote":"se sustituirá por una relación verbal circunstanciada, que reducirá a escrito de un modo fehaciente el funcionario del Ministerio fiscal, el Juez de instrucción o el municipal"}]}]},{"n":"5","title":"Termini de les vint-i-quatre hores i valor de l''atestat (arts. 295 i 297)","blocks":[{"text":"En cap cas la policia judicial no pot deixar passar més de vint-i-quatre hores sense donar coneixement de les diligències practicades a l''autoritat judicial o al Ministeri Fiscal, llevat de força major i del supòsit de l''atestat sense autor conegut de l''article 284.2 (art. 295). L''incompliment es corregeix disciplinàriament; la multa encara s''expressa en pessetes perquè el precepte no s''ha actualitzat.","refs":[{"ref":"Art. 295 LECrim","law":"LECrim","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036","quote":"En ningún caso los funcionarios de Policía Judicial podrán dejar transcurrir más de veinticuatro horas sin dar conocimiento a la autoridad judicial o al Ministerio Fiscal de las diligencias que hubieran practicado, salvo en los supuestos de fuerza mayor y en el previsto en el apartado 2 del artículo 284."},{"ref":"Art. 295 LECrim","law":"LECrim","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036","quote":"serán corregidos disciplinariamente con multa de 250 a 1.000 pesetas"}]},{"text":"Quant al valor, els atestats i les manifestacions dels funcionaris de policia judicial derivades de les seves averiguacions es consideren denúncies a efectes legals (art. 297). Les altres declaracions que prestin, signades, tenen valor de declaració testifical pel que fa als fets de coneixement propi. A més, han d''observar estrictament les formalitats legals i no poden fer servir mitjans d''averiguació que la llei no autoritzi.","refs":[{"ref":"Art. 297 LECrim","law":"LECrim","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036","quote":"Los atestados que redactaren y las manifestaciones que hicieren los funcionarios de Policía judicial, a consecuencia de las averiguaciones que hubiesen practicado, se considerarán denuncias para los efectos legales. Las demás declaraciones que prestaren deberán ser firmadas, y tendrán el valor de declaraciones testificales en cuanto se refieran a hechos de conocimiento propio."},{"ref":"Art. 297 LECrim","law":"LECrim","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036","quote":"se abstendrán bajo su responsabilidad de usar medios de averiguación que la Ley no autorice."}]}]},{"n":"6","title":"La detenció: legalitat i detenció per particulars (arts. 489-491)","blocks":[{"text":"La Constitució reconeix el dret a la llibertat: ningú no pot ser privat de llibertat sinó en els casos i la forma previstos a la llei (art. 17.1 CE). La LECrim ho reprodueix: cap espanyol ni estranger no pot ser detingut sinó en els casos i en la forma que prescriuen les lleis (art. 489).","refs":[{"ref":"Art. 17.1 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"Nadie puede ser privado de su libertad, sino con la observancia de lo establecido en este artículo y en los casos y en la forma previstos en la ley."},{"ref":"Art. 489 LECrim","law":"LECrim","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036","quote":"Ningún español ni extranjero podrá ser detenido sino en los casos y en la forma que las leyes prescriban."}]},{"text":"Qualsevol persona pot detenir (art. 490): qui intenta cometre un delicte en el moment d''anar a cometre''l; el delinqüent in fraganti; qui s''escapa de l''establiment penal on compleix condemna, de la presó on espera el trasllat o durant la conducció; qui s''escapa estant detingut o pres per causa pendent; i el processat o condemnat en rebel·lia. Tenir antecedents o ser vist a prop del lloc dels fets no és cap d''aquests supòsits. El particular que deté ha de justificar, si el detingut ho exigeix, que tenia motius racionalment suficients per creure que hi concorria algun d''aquests casos (art. 491).","refs":[{"ref":"Art. 490 LECrim","law":"LECrim","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036","quote":"Cualquier persona puede detener: 1.º Al que intentare cometer un delito en el momento de ir a cometerlo. 2.º Al delincuente in fraganti. 3.º Al que se fugare del establecimiento penal en que se halle extinguiendo condena."},{"ref":"Art. 490 LECrim","law":"LECrim","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036","quote":"6.º Al que se fugare estando detenido o preso por causa pendiente. 7.º Al procesado o condenado que estuviere en rebeldía."},{"ref":"Art. 491 LECrim","law":"LECrim","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036","quote":"El particular que detuviere a otro justificará, si éste lo exigiere, haber obrado en virtud de motivos racionalmente suficientes para creer que el detenido se hallaba comprendido en alguno de los casos del artículo anterior."}]}]},{"n":"7","title":"Obligació de detenir de l''autoritat i els agents (arts. 492-495)","blocks":[{"text":"Per a l''autoritat o l''agent de policia judicial, detenir no és una facultat sinó una obligació (art. 492): en tots els casos de l''article 490; el processat per delicte amb pena superior a la de «presó correccional» (denominació del 1882 que el text consolidat manté); el processat per delicte menys greu si es presumeix que no compareixerà, llevat que presti fiança suficient; i qui, encara no processat, es troba en aquest darrer cas, si concorren dues circumstàncies: motius racionalment suficients per creure en l''existència d''un fet amb caràcters de delicte i per creure que la persona hi va participar.","refs":[{"ref":"Art. 492 LECrim","law":"LECrim","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036","quote":"La Autoridad o agente de Policía judicial tendrá obligación de detener: 1.º A cualquiera que se halle en alguno de los casos del artículo 490. 2.º Al que estuviere procesado por delito que tenga señalada en el Código pena superior a la de prisión correccional."},{"ref":"Art. 492 LECrim","law":"LECrim","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036","quote":"4.º Al que estuviere en el caso del número anterior, aunque todavía no se hallase procesado, con tal que concurran las dos circunstancias siguientes: 1.ª Que la Autoridad o agente tenga motivos racionalmente bastantes para creer en la existencia de un hecho que presente los caracteres de delito. 2.ª Que los tenga también bastantes para creer que la persona a quien intente detener tuvo participación en él."}]},{"text":"Si l''agent no deté algú perquè no encaixa en cap d''aquests casos, n''ha de prendre nota del nom, cognom, domicili i altres circumstàncies per identificar-lo, i lliurar-la al jutge o tribunal (art. 493). Per delictes lleus no es pot detenir, tret que el presumpte autor no tingui domicili conegut ni doni fiança suficient a judici de l''autoritat o agent (art. 495).","refs":[{"ref":"Art. 493 LECrim","law":"LECrim","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036","quote":"La Autoridad o agente de Policía judicial tomará nota del nombre, apellido, domicilio y demás circunstancias bastantes para la averiguación e identificación de la persona del procesado o del delincuente a quienes no detuviere"},{"ref":"Art. 495 LECrim","law":"LECrim","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036","quote":"No se podrá detener por la presunta comisión de delitos leves, a no ser que el presunto reo no tuviese domicilio conocido ni diese fianza bastante, a juicio de la autoridad o agente que intente detenerle."}]}]},{"n":"8","title":"Terminis de la detenció (art. 17.2 CE i arts. 496, 497 i 520.1 LECrim)","blocks":[{"text":"Qui deté una persona —particular, autoritat o agent— l''ha de posar en llibertat o lliurar-la al jutge més pròxim al lloc de la detenció dins de les vint-i-quatre hores següents (art. 496). Si el jutge és el de la causa, ha d''elevar la detenció a presó o deixar-la sense efecte en setanta-dues hores des del lliurament (art. 497).","refs":[{"ref":"Art. 496 LECrim","law":"LECrim","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036","quote":"El particular, Autoridad o agente de Policía judicial que detuviere a una persona en virtud de lo dispuesto en los precedentes artículos, deberá ponerla en libertad o entregarla al Juez más próximo al lugar en que hubiere hecho la detención dentro de las veinticuatro horas siguientes al acto de la misma."},{"ref":"Art. 497 LECrim","law":"LECrim","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036","quote":"elevará la detención a prisión, o la dejará sin efecto, en el término de setenta y dos horas, a contar desde que el detenido le hubiese sido entregado."}]},{"text":"La detenció preventiva no pot durar més del temps estrictament necessari per a les averiguacions i, en tot cas, el detingut ha de ser posat en llibertat o a disposició judicial en el termini màxim de setanta-dues hores (art. 17.2 CE; art. 520.1 LECrim). A l''atestat hi ha de constar el lloc i l''hora de la detenció i de la posada a disposició judicial o, si escau, de la posada en llibertat.","refs":[{"ref":"Art. 17.2 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"La detención preventiva no podrá durar más del tiempo estrictamente necesario para la realización de las averiguaciones tendentes al esclarecimiento de los hechos, y, en todo caso, en el plazo máximo de setenta y dos horas, el detenido deberá ser puesto en libertad o a disposición de la autoridad judicial."},{"ref":"Art. 520.1 LECrim","law":"LECrim","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036","quote":"En el atestado deberá reflejarse el lugar y la hora de la detención y de la puesta a disposición de la autoridad judicial o en su caso, de la puesta en libertad."}]}]},{"n":"9","title":"Forma de practicar la detenció i informació de drets (art. 520.1-2)","blocks":[{"text":"La detenció s''ha de practicar de la manera que menys perjudiqui el detingut en la seva persona, reputació i patrimoni, i qui la practica ha de vetllar pels drets a l''honor, la intimitat i la imatge (art. 520.1). Tota persona detinguda ha de ser informada per escrit, en un llenguatge senzill i accessible, en una llengua que comprengui i de forma immediata, dels fets que se li atribueixen, de les raons de la privació de llibertat i dels seus drets (art. 520.2; vegeu també l''art. 17.3 CE).","refs":[{"ref":"Art. 520.1 LECrim","law":"LECrim","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036","quote":"La detención y la prisión provisional deberán practicarse en la forma que menos perjudique al detenido o preso en su persona, reputación y patrimonio."},{"ref":"Art. 520.2 LECrim","law":"LECrim","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036","quote":"Toda persona detenida o presa será informada por escrito, en un lenguaje sencillo y accesible, en una lengua que comprenda y de forma inmediata, de los hechos que se le atribuyan y las razones motivadoras de su privación de libertad"}]},{"text":"Els drets que s''han d''explicar són, entre d''altres: guardar silenci o declarar només davant el jutge; no declarar contra si mateix ni confessar-se culpable; designar advocat; accedir als elements de les actuacions essencials per impugnar la detenció; que es comuniqui a un familiar o a la persona que vulgui la privació de llibertat i el lloc de custòdia; comunicar-se per telèfon amb un tercer; intèrpret gratuït; reconeixement pel metge forense; i assistència jurídica gratuïta. També se l''ha d''informar del termini màxim de la detenció i de com pot impugnar-ne la legalitat, i pot conservar la declaració escrita de drets durant tota la detenció.","refs":[{"ref":"Art. 520.2 LECrim","law":"LECrim","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036","quote":"a) Derecho a guardar silencio no declarando si no quiere, a no contestar alguna o algunas de las preguntas que le formulen, o a manifestar que sólo declarará ante el juez. b) Derecho a no declarar contra sí mismo y a no confesarse culpable."},{"ref":"Art. 520.2 LECrim","law":"LECrim","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036","quote":"e) Derecho a que se ponga en conocimiento del familiar o persona que desee, sin demora injustificada, su privación de libertad y el lugar de custodia en que se halle en cada momento."},{"ref":"Art. 520.2 LECrim","law":"LECrim","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036","quote":"Asimismo, se le informará del plazo máximo legal de duración de la detención hasta la puesta a disposición de la autoridad judicial y del procedimiento por medio del cual puede impugnar la legalidad de su detención."}]}]},{"n":"10","title":"Detinguts estrangers, menors i amb capacitat modificada (art. 520.2-4)","blocks":[{"text":"Els estrangers tenen dret que la privació de llibertat i el lloc de custòdia es comuniquin a l''oficina consular del seu país, i a ser visitats per les autoritats consulars; si tenen més d''una nacionalitat, poden triar quines autoritats consulars s''han d''informar (art. 520.2.e i g, i 520.3).","refs":[{"ref":"Art. 520.2.e LECrim","law":"LECrim","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036","quote":"Los extranjeros tendrán derecho a que las circunstancias anteriores se comuniquen a la oficina consular de su país."},{"ref":"Art. 520.3 LECrim","law":"LECrim","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036","quote":"En caso de que el detenido tenga dos o más nacionalidades, podrá elegir a qué autoridades consulares debe informarse de que se encuentra privado de libertad y con quién desea comunicarse."}]},{"text":"Si el detingut és menor, es posa a disposició de les seccions de menors de la Fiscalia i es comunica el fet i el lloc de custòdia a qui n''exerceixi la pàtria potestat, la tutela o la guarda de fet, tan bon punt es tingui constància de la minoria d''edat (art. 520.4). Si hi ha conflicte d''interessos, se li nomena un defensor judicial.","refs":[{"ref":"Art. 520.4 LECrim","law":"LECrim","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036","quote":"Si se tratare de un menor, será puesto a disposición de las Secciones de Menores de la Fiscalía y se comunicará el hecho y el lugar de custodia a quienes ejerzan la patria potestad, la tutela o la guarda de hecho del mismo, tan pronto se tenga constancia de la minoría de edad."}]}]},{"n":"11","title":"L''assistència d''advocat (art. 520.5-8)","blocks":[{"text":"El detingut designa lliurement advocat i, si no ho fa, l''assisteix un advocat d''ofici. Cap autoritat o agent no li pot fer cap recomanació sobre l''advocat més enllà d''informar-lo del seu dret (art. 520.5). L''advocat ha d''acudir al centre de detenció amb la màxima promptitud i sempre dins del termini màxim de tres hores des que rep l''encàrrec; si no compareix, el Col·legi d''Advocats en designa un altre d''ofici.","refs":[{"ref":"Art. 520.5 LECrim","law":"LECrim","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036","quote":"El detenido designará libremente abogado y si no lo hace será asistido por un abogado de oficio. Ninguna autoridad o agente le efectuará recomendación alguna sobre el abogado a designar más allá de informarle de su derecho."},{"ref":"Art. 520.5 LECrim","law":"LECrim","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036","quote":"El abogado designado acudirá al centro de detención con la máxima premura, siempre dentro del plazo máximo de tres horas desde la recepción del encargo."}]},{"text":"L''advocat intervé en les declaracions, els reconeixements i les reconstruccions de fets, i es pot entrevistar reservadament amb el detingut, fins i tot abans de la declaració policial (art. 520.6). El detingut pot renunciar a l''assistència preceptiva d''advocat només si la detenció és per fets tipificables exclusivament com a delictes contra la seguretat del trànsit, havent rebut informació clara; la renúncia és revocable en qualsevol moment (art. 520.8).","refs":[{"ref":"Art. 520.6 LECrim","law":"LECrim","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036","quote":"d) Entrevistarse reservadamente con el detenido, incluso antes de que se le reciba declaración por la policía, el fiscal o la autoridad judicial"},{"ref":"Art. 520.8 LECrim","law":"LECrim","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036","quote":"el detenido o preso podrá renunciar a la preceptiva asistencia de abogado si su detención lo fuere por hechos susceptibles de ser tipificados exclusivamente como delitos contra la seguridad del tráfico"},{"ref":"Art. 520.8 LECrim","law":"LECrim","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036","quote":"El detenido podrá revocar su renuncia en cualquier momento."}]}]},{"n":"R","title":"Recorda per a l''examen","blocks":[{"text":"Atestat a l''autoritat judicial o al fiscal: mai més de 24 hores, llevat de força major i de l''atestat sense autor conegut.","refs":[{"ref":"Art. 295 LECrim","law":"LECrim","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036","quote":"En ningún caso los funcionarios de Policía Judicial podrán dejar transcurrir más de veinticuatro horas sin dar conocimiento a la autoridad judicial o al Ministerio Fiscal"}]},{"text":"Sense autor conegut, l''atestat es conserva, tret de delictes contra la vida, la integritat física, la llibertat i indemnitat sexuals o corrupció.","refs":[{"ref":"Art. 284.2 LECrim","law":"LECrim","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036","quote":"a) Que se trate de delitos contra la vida, contra la integridad física, contra la libertad e indemnidad sexuales o de delitos relacionados con la corrupción;"}]},{"text":"L''atestat val com a denúncia a efectes legals.","refs":[{"ref":"Art. 297 LECrim","law":"LECrim","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036","quote":"se considerarán denuncias para los efectos legales."}]},{"text":"Qualsevol persona pot detenir el delinqüent in fraganti; l''agent, a més, hi està obligat.","refs":[{"ref":"Art. 490 LECrim","law":"LECrim","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036","quote":"2.º Al delincuente in fraganti."}]},{"text":"Per delictes lleus no es deté, llevat que no hi hagi domicili conegut ni fiança suficient.","refs":[{"ref":"Art. 495 LECrim","law":"LECrim","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036","quote":"No se podrá detener por la presunta comisión de delitos leves, a no ser que el presunto reo no tuviese domicilio conocido ni diese fianza bastante"}]},{"text":"Lliurament al jutge més pròxim o llibertat: dins de les 24 hores (art. 496); detenció preventiva: màxim 72 hores (art. 17.2 CE).","refs":[{"ref":"Art. 496 LECrim","law":"LECrim","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036","quote":"dentro de las veinticuatro horas siguientes al acto de la misma."}]},{"text":"Informació de drets: per escrit, llenguatge senzill i accessible, llengua que comprengui i de forma immediata.","refs":[{"ref":"Art. 520.2 LECrim","law":"LECrim","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036","quote":"por escrito, en un lenguaje sencillo y accesible, en una lengua que comprenda y de forma inmediata"}]},{"text":"L''advocat ha de comparèixer en un màxim de tres hores des de l''encàrrec.","refs":[{"ref":"Art. 520.5 LECrim","law":"LECrim","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036","quote":"siempre dentro del plazo máximo de tres horas desde la recepción del encargo."}]},{"text":"Renúncia a advocat: només per delictes exclusivament contra la seguretat del trànsit.","refs":[{"ref":"Art. 520.8 LECrim","law":"LECrim","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036","quote":"exclusivamente como delitos contra la seguridad del tráfico"}]}]}]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036', null, null, null, null
