insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, lessons, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"Entrada i registre en lloc tancat: concepte de domicili (arts. 545-554)"},{"n":"2","title":"Autorització judicial i consentiment"},{"n":"3","title":"Pràctica del registre i acta (arts. 566-569)"},{"n":"4","title":"Habeas corpus: objecte i persones il·legalment detingudes (LO 6/1984, arts. 1 i 2)"},{"n":"5","title":"Legitimació i iniciació (arts. 3 i 4)"},{"n":"6","title":"Tramitació i resolució (arts. 5-8)"}]'::jsonb, '["Art. 545 LECrim: «Nadie podrá entrar en el domicilio de un español o extranjero residente en España sin su consentimiento, excepto en los casos y en la forma expresamente previstos en las leyes.»","Art. 550 LECrim: «o a falta de consentimiento, en virtud de auto motivado, que se notificará a la persona interesada inmediatamente, o lo más tarde dentro de las veinticuatro horas de haberse dictado.»","Art. 553 LECrim: «cuando un delincuente, inmediatamente perseguido por los Agentes de la autoridad, se oculte o refugie en alguna casa»","Art. 554 LECrim: «3.º Los buques nacionales mercantes.»","Art. 554.4 LECrim: «el espacio físico que constituya el centro de dirección de las mismas, ya se trate de su domicilio social o de un establecimiento dependiente»","Art. 558 LECrim: «El auto de entrada y registro en el domicilio de un particular será siempre fundado, y el Juez expresará en él concretamente el edificio o lugar cerrado en que haya de verificarse, si tendrá lugar tan sólo de día y la Autoridad o funcionario que los haya de practicar.»","Art. 566 LECrim: «Si no se halla a nadie, se hará constar por diligencia, que se extenderá con asistencia de dos vecinos, los cuales deberán firmarla.»","Art. 569 LECrim: «El registro se practicará siempre en presencia del Secretario del Juzgado o Tribunal que lo hubiera autorizado, o del Secretario del servicio de guardia que le sustituya»","Art. 1 LO 6/1984: «se podrá obtener la inmediata puesta a disposición de la Autoridad judicial competente, de cualquier persona detenida ilegalmente.»","Art. 2 LO 6/1984: «Es competente para conocer la solicitud de «Habeas Corpus» el Juez de Instrucción del lugar en que se encuentre la persona privada de libertad»","Art. 3 LO 6/1984: «b) El Ministerio Fiscal. c) El Defensor del Pueblo. d) El abogado defensor del privado de libertad.»","Art. 4 LO 6/1984: «no siendo preceptiva la intervención de Abogado ni de Procurador.»","Art. 5 LO 6/1984: «La autoridad gubernativa, agente de la misma o funcionario público, estarán obligados a poner inmediatamente en conocimiento del Juez competente la solicitud de «Habeas Corpus»»","Art. 6 LO 6/1984: «Contra la resolución que en uno u otro caso se adopte, no cabrá recurso alguno.»","Art. 7 LO 6/1984: «En el plazo de veinticuatro horas, contadas desde que sea dictado el auto de incoación, los Jueces practicarán todas las actuaciones a que se refiere este artículo y dictarán la resolución que proceda.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[{"n":"1","title":"La inviolabilitat del domicili (art. 18.2 CE i art. 545 LECrim)","blocks":[{"text":"La Constitució declara el domicili inviolable: no s''hi pot entrar ni fer-hi cap registre sense consentiment del titular o resolució judicial, llevat del cas de flagrant delicte (art. 18.2 CE). La LECrim, al capítol I del títol VIII del llibre II, desenvolupa aquesta garantia: ningú no pot entrar al domicili d''un espanyol o d''un estranger resident a Espanya sense el seu consentiment, excepte en els casos i en la forma expressament previstos a les lleis (art. 545). Hi ha, doncs, tres títols habilitants: consentiment, resolució judicial i flagrant delicte.","refs":[{"ref":"Art. 18.2 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"El domicilio es inviolable. Ninguna entrada o registro podrá hacerse en él sin consentimiento del titular o resolución judicial, salvo en caso de flagrante delito."},{"ref":"Art. 545 LECrim","law":"LECrim","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036","quote":"Nadie podrá entrar en el domicilio de un español o extranjero residente en España sin su consentimiento, excepto en los casos y en la forma expresamente previstos en las leyes."}]}]},{"n":"2","title":"Concepte de domicili i llocs públics (arts. 546, 547 i 554)","blocks":[{"text":"A efectes de l''entrada i registre, l''article 554 considera domicili: els palaus reials, estiguin habitats o no pel monarca; l''edifici o lloc tancat, o la part destinada principalment a l''habitatge de qualsevol espanyol o estranger resident a Espanya i de la seva família; els vaixells mercants nacionals; i, quan es tracta de persones jurídiques investigades, l''espai físic que constitueix el seu centre de direcció —domicili social o establiment dependent— o els llocs on custodien documents o suports de la seva vida diària reservats al coneixement de tercers. El text consolidat encara parla de persones jurídiques «imputadas».","refs":[{"ref":"Art. 554 LECrim","law":"LECrim","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036","quote":"1.º Los Palacios Reales, estén o no habitados por el Monarca al tiempo de la entrada o registro. 2.º El edificio o lugar cerrado, o la parte de él destinada principalmente a la habitación de cualquier español o extranjero residente en España y de su familia. 3.º Los buques nacionales mercantes."},{"ref":"Art. 554.4 LECrim","law":"LECrim","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036","quote":"4.º Tratándose de personas jurídicas imputadas, el espacio físico que constituya el centro de dirección de las mismas, ya se trate de su domicilio social o de un establecimiento dependiente, o aquellos otros lugares en que se custodien documentos u otros soportes de su vida diaria que quedan reservados al conocimiento de terceros."}]},{"text":"En canvi, són edificis o llocs públics els destinats a un servei oficial de l''Estat, la província o el municipi; els establiments de reunió o esbarjo, lícits o no; qualsevol altre lloc tancat que no sigui domicili d''un particular; i els vaixells de l''Estat (art. 547). El jutge que coneix de la causa hi pot decretar l''entrada i registre, de dia o de nit, quan hi hagi indicis que s''hi troba el processat o efectes, instruments o proves del delicte (art. 546).","refs":[{"ref":"Art. 547 LECrim","law":"LECrim","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036","quote":"1.º Los que estuvieren destinados a cualquier servicio oficial, militar o civil del Estado, de la Provincia o del Municipio, aunque habiten allí los encargados de dicho servicio o los de la conservación y custodia del edificio o lugar. 2.º Los que estuvieren destinados a cualquier establecimiento de reunión o recreo, fueren o no lícitos."},{"ref":"Art. 546 LECrim","law":"LECrim","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036","quote":"El Juez o Tribunal que conociere de la causa podrá decretar la entrada y registro, de día o de noche, en todos los edificios y lugares públicos"}]},{"text":"Alguns llocs tenen regles pròpies: al palau de qualsevol de les cambres de les Corts cal autorització del president de la cambra (art. 548); als temples n''hi ha prou de passar un avís d''atenció als responsables (art. 549); i a les seus de representants de nacions estrangeres el jutge demana la vènia per ofici, amb un termini de dotze hores per contestar (art. 559).","refs":[{"ref":"Art. 548 LECrim","law":"LECrim","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036","quote":"El Juez necesitará para la entrada y registro en el Palacio de cualquiera de los Cuerpos Colegisladores la autorización del Presidente respectivo."},{"ref":"Art. 549 LECrim","law":"LECrim","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036","quote":"Para la entrada y registro en los templos y demás lugares religiosos bastará pasar recado de atención a las personas a cuyo cargo estuvieren."},{"ref":"Art. 559 LECrim","law":"LECrim","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036","quote":"les pedirá su venia el Juez, por medio de atento oficio, en el que les rogará que contesten en el término de doce horas."}]}]},{"n":"3","title":"El consentiment del titular (arts. 550 i 551)","blocks":[{"text":"El primer títol habilitant és el consentiment de l''interessat. La llei entén que consent qui, requerit per fer l''entrada i registre, fa els actes necessaris que depenen d''ell perquè es pugui fer, sense invocar la inviolabilitat del domicili (art. 551). Les referències a «l''article 6.º de la Constitució» són a la Constitució vigent el 1882, no a la de 1978.","refs":[{"ref":"Art. 551 LECrim","law":"LECrim","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036","quote":"Se entenderá que presta su consentimiento aquel que, requerido por quien hubiere de efectuar la entrada y registro para que los permita, ejecuta por su parte los actos necesarios que de él dependan para que puedan tener efecto, sin invocar la inviolabilidad que reconoce al domicilio el artículo 6.º de la Constitución del Estado."}]}]},{"n":"4","title":"L''autorització judicial: interlocutòria motivada (arts. 550, 558 i 563)","blocks":[{"text":"A falta de consentiment, el jutge instructor pot ordenar l''entrada i registre en un domicili, de dia o de nit si la urgència ho fa necessari, mitjançant una interlocutòria (auto) motivada, que s''ha de notificar a l''interessat immediatament o, com a molt tard, dins de les vint-i-quatre hores d''haver-se dictat (art. 550).","refs":[{"ref":"Art. 550 LECrim","law":"LECrim","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036","quote":"la entrada y registro, de día o de noche, si la urgencia lo hiciere necesario, en cualquier edificio o lugar cerrado o parte de él, que constituya domicilio de cualquier español o extranjero residente en España, pero precediendo siempre el consentimiento del interesado"},{"ref":"Art. 550 LECrim","law":"LECrim","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036","quote":"o a falta de consentimiento, en virtud de auto motivado, que se notificará a la persona interesada inmediatamente, o lo más tarde dentro de las veinticuatro horas de haberse dictado."}]},{"text":"La interlocutòria ha de ser sempre fonamentada i ha d''expressar concretament l''edifici o lloc tancat, si el registre només es pot fer de dia i l''autoritat o funcionari que l''ha de practicar (art. 558). El jutge pot encomanar l''entrada i registre a qualsevol autoritat o agent de policia judicial (art. 563).","refs":[{"ref":"Art. 558 LECrim","law":"LECrim","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036","quote":"El auto de entrada y registro en el domicilio de un particular será siempre fundado, y el Juez expresará en él concretamente el edificio o lugar cerrado en que haya de verificarse, si tendrá lugar tan sólo de día y la Autoridad o funcionario que los haya de practicar."},{"ref":"Art. 563 LECrim","law":"LECrim","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036","quote":"podrá encomendar la entrada y registro al Juez municipal del territorio en que el edificio o lugar cerrado radiquen, o a cualquier Autoridad o agente de Policía judicial."}]}]},{"n":"5","title":"Entrada policial sense autorització judicial (art. 553 LECrim i art. 15 LOPSC)","blocks":[{"text":"Els agents poden actuar per pròpia autoritat i detenir immediatament una persona, sigui quin sigui el domicili on s''amagui, quan hi ha manament de presó contra ella, quan és sorpresa en flagrant delicte, quan un delinqüent perseguit immediatament pels agents s''amaga o es refugia en una casa, o, en casos d''excepcional o urgent necessitat, quan es tracta de presumptes responsables de terrorisme (accions de l''art. 384 bis LECrim). Això inclou el registre que es faci amb ocasió de la detenció i l''ocupació dels efectes relacionats amb el delicte (art. 553).","refs":[{"ref":"Art. 553 LECrim","law":"LECrim","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036","quote":"Los Agentes de policía podrán asimismo proceder de propia autoridad a la inmediata detención de las personas cuando haya mandamiento de prisión contra ellas, cuando sean sorprendidas en flagrante delito, cuando un delincuente, inmediatamente perseguido por los Agentes de la autoridad, se oculte o refugie en alguna casa"}]},{"text":"D''aquest registre se n''ha de donar compte immediat al jutge competent, indicant-ne les causes i els resultats, especialment les detencions practicades, així com les persones que hi han intervingut i els incidents.","refs":[{"ref":"Art. 553 LECrim","law":"LECrim","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036","quote":"Del registro efectuado, conforme a lo establecido en el párrafo anterior, se dará cuenta inmediata al Juez competente, con indicación de las causas que lo motivaron y de los resultados obtenidos en el mismo, con especial referencia a las detenciones que, en su caso, se hubieran practicado."}]},{"text":"Fora del procés penal, la Llei de seguretat ciutadana considera causa legítima d''entrada en domicili la necessitat d''evitar danys imminents i greus a persones i coses en casos de catàstrofe, calamitat, ruïna imminent o d''extrema i urgent necessitat; l''acta o atestat s''ha de remetre sense dilació a l''autoritat judicial (art. 15 LOPSC).","refs":[{"ref":"Art. 15.2 LOPSC","law":"LO 4/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442","quote":"Será causa legítima suficiente para la entrada en domicilio la necesidad de evitar daños inminentes y graves a las personas y a las cosas, en supuestos de catástrofe, calamidad, ruina inminente u otros semejantes de extrema y urgente necesidad."},{"ref":"Art. 15.4 LOPSC","law":"LO 4/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442","quote":"remitirán sin dilación el acta o atestado que instruyan a la autoridad judicial competente."}]}]},{"n":"6","title":"Pràctica del registre: notificació, vigilància i presència (arts. 552 i 566-569)","blocks":[{"text":"La interlocutòria es notifica al titular; si no hi és, al seu encarregat; si tampoc, a qualsevol persona major d''edat que sigui al domicili, preferint els familiars; i si no hi ha ningú, es fa constar per diligència estesa amb l''assistència de dos veïns, que l''han de signar (art. 566). El jutge adopta mesures de vigilància per evitar la fuga o la sostracció d''objectes (art. 567) i, si cal, es fa servir l''auxili de la força (art. 568).","refs":[{"ref":"Art. 566 LECrim","law":"LECrim","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036","quote":"Si no fuere tampoco habido el encargado, se hará la notificación a cualquier otra persona mayor de edad que se hallare en el domicilio, prefiriendo para esto a los individuos de la familia del interesado. Si no se halla a nadie, se hará constar por diligencia, que se extenderá con asistencia de dos vecinos, los cuales deberán firmarla."},{"ref":"Art. 568 LECrim","law":"LECrim","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036","quote":"se procederá a la entrada y registro, empleando para ello, si fuere necesario, el auxilio de la fuerza."}]},{"text":"El registre es fa en presència de l''interessat o del seu representant; si no se''l troba o no vol assistir-hi ni nomenar representant, davant d''un familiar major d''edat; i si no n''hi ha, davant de dos testimonis veïns del mateix poble (art. 569). Sempre hi ha de ser present el secretari del jutjat o tribunal que l''ha autoritzat —avui lletrat de l''Administració de justícia, encara que el text consolidat diu «Secretario»— o el de guàrdia, que n''aixeca acta signada per tots els assistents.","refs":[{"ref":"Art. 569 LECrim","law":"LECrim","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036","quote":"El registro se hará a presencia del interesado o de la persona que legítimamente le represente. Si aquél no fuere habido o no quisiese concurrir ni nombrar representante, se practicará a presencia de un individuo de su familia mayor de edad. Si no le hubiere, se hará a presencia de dos testigos, vecinos del mismo pueblo."},{"ref":"Art. 569 LECrim","law":"LECrim","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036","quote":"El registro se practicará siempre en presencia del Secretario del Juzgado o Tribunal que lo hubiera autorizado, o del Secretario del servicio de guardia que le sustituya, quien levantará acta del resultado, de la diligencia y de sus incidencias y que será firmada por todos los asistentes."}]},{"text":"Resistir-se a presenciar el registre genera la responsabilitat del delicte de desobediència greu, però el registre es fa igualment (art. 569). S''han d''evitar inspeccions inútils, no perjudicar l''interessat més del necessari i respectar-ne els secrets que no interessin a la instrucció (art. 552).","refs":[{"ref":"Art. 569 LECrim","law":"LECrim","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036","quote":"producirá la responsabilidad declarada en el Código Penal a los reos del delito de desobediencia grave a la Autoridad, sin perjuicio de que la diligencia se practique."},{"ref":"Art. 552 LECrim","law":"LECrim","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036","quote":"Al practicar los registros deberán evitarse las inspecciones inútiles, procurando no perjudicar ni importunar al interesado más de lo necesario"}]}]},{"n":"7","title":"Registre que no acaba de dia i acta (arts. 570-572)","blocks":[{"text":"Si s''acaba el dia sense haver acabat el registre en un domicili particular, cal demanar a l''interessat que en permeti la continuació de nit; si s''hi oposa, se suspèn (llevat que la interlocutòria l''hagi autoritzat de nit) i es tanca i segella el local (art. 570). L''acta ha d''expressar els noms dels qui intervenen, els incidents, l''hora d''inici i de final i la relació i els resultats del registre (art. 572).","refs":[{"ref":"Art. 570 LECrim","law":"LECrim","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036","quote":"el que lo haga requerirá al interesado o a su representante, si estuviere presente, para que permita la continuación durante la noche. Si se opusiere, se suspenderá la diligencia, salvo lo dispuesto en los artículos 546 y 550, cerrando y sellando el local o los muebles en que hubiere de continuarse"},{"ref":"Art. 572 LECrim","law":"LECrim","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036","quote":"se expresarán los nombres del Juez, o de su delegado, que la practique y de las demás personas que intervengan, los incidentes ocurridos, la hora en que se hubiese principiado y concluido la diligencia, y la relación del registro por el orden con que se haga, así como los resultados obtenidos."}]},{"text":"El registre no es pot suspendre més que pel temps en què sigui impossible continuar-lo, i durant la suspensió es mantenen les mesures de vigilància de l''article 567 (art. 571). Si no es troben les persones o els objectes buscats ni apareixen indicis sospitosos, s''expedeix a l''interessat, si ho reclama, una certificació de l''acta (art. 569).","refs":[{"ref":"Art. 571 LECrim","law":"LECrim","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036","quote":"El registro no se suspenderá sino por el tiempo en que no fuere posible continuarle, y se adoptarán, durante la suspensión, las medidas de vigilancia a que se refiere el artículo 567."},{"ref":"Art. 569 LECrim","law":"LECrim","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036","quote":"Si no se encontrasen las personas u objetos que se busquen ni apareciesen indicios sospechosos, se expedirá una certificación del acta a la parte interesada si la reclamare."}]}]},{"n":"8","title":"Habeas corpus: objecte i persones il·legalment detingudes (art. 17.4 CE i art. 1 LOHC)","blocks":[{"text":"L''article 17.4 CE encarrega a la llei un procediment d''habeas corpus per posar immediatament a disposició judicial tota persona detinguda il·legalment. El regula la Llei orgànica 6/1984: permet obtenir la posada immediata a disposició de l''autoritat judicial competent de qualsevol persona detinguda il·legalment (art. 1).","refs":[{"ref":"Art. 17.4 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"La ley regulará un procedimiento de «habeas corpus» para producir la inmediata puesta a disposición judicial de toda persona detenida ilegalmente."},{"ref":"Art. 1 LOHC","law":"LO 6/1984","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1984-11620","quote":"Mediante el procedimiento del «Habeas Corpus», regulado en la presente ley, se podrá obtener la inmediata puesta a disposición de la Autoridad judicial competente, de cualquier persona detenida ilegalmente."}]},{"text":"Es consideren il·legalment detingudes: les detingudes per una autoritat, agent, funcionari o particular sense que hi concorrin els supòsits legals o sense complir les formalitats; les il·lícitament internades en qualsevol establiment o lloc; les retingudes més enllà del termini legal sense ser alliberades o lliurades al jutge més pròxim; i les privades de llibertat a qui no es respecten els drets que garanteixen la Constitució i les lleis processals. Una detenció in fraganti, amb informació de drets i lliurament dins de termini, no n''és cap.","refs":[{"ref":"Art. 1 LOHC","law":"LO 6/1984","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1984-11620","quote":"a) Las que lo fueren por una autoridad, agente de la misma, funcionario público o particular, sin que concurran los supuestos legales, o sin haberse cumplido las formalidades prevenidas y requisitos exigidos por las leyes. b) Las que estén ilícitamente internadas en cualquier establecimiento o lugar. c) Las que lo estuvieran por plazo superior al señalado en las leyes, si transcurrido el mismo, no fuesen puestas en libertad o entregadas al Juez más próximo al lugar de la detención. d) Las privadas de libertad a quienes no les sean respetados los derechos que la Constitución y las leyes procesales garantizan a toda persona detenida."}]}]},{"n":"9","title":"Competència, legitimació i inici (arts. 2-5 LOHC)","blocks":[{"text":"És competent el jutge d''instrucció del lloc on es troba la persona privada de llibertat; si no consta, el del lloc de la detenció; i, si no, el del lloc de les darreres notícies sobre el seu parador. En detencions per terrorisme (art. 55.2 CE) és competent el jutge central d''instrucció (art. 2).","refs":[{"ref":"Art. 2 LOHC","law":"LO 6/1984","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1984-11620","quote":"Es competente para conocer la solicitud de «Habeas Corpus» el Juez de Instrucción del lugar en que se encuentre la persona privada de libertad; si no constare, el del lugar en que se produzca la detención, y, en defecto de los anteriores, el del lugar donde se hayan tenido las últimas noticias sobre el paradero del detenido."}]},{"text":"Poden instar el procediment: el mateix privat de llibertat, el seu cònjuge o parella anàloga, descendents, ascendents i germans, i els representants legals dels menors; el Ministeri Fiscal; el Defensor del Poble; i l''advocat defensor. També el pot iniciar d''ofici el jutge (art. 3). Els agents que han practicat la detenció no hi són legitimats.","refs":[{"ref":"Art. 3 LOHC","law":"LO 6/1984","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1984-11620","quote":"a) El privado de libertad, su cónyuge o persona unida por análoga relación de afectividad, descendientes, ascendientes, hermanos y, en su caso, respecto a los menores, sus representantes legales"},{"ref":"Art. 3 LOHC","law":"LO 6/1984","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1984-11620","quote":"b) El Ministerio Fiscal. c) El Defensor del Pueblo. d) El abogado defensor del privado de libertad. Asimismo, lo podrá iniciar, de oficio, el Juez competente a que se refiere el artículo anterior."}]},{"text":"S''inicia per escrit o compareixença, sense que calgui advocat ni procurador, i hi ha de constar la identitat del sol·licitant i del detingut, el lloc i la custòdia i el motiu concret (art. 4). L''autoritat, l''agent o el funcionari que té el detingut sota custòdia està obligat a comunicar immediatament la sol·licitud al jutge; si no ho fa, el jutge l''apercep, sens perjudici de responsabilitats penals i disciplinàries (art. 5).","refs":[{"ref":"Art. 4 LOHC","law":"LO 6/1984","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1984-11620","quote":"El procedimiento se iniciará, salvo cuando se incoe de oficio, por medio de escrito o comparecencia, no siendo preceptiva la intervención de Abogado ni de Procurador."},{"ref":"Art. 5 LOHC","law":"LO 6/1984","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1984-11620","quote":"La autoridad gubernativa, agente de la misma o funcionario público, estarán obligados a poner inmediatamente en conocimiento del Juez competente la solicitud de «Habeas Corpus», formulada por la persona privada de libertad que se encuentre bajo su custodia. Si incumplieren esta obligación, serán apercibidos por el Juez, sin perjuicio de las responsabilidades penales y disciplinarias en que pudieran incurrir."}]}]},{"n":"10","title":"Tramitació i resolució (arts. 6-9 LOHC)","blocks":[{"text":"El jutge examina els requisits, dona trasllat al fiscal i, per interlocutòria, acorda la incoació o denega la sol·licitud per improcedent; contra aquesta resolució no hi cap cap recurs (art. 6). En la interlocutòria d''incoació ordena que se li presenti el detingut o es desplaça on és; escolta el detingut, el seu advocat, el fiscal i l''autoritat o agent que va practicar la detenció, i admet proves. Tot s''ha de fer i resoldre en vint-i-quatre hores des de la interlocutòria d''incoació (art. 7).","refs":[{"ref":"Art. 6 LOHC","law":"LO 6/1984","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1984-11620","quote":"Seguidamente, mediante auto, acordará la incoación del procedimiento, o, en su caso, denegará la solicitud por ser ésta improcedente. Dicho auto se notificará, en todo caso, al Ministerio Fiscal. Contra la resolución que en uno u otro caso se adopte, no cabrá recurso alguno."},{"ref":"Art. 7 LOHC","law":"LO 6/1984","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1984-11620","quote":"En el plazo de veinticuatro horas, contadas desde que sea dictado el auto de incoación, los Jueces practicarán todas las actuaciones a que se refiere este artículo y dictarán la resolución que proceda."}]},{"text":"Per interlocutòria motivada, el jutge arxiva si la detenció és conforme a dret o, si és il·legal, acorda: la llibertat; la continuació de la privació de llibertat, si cal en un altre establiment o sota altres custodis; o la posada immediata a disposició judicial si ja ha passat el termini (art. 8). A més, dedueix testimoni per perseguir els delictes comesos i condemna en costes el sol·licitant temerari o de mala fe (art. 9).","refs":[{"ref":"Art. 8 LOHC","law":"LO 6/1984","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1984-11620","quote":"a) La puesta en libertad del privado de ésta, si lo fue ilegalmente. b) Que continúe la situación de privación de libertad de acuerdo con las disposiciones legales aplicables al caso, pero, si lo considerase necesario, en establecimiento distinto, o bajo la custodia de personas distintas a las que hasta entonces la detentaban. c) Que la persona privada de libertad sea puesta inmediatamente a disposición judicial, si ya hubiese transcurrido el plazo legalmente establecido para su detención."},{"ref":"Art. 9 LOHC","law":"LO 6/1984","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1984-11620","quote":"si se apreciase temeridad o mala fe, será condenado el solicitante al pago de las costas del procedimiento"}]}]},{"n":"R","title":"Recorda per a l''examen","blocks":[{"text":"Domicili: entrada amb consentiment, resolució judicial o flagrant delicte.","refs":[{"ref":"Art. 18.2 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"sin consentimiento del titular o resolución judicial, salvo en caso de flagrante delito."}]},{"text":"Els vaixells mercants nacionals són domicili; els vaixells de l''Estat són llocs públics.","refs":[{"ref":"Art. 554 LECrim","law":"LECrim","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036","quote":"3.º Los buques nacionales mercantes."}]},{"text":"Interlocutòria d''entrada: motivada i notificada immediatament o, com a molt tard, en 24 hores.","refs":[{"ref":"Art. 550 LECrim","law":"LECrim","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036","quote":"inmediatamente, o lo más tarde dentro de las veinticuatro horas de haberse dictado."}]},{"text":"Si no hi ha ningú al domicili: diligència amb dos veïns que la signen.","refs":[{"ref":"Art. 566 LECrim","law":"LECrim","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036","quote":"se hará constar por diligencia, que se extenderá con asistencia de dos vecinos, los cuales deberán firmarla."}]},{"text":"Registre per persecució immediata: compte immediat al jutge amb causes, resultats i detencions.","refs":[{"ref":"Art. 553 LECrim","law":"LECrim","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036","quote":"se dará cuenta inmediata al Juez competente"}]},{"text":"Habeas corpus: jutge d''instrucció del lloc on és el detingut.","refs":[{"ref":"Art. 2 LOHC","law":"LO 6/1984","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1984-11620","quote":"el Juez de Instrucción del lugar en que se encuentre la persona privada de libertad"}]},{"text":"Sol·licitud sense advocat ni procurador; l''agent custodi l''ha de comunicar immediatament al jutge.","refs":[{"ref":"Art. 4 LOHC","law":"LO 6/1984","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1984-11620","quote":"no siendo preceptiva la intervención de Abogado ni de Procurador."}]},{"text":"Contra la interlocutòria d''incoació o de denegació no hi cap recurs; resolució en 24 hores.","refs":[{"ref":"Art. 6 LOHC","law":"LO 6/1984","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1984-11620","quote":"Contra la resolución que en uno u otro caso se adopte, no cabrá recurso alguno."}]}]}]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036', null, null, null, 'Otras normas citadas: LO 6/1984 (https://www.boe.es/buscar/act.php?id=BOE-A-1984-11620)'
  from public.topics t where t.slug = 'plcat-t14-entrada-registre-habeas-corpus'
