insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('policia-local') and t.slug = 'plcat-t15-codi-penal-persones' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, lessons, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"Lesions (arts. 147-156)"},{"n":"2","title":"Detencions il·legals i segrests (arts. 163-168)"},{"n":"3","title":"Amenaces i coaccions (arts. 169-172)"},{"n":"4","title":"Tortures i altres delictes contra la integritat moral (arts. 173-177)"},{"n":"5","title":"Delictes contra la llibertat sexual (arts. 178-191)"}]'::jsonb, '["Art. 147.1 Codi penal: «siempre que la lesión requiera objetivamente para su sanidad, además de una primera asistencia facultativa, tratamiento médico o quirúrgico.»","Art. 147.3-4 Codi penal: «3. El que golpeare o maltratare de obra a otro sin causarle lesión, será castigado con la pena de multa de uno a dos meses.»","Art. 148 Codi penal: «3.º Si la víctima fuere menor de catorce años o persona con discapacidad necesitada de especial protección.»","Art. 149 Codi penal: «la pérdida o la inutilidad de un órgano o miembro principal, o de un sentido, la impotencia, la esterilidad, una grave deformidad, o una grave enfermedad somática o psíquica, será castigado con la pena de prisión de seis a 12 años.»","Art. 163 Codi penal: «1. El particular que encerrare o detuviere a otro, privándole de su libertad, será castigado con la pena de prisión de cuatro a seis años.»","Art. 163.2 Codi penal: «2. Si el culpable diera libertad al encerrado o detenido dentro de los tres primeros días de su detención, sin haber logrado el objeto que se había propuesto, se impondrá la pena inferior en grado.»","Art. 163.4 Codi penal: «4. El particular que, fuera de los casos permitidos por las leyes, aprehendiere a una persona para presentarla inmediatamente a la autoridad, será castigado con la pena de multa de tres a seis meses.»","Art. 167 Codi penal: «será castigado con las penas respectivamente previstas en éstos, en su mitad superior, pudiéndose llegar hasta la superior en grado.»","Art. 169 Codi penal: «Las penas señaladas en el párrafo anterior se impondrán en su mitad superior si las amenazas se hicieren por escrito, por teléfono o por cualquier medio de comunicación o de reproducción, o en nombre de entidades o grupos reales o supuestos.»","Art. 172.1 Codi penal: «1. El que, sin estar legítimamente autorizado, impidiere a otro con violencia hacer lo que la ley no prohíbe, o le compeliere a efectuar lo que no quiere, sea justo o injusto»","Art. 173.1 Codi penal: «1. El que infligiera a otra persona un trato degradante, menoscabando gravemente su integridad moral, será castigado con la pena de prisión de seis meses a dos años.»","Art. 174 Codi penal: «1. Comete tortura la autoridad o funcionario público que, abusando de su cargo, y con el fin de obtener una confesión o información de cualquier persona»","Art. 178.1 Codi penal: «Sólo se entenderá que hay consentimiento cuando se haya manifestado libremente mediante actos que, en atención a las circunstancias del caso, expresen de manera clara la voluntad de la persona.»","Art. 179 Codi penal: «el responsable será castigado como reo de violación con la pena de prisión de cuatro a doce años.»","Art. 181 Codi penal: «1. El que realizare actos de carácter sexual con un menor de dieciséis años, será castigado con la pena de prisión de dos a seis años.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[{"n":"1","title":"Lesions: tipus bàsic i delictes lleus (art. 147 CP)","blocks":[{"text":"El títol III del llibre II del Codi penal (CP) castiga qui, per qualsevol mitjà o procediment, causa a una altra persona una lesió que menyscaba la seva integritat corporal o la seva salut física o mental. El tipus bàsic (art. 147.1) es castiga amb presó de tres mesos a tres anys o multa de sis a dotze mesos, sempre que la lesió requereixi objectivament per a la seva sanitat, a més d''una primera assistència facultativa, tractament mèdic o quirúrgic. La simple vigilància o el seguiment facultatiu del curs de la lesió no es considera tractament mèdic.","refs":[{"ref":"Art. 147.1 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"El que, por cualquier medio o procedimiento, causare a otro una lesión que menoscabe su integridad corporal o su salud física o mental, será castigado, como reo del delito de lesiones con la pena de prisión de tres meses a tres años o multa de seis a doce meses, siempre que la lesión requiera objetivamente para su sanidad, además de una primera asistencia facultativa, tratamiento médico o quirúrgico. La simple vigilancia o seguimiento facultativo del curso de la lesión no se considerará tratamiento médico."}]},{"text":"La lesió que no necessita tractament es castiga amb multa d''un a tres mesos (art. 147.2), i colpejar o maltractar d''obra algú sense causar-li lesió, amb multa d''un a dos mesos (art. 147.3). Aquests dos delictes lleus només són perseguibles per denúncia de la persona agreujada o del seu representant legal (art. 147.4). Per a l''agent, això vol dir que cal informar la víctima que la denúncia és imprescindible.","refs":[{"ref":"Art. 147.2-4 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"2. El que, por cualquier medio o procedimiento, causare a otro una lesión no incluida en el apartado anterior, será castigado con la pena de multa de uno a tres meses. 3. El que golpeare o maltratare de obra a otro sin causarle lesión, será castigado con la pena de multa de uno a dos meses. 4. Los delitos previstos en los dos apartados anteriores sólo serán perseguibles mediante denuncia de la persona agraviada o de su representante legal."}]}]},{"n":"2","title":"Lesions agreujades i per resultat (arts. 148-150)","blocks":[{"text":"Les lesions del 147.1 es poden castigar amb presó de dos a cinc anys, atenent el resultat o el risc, si s''han fet servir armes o mitjans concretament perillosos; si hi ha hagut acarnissament o traïdoria; si la víctima és menor de catorze anys o persona amb discapacitat necessitada d''especial protecció; si és o ha estat esposa o parella de l''autor, encara que sense convivència; o si és una persona especialment vulnerable que hi conviu (art. 148).","refs":[{"ref":"Art. 148 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"podrán ser castigadas con la pena de prisión de dos a cinco años, atendiendo al resultado causado o riesgo producido: 1.º Si en la agresión se hubieren utilizado armas, instrumentos, objetos, medios, métodos o formas concretamente peligrosas para la vida o salud, física o psíquica, del lesionado. 2.º Si hubiere mediado ensañamiento o alevosía. 3.º Si la víctima fuere menor de catorce años o persona con discapacidad necesitada de especial protección."},{"ref":"Art. 148 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"4.º Si la víctima fuere o hubiere sido esposa, o mujer que estuviere o hubiere estado ligada al autor por una análoga relación de afectividad, aun sin convivencia. 5.º Si la víctima fuera una persona especialmente vulnerable que conviva con el autor."}]},{"text":"Segons el resultat, causar la pèrdua o la inutilitat d''un òrgan o membre principal, o d''un sentit, la impotència, l''esterilitat, una deformitat greu o una malaltia somàtica o psíquica greu es castiga amb presó de sis a dotze anys (art. 149.1); la mateixa pena té la mutilació genital (art. 149.2). Si l''òrgan o membre és no principal, o es causa una deformitat (sense el qualificatiu de greu), la pena és de tres a sis anys (art. 150).","refs":[{"ref":"Art. 149.1 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"la pérdida o la inutilidad de un órgano o miembro principal, o de un sentido, la impotencia, la esterilidad, una grave deformidad, o una grave enfermedad somática o psíquica, será castigado con la pena de prisión de seis a 12 años."},{"ref":"Art. 150 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"El que causare a otro la pérdida o la inutilidad de un órgano o miembro no principal, o la deformidad, será castigado con la pena de prisión de tres a seis años."}]}]},{"n":"3","title":"Lesions per imprudència, violència a la parella i consentiment (arts. 152, 153, 155 i 156)","blocks":[{"text":"Les lesions per imprudència greu es castiguen segons el resultat; si s''han comès amb vehicle de motor o ciclomotor, s''hi afegeix la privació del dret a conduir d''un a quatre anys, i es considera en tot cas imprudència greu la conducció en què una circumstància de l''article 379 determini el fet (art. 152.1). Les comeses per imprudència menys greu només són perseguibles per denúncia (art. 152.2).","refs":[{"ref":"Art. 152.1 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"Si los hechos se hubieran cometido utilizando un vehículo a motor o un ciclomotor, se impondrá asimismo la pena de privación del derecho a conducir vehículos a motor y ciclomotores de uno a cuatro años. A los efectos de este apartado, se reputará en todo caso como imprudencia grave la conducción en la que la concurrencia de alguna de las circunstancias previstas en el artículo 379 determinara la producción del hecho."},{"ref":"Art. 152.2 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"El delito previsto en este apartado solo será perseguible mediante denuncia de la persona agraviada o de su representante legal."}]},{"text":"L''article 153 converteix en delicte específic el menyscabament psíquic, la lesió lleu o el maltractament d''obra quan la víctima és o ha estat esposa o parella de l''autor, o persona especialment vulnerable que hi conviu, amb presó de sis mesos a un any o treballs en benefici de la comunitat. La pena es posa en la meitat superior si es comet davant de menors, amb armes, al domicili comú o de la víctima, o trencant una pena o mesura de l''article 48 (art. 153.3).","refs":[{"ref":"Art. 153.1 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"cuando la ofendida sea o haya sido esposa, o mujer que esté o haya estado ligada a él por una análoga relación de afectividad aun sin convivencia, o persona especialmente vulnerable que conviva con el autor, será castigado con la pena de prisión de seis meses a un año o de trabajos en beneficios de la comunidad de treinta y uno a ochenta días"},{"ref":"Art. 153.3 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"Las penas previstas en los apartados 1 y 2 se impondrán en su mitad superior cuando el delito se perpetre en presencia de menores, o utilizando armas, o tenga lugar en el domicilio común o en el domicilio de la víctima"}]},{"text":"El consentiment vàlid, lliure, espontani i exprés de l''ofès només rebaixa la pena en un o dos graus, i no val el d''un menor d''edat o d''una persona amb discapacitat necessitada d''especial protecció (art. 155). Sí que eximeix en el trasplantament d''òrgans legal, les esterilitzacions i la cirurgia transsexual feta per facultatiu (art. 156).","refs":[{"ref":"Art. 155 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"En los delitos de lesiones, si ha mediado el consentimiento válida, libre, espontánea y expresamente emitido del ofendido, se impondrá la pena inferior en uno o dos grados. No será válido el consentimiento otorgado por un menor de edad o una persona con discapacidad necesitada de especial protección."},{"ref":"Art. 156 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"exime de responsabilidad penal en los supuestos de trasplante de órganos efectuado con arreglo a lo dispuesto en la ley, esterilizaciones y cirugía transexual realizadas por facultativo"}]}]},{"n":"4","title":"Detencions il·legals i segrests (arts. 163-166)","blocks":[{"text":"El títol VI regula els delictes contra la llibertat. El particular que tanca o reté una altra persona privant-la de llibertat comet detenció il·legal, castigada amb presó de quatre a sis anys (art. 163.1). Si l''allibera dins dels tres primers dies sense haver aconseguit el seu objectiu, se li imposa la pena inferior en grau; si la detenció dura més de quinze dies, la pena és de cinc a vuit anys (art. 163.2 i 3).","refs":[{"ref":"Art. 163 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"1. El particular que encerrare o detuviere a otro, privándole de su libertad, será castigado con la pena de prisión de cuatro a seis años. 2. Si el culpable diera libertad al encerrado o detenido dentro de los tres primeros días de su detención, sin haber logrado el objeto que se había propuesto, se impondrá la pena inferior en grado. 3. Se impondrá la pena de prisión de cinco a ocho años si el encierro o detención ha durado más de quince días."}]},{"text":"El particular que, fora dels casos permesos per les lleis, apreheneix una persona per presentar-la immediatament a l''autoritat només és castigat amb multa de tres a sis mesos (art. 163.4). Cal relacionar-ho amb els casos en què qualsevol persona pot detenir segons l''article 490 LECrim: dins d''aquells casos la conducta és lícita.","refs":[{"ref":"Art. 163.4 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"4. El particular que, fuera de los casos permitidos por las leyes, aprehendiere a una persona para presentarla inmediatamente a la autoridad, será castigado con la pena de multa de tres a seis meses."}]},{"text":"El segrest és la detenció exigint alguna condició per alliberar la víctima, amb presó de sis a deu anys (art. 164). Les penes van a la meitat superior si es fingeix autoritat o funció pública, o la víctima és menor, persona amb discapacitat necessitada d''especial protecció o funcionari en exercici (art. 165). Qui no dona raó del parador de la persona detinguda té penes molt més altes: de deu a quinze anys en la detenció il·legal i de quinze a vint en el segrest (art. 166.1).","refs":[{"ref":"Art. 164 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"El secuestro de una persona exigiendo alguna condición para ponerla en libertad, será castigado con la pena de prisión de seis a diez años."},{"ref":"Art. 165 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"si la detención ilegal o secuestro se ha ejecutado con simulación de autoridad o función pública, o la víctima fuere menor de edad o persona con discapacidad necesitada de especial protección o funcionario público en el ejercicio de sus funciones."},{"ref":"Art. 166.1 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"será castigado con una pena de prisión de diez a quince años, en el caso de la detención ilegal, y de quince a veinte años en el de secuestro."}]}]},{"n":"5","title":"Detenció il·legal comesa per autoritat o funcionari (arts. 167 i 168)","blocks":[{"text":"Aquest precepte afecta directament els agents. L''autoritat o funcionari que, fora dels casos permesos per la llei i sense que hi hagi causa per delicte, comet algun d''aquests fets és castigat amb les penes previstes en la seva meitat superior, i es pot arribar a la superior en grau (art. 167.1). La mateixa pena té el funcionari que no reconeix una privació de llibertat o n''oculta el parador, i s''hi afegeix sempre la inhabilitació absoluta de vuit a dotze anys (art. 167.2 i 3). La provocació, la conspiració i la proposició també són punibles (art. 168).","refs":[{"ref":"Art. 167.1 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"La autoridad o funcionario público que, fuera de los casos permitidos por la ley, y sin mediar causa por delito, cometiere alguno de los hechos descritos en este Capítulo será castigado con las penas respectivamente previstas en éstos, en su mitad superior, pudiéndose llegar hasta la superior en grado."},{"ref":"Art. 167.3 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"se les impondrá, además, la pena de inhabilitación absoluta por tiempo de ocho a doce años."},{"ref":"Art. 168 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"La provocación, la conspiración y la proposición para cometer los delitos previstos en este Capítulo se castigarán con la pena inferior en uno o dos grados"}]}]},{"n":"6","title":"Amenaces (arts. 169-171)","blocks":[{"text":"Comet amenaces qui amenaça una altra persona, la seva família o persones íntimament vinculades amb un mal constitutiu de delicte (homicidi, lesions, llibertat, tortures, llibertat sexual, intimitat, honor, patrimoni…). Si l''amenaça és condicional —exigint una quantitat o imposant una condició— la pena és de presó d''un a cinc anys si aconsegueix el propòsit i de sis mesos a tres anys si no; aquestes penes van a la meitat superior si l''amenaça es fa per escrit, per telèfon o per qualsevol mitjà de comunicació o de reproducció, o en nom d''entitats o grups reals o suposats. L''amenaça no condicional es castiga amb presó de sis mesos a dos anys (art. 169).","refs":[{"ref":"Art. 169 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"1.º Con la pena de prisión de uno a cinco años, si se hubiere hecho la amenaza exigiendo una cantidad o imponiendo cualquier otra condición, aunque no sea ilícita, y el culpable hubiere conseguido su propósito. De no conseguirlo, se impondrá la pena de prisión de seis meses a tres años. Las penas señaladas en el párrafo anterior se impondrán en su mitad superior si las amenazas se hicieren por escrito, por teléfono o por cualquier medio de comunicación o de reproducción, o en nombre de entidades o grupos reales o supuestos. 2.º Con la pena de prisión de seis meses a dos años, cuando la amenaza no haya sido condicional."}]},{"text":"Les amenaces de mal no constitutiu de delicte es castiguen si són condicionals i la condició no és una conducta deguda (art. 171.1); exigir diners amb l''amenaça de revelar fets de la vida privada té presó de dos a quatre anys si s''aconsegueix (art. 171.2). L''amenaça lleu genèrica té multa d''un a tres mesos i només és perseguible per denúncia, excepte quan l''ofès és una de les persones de l''article 173.2 (art. 171.7).","refs":[{"ref":"Art. 171.2 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"Si alguien exigiere de otro una cantidad o recompensa bajo la amenaza de revelar o difundir hechos referentes a su vida privada o relaciones familiares que no sean públicamente conocidos y puedan afectar a su fama, crédito o interés, será castigado con la pena de prisión de dos a cuatro años, si ha conseguido la entrega de todo o parte de lo exigido"},{"ref":"Art. 171.7 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"Fuera de los casos anteriores, el que de modo leve amenace a otro será castigado con la pena de multa de uno a tres meses. Este hecho sólo será perseguible mediante denuncia de la persona agraviada o de su representante legal."}]}]},{"n":"7","title":"Coaccions i assetjament (arts. 172 i 172 ter)","blocks":[{"text":"Comet coaccions qui, sense estar legítimament autoritzat, impedeix a una altra persona amb violència fer el que la llei no prohibeix, o l''obliga a fer el que no vol, sigui just o injust; la pena és de presó de sis mesos a tres anys o multa de dotze a vint-i-quatre mesos (art. 172.1). Les penes van a la meitat superior quan la coacció pretén impedir l''exercici d''un dret fonamental o el legítim gaudi de l''habitatge.","refs":[{"ref":"Art. 172.1 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"1. El que, sin estar legítimamente autorizado, impidiere a otro con violencia hacer lo que la ley no prohíbe, o le compeliere a efectuar lo que no quiere, sea justo o injusto, será castigado con la pena de prisión de seis meses a tres años o con multa de 12 a 24 meses"},{"ref":"Art. 172.1 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"Cuando la coacción ejercida tuviera como objeto impedir el ejercicio de un derecho fundamental se le impondrán las penas en su mitad superior, salvo que el hecho tuviera señalada mayor pena en otro precepto de este Código. También se impondrán las penas en su mitad superior cuando la coacción ejercida tuviera por objeto impedir el legítimo disfrute de la vivienda."}]},{"text":"L''assetjament (stalking) consisteix a assetjar una persona de forma insistent i reiterada —vigilar-la, perseguir-la, contactar-hi per qualsevol mitjà, fer servir les seves dades per contractar serveis o atemptar contra la seva llibertat o patrimoni— alterant el desenvolupament normal de la seva vida quotidiana; es castiga amb presó de tres mesos a dos anys o multa i, en general, requereix denúncia (art. 172 ter).","refs":[{"ref":"Art. 172 ter.1 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"el que acose a una persona llevando a cabo de forma insistente y reiterada, y sin estar legítimamente autorizado, alguna de las conductas siguientes y, de esta forma, altere el normal desarrollo de su vida cotidiana: 1.ª La vigile, la persiga o busque su cercanía física."}]}]},{"n":"8","title":"Tortures i altres delictes contra la integritat moral (arts. 173-177)","blocks":[{"text":"El títol VII castiga qui infligeix a una altra persona un tracte degradant que menyscaba greument la seva integritat moral, amb presó de sis mesos a dos anys (art. 173.1); la mateixa pena s''aplica a l''assetjament laboral o funcionarial greu i als actes hostils reiterats per impedir el gaudi de l''habitatge. L''article 173.2 castiga la violència física o psíquica habitual en l''àmbit familiar, i el 173.3 indica com s''aprecia l''habitualitat (nombre d''actes i proximitat temporal).","refs":[{"ref":"Art. 173.1 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"1. El que infligiera a otra persona un trato degradante, menoscabando gravemente su integridad moral, será castigado con la pena de prisión de seis meses a dos años."},{"ref":"Art. 173.3 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"Para apreciar la habitualidad a que se refiere el apartado anterior, se atenderá al número de actos de violencia que resulten acreditados, así como a la proximidad temporal de los mismos"}]},{"text":"La tortura només la pot cometre l''autoritat o funcionari públic que, abusant del seu càrrec, i per obtenir una confessió o informació, castigar algú o per qualsevol raó discriminatòria, el sotmet a condicions o procediments que li suposen sofriments físics o mentals o atempten contra la seva integritat moral. La pena és de presó de dos a sis anys si l''atemptat és greu i d''un a tres si no ho és, més, en tot cas, inhabilitació absoluta de vuit a dotze anys (art. 174.1).","refs":[{"ref":"Art. 174.1 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"1. Comete tortura la autoridad o funcionario público que, abusando de su cargo, y con el fin de obtener una confesión o información de cualquier persona o de castigarla por cualquier hecho que haya cometido o se sospeche que ha cometido, o por cualquier razón basada en algún tipo de discriminación"},{"ref":"Art. 174.1 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"El culpable de tortura será castigado con la pena de prisión de dos a seis años si el atentado fuera grave, y de prisión de uno a tres años si no lo es. Además de las penas señaladas se impondrá, en todo caso, la pena de inhabilitación absoluta de ocho a 12 años."}]},{"text":"Fora de la tortura, l''autoritat o funcionari que, abusant del càrrec, atempta contra la integritat moral d''una persona té presó de dos a quatre anys si és greu (art. 175). Respon igual el funcionari que, faltant als seus deures, permet que altres executin aquests fets (art. 176), i les lesions o danys que es produeixin es castiguen per separat (art. 177).","refs":[{"ref":"Art. 175 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"La autoridad o funcionario público que, abusando de su cargo y fuera de los casos comprendidos en el artículo anterior, atentare contra la integridad moral de una persona será castigado con la pena de prisión de dos a cuatro años si el atentado fuera grave"},{"ref":"Art. 176 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"Se impondrán las penas respectivamente establecidas en los artículos precedentes a la autoridad o funcionario que, faltando a los deberes de su cargo, permitiere que otras personas ejecuten los hechos previstos en ellos."}]}]},{"n":"9","title":"Delictes contra la llibertat sexual: agressió sexual i violació (arts. 178-180)","blocks":[{"text":"El títol VIII es titula avui «Delitos contra la libertad sexual»; el temari de Terrassa encara parla de «llibertat i indemnitat sexuals», denominació anterior. És agressió sexual qualsevol acte que atempti contra la llibertat sexual d''una altra persona sense el seu consentiment, amb presó d''un a quatre anys. Només hi ha consentiment quan s''ha manifestat lliurement mitjançant actes que, segons les circumstàncies, expressin de manera clara la voluntat de la persona (art. 178.1). En tot cas és agressió sexual l''acte comès amb violència, intimidació o abús de superioritat o vulnerabilitat, sobre persones privades de sentit o amb la voluntat anul·lada (art. 178.2).","refs":[{"ref":"Art. 178.1 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"Será castigado con la pena de prisión de uno a cuatro años, como responsable de agresión sexual, el que realice cualquier acto que atente contra la libertad sexual de otra persona sin su consentimiento. Sólo se entenderá que hay consentimiento cuando se haya manifestado libremente mediante actos que, en atención a las circunstancias del caso, expresen de manera clara la voluntad de la persona."},{"ref":"Art. 178.2 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"Se consideran en todo caso agresión sexual los actos de contenido sexual que se realicen empleando violencia, intimidación o abuso de una situación de superioridad o de vulnerabilidad de la víctima"}]},{"text":"Quan l''agressió consisteix en accés carnal per via vaginal, anal o bucal, o introducció de membres corporals o objectes per alguna de les dues primeres vies, el responsable és castigat com a reu de violació, amb presó de quatre a dotze anys, i de sis a dotze si hi ha violència, intimidació o voluntat anul·lada (art. 179). L''article 180 agreuja les penes en casos com l''actuació conjunta de dues o més persones, l''ús d''armes o la submissió química, i si el culpable s''ha prevalgut de la condició d''autoritat o agent, hi afegeix inhabilitació absoluta de sis a dotze anys (art. 180.3).","refs":[{"ref":"Art. 179.1 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"1. Cuando la agresión sexual consista en acceso carnal por vía vaginal, anal o bucal, o introducción de miembros corporales u objetos por alguna de las dos primeras vías, el responsable será castigado como reo de violación con la pena de prisión de cuatro a doce años."},{"ref":"Art. 180 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"1.ª Cuando los hechos se cometan por la actuación conjunta de dos o más personas."},{"ref":"Art. 180.3 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"cuando el culpable se hubiera prevalido de su condición de autoridad, agente de ésta o funcionario público, se impondrá, además, la pena de inhabilitación absoluta de seis a doce años."}]}]},{"n":"10","title":"Menors de setze anys, assetjament sexual i perseguibilitat (arts. 181, 183 bis, 184 i 191)","blocks":[{"text":"Qui fa actes de caràcter sexual amb un menor de setze anys és castigat amb presó de dos a sis anys (art. 181.1), i amb vuit a dotze si hi ha accés carnal (art. 181.4). El lliure consentiment del menor de setze anys exclou la responsabilitat quan l''autor és una persona pròxima al menor per edat i grau de desenvolupament o maduresa, llevat que hi concorri alguna circumstància de l''article 178.2 (art. 183 bis).","refs":[{"ref":"Art. 181.1 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"1. El que realizare actos de carácter sexual con un menor de dieciséis años, será castigado con la pena de prisión de dos a seis años."},{"ref":"Art. 183 bis CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"Salvo en los casos en que concurra alguna de las circunstancias previstas en el apartado segundo del artículo 178, el libre consentimiento del menor de dieciséis años excluirá la responsabilidad penal por los delitos previstos en este capítulo cuando el autor sea una persona próxima al menor por edad y grado de desarrollo o madurez física y psicológica."}]},{"text":"L''assetjament sexual és demanar favors sexuals en una relació laboral, docent o de prestació de serveis que provoqui a la víctima una situació objectiva i greument intimidatòria, hostil o humiliant (art. 184). Per perseguir agressions i assetjament sexuals cal denúncia de la víctima o el seu representant, o querella del fiscal (si és menor, n''hi ha prou amb la denúncia del fiscal), i el perdó de l''ofès no extingeix l''acció penal ni la responsabilitat (art. 191).","refs":[{"ref":"Art. 184.1 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"El que solicitare favores de naturaleza sexual, para sí o para un tercero, en el ámbito de una relación laboral, docente, de prestación de servicios o análoga, continuada o habitual, y con tal comportamiento provocare a la víctima una situación objetiva y gravemente intimidatoria, hostil o humillante"},{"ref":"Art. 191 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"Para proceder por los delitos de agresiones sexuales y acoso sexual será precisa denuncia de la persona agraviada, de su representante legal o querella del Ministerio Fiscal"},{"ref":"Art. 191.2 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"En estos delitos el perdón del ofendido o del representante legal no extingue la acción penal ni la responsabilidad de esa clase."}]}]},{"n":"R","title":"Recorda per a l''examen","blocks":[{"text":"Lesió del 147.1: primera assistència + tractament mèdic o quirúrgic; la vigilància o seguiment no és tractament.","refs":[{"ref":"Art. 147.1 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"La simple vigilancia o seguimiento facultativo del curso de la lesión no se considerará tratamiento médico."}]},{"text":"Maltractament d''obra sense lesió: multa d''un a dos mesos i només per denúncia.","refs":[{"ref":"Art. 147.3 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"El que golpeare o maltratare de obra a otro sin causarle lesión, será castigado con la pena de multa de uno a dos meses."}]},{"text":"Víctima menor de catorze anys: lesió agreujada (art. 148.3).","refs":[{"ref":"Art. 148 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"3.º Si la víctima fuere menor de catorce años o persona con discapacidad necesitada de especial protección."}]},{"text":"Òrgan o membre principal: sis a dotze anys; no principal: tres a sis anys.","refs":[{"ref":"Art. 149.1 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"será castigado con la pena de prisión de seis a 12 años."}]},{"text":"Detenció il·legal per particular: quatre a sis anys; alliberament en tres dies sense objectiu: pena inferior en grau.","refs":[{"ref":"Art. 163.2 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"dentro de los tres primeros días de su detención, sin haber logrado el objeto que se había propuesto, se impondrá la pena inferior en grado."}]},{"text":"Aprehendre algú per presentar-lo a l''autoritat fora dels casos legals: multa de tres a sis mesos.","refs":[{"ref":"Art. 163.4 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"será castigado con la pena de multa de tres a seis meses."}]},{"text":"Tortura: només autoritat o funcionari; sempre inhabilitació absoluta de vuit a dotze anys.","refs":[{"ref":"Art. 174.1 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"Comete tortura la autoridad o funcionario público que, abusando de su cargo"}]},{"text":"Violació: presó de quatre a dotze anys; menor de setze anys: dos a sis anys.","refs":[{"ref":"Art. 179.1 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"el responsable será castigado como reo de violación con la pena de prisión de cuatro a doce años."}]},{"text":"En agressions i assetjament sexuals el perdó no extingeix l''acció penal.","refs":[{"ref":"Art. 191.2 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"el perdón del ofendido o del representante legal no extingue la acción penal"}]}]}]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444', null, null, null, null
