insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, lessons, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"Furts (arts. 234-236)"},{"n":"2","title":"Robatoris (arts. 237-242)"},{"n":"3","title":"Robatori i furt d''ús de vehicles (arts. 244)"},{"n":"4","title":"Danys (arts. 263-267)"},{"n":"5","title":"Delictes contra el medi ambient"},{"n":"6","title":"Delictes contra la salut pública: tràfic de drogues (arts. 368-369)"},{"n":"7","title":"Delictes contra la seguretat viària (arts. 379-385 ter)"}]'::jsonb, '["Art. 234 Codi penal: «1. El que, con ánimo de lucro, tomare las cosas muebles ajenas sin la voluntad de su dueño será castigado, como reo de hurto, con la pena de prisión de seis a dieciocho meses si la cuantía de lo sustraído excediese de 400 euros.»","Art. 234.2 Codi penal: «en el caso de que el culpable hubiera sido condenado ejecutoriamente al menos por tres delitos de la misma naturaleza, comprendidos en este Título, y siendo al menos uno de ellos leve»","Art. 237 Codi penal: «empleando fuerza en las cosas para acceder o abandonar el lugar donde éstas se encuentran o violencia o intimidación en las personas»","Art. 238 Codi penal: «1.º Escalamiento. 2.º Rompimiento de pared, techo o suelo, o fractura de puerta o ventana.»","Art. 240 Codi penal: «1. El culpable de robo con fuerza en las cosas será castigado con la pena de prisión de uno a tres años.»","Art. 242 Codi penal: «2. Cuando el robo se cometa en casa habitada, edificio o local abiertos al público o en cualquiera de sus dependencias, se impondrá la pena de prisión de tres años y seis meses a cinco años.»","Art. 242.3 Codi penal: «cuando el delincuente hiciere uso de armas u otros medios igualmente peligrosos, sea al cometer el delito o para proteger la huida»","Art. 244 Codi penal: «si lo restituyera, directa o indirectamente, en un plazo no superior a cuarenta y ocho horas»","Art. 245.2 Codi penal: «2. El que ocupare, sin autorización debida, un inmueble, vivienda o edificio ajenos que no constituyan morada, o se mantuviere en ellos contra la voluntad de su titular, será castigado con la pena de multa de tres a seis meses.»","Art. 263 Codi penal: «Si la cuantía del daño causado no excediere de 400 euros, se impondrá una pena de multa de uno a tres meses.»","Art. 325 Codi penal: «ruidos, vibraciones, inyecciones o depósitos»","Art. 368 Codi penal: «serán castigados con las penas de prisión de tres a seis años y multa del tanto al triplo del valor de la droga objeto del delito si se tratare de sustancias o productos que causen grave daño a la salud»","Art. 379.1 Codi penal: «a velocidad superior en sesenta kilómetros por hora en vía urbana o en ochenta kilómetros por hora en vía interurbana a la permitida reglamentariamente»","Art. 379.2 Codi penal: «En todo caso será condenado con dichas penas el que condujere con una tasa de alcohol en aire espirado superior a 0,60 miligramos por litro o con una tasa de alcohol en sangre superior a 1,2 gramos por litro.»","Art. 380 Codi penal: «será castigado con las penas de prisión de seis meses a dos años y privación del derecho a conducir vehículos a motor y ciclomotores por tiempo superior a uno y hasta seis años.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[{"n":"1","title":"El furt: tipus bàsic i furt lleu (art. 234 CP)","blocks":[{"text":"El títol XIII del llibre II del Codi penal recull els delictes contra el patrimoni. Comet furt qui, amb ànim de lucre, pren les coses mobles alienes sense la voluntat del propietari; si la quantia del que s''ha sostret excedeix de 400 euros, la pena és de presó de sis a divuit mesos (art. 234.1). Els elements que cal identificar en una intervenció són, doncs, l''ànim de lucre, la cosa moble aliena, l''absència de voluntat del propietari i el valor.","refs":[{"ref":"Art. 234.1 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"1. El que, con ánimo de lucro, tomare las cosas muebles ajenas sin la voluntad de su dueño será castigado, como reo de hurto, con la pena de prisión de seis a dieciocho meses si la cuantía de lo sustraído excediese de 400 euros."}]},{"text":"Si la quantia no supera els 400 euros, és un furt lleu castigat amb multa d''un a tres mesos, llevat que hi concorri una circumstància de l''article 235. Però s''aplica la pena del furt bàsic quan el culpable ha estat condemnat executòriament almenys per tres delictes de la mateixa naturalesa del títol, i almenys un és lleu; no compten els antecedents cancel·lats o que ho haurien d''estar (art. 234.2). La pena va a la meitat superior si s''han neutralitzat o inutilitzat les alarmes o dispositius de seguretat de les coses sostretes (art. 234.3).","refs":[{"ref":"Art. 234.2 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"Se impondrá la pena de multa de uno a tres meses si la cuantía de lo sustraído no excediese de 400 euros, salvo si concurriere alguna de las circunstancias del artículo 235. No obstante, en el caso de que el culpable hubiera sido condenado ejecutoriamente al menos por tres delitos de la misma naturaleza, comprendidos en este Título, y siendo al menos uno de ellos leve, se impondrá la pena prevista en el apartado 1 de este artículo. No se tendrán en cuenta los antecedentes penales cancelados o que debieran serlo."},{"ref":"Art. 234.3 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"cuando en la comisión del hecho se hubieran neutralizado, eliminado o inutilizado, por cualquier medio, los dispositivos de alarma o seguridad instalados en las cosas sustraídas."}]}]},{"n":"2","title":"Furt agreujat i sostracció per part del propietari (arts. 235 i 236)","blocks":[{"text":"El furt es castiga amb presó d''un a tres anys en els supòsits de l''article 235, entre els quals: coses de valor artístic, històric, cultural o científic; cablejat o components d''infraestructures elèctriques o de telecomunicacions amb perjudici greu; especial gravetat pel valor; abús de la situació de desemparament de la víctima; tres condemnes executòries prèvies per delictes menys greus o greus de la mateixa naturalesa; utilització de menors de setze anys; pertinença a organització o grup criminal; i, segons el text consolidat vigent, quan els objectes sostrets són telèfons mòbils o altres dispositius que puguin contenir dades personals (exclosos els que estan a la venda en comerços).","refs":[{"ref":"Art. 235.1 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"1.º Cuando se sustraigan cosas de valor artístico, histórico, cultural o científico."},{"ref":"Art. 235.1 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"8.º Cuando se utilice a menores de dieciséis años para la comisión del delito."},{"ref":"Art. 235.1 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"10.º Cuando los objetos sustraídos fueran teléfonos móviles. Así mismo, cualquier otro dispositivo móvil de comunicación, o de almacenamiento masivo de información digital susceptible de contener datos e información de carácter personal."}]},{"text":"També comet un delicte qui, sent el propietari d''una cosa moble o amb el seu consentiment, la sostreu de qui la té legítimament en el seu poder, amb perjudici d''aquest o d''un tercer: multa de tres a dotze mesos, o d''un a tres mesos si el valor no excedeix de 400 euros (art. 236).","refs":[{"ref":"Art. 236 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"Será castigado con multa de tres a doce meses el que, siendo dueño de una cosa mueble o actuando con el consentimiento de éste, la sustrajere de quien la tenga legítimamente en su poder, con perjuicio del mismo o de un tercero."}]}]},{"n":"3","title":"El robatori i el robatori amb força en les coses (arts. 237-240)","blocks":[{"text":"El robatori es diferencia del furt pel mitjà: l''apoderament amb ànim de lucre de coses mobles alienes es fa emprant força en les coses per accedir o abandonar el lloc on són, o violència o intimidació en les persones, sigui en cometre el delicte, per protegir la fugida o sobre els qui acudeixen en auxili de la víctima o la persegueixen (art. 237).","refs":[{"ref":"Art. 237 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"Son reos del delito de robo los que, con ánimo de lucro, se apoderaren de las cosas muebles ajenas empleando fuerza en las cosas para acceder o abandonar el lugar donde éstas se encuentran o violencia o intimidación en las personas, sea al cometer el delito, para proteger la huida, o sobre los que acudiesen en auxilio de la víctima o que le persiguieren."}]},{"text":"Hi ha força en les coses només quan concorre alguna d''aquestes circumstàncies taxades: escalament; trencament de paret, sostre o terra, o fractura de porta o finestra; fractura d''armaris, arques o objectes tancats o forçament dels seus panys; ús de claus falses; o inutilització de sistemes específics d''alarma o guarda (art. 238). Entrar per una porta oberta i agafar un objecte, per tant, no és robatori sinó furt. Són claus falses les ganzúes, les claus legítimes perdudes o obtingudes il·lícitament i qualsevol altra no destinada pel propietari; també les targetes i els comandaments a distància (art. 239).","refs":[{"ref":"Art. 238 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"1.º Escalamiento. 2.º Rompimiento de pared, techo o suelo, o fractura de puerta o ventana. 3.º Fractura de armarios, arcas u otra clase de muebles u objetos cerrados o sellados, o forzamiento de sus cerraduras o descubrimiento de sus claves para sustraer su contenido, sea en el lugar del robo o fuera del mismo. 4.º Uso de llaves falsas. 5.º Inutilización de sistemas específicos de alarma o guarda."},{"ref":"Art. 239 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"A los efectos del presente artículo, se consideran llaves las tarjetas, magnéticas o perforadas, los mandos o instrumentos de apertura a distancia y cualquier otro instrumento tecnológico de eficacia similar."}]},{"text":"El robatori amb força en les coses es castiga amb presó d''un a tres anys, i de dos a cinc si hi concorre alguna circumstància de l''article 235 (art. 240).","refs":[{"ref":"Art. 240 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"1. El culpable de robo con fuerza en las cosas será castigado con la pena de prisión de uno a tres años. 2. Se impondrá la pena de prisión de dos a cinco años cuando concurra alguna de las circunstancias previstas en el artículo 235."}]}]},{"n":"4","title":"Robatori en casa habitada o local obert al públic (art. 241)","blocks":[{"text":"El robatori en casa habitada, edifici o local obert al públic, o en les seves dependències, es castiga amb presó de dos a cinc anys; si es comet en un establiment obert al públic fora de l''horari d''obertura, d''un a cinc anys (art. 241.1). És casa habitada tot alberg que constitueixi la morada d''una o més persones, encara que accidentalment no hi siguin, i en són dependències els patis, garatges i altres espais tancats i contigus en comunicació interior que formen una unitat física (art. 241.2 i 3).","refs":[{"ref":"Art. 241.1 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"El robo cometido en casa habitada, edificio o local abiertos al público, o en cualquiera de sus dependencias, se castigará con una pena de prisión de dos a cinco años."},{"ref":"Art. 241.2 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"Se considera casa habitada todo albergue que constituya morada de una o más personas, aunque accidentalmente se encuentren ausentes de ella cuando el robo tenga lugar."}]}]},{"n":"5","title":"Robatori amb violència o intimidació (art. 242)","blocks":[{"text":"El robatori amb violència o intimidació en les persones es castiga amb presó de dos a cinc anys, sens perjudici de la pena per la violència física exercida (art. 242.1). Si es comet en casa habitada, edifici o local obert al públic o en les seves dependències, la pena és de tres anys i sis mesos a cinc anys (art. 242.2). Les penes van a la meitat superior quan el delinqüent fa servir armes o altres mitjans igualment perillosos, en cometre el delicte o per protegir la fugida, i quan ataca els qui acudeixen en auxili de la víctima o el persegueixen (art. 242.3). Si la violència o intimidació és de menor entitat, es pot imposar la pena inferior en grau (art. 242.4).","refs":[{"ref":"Art. 242.1-2 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"1. El culpable de robo con violencia o intimidación en las personas será castigado con la pena de prisión de dos a cinco años, sin perjuicio de la que pudiera corresponder a los actos de violencia física que realizase. 2. Cuando el robo se cometa en casa habitada, edificio o local abiertos al público o en cualquiera de sus dependencias, se impondrá la pena de prisión de tres años y seis meses a cinco años."},{"ref":"Art. 242.3 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"3. Las penas señaladas en los apartados anteriores se impondrán en su mitad superior cuando el delincuente hiciere uso de armas u otros medios igualmente peligrosos, sea al cometer el delito o para proteger la huida, y cuando atacare a los que acudiesen en auxilio de la víctima o a los que le persiguieren."}]}]},{"n":"6","title":"Robatori i furt d''ús de vehicles (art. 244)","blocks":[{"text":"Qui sostreu o utilitza sense autorització un vehicle de motor o ciclomotor aliè, sense ànim d''apropiar-se''l, i el restitueix directament o indirectament en un termini no superior a quaranta-vuit hores, comet furt d''ús, castigat amb treballs en benefici de la comunitat de trenta-un a noranta dies o multa de dos a dotze mesos (art. 244.1). Si s''empra força en les coses, la pena va a la meitat superior; si no es restitueix dins del termini, el fet es castiga com a furt o robatori; i si hi ha violència o intimidació, s''imposen en tot cas les penes de l''article 242.","refs":[{"ref":"Art. 244.1 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"El que sustrajere o utilizare sin la debida autorización un vehículo a motor o ciclomotor ajenos, sin ánimo de apropiárselo, será castigado con la pena de trabajos en beneficio de la comunidad de treinta y uno a noventa días o multa de dos a doce meses, si lo restituyera, directa o indirectamente, en un plazo no superior a cuarenta y ocho horas"},{"ref":"Art. 244.2-4 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"2. Si el hecho se ejecutare empleando fuerza en las cosas, la pena se aplicará en su mitad superior. 3. De no efectuarse la restitución en el plazo señalado, se castigará el hecho como hurto o robo en sus respectivos casos. 4. Si el hecho se cometiere con violencia o intimidación en las personas, se impondrán, en todo caso, las penas del artículo 242."}]}]},{"n":"7","title":"Usurpació d''immobles (art. 245)","blocks":[{"text":"Qui ocupa amb violència o intimidació un immoble aliè o usurpa un dret real immobiliari té presó d''un a dos anys, a més de la pena per les violències (art. 245.1). L''ocupació sense autorització d''un immoble, habitatge o edifici aliè que no constitueix morada, o mantenir-s''hi contra la voluntat del titular, es castiga amb multa de tres a sis mesos (art. 245.2). Si l''immoble sí que és morada d''algú, s''entra en l''àmbit de la inviolabilitat del domicili (tema 14).","refs":[{"ref":"Art. 245.1 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"Al que con violencia o intimidación en las personas ocupare una cosa inmueble o usurpare un derecho real inmobiliario de pertenencia ajena, se le impondrá, además de las penas en que incurriere por las violencias ejercidas, la pena de prisión de uno a dos años"},{"ref":"Art. 245.2 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"2. El que ocupare, sin autorización debida, un inmueble, vivienda o edificio ajenos que no constituyan morada, o se mantuviere en ellos contra la voluntad de su titular, será castigado con la pena de multa de tres a seis meses."}]}]},{"n":"8","title":"Danys (arts. 263, 264, 266 i 267)","blocks":[{"text":"Qui causa danys en propietat aliena es castiga amb multa de sis a vint-i-quatre mesos, segons la condició econòmica de la víctima i la quantia; si el dany no excedeix de 400 euros, multa d''un a tres mesos (art. 263.1). La pena puja a presó d''un a tres anys i multa quan els danys es fan per impedir el lliure exercici de l''autoritat o com a conseqüència d''accions executades en l''exercici de les seves funcions, quan afecten béns de domini o ús públic o comunal, o quan s''empren substàncies verinoses o corrosives, entre altres supòsits (art. 263.2).","refs":[{"ref":"Art. 263.1 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"1. El que causare daños en propiedad ajena no comprendidos en otros títulos de este Código, será castigado con multa de seis a veinticuatro meses, atendidas la condición económica de la víctima y la cuantía del daño. Si la cuantía del daño causado no excediere de 400 euros, se impondrá una pena de multa de uno a tres meses."},{"ref":"Art. 263.2 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"1.º Que se realicen para impedir el libre ejercicio de la autoridad o como consecuencia de acciones ejecutadas en el ejercicio de sus funciones"},{"ref":"Art. 263.2 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"3.º Que se empleen sustancias venenosas o corrosivas. 4.º Que afecten a bienes de dominio o uso público o comunal."}]},{"text":"Els danys mitjançant incendi, explosions o mitjans de potència destructiva similar es castiguen amb presó d''un a tres anys (art. 266.1); els danys informàtics greus, amb presó de sis mesos a tres anys (art. 264.1). Els danys per imprudència greu només són delicte si superen els 80.000 euros, requereixen denúncia i el perdó de l''ofès extingeix l''acció penal (art. 267).","refs":[{"ref":"Art. 266.1 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"Será castigado con la pena de prisión de uno a tres años el que cometiere los daños previstos en el apartado 1 del artículo 263 mediante incendio, o provocando explosiones"},{"ref":"Art. 267 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"Los daños causados por imprudencia grave en cuantía superior a 80.000 euros, serán castigados con la pena de multa de tres a nueve meses"},{"ref":"Art. 267 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"En estos casos, el perdón de la persona ofendida extingue la acción penal."}]}]},{"n":"9","title":"Delictes contra els recursos naturals, el medi ambient, la fauna i els animals (arts. 325-340 bis)","blocks":[{"text":"El delicte ambiental bàsic castiga qui, contravenint les lleis o disposicions generals protectores del medi ambient, provoca o fa emissions, abocaments, radiacions, extraccions, excavacions, soterraments, sorolls, vibracions, injeccions o dipòsits a l''atmosfera, el sòl, el subsòl o les aigües, que causin o puguin causar danys substancials a la qualitat de l''aire, del sòl o de les aigües, o a animals o plantes: presó de sis mesos a dos anys, multa i inhabilitació especial (art. 325.1). Si es pot perjudicar greument l''equilibri dels sistemes naturals, presó de dos a cinc anys (art. 325.2). La gestió il·legal de residus té les mateixes penes (art. 326), i la imprudència greu rebaixa la pena en un grau (art. 331).","refs":[{"ref":"Art. 325.1 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"el que, contraviniendo las leyes u otras disposiciones de carácter general protectoras del medio ambiente, provoque o realice directa o indirectamente emisiones, vertidos, radiaciones, extracciones o excavaciones, aterramientos, ruidos, vibraciones, inyecciones o depósitos, en la atmósfera, el suelo, el subsuelo o las aguas terrestres"},{"ref":"Art. 325.1 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"cause o pueda causar daños sustanciales a la calidad del aire, del suelo o de las aguas, o a animales o plantas."},{"ref":"Art. 331 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"Los hechos previstos en este capítulo serán sancionados, en su caso, con la pena inferior en grado, en sus respectivos supuestos, cuando se hayan cometido por imprudencia grave."}]},{"text":"Al capítol de flora i fauna, l''article 334 castiga qui caça, pesca, posseeix o destrueix espècies protegides de fauna silvestre, o en trafica. Atenció a l''actualització: el temari de Terrassa situa els animals domèstics en aquest capítol IV, però la LO 3/2023 va suprimir els articles 337 i 337 bis i el maltractament animal és ara al nou títol XVI bis («De los delitos contra los animales», art. 340 bis), que castiga la lesió a un animal domèstic que requereixi tractament veterinari.","refs":[{"ref":"Art. 334.1 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"a) cace, pesque, adquiera, posea o destruya especies protegidas de fauna silvestre;"},{"ref":"Art. 340 bis CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"cause a un animal doméstico, amansado, domesticado o que viva temporal o permanentemente bajo el control humano lesión que requiera tratamiento veterinario para el restablecimiento de su salud."}]}]},{"n":"10","title":"Delictes contra la salut pública: tràfic de drogues (arts. 368 i 369)","blocks":[{"text":"Els qui executen actes de cultiu, elaboració o tràfic, o d''una altra manera promouen, afavoreixen o faciliten el consum il·legal de drogues tòxiques, estupefaents o substàncies psicotròpiques, o les posseeixen amb aquestes finalitats, són castigats amb presó de tres a sis anys i multa del tant al triple del valor de la droga si causen greu dany a la salut, i amb presó d''un a tres anys i multa del tant al doble en els altres casos (art. 368). Per l''escassa entitat del fet es pot imposar la pena inferior en grau.","refs":[{"ref":"Art. 368 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"Los que ejecuten actos de cultivo, elaboración o tráfico, o de otro modo promuevan, favorezcan o faciliten el consumo ilegal de drogas tóxicas, estupefacientes o sustancias psicotrópicas, o las posean con aquellos fines, serán castigados con las penas de prisión de tres a seis años y multa del tanto al triplo del valor de la droga objeto del delito si se tratare de sustancias o productos que causen grave daño a la salud, y de prisión de uno a tres años y multa del tanto al duplo en los demás casos."}]},{"text":"Les penes pugen en grau, amb multa del tant al quàdruple, quan, per exemple, el culpable és autoritat o funcionari en exercici del càrrec, els fets es fan en establiments oberts al públic pels responsables o empleats, la droga es facilita a menors de 18 anys, la quantitat és de notòria importància o es fa en centres docents o penitenciaris o a prop (art. 369).","refs":[{"ref":"Art. 369.1 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"1.ª El culpable fuere autoridad, funcionario público, facultativo, trabajador social, docente o educador y obrase en el ejercicio de su cargo, profesión u oficio."},{"ref":"Art. 369.1 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"4.ª Las sustancias a que se refiere el artículo anterior se faciliten a menores de 18 años"},{"ref":"Art. 369.1 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"5.ª Fuere de notoria importancia la cantidad de las citadas sustancias"}]}]},{"n":"11","title":"Seguretat viària (I): velocitat, alcohol i temeritat (arts. 379-382)","blocks":[{"text":"Conduir un vehicle de motor o ciclomotor a una velocitat superior en seixanta km/h en via urbana o en vuitanta km/h en via interurbana a la permesa reglamentàriament es castiga amb presó de tres a sis mesos, multa o treballs en benefici de la comunitat, i sempre amb privació del dret a conduir de més d''un any i fins a quatre (art. 379.1). Les mateixes penes té qui condueix sota la influència de drogues o begudes alcohòliques i, en tot cas, qui condueix amb una taxa d''alcohol en aire espirat superior a 0,60 mil·ligrams per litre o en sang superior a 1,2 grams per litre (art. 379.2).","refs":[{"ref":"Art. 379.1 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"El que condujere un vehículo de motor o un ciclomotor a velocidad superior en sesenta kilómetros por hora en vía urbana o en ochenta kilómetros por hora en vía interurbana a la permitida reglamentariamente"},{"ref":"Art. 379.2 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"En todo caso será condenado con dichas penas el que condujere con una tasa de alcohol en aire espirado superior a 0,60 miligramos por litro o con una tasa de alcohol en sangre superior a 1,2 gramos por litro."}]},{"text":"La conducció amb temeritat manifesta que posa en perill concret la vida o la integritat de les persones es castiga amb presó de sis mesos a dos anys i privació del dret a conduir de més d''un any i fins a sis; és manifestament temerària la conducció en què concorren l''excés de velocitat i la taxa d''alcohol de l''article 379 (art. 380). Si hi ha manifest menyspreu per la vida dels altres, la presó és de dos a cinc anys (art. 381). Si a més del risc es produeix un resultat lesiu, només s''aprecia la infracció més greu, en la meitat superior (art. 382).","refs":[{"ref":"Art. 380 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"1. El que condujere un vehículo a motor o un ciclomotor con temeridad manifiesta y pusiere en concreto peligro la vida o la integridad de las personas será castigado con las penas de prisión de seis meses a dos años y privación del derecho a conducir vehículos a motor y ciclomotores por tiempo superior a uno y hasta seis años."},{"ref":"Art. 381.1 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"el que, con manifiesto desprecio por la vida de los demás, realizare la conducta descrita en el artículo anterior."},{"ref":"Art. 382 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"los Jueces o Tribunales apreciarán tan sólo la infracción más gravemente penada, aplicando la pena en su mitad superior"}]}]},{"n":"12","title":"Seguretat viària (II): negativa a les proves, conducció sense permís i creació de risc (arts. 383-385 ter)","blocks":[{"text":"El conductor que, requerit per un agent de l''autoritat, es nega a sotmetre''s a les proves legals de comprovació d''alcohol i drogues és castigat amb presó de sis mesos a un any i privació del dret a conduir de més d''un any i fins a quatre (art. 383). És delicte conduir amb el permís sense vigència per pèrdua total de punts, després d''haver-ne estat privat per decisió judicial, o sense haver obtingut mai permís o llicència (art. 384).","refs":[{"ref":"Art. 383 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"El conductor que, requerido por un agente de la autoridad, se negare a someterse a las pruebas legalmente establecidas para la comprobación de las tasas de alcoholemia y la presencia de las drogas tóxicas, estupefacientes y sustancias psicotrópicas a que se refieren los artículos anteriores, será castigado con la penas de prisión de seis meses a un año y privación del derecho a conducir vehículos a motor y ciclomotores por tiempo superior a uno y hasta cuatro años."},{"ref":"Art. 384 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"La misma pena se impondrá al que realizare la conducción tras haber sido privado cautelar o definitivamente del permiso o licencia por decisión judicial y al que condujere un vehículo de motor o ciclomotor sin haber obtenido nunca permiso o licencia de conducción."}]},{"text":"Qui origina un risc greu per a la circulació col·locant obstacles imprevisibles, vessant substàncies lliscants o inflamables, alterant o anul·lant la senyalització, o no restablint la seguretat de la via quan hi té l''obligació, té presó de sis mesos a dos anys o multa i treballs (art. 385). El vehicle es considera instrument del delicte (art. 385 bis), i en els delictes dels articles 379, 383, 384 i 385 el jutge pot rebaixar un grau la pena de presó per la menor entitat del risc (art. 385 ter).","refs":[{"ref":"Art. 385 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"1.ª Colocando en la vía obstáculos imprevisibles, derramando sustancias deslizantes o inflamables o mutando, sustrayendo o anulando la señalización o por cualquier otro medio. 2.ª No restableciendo la seguridad de la vía, cuando haya obligación de hacerlo."},{"ref":"Art. 385 ter CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"En los delitos previstos en los artículos 379, 383, 384 y 385, el Juez o Tribunal, razonándolo en sentencia, podrá rebajar en un grado la pena de prisión en atención a la menor entidad del riesgo causado y a las demás circunstancias del hecho."}]}]},{"n":"R","title":"Recorda per a l''examen","blocks":[{"text":"Furt: més de 400 euros, presó de sis a divuit mesos; fins a 400, multa d''un a tres mesos.","refs":[{"ref":"Art. 234.1 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"con la pena de prisión de seis a dieciocho meses si la cuantía de lo sustraído excediese de 400 euros."}]},{"text":"Robatori amb força en les coses: presó d''un a tres anys; la porta oberta no és força.","refs":[{"ref":"Art. 240.1 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"El culpable de robo con fuerza en las cosas será castigado con la pena de prisión de uno a tres años."}]},{"text":"Robatori amb violència en casa habitada: tres anys i sis mesos a cinc anys.","refs":[{"ref":"Art. 242.2 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"se impondrá la pena de prisión de tres años y seis meses a cinco años."}]},{"text":"Furt d''ús de vehicle: restitució en 48 hores com a màxim.","refs":[{"ref":"Art. 244.1 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"en un plazo no superior a cuarenta y ocho horas"}]},{"text":"Ocupació d''immoble que no és morada: multa de tres a sis mesos.","refs":[{"ref":"Art. 245.2 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"será castigado con la pena de multa de tres a seis meses."}]},{"text":"Danys fins a 400 euros: multa d''un a tres mesos.","refs":[{"ref":"Art. 263.1 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"Si la cuantía del daño causado no excediere de 400 euros, se impondrá una pena de multa de uno a tres meses."}]},{"text":"Droga que causa greu dany a la salut: presó de tres a sis anys i multa del tant al triple.","refs":[{"ref":"Art. 368 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"prisión de tres a seis años y multa del tanto al triplo del valor de la droga"}]},{"text":"Delicte d''alcohol: més de 0,60 mg/l en aire espirat o 1,2 g/l en sang; velocitat: +60 km/h urbana, +80 km/h interurbana.","refs":[{"ref":"Art. 379.2 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"superior a 0,60 miligramos por litro o con una tasa de alcohol en sangre superior a 1,2 gramos por litro."}]},{"text":"Negativa a les proves: presó de sis mesos a un any i privació del permís de més d''un any i fins a quatre.","refs":[{"ref":"Art. 383 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"será castigado con la penas de prisión de seis meses a un año"}]}]}]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444', null, null, null, null
