insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, lessons, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"Circumstàncies agreujants: motius discriminatoris (art. 22.4)"},{"n":"2","title":"Concepte d''autoritat i funcionari públic (art. 24)"},{"n":"3","title":"Omissió del deure de socors (art. 195)"},{"n":"4","title":"Prevaricació, infidelitat en la custòdia, revelació de secrets i suborn (arts. 404-419)"},{"n":"5","title":"Delictes dels funcionaris contra les garanties constitucionals (art. 534)"},{"n":"6","title":"Atemptat, resistència i desobediència (arts. 550-556)"},{"n":"7","title":"Desordres públics (art. 557)"}]'::jsonb, '["Art. 24 Codi penal: «2. Se considerará funcionario público todo el que por disposición inmediata de la Ley o por elección o por nombramiento de autoridad competente participe en el ejercicio de funciones públicas.»","Art. 24.1 Codi penal: «1. A los efectos penales se reputará autoridad al que por sí solo o como miembro de alguna corporación, tribunal u órgano colegiado tenga mando o ejerza jurisdicción propia.»","Art. 22.4 Codi penal: «con independencia de que tales condiciones o circunstancias concurran efectivamente en la persona sobre la que recaiga la conducta.»","Art. 195 Codi penal: «1. El que no socorriere a una persona que se halle desamparada y en peligro manifiesto y grave, cuando pudiere hacerlo sin riesgo propio ni de terceros, será castigado con la pena de multa de tres a doce meses.»","Art. 195.2 Codi penal: «2. En las mismas penas incurrirá el que, impedido de prestar socorro, no demande con urgencia auxilio ajeno.»","Art. 404 Codi penal: «A la autoridad o funcionario público que, a sabiendas de su injusticia, dictare una resolución arbitraria en un asunto administrativo se le castigará con la pena de inhabilitación especial para empleo o cargo público y para el ejercicio del derecho de sufragio pasivo por tiempo de nueve a quince años.»","Art. 408 Codi penal: «La autoridad o funcionario que, faltando a la obligación de su cargo, dejare intencionadamente de promover la persecución de los delitos de que tenga noticia o de sus responsables»","Art. 412.2 Codi penal: «2. Si el requerido fuera autoridad, jefe o responsable de una fuerza pública o un agente de la autoridad, se impondrán las penas de multa de doce a dieciocho meses y suspensión de empleo o cargo público por tiempo de dos a tres años.»","Art. 413 Codi penal: «La autoridad o funcionario público que, a sabiendas, sustrajere, destruyere, inutilizare u ocultare, total o parcialmente, documentos cuya custodia le esté encomendada por razón de su cargo»","Art. 419 Codi penal: «incurrirá en la pena de prisión de tres a seis años, multa de doce a veinticuatro meses, e inhabilitación especial para empleo o cargo público y para el ejercicio del derecho de sufragio pasivo por tiempo de nueve a doce años»","Art. 534 Codi penal: «1. Será castigado con las penas de multa de seis a doce meses e inhabilitación especial para empleo o cargo público de dos a seis años la autoridad o funcionario público que, mediando causa por delito, y sin respetar las garantías constitucionales o legales:»","Art. 550 Codi penal: «cuando se hallen en el ejercicio de las funciones de sus cargos o con ocasión de ellas.»","Art. 550.2 Codi penal: «2. Los atentados serán castigados con las penas de prisión de uno a cuatro años y multa de tres a seis meses si el atentado fuera contra autoridad y de prisión de seis meses a tres años en los demás casos.»","Art. 551 Codi penal: «3.º Acometiendo a la autoridad, a su agente o al funcionario público haciendo uso de un vehículo de motor.»","Art. 554 Codi penal: «2. Las mismas penas se impondrán a quienes acometan, empleen violencia o intimiden a las personas que acudan en auxilio de la autoridad, sus agentes o funcionarios.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[{"n":"1","title":"Concepte penal d''autoritat i de funcionari públic (art. 24 CP)","blocks":[{"text":"Molts delictes d''aquest tema només els pot cometre, o només es poden cometre contra, una autoritat o un funcionari públic, i per això el Codi penal en dona una definició pròpia, a efectes penals. És autoritat qui, per si sol o com a membre d''una corporació, tribunal o òrgan col·legiat, té comandament o exerceix jurisdicció pròpia (art. 24.1 CP). La llei hi inclou sempre els membres del Congrés, del Senat, de les assemblees legislatives autonòmiques i del Parlament Europeu, i també els funcionaris del Ministeri Fiscal i els fiscals de la Fiscalia Europea.","refs":[{"ref":"Art. 24.1 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"A los efectos penales se reputará autoridad al que por sí solo o como miembro de alguna corporación, tribunal u órgano colegiado tenga mando o ejerza jurisdicción propia. En todo caso, tendrán la consideración de autoridad los miembros del Congreso de los Diputados, del Senado, de las Asambleas Legislativas de las Comunidades Autónomas y del Parlamento Europeo. Tendrán también la consideración de autoridad los funcionarios del Ministerio Fiscal y los Fiscales de la Fiscalía Europea."}]},{"text":"El concepte de funcionari públic és funcional, no administratiu: és funcionari qui participa en l''exercici de funcions públiques per disposició immediata de la llei, per elecció o per nomenament d''autoritat competent (art. 24.2 CP). L''agent de policia local és agent de l''autoritat i funcionari públic a efectes penals.","refs":[{"ref":"Art. 24.2 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"Se considerará funcionario público todo el que por disposición inmediata de la Ley o por elección o por nombramiento de autoridad competente participe en el ejercicio de funciones públicas."}]}]},{"n":"2","title":"Agreujant de discriminació i delictes d''odi (arts. 22.4, 510-512 CP)","blocks":[{"text":"L''article 22.4a CP és una circumstància agreujant genèrica: cometre el delicte per motius racistes, antisemites, antigitans o per una altra discriminació referida a la ideologia, la religió o les creences de la víctima, l''ètnia, la raça o la nació, el sexe, l''edat, l''orientació o identitat sexual o de gènere, raons de gènere, aporofòbia o exclusió social, malaltia o discapacitat. S''aplica amb independència que aquestes condicions concorrin efectivament en la víctima.","refs":[{"ref":"Art. 22.4 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"4.ª Cometer el delito por motivos racistas, antisemitas, antigitanos u otra clase de discriminación referente a la ideología, religión o creencias de la víctima, la etnia, raza o nación a la que pertenezca, su sexo, edad, orientación o identidad sexual o de género, razones de género, de aporofobia o de exclusión social, la enfermedad que padezca o su discapacidad, con independencia de que tales condiciones o circunstancias concurran efectivamente en la persona sobre la que recaiga la conducta."}]},{"text":"A més de l''agreujant, hi ha delictes d''odi específics. L''article 510.1 CP castiga amb presó d''un a quatre anys i multa de sis a dotze mesos qui fomenta, promou o incita públicament, directament o indirectament, a l''odi, l''hostilitat, la discriminació o la violència contra un grup o una persona per la seva pertinença a aquest grup. Les penes s''imposen en la meitat superior quan els fets es fan per mitjans de comunicació, internet o tecnologies de la informació i arriben a un nombre elevat de persones (art. 510.3 CP).","refs":[{"ref":"Art. 510.1.a CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"Serán castigados con una pena de prisión de uno a cuatro años y multa de seis a doce meses: a) Quienes públicamente fomenten, promuevan o inciten directa o indirectamente al odio, hostilidad, discriminación o violencia contra un grupo, una parte del mismo o contra una persona determinada por razón de su pertenencia a aquel"},{"ref":"Art. 510.3 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"Las penas previstas en los apartados anteriores se impondrán en su mitad superior cuando los hechos se hubieran llevado a cabo a través de un medio de comunicación social, por medio de internet o mediante el uso de tecnologías de la información, de modo que, aquel se hiciera accesible a un elevado número de personas."}]},{"text":"També és delicte denegar una prestació a la qual una persona té dret per motius discriminatoris: si ho fa el particular encarregat d''un servei públic, presó de sis mesos a dos anys (art. 511.1 CP), i si ho fa un funcionari públic, les mateixes penes en la meitat superior i inhabilitació especial de dos a quatre anys (art. 511.3 CP).","refs":[{"ref":"Art. 511.1 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"Incurrirá en la pena de prisión de seis meses a dos años, multa de doce a veinticuatro meses e inhabilitación especial para empleo o cargo público por tiempo de uno a tres años el particular encargado de un servicio público que deniegue a una persona una prestación a la que tenga derecho"},{"ref":"Art. 511.3 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"Los funcionarios públicos que cometan alguno de los hechos previstos en este artículo, incurrirán en las mismas penas en su mitad superior y en la de inhabilitación especial para empleo o cargo público por tiempo de dos a cuatro años."}]}]},{"n":"3","title":"Omissió del deure de socors (art. 195 CP)","blocks":[{"text":"Comet omissió del deure de socors qui no socorre una persona desemparada i en perill manifest i greu, quan pot fer-ho sense risc propi ni de tercers; la pena és multa de tres a dotze mesos (art. 195.1 CP). Incorre en la mateixa pena qui, impedit de prestar socors, no demana amb urgència auxili aliè (art. 195.2 CP).","refs":[{"ref":"Art. 195.1 i 195.2 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"El que no socorriere a una persona que se halle desamparada y en peligro manifiesto y grave, cuando pudiere hacerlo sin riesgo propio ni de terceros, será castigado con la pena de multa de tres a doce meses. […] En las mismas penas incurrirá el que, impedido de prestar socorro, no demande con urgencia auxilio ajeno."}]},{"text":"La pena s''agreuja quan qui omet l''auxili ha causat l''accident: si l''accident va ser fortuït, presó de sis a divuit mesos, i si es va deure a imprudència, presó de sis mesos a quatre anys (art. 195.3 CP).","refs":[{"ref":"Art. 195.3 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"Si la víctima lo fuere por accidente ocasionado fortuitamente por el que omitió el auxilio, la pena será de prisión de seis meses a 18 meses, y si el accidente se debiere a imprudencia, la de prisión de seis meses a cuatro años."}]}]},{"n":"4","title":"Omissió del deure d''impedir delictes o de promoure''n la persecució (arts. 450, 407 i 408 CP)","blocks":[{"text":"L''article 450 CP castiga qui, podent-ho fer amb la seva intervenció immediata i sense risc propi o aliè, no impedeix un delicte contra la vida, la integritat o salut, la llibertat o la llibertat sexual: presó de sis mesos a dos anys si el delicte és contra la vida i multa de sis a vint-i-quatre mesos en els altres casos. Hi incorre també qui, podent-ho fer, no acudeix a l''autoritat o als seus agents perquè impedeixin un d''aquests delictes del qual sap que es cometrà o s''està cometent (art. 450.2 CP).","refs":[{"ref":"Art. 450.1 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"El que, pudiendo hacerlo con su intervención inmediata y sin riesgo propio o ajeno, no impidiere la comisión de un delito que afecte a las personas en su vida, integridad o salud, libertad o libertad sexual, será castigado con la pena de prisión de seis meses a dos años si el delito fuera contra la vida, y la de multa de seis a veinticuatro meses en los demás casos"},{"ref":"Art. 450.2 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"En las mismas penas incurrirá quien, pudiendo hacerlo, no acuda a la autoridad o a sus agentes para que impidan un delito de los previstos en el apartado anterior y de cuya próxima o actual comisión tenga noticia."}]},{"text":"Per als funcionaris hi ha un deure reforçat. L''autoritat o funcionari que, faltant a l''obligació del càrrec, deixa intencionadament de promoure la persecució dels delictes dels quals té notícia o dels seus responsables és castigat amb inhabilitació especial de sis mesos a dos anys (art. 408 CP). Qui abandona la seva destinació per no impedir o no perseguir delictes dels títols XXI a XXIV té presó d''un a quatre anys i inhabilitació absoluta de sis a deu anys (art. 407.1 CP).","refs":[{"ref":"Art. 408 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"La autoridad o funcionario que, faltando a la obligación de su cargo, dejare intencionadamente de promover la persecución de los delitos de que tenga noticia o de sus responsables, incurrirá en la pena de inhabilitación especial para empleo o cargo público por tiempo de seis meses a dos años."},{"ref":"Art. 407.1 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"A la autoridad o funcionario público que abandonare su destino con el propósito de no impedir o no perseguir cualquiera de los delitos comprendidos en los Títulos XXI, XXII, XXIII y XXIV se le castigará con la pena de prisión de uno a cuatro años e inhabilitación absoluta para empleo o cargo público por tiempo de seis a diez años."}]}]},{"n":"5","title":"Prevaricació dels funcionaris públics (arts. 404-406 CP)","blocks":[{"text":"Comet prevaricació l''autoritat o funcionari públic que, sabent que és injusta, dicta una resolució arbitrària en un assumpte administratiu (art. 404 CP). La pena és inhabilitació especial per a ocupació o càrrec públic i per al dret de sufragi passiu de nou a quinze anys. També és un comportament injust proposar, nomenar o donar possessió d''un càrrec públic a qui no reuneix els requisits legals, sabent-ne la il·legalitat (art. 405 CP), i la persona que accepta el nomenament sabent que no té els requisits rep la mateixa multa (art. 406 CP).","refs":[{"ref":"Art. 404 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"A la autoridad o funcionario público que, a sabiendas de su injusticia, dictare una resolución arbitraria en un asunto administrativo se le castigará con la pena de inhabilitación especial para empleo o cargo público y para el ejercicio del derecho de sufragio pasivo por tiempo de nueve a quince años."},{"ref":"Art. 405 i 406 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"A la autoridad o funcionario público que, en el ejercicio de su competencia y a sabiendas de su ilegalidad, propusiere, nombrare o diere posesión para el ejercicio de un determinado cargo público a cualquier persona sin que concurran los requisitos legalmente establecidos para ello […] La misma pena de multa se impondrá a la persona que acepte la propuesta, nombramiento o toma de posesión mencionada en el artículo anterior, sabiendo que carece de los requisitos legalmente exigibles."}]}]},{"n":"6","title":"Desobediència i denegació d''auxili (arts. 410-412 CP)","blocks":[{"text":"Les autoritats o funcionaris que es neguen obertament a complir resolucions judicials o ordres de l''autoritat superior dictades dins la seva competència i amb les formalitats legals incorren en multa de tres a dotze mesos i inhabilitació especial de sis mesos a dos anys (art. 410.1 CP). Ara bé, no hi ha responsabilitat penal per no complir un manament que constitueix una infracció manifesta, clara i terminant d''una llei o d''una altra disposició general (art. 410.2 CP).","refs":[{"ref":"Art. 410.1 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"Las autoridades o funcionarios públicos que se negaren abiertamente a dar el debido cumplimiento a resoluciones judiciales, decisiones u órdenes de la autoridad superior, dictadas dentro del ámbito de su respectiva competencia y revestidas de las formalidades legales, incurrirán en la pena de multa de tres a doce meses e inhabilitación especial para empleo o cargo público por tiempo de seis meses a dos años."},{"ref":"Art. 410.2 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"no incurrirán en responsabilidad criminal las autoridades o funcionarios por no dar cumplimiento a un mandato que constituya una infracción manifiesta, clara y terminante de un precepto de Ley o de cualquier otra disposición general."}]},{"text":"El funcionari que, requerit per l''autoritat competent, no presta l''auxili degut per a l''Administració de justícia o un altre servei públic té multa de tres a dotze mesos i suspensió de sis mesos a dos anys (art. 412.1 CP). Si el requerit és autoritat, cap o responsable d''una força pública o agent de l''autoritat (com un policia local), la pena puja a multa de dotze a divuit mesos i suspensió de dos a tres anys (art. 412.2 CP). Si el requeriment el fa un particular per evitar un delicte contra la vida, la pena és multa de divuit a vint-i-quatre mesos i inhabilitació especial de tres a sis anys (art. 412.3 CP).","refs":[{"ref":"Art. 412.1 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"El funcionario público que, requerido por autoridad competente, no prestare el auxilio debido para la Administración de Justicia u otro servicio público, incurrirá en las penas de multa de tres a doce meses, y suspensión de empleo o cargo público por tiempo de seis meses a dos años."},{"ref":"Art. 412.2 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"Si el requerido fuera autoridad, jefe o responsable de una fuerza pública o un agente de la autoridad, se impondrán las penas de multa de doce a dieciocho meses y suspensión de empleo o cargo público por tiempo de dos a tres años."},{"ref":"Art. 412.3 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"La autoridad o funcionario público que, requerido por un particular a prestar algún auxilio a que venga obligado por razón de su cargo para evitar un delito contra la vida de las personas, se abstuviera de prestarlo, será castigado con la pena de multa de dieciocho a veinticuatro meses e inhabilitación especial para empleo o cargo público por tiempo de tres a seis años."}]}]},{"n":"7","title":"Infidelitat en la custòdia de documents i violació de secrets (arts. 413-417 CP)","blocks":[{"text":"Comet infidelitat en la custòdia de documents l''autoritat o funcionari que, sabent-ho, sostreu, destrueix, inutilitza o oculta, totalment o parcialment, documents la custòdia dels quals té encomanada per raó del càrrec (art. 413 CP). La pena és presó d''un a quatre anys, multa de set a vint-i-quatre mesos i inhabilitació especial de tres a sis anys. El funcionari que, sense autorització, accedeix o permet accedir a documents secrets que custodia té multa de sis a dotze mesos i inhabilitació especial d''un a tres anys (art. 415 CP).","refs":[{"ref":"Art. 413 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"La autoridad o funcionario público que, a sabiendas, sustrajere, destruyere, inutilizare u ocultare, total o parcialmente, documentos cuya custodia le esté encomendada por razón de su cargo, incurrirá en las penas de prisión de uno a cuatro años, multa de siete a veinticuatro meses, e inhabilitación especial para empleo o cargo público por tiempo de tres a seis años."},{"ref":"Art. 415 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"La autoridad o funcionario público no comprendido en el artículo anterior que, a sabiendas y sin la debida autorización, accediere o permitiere acceder a documentos secretos cuya custodia le esté confiada por razón de su cargo, incurrirá en la pena de multa de seis a doce meses, e inhabilitación especial para empleo o cargo público por tiempo de uno a tres años."}]},{"text":"La revelació de secrets o informacions conegudes per raó del càrrec i que no s''han de divulgar es castiga amb multa de dotze a divuit mesos i inhabilitació especial d''un a tres anys; si causa un dany greu a la causa pública o a un tercer, presó d''un a tres anys (art. 417.1 CP). Si són secrets d''un particular, presó de dos a quatre anys (art. 417.2 CP).","refs":[{"ref":"Art. 417.1 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"La autoridad o funcionario público que revelare secretos o informaciones de los que tenga conocimiento por razón de su oficio o cargo y que no deban ser divulgados, incurrirá en la pena de multa de doce a dieciocho meses e inhabilitación especial para empleo o cargo público por tiempo de uno a tres años."},{"ref":"Art. 417.2 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"Si se tratara de secretos de un particular, las penas serán las de prisión de dos a cuatro años, multa de doce a dieciocho meses, y suspensión de empleo o cargo público por tiempo de uno a tres años."}]}]},{"n":"8","title":"El suborn (arts. 419-426 CP)","blocks":[{"text":"El suborn més greu el comet l''autoritat o funcionari que, en profit propi o d''un tercer, sol·licita o rep una dàdiva, favor o retribució, o n''accepta l''oferiment o la promesa, per fer en l''exercici del càrrec un acte contrari als deures que hi són inherents, o per no fer o retardar injustificadament el que ha de fer (art. 419 CP). La pena és presó de tres a sis anys, multa de dotze a vint-i-quatre mesos i inhabilitació especial de nou a dotze anys, sens perjudici de la pena de l''acte mateix si és delicte.","refs":[{"ref":"Art. 419 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"La autoridad o funcionario público que, en provecho propio o de un tercero, recibiere o solicitare, por sí o por persona interpuesta, dádiva, favor o retribución de cualquier clase o aceptare ofrecimiento o promesa para realizar en el ejercicio de su cargo un acto contrario a los deberes inherentes al mismo o para no realizar o retrasar injustificadamente el que debiera practicar, incurrirá en la pena de prisión de tres a seis años, multa de doce a veinticuatro meses, e inhabilitación especial para empleo o cargo público y para el ejercicio del derecho de sufragio pasivo por tiempo de nueve a doce años, sin perjuicio de la pena correspondiente al acto realizado"}]},{"text":"Si la retribució és per fer un acte propi del càrrec, la presó és de dos a quatre anys (art. 420 CP), i admetre una dàdiva oferta en consideració al càrrec es castiga amb presó de sis mesos a un any (art. 422 CP). El particular que ofereix o lliura la dàdiva rep les mateixes penes de presó i multa que el funcionari corromput (art. 424.1 CP), però queda exempt de pena si, havent accedit ocasionalment a la sol·licitud del funcionari, ho denuncia abans que s''obri el procediment i dins dels dos mesos següents als fets (art. 426 CP).","refs":[{"ref":"Art. 420 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"para realizar un acto propio de su cargo, incurrirá en la pena de prisión de dos a cuatro años"},{"ref":"Art. 422 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"La autoridad o funcionario público que, en provecho propio o de un tercero, admitiera, por sí o por persona interpuesta, dádiva o regalo que le fueren ofrecidos en consideración a su cargo o función, incurrirá en la pena de prisión de seis meses a un año"},{"ref":"Art. 426 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"Quedará exento de pena por el delito de cohecho el particular que, habiendo accedido ocasionalmente a la solicitud de dádiva u otra retribución realizada por autoridad o funcionario público, denunciare el hecho a la autoridad que tenga el deber de proceder a su averiguación antes de la apertura del procedimiento, siempre que no haya transcurrido más de dos meses desde la fecha de los hechos."}]}]},{"n":"9","title":"Delictes dels funcionaris contra les garanties constitucionals: llibertat individual i drets del detingut (arts. 530-532 i 537 CP)","blocks":[{"text":"El capítol V del títol XXI castiga els funcionaris que, «mediant causa per delicte», vulneren les garanties constitucionals. L''autoritat o funcionari que acorda, practica o prolonga una privació de llibertat d''un detingut, pres o condemnat violant els terminis o altres garanties té inhabilitació especial de quatre a vuit anys (art. 530 CP); si es tracta de la incomunicació, de dos a sis anys (art. 531 CP). Si aquests fets es cometen per imprudència greu, la pena és suspensió de sis mesos a dos anys (art. 532 CP).","refs":[{"ref":"Art. 530 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"La autoridad o funcionario público que, mediando causa por delito, acordare, practicare o prolongare cualquier privación de libertad de un detenido, preso o sentenciado, con violación de los plazos o demás garantías constitucionales o legales, será castigado con la pena de inhabilitación especial para empleo o cargo público por tiempo de cuatro a ocho años."},{"ref":"Art. 532 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"Si los hechos descritos en los dos artículos anteriores fueran cometidos por imprudencia grave, se castigarán con la pena de suspensión de empleo o cargo público por tiempo de seis meses a dos años."}]},{"text":"Per a la detenció policial és clau l''article 537 CP: comet delicte qui impedeix o obstaculitza el dret del detingut a l''assistència d''advocat, en procura o afavoreix la renúncia o no l''informa de manera immediata i comprensible dels seus drets i de les raons de la detenció. La pena és multa de quatre a deu mesos i inhabilitació especial de dos a quatre anys.","refs":[{"ref":"Art. 537 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"La autoridad o funcionario público que impida u obstaculice el derecho a la asistencia de abogado al detenido o preso, procure o favorezca la renuncia del mismo a dicha asistencia o no le informe de forma inmediata y de modo que le sea comprensible de sus derechos y de las razones de su detención, será castigado con la pena de multa de cuatro a diez meses e inhabilitación especial para empleo o cargo público de dos a cuatro años."}]}]},{"n":"10","title":"Inviolabilitat del domicili, intimitat i altres drets (arts. 534-536 i 538-542 CP)","blocks":[{"text":"L''autoritat o funcionari que, mediant causa per delicte i sense respectar les garanties constitucionals o legals, entra en un domicili sense el consentiment del morador o en registra papers, documents o efectes sense el consentiment lliure del titular és castigat amb multa de sis a dotze mesos i inhabilitació especial de dos a sis anys (art. 534.1 CP). Si no torna immediatament el que ha registrat, la inhabilitació puja a sis a dotze anys. En un registre lícit, la vexació injusta o el dany innecessari també es castiguen (art. 534.2 CP).","refs":[{"ref":"Art. 534.1 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"Será castigado con las penas de multa de seis a doce meses e inhabilitación especial para empleo o cargo público de dos a seis años la autoridad o funcionario público que, mediando causa por delito, y sin respetar las garantías constitucionales o legales: 1.º Entre en un domicilio sin el consentimiento del morador. 2.º Registre los papeles o documentos de una persona o los efectos que se hallen en su domicilio, a no ser que el dueño haya prestado libremente su consentimiento."},{"ref":"Art. 534.2 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"La autoridad o funcionario público que, con ocasión de lícito registro de papeles, documentos o efectos de una persona, cometa cualquier vejación injusta o daño innecesario en sus bienes"}]},{"text":"També són delictes interceptar correspondència privada (art. 535 CP) o telecomunicacions sense garanties (art. 536 CP), amb inhabilitació de dos a sis anys. Prohibir una reunió pacífica o dissoldre-la fora dels casos permesos per les lleis comporta inhabilitació especial de quatre a vuit anys i multa de sis a nou mesos (art. 540 CP).","refs":[{"ref":"Art. 536 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"La autoridad, funcionario público o agente de éstos que, mediando causa por delito, interceptare las telecomunicaciones o utilizare artificios técnicos de escuchas, transmisión, grabación o reproducción del sonido, de la imagen o de cualquier otra señal de comunicación, con violación de las garantías constitucionales o legales, incurrirá en la pena de inhabilitación especial para empleo o cargo público de dos a seis años."},{"ref":"Art. 540 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"La autoridad o funcionario público que prohiba una reunión pacífica o la disuelva fuera de los casos expresamente permitidos por las Leyes, será castigado con la pena de inhabilitación especial para empleo o cargo público de cuatro a ocho años y multa de seis a nueve meses."}]}]},{"n":"11","title":"Atemptat, resistència i desobediència (arts. 550-556 CP)","blocks":[{"text":"Són reus d''atemptat els qui agredeixen o, amb intimidació greu o violència, oposen resistència greu a l''autoritat, als seus agents o als funcionaris públics, o els escometen, quan són en l''exercici de les funcions o amb ocasió d''aquestes (art. 550.1 CP). En tot cas, són atemptat els actes contra funcionaris docents o sanitaris en l''exercici de les seves funcions. La pena és presó d''un a quatre anys i multa de tres a sis mesos si l''atemptat és contra l''autoritat, i presó de sis mesos a tres anys en els altres casos, com ara contra un agent (art. 550.2 CP).","refs":[{"ref":"Art. 550.1 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"Son reos de atentado los que agredieren o, con intimidación grave o violencia, opusieren resistencia grave a la autoridad, a sus agentes o funcionarios públicos, o los acometieren, cuando se hallen en el ejercicio de las funciones de sus cargos o con ocasión de ellas. En todo caso, se considerarán actos de atentado los cometidos contra los funcionarios docentes o sanitarios que se hallen en el ejercicio de las funciones propias de su cargo, o con ocasión de ellas."},{"ref":"Art. 550.2 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"Los atentados serán castigados con las penas de prisión de uno a cuatro años y multa de tres a seis meses si el atentado fuera contra autoridad y de prisión de seis meses a tres años en los demás casos."}]},{"text":"S''imposen les penes superiors en grau si l''atemptat es comet amb armes o objectes perillosos, amb una violència potencialment perillosa per a la vida, escometent amb un vehicle de motor o en un motí dins d''un centre penitenciari (art. 551 CP). Les penes de l''atemptat s''apliquen també a qui escomet, empra violència o intimida les persones que acudeixen en auxili de l''autoritat, dels seus agents o dels funcionaris (art. 554.2 CP), i als bombers, sanitaris o equips de socors en una emergència (art. 554.3 CP).","refs":[{"ref":"Art. 551 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"Se impondrán las penas superiores en grado a las respectivamente previstas en el artículo anterior siempre que el atentado se cometa: 1.º Haciendo uso de armas u otros objetos peligrosos. […] 3.º Acometiendo a la autoridad, a su agente o al funcionario público haciendo uso de un vehículo de motor."},{"ref":"Art. 554.2 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"Las mismas penas se impondrán a quienes acometan, empleen violencia o intimiden a las personas que acudan en auxilio de la autoridad, sus agentes o funcionarios."}]},{"text":"Sense arribar a l''atemptat, qui resisteix o desobeeix greument l''autoritat o els seus agents en l''exercici de les funcions té presó de tres mesos a un any o multa de sis a divuit mesos (art. 556.1 CP). Faltar al respecte i a la consideració deguda a l''autoritat en l''exercici de les seves funcions es castiga amb multa d''un a tres mesos (art. 556.2 CP); fixa''t que aquest apartat parla només de l''autoritat.","refs":[{"ref":"Art. 556.1 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"Serán castigados con la pena de prisión de tres meses a un año o multa de seis a dieciocho meses, los que, sin estar comprendidos en el artículo 550, resistieren o desobedecieren gravemente a la autoridad o sus agentes en el ejercicio de sus funciones"},{"ref":"Art. 556.2 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"Los que faltaren al respeto y consideración debida a la autoridad, en el ejercicio de sus funciones, serán castigados con la pena de multa de uno a tres meses."}]}]},{"n":"12","title":"Desordres públics (art. 557 CP)","blocks":[{"text":"Hi ha desordres públics quan s''actua en grup i amb la finalitat d''atemptar contra la pau pública, executant actes de violència o intimidació sobre les persones o les coses, obstaculitzant les vies públiques amb perill per a la vida o la salut, o envaint instal·lacions o edificis i alterant greument serveis essencials. La pena és presó de sis mesos a tres anys (art. 557.1 CP), i de tres a cinc anys si ho fa una multitud idònia per afectar greument l''ordre públic (art. 557.2 CP).","refs":[{"ref":"Art. 557.1 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"Serán castigados con la pena de prisión de seis meses a tres años los que, actuando en grupo y con el fin de atentar contra la paz pública, ejecuten actos de violencia o intimidación: a) Sobre las personas o las cosas; u b) obstaculizando las vías públicas ocasionando un peligro para la vida o salud de las personas; o c) invadiendo instalaciones o edificios alterando gravemente el funcionamiento efectivo de servicios esenciales en esos lugares."},{"ref":"Art. 557.2 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"Los hechos descritos en el apartado anterior serán castigados con la pena de prisión de tres a cinco años e inhabilitación especial para empleo o cargo público por el mismo tiempo cuando se cometan por una multitud cuyo número, organización y propósito sean idóneos para afectar gravemente el orden público."}]},{"text":"Provocar en un lloc concorregut una allau, una estampida o una reacció anàloga que posi en perill la vida o la salut del públic es castiga amb presó de sis mesos a dos anys (art. 557.5 CP). Aquestes penes s''imposen sens perjudici de les que corresponguin per les lesions, amenaces, coaccions o danys concrets (art. 557.6 CP).","refs":[{"ref":"Art. 557.5 i 557.6 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"Será castigado con pena de prisión de seis meses a dos años quien en lugar concurrido provocara avalancha, estampida u otra reacción análoga en el público que pongan en situación de peligro la vida o la salud de las personas. […] Las penas señaladas en este artículo se impondrán sin perjuicio de las que les puedan corresponder a los actos concretos de lesiones, amenazas, coacciones o daños que se hubieran llevado a cabo."}]}]},{"n":"R","title":"Recorda per a l''examen","blocks":[{"text":"Autoritat: té comandament o jurisdicció pròpia; funcionari: participa en funcions públiques per llei, elecció o nomenament (art. 24 CP).","refs":[{"ref":"Art. 24.2 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"Se considerará funcionario público todo el que por disposición inmediata de la Ley o por elección o por nombramiento de autoridad competente participe en el ejercicio de funciones públicas."}]},{"text":"L''agreujant de discriminació s''aplica encara que la víctima no tingui realment la condició que motiva l''autor (art. 22.4a CP).","refs":[{"ref":"Art. 22.4 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"con independencia de que tales condiciones o circunstancias concurran efectivamente en la persona sobre la que recaiga la conducta."}]},{"text":"Omissió del socors: multa de tres a dotze mesos; si l''accident el va causar per imprudència qui omet l''auxili, presó de sis mesos a quatre anys (art. 195 CP).","refs":[{"ref":"Art. 195.3 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"si el accidente se debiere a imprudencia, la de prisión de seis meses a cuatro años."}]},{"text":"Prevaricació: inhabilitació de nou a quinze anys (art. 404 CP); no promoure la persecució de delictes: inhabilitació de sis mesos a dos anys (art. 408 CP).","refs":[{"ref":"Art. 408 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"incurrirá en la pena de inhabilitación especial para empleo o cargo público por tiempo de seis meses a dos años."}]},{"text":"Agent de l''autoritat que no presta l''auxili requerit: multa de dotze a divuit mesos i suspensió de dos a tres anys (art. 412.2 CP).","refs":[{"ref":"Art. 412.2 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"se impondrán las penas de multa de doce a dieciocho meses y suspensión de empleo o cargo público por tiempo de dos a tres años."}]},{"text":"Suborn per a un acte contrari al càrrec: presó de tres a sis anys i inhabilitació de nou a dotze anys (art. 419 CP).","refs":[{"ref":"Art. 419 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"incurrirá en la pena de prisión de tres a seis años, multa de doce a veinticuatro meses, e inhabilitación especial para empleo o cargo público y para el ejercicio del derecho de sufragio pasivo por tiempo de nueve a doce años"}]},{"text":"Entrar en un domicili sense consentiment i sense garanties: multa de sis a dotze mesos i inhabilitació de dos a sis anys (art. 534.1 CP).","refs":[{"ref":"Art. 534.1 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"1.º Entre en un domicilio sin el consentimiento del morador."}]},{"text":"Atemptat contra un agent: presó de sis mesos a tres anys; contra l''autoritat: d''un a quatre anys (art. 550.2 CP). Amb vehicle de motor, pena superior en grau (art. 551 CP).","refs":[{"ref":"Art. 550.2 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"de prisión de seis meses a tres años en los demás casos."}]},{"text":"Resistència o desobediència greu: presó de tres mesos a un any o multa de sis a divuit mesos; falta de respecte a l''autoritat: multa d''un a tres mesos (art. 556 CP).","refs":[{"ref":"Art. 556.2 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"serán castigados con la pena de multa de uno a tres meses."}]},{"text":"Desordres públics: actuar en grup, amb la finalitat d''atemptar contra la pau pública i amb violència o intimidació (art. 557.1 CP).","refs":[{"ref":"Art. 557.1 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"actuando en grupo y con el fin de atentar contra la paz pública, ejecuten actos de violencia o intimidación"}]}]}]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444', null, null, null, null
  from public.topics t where t.slug = 'plcat-t17-codi-penal-ordre-public-funcionaris'
