insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, lessons, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"Àmbit d''aplicació de la LO 5/2000 i edat penal"},{"n":"2","title":"Drets dels menors i principis"},{"n":"3","title":"Detenció del menor: termini i custòdia"},{"n":"4","title":"Comunicació al Ministeri Fiscal i als representants legals"},{"n":"5","title":"Mesures aplicables"}]'::jsonb, '["Art. 1 LO 5/2000: «1. Esta Ley se aplicará para exigir la responsabilidad de las personas mayores de catorce años y menores de dieciocho»","Art. 3 LO 5/2000: «Cuando el autor de los hechos mencionados en los artículos anteriores sea menor de catorce años, no se le exigirá responsabilidad con arreglo a la presente Ley, sino que se le aplicará lo dispuesto en las normas sobre protección de menores»","Art. 2.3 LO 5/2000: «3. La competencia corresponde al Juez de Menores del lugar donde se haya cometido el hecho delictivo»","Art. 5.3 LO 5/2000: «3. Las edades indicadas en el articulado de esta Ley se han de entender siempre referidas al momento de la comisión de los hechos»","Art. 7.1 LO 5/2000: «a) Internamiento en régimen cerrado.»","Art. 7.1.g LO 5/2000: «g) Permanencia de fin de semana. Las personas sometidas a esta medida permanecerán en su domicilio o en un centro hasta un máximo de treinta y seis horas»","Art. 7.1.c LO 5/2000: «c) Internamiento en régimen abierto. Las personas sometidas a esta medida llevarán a cabo todas las actividades del proyecto educativo en los servicios normalizados del entorno»","Art. 10.1 LO 5/2000: «a) si al tiempo de cometer los hechos el menor tuviere catorce o quince años de edad, la medida podrá alcanzar tres años de duración.»","Art. 10.2 LO 5/2000: «b) Si al tiempo de cometer los hechos el menor tuviere dieciséis o diecisiete años de edad, una medida de internamiento en régimen cerrado de uno a ocho años de duración»","Art. 17.1 LO 5/2000: «También deberán notificar inmediatamente el hecho de la detención y el lugar de la custodia a los representantes legales del menor y al Ministerio Fiscal.»","Art. 17.2 LO 5/2000: «2. Toda declaración del detenido, se llevará a cabo en presencia de su letrado y de aquéllos que ejerzan la patria potestad, tutela o guarda del menor»","Art. 17.3 LO 5/2000: «3. Mientras dure la detención, los menores deberán hallarse custodiados en dependencias adecuadas y separadas de las que se utilicen para los mayores de edad»","Art. 17.4 LO 5/2000: «dentro del plazo máximo de veinticuatro horas, el menor detenido deberá ser puesto en libertad o a disposición del Ministerio Fiscal.»","Art. 17.5 LO 5/2000: «éste habrá de resolver, dentro de las cuarenta y ocho horas a partir de la detención»","Art. 17.6 LO 5/2000: «Cuando el procedimiento de hábeas corpus sea instado por el propio menor, la fuerza pública responsable de la detención lo notificará inmediatamente al Ministerio Fiscal»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[{"n":"1","title":"Objecte i àmbit d''aplicació: la franja d''edat penal (arts. 1 i 3 LORPM)","blocks":[{"text":"La Llei orgànica 5/2000, de 12 de gener, reguladora de la responsabilitat penal dels menors (LORPM), s''aplica per exigir la responsabilitat de les persones majors de catorze anys i menors de divuit que cometen fets tipificats com a delictes al Codi penal o a les lleis penals especials (art. 1.1 LORPM). Els majors de divuit anys responen d''acord amb el Codi penal general; la LORPM és, doncs, un sistema penal específic per als adolescents d''aquesta franja.","refs":[{"ref":"Art. 1.1 LORPM","law":"LO 5/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-641","quote":"Esta Ley se aplicará para exigir la responsabilidad de las personas mayores de catorce años y menores de dieciocho por la comisión de hechos tipificados como delitos o faltas en el Código Penal o las leyes penales especiales."}]},{"text":"Quan l''autor dels fets és menor de catorze anys, no se li exigeix responsabilitat d''acord amb aquesta llei, sinó que se li apliquen les normes de protecció de menors del Codi civil i la resta de disposicions vigents (art. 3 LORPM). En aquest cas, el Ministeri Fiscal remet a l''entitat pública de protecció de menors el testimoni necessari perquè valori la situació del menor i promogui les mesures de protecció adequades.","refs":[{"ref":"Art. 3 LORPM","law":"LO 5/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-641","quote":"Cuando el autor de los hechos mencionados en los artículos anteriores sea menor de catorce años, no se le exigirá responsabilidad con arreglo a la presente Ley, sino que se le aplicará lo dispuesto en las normas sobre protección de menores previstas en el Código Civil y demás disposiciones vigentes. El Ministerio Fiscal deberá remitir a la entidad pública de protección de menores testimonio de los particulares que considere precisos respecto al menor, a fin de valorar su situación"}]},{"text":"Les edats que fixa la llei es refereixen sempre al moment de la comissió dels fets. Si el menor les supera abans de començar el procediment o mentre es tramita, això no afecta la competència dels jutges i fiscals de menors (art. 5.3 LORPM). Per exemple, qui va cometre el fet amb disset anys continua sotmès a la LORPM encara que en tingui divuit quan se''l jutja.","refs":[{"ref":"Art. 5.3 LORPM","law":"LO 5/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-641","quote":"Las edades indicadas en el articulado de esta Ley se han de entender siempre referidas al momento de la comisión de los hechos, sin que el haberse rebasado las mismas antes del comienzo del procedimiento o durante la tramitación del mismo tenga incidencia alguna sobre la competencia atribuida por esta misma Ley a los Jueces y Fiscales de Menores."}]}]},{"n":"2","title":"Drets dels menors i de les víctimes (arts. 1.2 i 4 LORPM)","blocks":[{"text":"Els menors als quals s''aplica la llei gaudeixen de tots els drets reconeguts a la Constitució i a l''ordenament jurídic, particularment a la Llei orgànica 1/1996, de protecció jurídica del menor, i a la Convenció sobre els Drets de l''Infant de 20 de novembre de 1989, a més dels tractats sobre protecció de menors ratificats per Espanya (art. 1.2 LORPM).","refs":[{"ref":"Art. 1.2 LORPM","law":"LO 5/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-641","quote":"Las personas a las que se aplique la presente Ley gozarán de todos los derechos reconocidos en la Constitución y en el ordenamiento jurídico, particularmente en la Ley Orgánica 1/1996, de 15 de enero, de Protección Jurídica del Menor, así como en la Convención sobre los Derechos del Niño de 20 de noviembre de 1989"}]},{"text":"La llei també protegeix les víctimes: el Ministeri Fiscal i el jutge de menors han de vetllar en tot moment pels drets de les víctimes i dels perjudicats (art. 4 LORPM). Les víctimes tenen dret a personar-se i ser part en l''expedient, i el lletrat de l''Administració de justícia ha de derivar la víctima de violència a l''Oficina d''Atenció a la Víctima competent.","refs":[{"ref":"Art. 4 LORPM","law":"LO 5/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-641","quote":"El Ministerio Fiscal y el Juez de Menores velarán en todo momento por la protección de los derechos de las víctimas y de las personas perjudicadas por las infracciones cometidas por las personas menores de edad. […] Las víctimas y las personas perjudicadas tendrán derecho a personarse y ser parte en el expediente que se incoe al efecto"},{"ref":"Art. 4 LORPM","law":"LO 5/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-641","quote":"debiendo el Letrado de la Administración de Justicia derivar a la víctima de violencia a la Oficina de Atención a la Víctima competente."}]}]},{"n":"3","title":"Òrgans competents: jutges de menors i Ministeri Fiscal (arts. 2, 6 i 16 LORPM)","blocks":[{"text":"Els jutges de menors són competents per conèixer dels fets comesos pels menors de la franja de l''article 1 i per fer executar les sentències (art. 2.1 LORPM). També ho són per resoldre sobre les responsabilitats civils derivades d''aquests fets (art. 2.2 LORPM). Amb caràcter general, la competència territorial correspon al jutge de menors del lloc on s''ha comès el fet delictiu (art. 2.3 LORPM), mentre que els delictes de terrorisme (arts. 571 a 580 CP) corresponen al Jutjat Central de Menors de l''Audiència Nacional (art. 2.4 LORPM).","refs":[{"ref":"Art. 2.2 LORPM","law":"LO 5/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-641","quote":"Los Jueces de Menores serán asimismo competentes para resolver sobre las responsabilidades civiles derivadas de los hechos cometidos por las personas a las que resulta aplicable la presente Ley."},{"ref":"Art. 2.3 i 2.4 LORPM","law":"LO 5/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-641","quote":"La competencia corresponde al Juez de Menores del lugar donde se haya cometido el hecho delictivo, sin perjuicio de lo establecido en el artículo 20.3 de esta Ley. […] La competencia para conocer de los delitos previstos en los artículos 571 a 580 del Código Penal corresponderá al Juzgado Central de Menores de la Audiencia Nacional."}]},{"text":"La instrucció no la fa un jutge, sinó el Ministeri Fiscal (art. 16.1 LORPM). El fiscal defensa els drets del menor, vigila les garanties del procediment, dirigeix personalment la investigació i ordena a la policia judicial les actuacions necessàries per comprovar els fets i la participació del menor (art. 6 LORPM). Per això, qui té notícia d''un fet presumptament comès per un menor de divuit anys l''ha de posar en coneixement del Ministeri Fiscal (art. 16.2 LORPM).","refs":[{"ref":"Art. 6 LORPM","law":"LO 5/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-641","quote":"Corresponde al Ministerio Fiscal la defensa de los derechos que a los menores reconocen las leyes, así como la vigilancia de las actuaciones que deban efectuarse en su interés y la observancia de las garantías del procedimiento, para lo cual dirigirá personalmente la investigación de los hechos y ordenará que la policía judicial practique las actuaciones necesarias"},{"ref":"Art. 16.1 i 16.2 LORPM","law":"LO 5/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-641","quote":"Corresponde al Ministerio Fiscal la instrucción de los procedimientos por los hechos a los que se refiere el artículo 1 de esta Ley. […] Quienes tuvieren noticia de algún hecho de los indicados en el apartado anterior, presuntamente cometido por un menor de dieciocho años, deberán ponerlo en conocimiento del Ministerio Fiscal"}]}]},{"n":"4","title":"La detenció del menor: forma, informació i notificacions (art. 17.1 LORPM)","blocks":[{"text":"Les autoritats i funcionaris que intervenen en la detenció d''un menor l''han de practicar de la manera que menys el perjudiqui. Estan obligats a informar-lo, en un llenguatge clar i comprensible i de forma immediata, dels fets que se li imputen, de les raons de la detenció i dels drets que li assisteixen, especialment els de l''article 520 LECrim, i a garantir-ne el respecte (art. 17.1 LORPM).","refs":[{"ref":"Art. 17.1 LORPM","law":"LO 5/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-641","quote":"Las autoridades y funcionarios que intervengan en la detención de un menor deberán practicarla en la forma que menos perjudique a éste y estarán obligados a informarle, en un lenguaje claro y comprensible y de forma inmediata, de los hechos que se le imputan, de las razones de su detención y de los derechos que le asisten, especialmente los reconocidos en el artículo 520 de la Ley de Enjuiciamiento Criminal, así como a garantizar el respeto de los mismos."}]},{"text":"La policia ha de notificar immediatament el fet de la detenció i el lloc de custòdia als representants legals del menor i al Ministeri Fiscal. Si el menor és estranger, la detenció es notifica a les autoritats consulars quan té la residència habitual fora d''Espanya o quan ho demana ell mateix o els seus representants legals (art. 17.1 LORPM).","refs":[{"ref":"Art. 17.1 LORPM","law":"LO 5/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-641","quote":"También deberán notificar inmediatamente el hecho de la detención y el lugar de la custodia a los representantes legales del menor y al Ministerio Fiscal. Si el menor detenido fuera extranjero, el hecho de la detención se notificará a las correspondientes autoridades consulares cuando el menor tuviera su residencia habitual fuera de España o cuando así lo solicitaran el propio menor o sus representantes legales."}]}]},{"n":"5","title":"Declaració i custòdia del menor detingut (art. 17.2 i 17.3 LORPM)","blocks":[{"text":"Tota declaració del menor detingut s''ha de fer en presència del seu advocat i dels qui n''exerceixen la pàtria potestat, la tutela o la guarda, de fet o de dret, llevat que, en aquest darrer cas, les circumstàncies aconsellin el contrari. Si no hi són, la declaració es fa en presència del Ministeri Fiscal, representat per una persona diferent de l''instructor de l''expedient. El menor té dret a una entrevista reservada amb l''advocat abans i en acabar la declaració (art. 17.2 LORPM).","refs":[{"ref":"Art. 17.2 LORPM","law":"LO 5/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-641","quote":"Toda declaración del detenido, se llevará a cabo en presencia de su letrado y de aquéllos que ejerzan la patria potestad, tutela o guarda del menor -de hecho o de derecho-, salvo que, en este último caso, las circunstancias aconsejen lo contrario. En defecto de estos últimos la declaración se llevará a cabo en presencia del Ministerio Fiscal, representado por persona distinta del instructor del expediente. El menor detenido tendrá derecho a la entrevista reservada con su abogado con anterioridad y al término de la práctica de la diligencia de toma de declaración."}]},{"text":"Mentre dura la detenció, els menors han d''estar custodiats en dependències adequades i separades de les que s''utilitzen per als majors d''edat. Han de rebre les cures, la protecció i l''assistència social, psicològica, mèdica i física que necessitin segons l''edat, el sexe i les característiques individuals (art. 17.3 LORPM).","refs":[{"ref":"Art. 17.3 LORPM","law":"LO 5/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-641","quote":"Mientras dure la detención, los menores deberán hallarse custodiados en dependencias adecuadas y separadas de las que se utilicen para los mayores de edad, y recibirán los cuidados, protección y asistencia social, psicológica, médica y física que requieran, habida cuenta de su edad, sexo y características individuales."}]}]},{"n":"6","title":"Terminis de la detenció i habeas corpus (art. 17.4 a 17.6 LORPM)","blocks":[{"text":"La detenció d''un menor per la policia no pot durar més del temps estrictament necessari per esclarir els fets i, en tot cas, en un termini màxim de vint-i-quatre hores el menor ha de ser posat en llibertat o a disposició del Ministeri Fiscal (art. 17.4 LORPM). Si escau, s''aplica l''article 520 bis LECrim, però les resolucions judicials que preveu les dicta el jutge de menors.","refs":[{"ref":"Art. 17.4 LORPM","law":"LO 5/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-641","quote":"La detención de un menor por funcionarios de policía no podrá durar más tiempo del estrictamente necesario para la realización de las averiguaciones tendentes al esclarecimiento de los hechos, y, en todo caso, dentro del plazo máximo de veinticuatro horas, el menor detenido deberá ser puesto en libertad o a disposición del Ministerio Fiscal."}]},{"text":"Un cop el menor és a disposició del fiscal, aquest ha de resoldre dins de les quaranta-vuit hores a partir de la detenció sobre la posada en llibertat, el desistiment o la incoació de l''expedient; en aquest últim cas, el posa a disposició del jutge de menors i insta les mesures cautelars oportunes (art. 17.5 LORPM).","refs":[{"ref":"Art. 17.5 LORPM","law":"LO 5/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-641","quote":"Cuando el detenido sea puesto a disposición del Ministerio Fiscal, éste habrá de resolver, dentro de las cuarenta y ocho horas a partir de la detención, sobre la puesta en libertad del menor, sobre el desistimiento al que se refiere el artículo siguiente, o sobre la incoación del expediente, poniendo a aquél a disposición del Juez de Menores competente"}]},{"text":"Per a l''habeas corpus d''un menor és competent el jutge d''instrucció del lloc on es troba el menor privat de llibertat; si no consta, el del lloc de la detenció, i, si no, el del lloc de les darreres notícies. Quan és el menor mateix qui l''insta, la força pública responsable de la detenció ho ha de notificar immediatament al Ministeri Fiscal, a més de donar curs al procediment (art. 17.6 LORPM).","refs":[{"ref":"Art. 17.6 LORPM","law":"LO 5/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-641","quote":"El Juez competente para el procedimiento de hábeas corpus en relación a un menor será el Juez de Instrucción del lugar en el que se encuentre el menor privado de libertad; si no constare, el del lugar donde se produjo la detención, y, en defecto de los anteriores, el del lugar donde se hayan tenido las últimas noticias sobre el paradero del menor detenido. Cuando el procedimiento de hábeas corpus sea instado por el propio menor, la fuerza pública responsable de la detención lo notificará inmediatamente al Ministerio Fiscal"}]},{"text":"Atenció a una dada de vigència: el text consolidat de la LORPM encara parla de «faltas», que la LO 1/2015 va suprimir. Per a la LECrim, el BOE adverteix que des de l''1 de juliol de 2015 les mencions a les faltes s''entenen referides als delictes lleus; la LORPM consolidada de la carpeta no porta aquesta nota, però als exàmens s''acostuma a llegir «faltes (delictes lleus)».","refs":[{"ref":"Nota del BOE a la LECrim","law":"LECrim","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036","quote":"desde el 1 de julio de 2015, las menciones contenidas en esta ley a las \"faltas\" se entenderán referidas a los \"delitos leves\", según establece la disposición adicional 2 de la Ley Orgánica 1/2015, de 30 de marzo."}]}]},{"n":"7","title":"Desistiment i conciliació amb la víctima (arts. 18 i 19 LORPM)","blocks":[{"text":"El Ministeri Fiscal pot desistir d''incoar l''expedient quan els fets denunciats constitueixen delictes menys greus sense violència o intimidació en les persones, o faltes. En aquest cas trasllada el que s''ha actuat a l''entitat pública de protecció de menors i comunica el desistiment als ofesos o perjudicats. Ara bé, si consta que el menor ja ha comès abans fets de la mateixa naturalesa, ha d''incoar l''expedient (art. 18 LORPM).","refs":[{"ref":"Art. 18 LORPM","law":"LO 5/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-641","quote":"El Ministerio Fiscal podrá desistir de la incoación del expediente cuando los hechos denunciados constituyan delitos menos graves sin violencia o intimidación en las personas o faltas, tipificados en el Código Penal o en las leyes penales especiales. […] No obstante, cuando conste que el menor ha cometido con anterioridad otros hechos de la misma naturaleza, el Ministerio Fiscal deberá incoar el expediente"}]},{"text":"El fiscal també pot desistir de continuar l''expedient, si es tracta de delicte menys greu o falta, quan el menor s''ha conciliat amb la víctima o s''ha compromès a reparar el dany (art. 19.1 LORPM). Hi ha conciliació quan el menor reconeix el dany causat i es disculpa davant la víctima, i aquesta n''accepta les disculpes; la reparació és el compromís de fer determinades accions en benefici de la víctima o de la comunitat, seguit de la seva realització efectiva (art. 19.2 LORPM). L''equip tècnic fa la mediació (art. 19.3 LORPM).","refs":[{"ref":"Art. 19.2 LORPM","law":"LO 5/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-641","quote":"se entenderá producida la conciliación cuando el menor reconozca el daño causado y se disculpe ante la víctima, y ésta acepte sus disculpas, y se entenderá por reparación el compromiso asumido por el menor con la víctima o perjudicado de realizar determinadas acciones en beneficio de aquellos o de la comunidad, seguido de su realización efectiva."},{"ref":"Art. 19.3 LORPM","law":"LO 5/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-641","quote":"El correspondiente equipo técnico realizará las funciones de mediación entre el menor y la víctima o perjudicado"}]}]},{"n":"8","title":"Les mesures que pot imposar el jutge de menors (art. 7 LORPM)","blocks":[{"text":"La LORPM no parla de penes sinó de mesures, ordenades segons la restricció de drets que comporten (art. 7.1 LORPM). La més restrictiva és l''internament en règim tancat, en què el menor resideix al centre i hi fa les activitats formatives, educatives, laborals i d''oci. En el règim semiobert resideix al centre però pot fer fora algunes activitats, i en el règim obert fa totes les activitats del projecte educatiu en els serveis normalitzats de l''entorn i resideix al centre com a domicili habitual.","refs":[{"ref":"Art. 7.1.a LORPM","law":"LO 5/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-641","quote":"a) Internamiento en régimen cerrado. Las personas sometidas a esta medida residirán en el centro y desarrollarán en el mismo las actividades formativas, educativas, laborales y de ocio."},{"ref":"Art. 7.1.c LORPM","law":"LO 5/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-641","quote":"c) Internamiento en régimen abierto. Las personas sometidas a esta medida llevarán a cabo todas las actividades del proyecto educativo en los servicios normalizados del entorno, residiendo en el centro como domicilio habitual, con sujeción al programa y régimen interno del mismo."}]},{"text":"Altres mesures són l''internament terapèutic, el tractament ambulatori, l''assistència a un centre de dia i la permanència de cap de setmana, en què el menor roman al domicili o en un centre fins a un màxim de trenta-sis hores entre la tarda o la nit del divendres i la nit del diumenge (art. 7.1.g LORPM). A la llibertat vigilada es fa un seguiment de l''activitat del menor i de la seva assistència a l''escola, al centre de formació o a la feina (art. 7.1.h LORPM).","refs":[{"ref":"Art. 7.1.g LORPM","law":"LO 5/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-641","quote":"g) Permanencia de fin de semana. Las personas sometidas a esta medida permanecerán en su domicilio o en un centro hasta un máximo de treinta y seis horas entre la tarde o noche del viernes y la noche del domingo"},{"ref":"Art. 7.1.h LORPM","law":"LO 5/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-641","quote":"h) Libertad vigilada. En esta medida se ha de hacer un seguimiento de la actividad de la persona sometida a la misma y de su asistencia a la escuela, al centro de formación profesional o al lugar de trabajo"}]},{"text":"La llista acaba amb la prohibició d''aproximar-se o comunicar-se amb la víctima, la convivència amb una altra persona, família o grup educatiu, les prestacions en benefici de la comunitat, que no es poden imposar sense el consentiment del menor, les tasques socioeducatives, l''amonestació, la privació del permís de conduir o de llicències i la inhabilitació absoluta (art. 7.1.i a 7.1.ñ LORPM).","refs":[{"ref":"Art. 7.1.k LORPM","law":"LO 5/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-641","quote":"k) Prestaciones en beneficio de la comunidad. La persona sometida a esta medida, que no podrá imponerse sin su consentimiento, ha de realizar las actividades no retribuidas que se le indiquen"},{"ref":"Art. 7.1.m LORPM","law":"LO 5/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-641","quote":"m) Amonestación. Esta medida consiste en la reprensión de la persona llevada a cabo por el Juez de Menores"}]}]},{"n":"9","title":"Regles d''aplicació i durada de les mesures (arts. 9 i 10 LORPM)","blocks":[{"text":"L''internament en règim tancat només es pot aplicar si els fets són delicte greu, si són delicte menys greu comès amb violència o intimidació o amb risc greu per a la vida o la integritat, o si es cometen en grup o al servei d''una banda o organització (art. 9.2 LORPM). Amb caràcter general, les mesures no poden durar més de dos anys (art. 9.3 LORPM), i els fets imprudents no es poden sancionar amb internament tancat (art. 9.4 LORPM).","refs":[{"ref":"Art. 9.2 LORPM","law":"LO 5/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-641","quote":"La medida de internamiento en régimen cerrado sólo podrá ser aplicable cuando: a) Los hechos estén tipificados como delito grave por el Código Penal o las leyes penales especiales. b) Tratándose de hechos tipificados como delito menos grave, en su ejecución se haya empleado violencia o intimidación en las personas o se haya generado grave riesgo para la vida o la integridad física de las mismas. c) Los hechos tipificados como delito se cometan en grupo o el menor perteneciere o actuare al servicio de una banda, organización o asociación"},{"ref":"Art. 9.3 i 9.4 LORPM","law":"LO 5/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-641","quote":"La duración de las medidas no podrá exceder de dos años […] Las acciones u omisiones imprudentes no podrán ser sancionadas con medidas de internamiento en régimen cerrado."}]},{"text":"En els fets de l''article 9.2, si el menor tenia catorze o quinze anys la mesura pot arribar a tres anys, i si en tenia setze o disset, a sis anys (art. 10.1 LORPM). Per als delictes més greus de l''article 10.2 (entre d''altres, els dels arts. 138 i 139 CP, el terrorisme o els castigats amb presó de quinze anys o més), el jutge ha d''imposar internament tancat d''un a cinc anys, més llibertat vigilada de fins a tres anys, als de catorze o quinze, i d''un a vuit anys, més llibertat vigilada amb assistència educativa de fins a cinc anys, als de setze o disset (art. 10.2 LORPM).","refs":[{"ref":"Art. 10.1 LORPM","law":"LO 5/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-641","quote":"a) si al tiempo de cometer los hechos el menor tuviere catorce o quince años de edad, la medida podrá alcanzar tres años de duración. […] b) si al tiempo de cometer los hechos el menor tuviere dieciséis o diecisiete años de edad, la duración máxima de la medida será de seis años"},{"ref":"Art. 10.2 LORPM","law":"LO 5/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-641","quote":"Cuando el hecho sea constitutivo de alguno de los delitos tipificados en los artículos 138, 139, 178, apartados 2 y 3, 179, 180, 181, apartados 2, 4, 5 y 6, y 571 a 580 del Código Penal, o de cualquier otro delito que tenga señalada en dicho Código o en las leyes penales especiales pena de prisión igual o superior a quince años, el Juez deberá imponer las medidas siguientes: a) Si al tiempo de cometer los hechos el menor tuviere catorce o quince años de edad, una medida de internamiento en régimen cerrado de uno a cinco años de duración, complementada en su caso por otra medida de libertad vigilada de hasta tres años. b) Si al tiempo de cometer los hechos el menor tuviere dieciséis o diecisiete años de edad, una medida de internamiento en régimen cerrado de uno a ocho años de duración, complementada en su caso por otra de libertad vigilada con asistencia educativa de hasta cinco años."}]}]},{"n":"10","title":"Mesures cautelars (art. 28 LORPM)","blocks":[{"text":"Quan hi ha indicis racionals de delicte i risc que el menor eludeixi o obstrueixi la justícia o atempti contra la víctima, el Ministeri Fiscal pot demanar al jutge de menors mesures cautelars: internament, llibertat vigilada, prohibició d''aproximació o comunicació amb la víctima o convivència amb una altra persona, família o grup educatiu (art. 28.1 LORPM). L''internament cautelar dura com a màxim sis mesos, prorrogables per tres mesos més (art. 28.3 LORPM).","refs":[{"ref":"Art. 28.1 LORPM","law":"LO 5/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-641","quote":"Dichas medidas podrán consistir en internamiento en centro en el régimen adecuado, libertad vigilada, prohibición de aproximarse o comunicarse con la víctima o con aquellos de sus familiares u otras personas que determine el Juez, o convivencia con otra persona, familia o grupo educativo."},{"ref":"Art. 28.3 LORPM","law":"LO 5/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-641","quote":"El tiempo máximo de la medida cautelar de internamiento será de seis meses, y podrá prorrogarse, a instancia del Ministerio Fiscal, previa audiencia del letrado del menor y mediante auto motivado, por otros tres meses como máximo."}]}]},{"n":"R","title":"Recorda per a l''examen","blocks":[{"text":"La LORPM s''aplica a majors de catorze i menors de divuit anys; als menors de catorze, les normes de protecció de menors (arts. 1 i 3).","refs":[{"ref":"Art. 1.1 LORPM","law":"LO 5/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-641","quote":"mayores de catorce años y menores de dieciocho"}]},{"text":"L''edat que compta és la del moment dels fets (art. 5.3).","refs":[{"ref":"Art. 5.3 LORPM","law":"LO 5/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-641","quote":"referidas al momento de la comisión de los hechos"}]},{"text":"Jutge competent: el de menors del lloc dels fets, que també resol la responsabilitat civil (art. 2.2 i 2.3).","refs":[{"ref":"Art. 2.3 LORPM","law":"LO 5/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-641","quote":"La competencia corresponde al Juez de Menores del lugar donde se haya cometido el hecho delictivo"}]},{"text":"La detenció es notifica immediatament als representants legals i al Ministeri Fiscal (art. 17.1).","refs":[{"ref":"Art. 17.1 LORPM","law":"LO 5/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-641","quote":"a los representantes legales del menor y al Ministerio Fiscal."}]},{"text":"Custòdia en dependències adequades i separades de les dels adults (art. 17.3).","refs":[{"ref":"Art. 17.3 LORPM","law":"LO 5/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-641","quote":"custodiados en dependencias adecuadas y separadas de las que se utilicen para los mayores de edad"}]},{"text":"Detenció policial: màxim vint-i-quatre hores; el fiscal resol dins de les quaranta-vuit hores des de la detenció (art. 17.4 i 17.5).","refs":[{"ref":"Art. 17.4 i 17.5 LORPM","law":"LO 5/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-641","quote":"dentro del plazo máximo de veinticuatro horas […] dentro de las cuarenta y ocho horas a partir de la detención"}]},{"text":"Habeas corpus instat pel menor: la força pública ho notifica immediatament al fiscal (art. 17.6).","refs":[{"ref":"Art. 17.6 LORPM","law":"LO 5/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-641","quote":"la fuerza pública responsable de la detención lo notificará inmediatamente al Ministerio Fiscal"}]},{"text":"Mesura més restrictiva: internament en règim tancat; permanència de cap de setmana: màxim trenta-sis hores (art. 7.1).","refs":[{"ref":"Art. 7.1.g LORPM","law":"LO 5/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-641","quote":"hasta un máximo de treinta y seis horas"}]}]}]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-641'), 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-641', null, null, null, null
  from public.topics t where t.slug = 'plcat-t18-menors'
