insert into public.sources (title, url, kind, publisher, published_on) values ('Ley Orgánica 1/2004, de 28 de diciembre, de Medidas de Protección Integral contra la Violencia de Género (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-2004-21760', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('plcat-t19-violencia-masclista', 'Tema 19. Violència masclista i domèstica: Llei 5/2008, LO 1/2004 i ordre de protecció') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('policia-local') and t.slug = 'plcat-t19-violencia-masclista' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, lessons, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"Concepte de violència masclista i formes (Llei 5/2008)"},{"n":"2","title":"Àmbits de la violència masclista"},{"n":"3","title":"LO 1/2004: objecte i drets de les víctimes"},{"n":"4","title":"Unitats de valoració policial i protecció"},{"n":"5","title":"Ordre de protecció (art. 544 ter LECrim)"},{"n":"6","title":"Maltractament en l''àmbit familiar (art. 153 CP)"}]'::jsonb, '["Art. 1.1 LO 1/2004: «se ejerce sobre éstas por parte de quienes sean o hayan sido sus cónyuges o de quienes estén o hayan estado ligados a ellas por relaciones similares de afectividad, aun sin convivencia.»","Art. 1.3 LO 1/2004: «3. La violencia de género a que se refiere la presente Ley comprende todo acto de violencia física y psicológica, incluidas las agresiones a la libertad sexual, las amenazas, las coacciones o la privación arbitraria de libertad.»","Art. 1.4 LO 1/2004: «4. La violencia de género a que se refiere esta Ley también comprende la violencia que con el objetivo de causar perjuicio o daño a las mujeres se ejerza sobre sus familiares o allegados menores de edad por parte de las personas indicadas en el apartado primero.»","Art. 31.2 LO 1/2004: «para que las Policías Locales, en el marco de su colaboración con las Fuerzas y Cuerpos de Seguridad del Estado, cooperen en asegurar el cumplimiento de las medidas acordadas por los órganos judiciales»","Art. 3 Llei 5/2008: «tiene como resultado un daño o sufrimiento físico, sexual o psicológico, tanto si se produce en el ámbito público como en el privado.»","Art. 4 Llei 5/2008: «b) Violencia psicológica: comprende toda conducta u omisión que produce en una mujer una desvaloración o un sufrimiento»","Art. 5 Llei 5/2008: «Incluye los matrimonios forzados. No incluye la violencia ejercida en el ámbito de la pareja.»","Art. 11 Llei 5/2008: «deben intervenir obligatoriamente cuando tengan conocimiento de una situación de riesgo o de una evidencia fundamentada de violencia machista»","Art. 31 Llei 5/2008: «1. La Policía de la Generalidad –Mossos d’Esquadra– debe vigilar y controlar el cumplimiento exacto de las medidas acordadas por los órganos judiciales.»","Art. 544 ter LECrim: «1. El Juez de Instrucción dictará orden de protección para las víctimas de violencia doméstica»","Art. 544 ter.3 LECrim: «3. La orden de protección podrá solicitarse directamente ante la autoridad judicial o el Ministerio Fiscal, o bien ante las Fuerzas y Cuerpos de Seguridad, las oficinas de atención a la víctima o los servicios sociales o instituciones asistenciales dependientes de las Administraciones públicas.»","Art. 544 ter.4 LECrim: «Durante la audiencia, el Juez de guardia adoptará las medidas oportunas para evitar la confrontación entre el presunto agresor y la víctima, sus hijos y los restantes miembros de la familia.»","Art. 544 ter.5 LECrim: «5. La orden de protección confiere a la víctima de los hechos mencionados en el apartado 1 un estatuto integral de protección que comprenderá las medidas cautelares de orden civil y penal contempladas en este artículo y aquellas otras medidas de asistencia y protección social establecidas en el ordenamiento jurídico.»","Art. 153 Codi penal: «será castigado con la pena de prisión de seis meses a un año o de trabajos en beneficios de la comunidad de treinta y uno a ochenta días y, en todo caso, privación del derecho a la tenencia y porte de armas de un año y un día a tres años»","Art. 31.1 LO 1/2004: «1. El Gobierno establecerá, en las Fuerzas y Cuerpos de Seguridad del Estado, unidades especializadas en la prevención de la violencia de género y en el control de la ejecución de las medidas judiciales adoptadas.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[{"n":"1","title":"LO 1/2004: objecte i concepte de violència de gènere (art. 1 LOVG)","blocks":[{"text":"La Llei orgànica 1/2004, de 28 de desembre, de mesures de protecció integral contra la violència de gènere (LOVG), actua contra la violència que, com a manifestació de la discriminació, la desigualtat i les relacions de poder dels homes sobre les dones, exerceixen sobre elles els qui són o han estat els seus cònjuges o els qui hi estan o hi han estat lligats per relacions similars d''afectivitat, fins i tot sense convivència (art. 1.1 LOVG). L''àmbit de la llei estatal és, doncs, la parella o exparella.","refs":[{"ref":"Art. 1.1 LOVG","law":"LO 1/2004","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2004-21760","quote":"La presente Ley tiene por objeto actuar contra la violencia que, como manifestación de la discriminación, la situación de desigualdad y las relaciones de poder de los hombres sobre las mujeres, se ejerce sobre éstas por parte de quienes sean o hayan sido sus cónyuges o de quienes estén o hayan estado ligados a ellas por relaciones similares de afectividad, aun sin convivencia."}]},{"text":"La violència de gènere comprèn tot acte de violència física i psicològica, incloses les agressions a la llibertat sexual, les amenaces, les coaccions o la privació arbitrària de llibertat (art. 1.3 LOVG). Comprèn també la violència que, amb l''objectiu de causar perjudici o dany a les dones, s''exerceix sobre els seus familiars o persones properes menors d''edat per part de la parella o exparella (art. 1.4 LOVG). Les mesures de la llei volen prevenir, sancionar i eradicar aquesta violència i assistir les dones i els seus fills menors (art. 1.2 LOVG).","refs":[{"ref":"Art. 1.3 LOVG","law":"LO 1/2004","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2004-21760","quote":"La violencia de género a que se refiere la presente Ley comprende todo acto de violencia física y psicológica, incluidas las agresiones a la libertad sexual, las amenazas, las coacciones o la privación arbitraria de libertad."},{"ref":"Art. 1.4 LOVG","law":"LO 1/2004","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2004-21760","quote":"La violencia de género a que se refiere esta Ley también comprende la violencia que con el objetivo de causar perjuicio o daño a las mujeres se ejerza sobre sus familiares o allegados menores de edad por parte de las personas indicadas en el apartado primero."},{"ref":"Art. 1.2 LOVG","law":"LO 1/2004","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2004-21760","quote":"Por esta ley se establecen medidas de protección integral cuya finalidad es prevenir, sancionar y erradicar esta violencia y prestar asistencia a las mujeres, a sus hijos menores y a los menores sujetos a su tutela, o guarda y custodia, víctimas de esta violencia."}]}]},{"n":"2","title":"LO 1/2004: drets de les víctimes (arts. 17-19 LOVG)","blocks":[{"text":"Totes les dones víctimes de violència de gènere tenen garantits els drets de la llei, sense discriminació en l''accés (art. 17.1 LOVG). Tenen dret a rebre informació plena i assessorament adequat a la seva situació personal (art. 18.1 LOVG), en formats accessibles per a les dones amb discapacitat i comprensibles per a les que desconeixen la llengua (art. 18.2 i 18.3 LOVG).","refs":[{"ref":"Art. 17.1 LOVG","law":"LO 1/2004","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2004-21760","quote":"Todas las mujeres víctimas de violencia de género tienen garantizados los derechos reconocidos en esta ley, sin que pueda existir discriminación en el acceso a los mismos."},{"ref":"Art. 18.1 LOVG","law":"LO 1/2004","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2004-21760","quote":"Las mujeres víctimas de violencia de género tienen derecho a recibir plena información y asesoramiento adecuado a su situación personal"}]},{"text":"També tenen dret a serveis socials d''atenció, d''emergència, de suport i acollida i de recuperació integral, organitzats per les comunitats autònomes i els ens locals d''acord amb els principis d''atenció permanent, actuació urgent, especialització i multidisciplinarietat (art. 19.1 LOVG). Els serveis d''informació, atenció psicosocial immediata, assessorament jurídic 24 hores i acollida tenen la consideració de serveis essencials (art. 17.3 LOVG).","refs":[{"ref":"Art. 19.1 LOVG","law":"LO 1/2004","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2004-21760","quote":"Las mujeres víctimas de violencia de género tienen derecho a servicios sociales de atención, de emergencia, de apoyo y acogida y de recuperación integral. La organización de estos servicios por parte de las comunidades autónomas y las Corporaciones Locales responderá a los principios de atención permanente, actuación urgente, especialización de prestaciones y multidisciplinariedad profesional."},{"ref":"Art. 17.3 LOVG","law":"LO 1/2004","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2004-21760","quote":"Los servicios de información y orientación, atención psicosocial inmediata, telefónica y en línea, asesoramiento jurídico 24 horas, los servicios de acogida y asistencia social integral, consistentes en orientación jurídica, psicológica y social destinadas a las víctimas de violencias contra las mujeres tendrán carácter de servicios esenciales."}]}]},{"n":"3","title":"LO 1/2004: unitats policials especialitzades i policies locals (art. 31 LOVG)","blocks":[{"text":"El Govern ha d''establir a les forces i cossos de seguretat de l''Estat unitats especialitzades en la prevenció de la violència de gènere i en el control de l''execució de les mesures judicials adoptades (art. 31.1 LOVG). Per fer més efectiva la protecció, ha de promoure que les policies locals, en el marc de la col·laboració amb aquestes forces, cooperin a assegurar el compliment de les mesures acordades pels òrgans judicials (art. 31.2 LOVG).","refs":[{"ref":"Art. 31.1 LOVG","law":"LO 1/2004","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2004-21760","quote":"El Gobierno establecerá, en las Fuerzas y Cuerpos de Seguridad del Estado, unidades especializadas en la prevención de la violencia de género y en el control de la ejecución de las medidas judiciales adoptadas."},{"ref":"Art. 31.2 LOVG","law":"LO 1/2004","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2004-21760","quote":"promoverá las actuaciones necesarias para que las Policías Locales, en el marco de su colaboración con las Fuerzas y Cuerpos de Seguridad del Estado, cooperen en asegurar el cumplimiento de las medidas acordadas por los órganos judiciales"}]},{"text":"La seva actuació ha de tenir en compte el Protocol d''actuació de les forces i cossos de seguretat i de coordinació amb els òrgans judicials (art. 31.3 LOVG), i l''article s''aplica també a les comunitats autònomes amb cossos de policia propis (art. 31.4 LOVG).","refs":[{"ref":"Art. 31.3 LOVG","law":"LO 1/2004","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2004-21760","quote":"La actuación de las Fuerzas y Cuerpos de Seguridad habrá de tener en cuenta el Protocolo de Actuación de las Fuerzas y Cuerpos de Seguridad y de Coordinación con los Órganos Judiciales para la protección de la violencia doméstica y de género."},{"ref":"Art. 31.4 LOVG","law":"LO 1/2004","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2004-21760","quote":"Lo dispuesto en el presente artículo será de aplicación en las Comunidades Autónomas que cuenten con cuerpos de policía que desarrollen las funciones de protección de las personas y bienes y el mantenimiento del orden y la seguridad ciudadana dentro del territorio autónomo"}]}]},{"n":"4","title":"Llei 5/2008: objecte, titulars i concepte de violència masclista (arts. 1-3 LVM)","blocks":[{"text":"La Llei catalana 5/2008, de 24 d''abril, del dret de les dones a erradicar la violència masclista, té per objecte erradicar aquesta violència i remoure les estructures socials i els estereotips culturals que la perpetuen (art. 1.1 LVM). Nota de font: la carpeta només conté la versió castellana del BOE, ja modificada per la Llei 17/2020; per això les cites són en castellà i no reprodueixen el text català del DOGC.","refs":[{"ref":"Art. 1.1 LVM","law":"Llei 5/2008","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2008-9294","quote":"La presente ley tiene por objeto la erradicación de la violencia machista y la remoción de las estructuras sociales y los estereotipos culturales que la perpetúan"},{"ref":"Nota del BOE a l''art. 3 LVM","law":"Llei 5/2008","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2008-9294","quote":"Se modifica por el art. 2 de la Ley 17/2020, de 22 de diciembre."}]},{"text":"La llei protegeix totes les dones en situació de violència masclista, i els seus fills i filles dependents, que viuen o treballen a Catalunya, sigui quin sigui el seu veïnatge civil, nacionalitat o situació administrativa (art. 2.1 LVM); les referències a les dones inclouen les nenes, les adolescents i les dones transgènere (art. 2.2 LVM).","refs":[{"ref":"Art. 2.1 LVM","law":"Llei 5/2008","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2008-9294","quote":"Todas las mujeres que se hallan en situaciones de violencia machista, así como sus hijos e hijas dependientes, que vivan o trabajen en Cataluña y con independencia de la vecindad civil, la nacionalidad o la situación administrativa y personal"},{"ref":"Art. 2.2 LVM","law":"Llei 5/2008","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2008-9294","quote":"Las referencias a las mujeres incluidas en la presente ley se entiende que incluyen a las niñas y las adolescentes, y, por lo tanto, también a las mujeres, niñas y adolescentes transgénero."}]},{"text":"La violència masclista és una violació dels drets humans: la violència que s''exerceix contra les dones com a manifestació de la discriminació i de la desigualtat en un sistema de relacions de poder dels homes sobre les dones. Es pot produir per mitjans físics, econòmics o psicològics, incloses amenaces, intimidacions i coaccions, i té com a resultat un dany o patiment físic, sexual o psicològic, tant en l''àmbit públic com en el privat (art. 3.a LVM).","refs":[{"ref":"Art. 3.a LVM","law":"Llei 5/2008","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2008-9294","quote":"a) Violencia machista: violación de los derechos humanos a través de la violencia que se ejerce contra las mujeres como manifestación de la discriminación y de la situación de desigualdad en el marco de un sistema de relaciones de poder de los hombres sobre las mujeres y que, producida por medios físicos, económicos o psicológicos, incluidas las amenazas, las intimidaciones y las coacciones, tiene como resultado un daño o sufrimiento físico, sexual o psicológico, tanto si se produce en el ámbito público como en el privado."}]}]},{"n":"5","title":"Formes de violència masclista (art. 4 LVM)","blocks":[{"text":"La violència masclista es pot exercir de manera puntual o reiterada (art. 4.2 LVM). La violència física és qualsevol acte de força contra el cos d''una dona amb el resultat o el risc de produir-li una lesió física o un dany. La violència psicològica és tota conducta o omissió que produeix en una dona una desvaloració o un patiment, mitjançant amenaces, humiliació, vexacions, menyspreu, exigència d''obediència, insults, aïllament o qualsevol altra limitació de la seva llibertat.","refs":[{"ref":"Art. 4.2.a LVM","law":"Llei 5/2008","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2008-9294","quote":"a) Violencia física: comprende cualquier acto de fuerza contra el cuerpo de una mujer, con el resultado o el riesgo de producirle una lesión física o un daño."},{"ref":"Art. 4.2.b LVM","law":"Llei 5/2008","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2008-9294","quote":"b) Violencia psicológica: comprende toda conducta u omisión que produce en una mujer una desvaloración o un sufrimiento, mediante amenazas, humillación, vejaciones, menosprecio, desprecio, exigencia de obediencia o sumisión, coerción verbal, insultos, aislamiento o cualquier otra limitación de su ámbito de libertad."}]},{"text":"La violència sexual comprèn qualsevol acte que imposi una pràctica sexual sense el consentiment ni la voluntat de la dona, amb independència del vincle amb l''agressor. La llei també recull la violència obstètrica, l''econòmica (privació intencionada de recursos o impagament reiterat de pensions), la digital, la de segon ordre contra les persones que donen suport a les víctimes i la vicària, exercida contra els fills i filles per fer mal a la mare (art. 4.2.c a 4.2.h LVM).","refs":[{"ref":"Art. 4.2.c LVM","law":"Llei 5/2008","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2008-9294","quote":"c) Violencia sexual: comprende cualquier acto que atente contra la libertad sexual y la dignidad personal de la mujer creando unas condiciones o aprovechándose de un contexto que, directa o indirectamente, impongan una práctica sexual sin contar con el consentimiento ni la voluntad de la mujer, con independencia del vínculo que exista entre la mujer y el agresor o agresores."},{"ref":"Art. 4.2.g i 4.2.h LVM","law":"Llei 5/2008","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2008-9294","quote":"g) Violencia de segundo orden: consiste en la violencia física o psicológica, las represalias, las humillaciones y la persecución ejercidas contra las personas que apoyan a las víctimas de violencia machista. […] h) Violencia vicaria: consiste en cualquier tipo de violencia ejercida contra los hijos e hijas con el fin de provocar daño psicológico a la madre."}]}]},{"n":"6","title":"Àmbits de la violència masclista (art. 5 LVM)","blocks":[{"text":"El primer àmbit és la parella: violència exercida contra una dona pel cònjuge o excònjuge o per qui hi té o hi ha tingut relacions similars d''afectivitat. El segon és el familiar: violència contra les dones i els menors dins la família, perpetrada per membres de la família o del nucli de convivència; inclou els matrimonis forçats, però no la violència en l''àmbit de la parella (art. 5 LVM).","refs":[{"ref":"Art. 5 primer LVM","law":"Llei 5/2008","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2008-9294","quote":"Primero. Violencia en el ámbito de la pareja: consiste en la violencia física, psicológica, digital, sexual o económica ejercida contra una mujer y perpetrada por el hombre que es o ha sido su cónyuge o por la persona que tiene o ha tenido relaciones similares de afectividad con ella."},{"ref":"Art. 5 segon LVM","law":"Llei 5/2008","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2008-9294","quote":"Incluye los matrimonios forzados. No incluye la violencia ejercida en el ámbito de la pareja."}]},{"text":"La violència en l''àmbit laboral es pot produir en l''àmbit públic o privat durant la jornada de treball, o fora del centre i de l''horari si té relació amb la feina, i pren la forma d''assetjament per raó de sexe, assetjament sexual o discriminació per embaràs o maternitat. Els altres àmbits són el social o comunitari (agressions sexuals, tràfic de dones, mutilació genital, feminicidis…), el digital, l''institucional, el de la vida política i l''educatiu (art. 5 LVM).","refs":[{"ref":"Art. 5 tercer LVM","law":"Llei 5/2008","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2008-9294","quote":"Tercero. Violencia en el ámbito laboral: consiste en la violencia física, sexual, económica, digital o psicológica que puede producirse en el ámbito público o privado durante la jornada de trabajo, o fuera del centro y del horario establecido si tiene relación con el trabajo."},{"ref":"Art. 5 quart LVM","law":"Llei 5/2008","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2008-9294","quote":"g) Feminicidios: los asesinatos y homicidios de mujeres por razón de género"}]}]},{"n":"7","title":"Detecció i obligació d''intervenir (arts. 10 i 11 LVM)","blocks":[{"text":"Les administracions públiques de Catalunya han de desenvolupar les accions necessàries per detectar i identificar situacions de risc o de violència masclista (art. 10.1 LVM). Tots els professionals, especialment els de la salut, els serveis socials i l''educació, han d''intervenir obligatòriament quan coneixen una situació de risc o una evidència fonamentada de violència masclista, d''acord amb els protocols específics i en coordinació amb la Xarxa d''Atenció i Recuperació Integral (art. 11.1 LVM). Aquesta obligació s''entén sens perjudici del deure de comunicar els fets als cossos de seguretat o al Ministeri Fiscal (art. 11.3 LVM).","refs":[{"ref":"Art. 10.1 LVM","law":"Llei 5/2008","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2008-9294","quote":"Las administraciones públicas de Cataluña deben desarrollar las acciones necesarias para detectar e identificar situaciones de riesgo o existencia de violencia machista."},{"ref":"Art. 11.1 LVM","law":"Llei 5/2008","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2008-9294","quote":"Todas las personas profesionales, especialmente profesionales de la salud, los servicios sociales y la educación, deben intervenir obligatoriamente cuando tengan conocimiento de una situación de riesgo o de una evidencia fundamentada de violencia machista, de acuerdo con los protocolos específicos y en coordinación con los servicios de la Red de Atención y Recuperación Integral."},{"ref":"Art. 11.3 LVM","law":"Llei 5/2008","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2008-9294","quote":"Las obligaciones a que se refieren los apartados 1 y 2 se entienden sin perjuicio del deber de comunicación de los hechos a los cuerpos y fuerzas de seguridad o al Ministerio Fiscal."}]}]},{"n":"8","title":"Dret a la protecció efectiva i paper dels cossos policials (arts. 30 i 31 LVM)","blocks":[{"text":"Les dones en risc o en situació de violència masclista tenen dret a rebre immediatament de les administracions catalanes una protecció integral, real i efectiva, garantida per mitjans tecnològics, per serveis policials i per qualsevol altre mitjà (art. 30.1 i 30.2 LVM).","refs":[{"ref":"Art. 30.1 i 30.2 LVM","law":"Llei 5/2008","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2008-9294","quote":"Las mujeres que se hallan en riesgo o en situación de violencia machista tienen derecho a recibir de inmediato de las administraciones públicas de Cataluña una protección integral, real y efectiva. […] Las garantías de protección deben asegurarse tanto por medios tecnológicos como por servicios policiales, así como por cualquier otro medio que asegure la protección de las mujeres."}]},{"text":"La Policia de la Generalitat-Mossos d''Esquadra ha de vigilar i controlar el compliment exacte de les mesures judicials, i les policies locals de Catalunya han de col·laborar-hi en el marc de cooperació establert (art. 31.1 LVM). Les administracions han de garantir que els cossos policials prestin una atenció específica en protecció i tinguin formació bàsica en violència masclista i formació específica i permanent en prevenció, assistència i protecció (art. 31.2 i 31.3 LVM).","refs":[{"ref":"Art. 31.1 LVM","law":"Llei 5/2008","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2008-9294","quote":"La Policía de la Generalidad –Mossos d’Esquadra– debe vigilar y controlar el cumplimiento exacto de las medidas acordadas por los órganos judiciales. En el marco de cooperación establecido con las fuerzas y cuerpos de seguridad, las policías locales de Cataluña deben colaborar para asegurar el cumplimiento de las medidas acordadas por los órganos judiciales."},{"ref":"Art. 31.3 LVM","law":"Llei 5/2008","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2008-9294","quote":"Las administraciones públicas de Cataluña deben garantizar que los cuerpos policiales dispongan de la adecuada formación básica en materia de violencia machista y de la formación y capacitación específicas y permanentes en materia de prevención, asistencia y protección de las mujeres que sufren violencias."}]},{"text":"La valoració del risc la fan els Mossos d''Esquadra de manera individualitzada i adaptada al tipus de violència, i ha d''incloure el risc per als fills i filles (art. 31.5 LVM). Quan una dona va a una comissaria a denunciar, els agents dels Mossos o de les policies locals han de demanar al col·legi d''advocats la presència d''un lletrat des del moment inicial de la denúncia (art. 31.6 LVM).","refs":[{"ref":"Art. 31.5 LVM","law":"Llei 5/2008","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2008-9294","quote":"La evaluación de riesgo por parte de la Policía de la Generalidad-Mossos d’Esquadra debe ser individualizada y adaptada al tipo de violencia concreta. […] La evaluación de riesgo debe incluir el riesgo sufrido por los hijos e hijas de la mujer."},{"ref":"Art. 31.6 LVM","law":"Llei 5/2008","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2008-9294","quote":"los agentes de la Policía de la Generalidad-Mossos d’Esquadra o de las policías locales de Cataluña deben requerir al colegio de abogados la presencia de un letrado para garantizar la asistencia letrada desde el momento inicial de la denuncia."}]}]},{"n":"9","title":"L''ordre de protecció: pressupostos, legitimació i sol·licitud (art. 544 ter.1-3 LECrim)","blocks":[{"text":"L''ordre de protecció es va introduir a la LECrim amb la Llei 27/2003, de 31 de juliol. La dicta el jutge d''instrucció per a les víctimes de violència domèstica quan hi ha indicis fundats d''un delicte contra la vida, la integritat física o moral, la llibertat sexual, la llibertat o la seguretat d''alguna de les persones de l''article 173.2 CP i en resulta una situació objectiva de risc per a la víctima (art. 544 ter.1 LECrim).","refs":[{"ref":"Nota del BOE a l''art. 544 ter LECrim","law":"LECrim","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036","quote":"Se añade por el art. 2 de la Ley 27/2003, de 31 de julio."},{"ref":"Art. 544 ter.1 LECrim","law":"LECrim","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036","quote":"El Juez de Instrucción dictará orden de protección para las víctimas de violencia doméstica en los casos en que, existiendo indicios fundados de la comisión de un delito o falta contra la vida, integridad física o moral, libertad sexual, libertad o seguridad de alguna de las personas mencionadas en el artículo 173.2 del Código Penal, resulte una situación objetiva de riesgo para la víctima"}]},{"text":"L''ordre s''acorda d''ofici pel jutge o a instància de la víctima, d''una persona amb alguna de les relacions de l''apartat 1 o del Ministeri Fiscal (art. 544 ter.2 LECrim). Es pot sol·licitar davant l''autoritat judicial o el Ministeri Fiscal, o bé davant les forces i cossos de seguretat, les oficines d''atenció a la víctima o els serveis socials o institucions assistencials públiques; la sol·licitud s''ha de remetre de forma immediata al jutge competent (art. 544 ter.3 LECrim). Per tant, si la víctima la demana a la policia local, aquesta l''ha de fer arribar de seguida al jutjat.","refs":[{"ref":"Art. 544 ter.2 LECrim","law":"LECrim","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036","quote":"La orden de protección será acordada por el juez de oficio o a instancia de la víctima o persona que tenga con ella alguna de las relaciones indicadas en el apartado anterior, o del Ministerio Fiscal."},{"ref":"Art. 544 ter.3 LECrim","law":"LECrim","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036","quote":"La orden de protección podrá solicitarse directamente ante la autoridad judicial o el Ministerio Fiscal, o bien ante las Fuerzas y Cuerpos de Seguridad, las oficinas de atención a la víctima o los servicios sociales o instituciones asistenciales dependientes de las Administraciones públicas. Dicha solicitud habrá de ser remitida de forma inmediata al juez competente."}]}]},{"n":"10","title":"L''ordre de protecció: audiència, contingut i efectes (art. 544 ter.4-10 LECrim)","blocks":[{"text":"Rebuda la sol·licitud, el jutge de guàrdia convoca una audiència urgent amb la víctima, el sol·licitant, el presumpte agressor i el Ministeri Fiscal, que s''ha de fer en un màxim de setanta-dues hores des de la sol·licitud. Durant l''audiència, el jutge ha d''evitar la confrontació entre el presumpte agressor i la víctima, els fills i la resta de la família, i disposa que les declaracions es facin per separat (art. 544 ter.4 LECrim).","refs":[{"ref":"Art. 544 ter.4 LECrim","law":"LECrim","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036","quote":"En cualquier caso la audiencia habrá de celebrarse en un plazo máximo de setenta y dos horas desde la presentación de la solicitud. Durante la audiencia, el Juez de guardia adoptará las medidas oportunas para evitar la confrontación entre el presunto agresor y la víctima, sus hijos y los restantes miembros de la familia. A estos efectos dispondrá que su declaración en esta audiencia se realice por separado."}]},{"text":"L''ordre confereix a la víctima un estatut integral de protecció que comprèn mesures cautelars d''ordre civil i penal i altres mesures d''assistència i protecció social, i es pot fer valer davant qualsevol autoritat i Administració pública (art. 544 ter.5 LECrim). Les mesures civils tenen una vigència de trenta dies, llevat que s''iniciï un procés de família (art. 544 ter.7 LECrim). L''ordre s''inscriu al Registre Central per a la Protecció de les Víctimes de la Violència Domèstica i de Gènere (art. 544 ter.10 LECrim).","refs":[{"ref":"Art. 544 ter.5 LECrim","law":"LECrim","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036","quote":"La orden de protección confiere a la víctima de los hechos mencionados en el apartado 1 un estatuto integral de protección que comprenderá las medidas cautelares de orden civil y penal contempladas en este artículo y aquellas otras medidas de asistencia y protección social establecidas en el ordenamiento jurídico. La orden de protección podrá hacerse valer ante cualquier autoridad y Administración pública."},{"ref":"Art. 544 ter.7 LECrim","law":"LECrim","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036","quote":"Las medidas de carácter civil contenidas en la orden de protección tendrán una vigencia temporal de treinta días."},{"ref":"Art. 544 ter.10 LECrim","law":"LECrim","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036","quote":"La orden de protección será inscrita en el Registro Central para la Protección de las Víctimas de la Violencia Doméstica y de Género."}]}]},{"n":"11","title":"Maltractament en l''àmbit familiar i violència habitual (arts. 153 i 173.2 CP)","blocks":[{"text":"L''article 153.1 CP castiga qui causa un menyscapte psíquic o una lesió de menor gravetat, o colpeja o maltracta d''obra sense causar lesió, quan l''ofesa és o ha estat la seva esposa o dona lligada a ell per una relació anàloga d''afectivitat, fins i tot sense convivència, o una persona especialment vulnerable que hi conviu. La pena és presó de sis mesos a un any o treballs en benefici de la comunitat de trenta-un a vuitanta dies i, en tot cas, privació del dret a la tinença i el port d''armes d''un any i un dia a tres anys.","refs":[{"ref":"Art. 153.1 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"o golpeare o maltratare de obra a otro sin causarle lesión, cuando la ofendida sea o haya sido esposa, o mujer que esté o haya estado ligada a él por una análoga relación de afectividad aun sin convivencia, o persona especialmente vulnerable que conviva con el autor, será castigado con la pena de prisión de seis meses a un año o de trabajos en beneficios de la comunidad de treinta y uno a ochenta días y, en todo caso, privación del derecho a la tenencia y porte de armas de un año y un día a tres años"}]},{"text":"Si la víctima és una altra de les persones de l''article 173.2 CP, la presó és de tres mesos a un any (art. 153.2 CP). Les penes s''imposen en la meitat superior quan el fet es comet davant de menors, amb armes, al domicili comú o al de la víctima, o trencant una pena o mesura d''allunyament (art. 153.3 CP). Qui exerceix habitualment violència física o psíquica sobre la parella o exparella o sobre altres familiars i convivents comet el delicte de l''article 173.2 CP, castigat amb presó de sis mesos a tres anys.","refs":[{"ref":"Art. 153.3 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"Las penas previstas en los apartados 1 y 2 se impondrán en su mitad superior cuando el delito se perpetre en presencia de menores, o utilizando armas, o tenga lugar en el domicilio común o en el domicilio de la víctima, o se realice quebrantando una pena de las contempladas en el artículo 48 de este Código o una medida cautelar o de seguridad de la misma naturaleza."},{"ref":"Art. 173.2 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"El que habitualmente ejerza violencia física o psíquica sobre quien sea o haya sido su cónyuge o sobre persona que esté o haya estado ligada a él por una análoga relación de afectividad aun sin convivencia […] será castigado con la pena de prisión de seis meses a tres años"}]}]},{"n":"R","title":"Recorda per a l''examen","blocks":[{"text":"LOVG: violència sobre la dona per part de la parella o exparella, fins i tot sense convivència (art. 1.1).","refs":[{"ref":"Art. 1.1 LOVG","law":"LO 1/2004","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2004-21760","quote":"aun sin convivencia."}]},{"text":"El Govern crea unitats especialitzades a les FCSE; les policies locals cooperen a fer complir les mesures judicials (art. 31 LOVG).","refs":[{"ref":"Art. 31.2 LOVG","law":"LO 1/2004","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2004-21760","quote":"cooperen en asegurar el cumplimiento de las medidas acordadas por los órganos judiciales"}]},{"text":"Llei 5/2008: la violència masclista es pot produir tant en l''àmbit públic com en el privat (art. 3.a).","refs":[{"ref":"Art. 3.a LVM","law":"Llei 5/2008","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2008-9294","quote":"tanto si se produce en el ámbito público como en el privado."}]},{"text":"Àmbit familiar: inclou els matrimonis forçats i exclou la violència de parella (art. 5 LVM).","refs":[{"ref":"Art. 5 LVM","law":"Llei 5/2008","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2008-9294","quote":"Incluye los matrimonios forzados. No incluye la violencia ejercida en el ámbito de la pareja."}]},{"text":"Els Mossos vigilen el compliment de les mesures judicials; les policies locals hi col·laboren (art. 31.1 LVM).","refs":[{"ref":"Art. 31.1 LVM","law":"Llei 5/2008","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2008-9294","quote":"las policías locales de Cataluña deben colaborar para asegurar el cumplimiento de las medidas acordadas por los órganos judiciales."}]},{"text":"L''ordre de protecció la dicta el jutge d''instrucció; la policia remet la sol·licitud de forma immediata al jutge (art. 544 ter.1 i 3 LECrim).","refs":[{"ref":"Art. 544 ter.3 LECrim","law":"LECrim","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036","quote":"Dicha solicitud habrá de ser remitida de forma inmediata al juez competente."}]},{"text":"Audiència urgent en un màxim de setanta-dues hores, amb declaracions per separat (art. 544 ter.4 LECrim).","refs":[{"ref":"Art. 544 ter.4 LECrim","law":"LECrim","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036","quote":"A estos efectos dispondrá que su declaración en esta audiencia se realice por separado."}]},{"text":"Maltractament d''obra sense lesió a la parella o exparella dona: presó de sis mesos a un any o treballs en benefici de la comunitat, i sempre privació d''armes (art. 153.1 CP).","refs":[{"ref":"Art. 153.1 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"será castigado con la pena de prisión de seis meses a un año"}]}]}]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2004-21760'), 'https://www.boe.es/buscar/act.php?id=BOE-A-2004-21760', null, null, null, 'Otras normas citadas: Llei 5/2008 (https://www.boe.es/buscar/act.php?id=BOE-A-2008-9294), LECrim (https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036), Codi penal (https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444)'
  from public.topics t where t.slug = 'plcat-t19-violencia-masclista'
on conflict (topic_id, locale) do update
   set outline = excluded.outline, key_ideas = excluded.key_ideas, glossary = excluded.glossary,
       amendments = excluded.amendments, lessons = excluded.lessons, source_id = excluded.source_id, source_url = excluded.source_url,
       page_from = excluded.page_from, page_to = excluded.page_to, key_ideas_page = excluded.key_ideas_page
 where (n.outline, n.key_ideas, n.glossary, n.amendments, n.lessons)
       is distinct from (excluded.outline, excluded.key_ideas, excluded.glossary, excluded.amendments, excluded.lessons);
insert into public.sources (title, url, kind, publisher, published_on) values ('Real Decreto Legislativo 6/2015, de 30 de octubre, texto refundido de la Ley sobre Tráfico, Circulación de Vehículos a Motor y Seguridad Vial (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11722', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('plcat-t20-transit-seguretat-viaria', 'Tema 20. Trànsit i seguretat viària: text refós de la Llei de trànsit, Reglament general de circulació i Reglament general de conductors') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('policia-local') and t.slug = 'plcat-t20-transit-seguretat-viaria' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, lessons, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"Competències dels municipis en trànsit (art. 7 LTSV)"},{"n":"2","title":"Normes de comportament i alcohol (art. 14 LTSV)"},{"n":"3","title":"Infraccions (art. 65 LTSV)"},{"n":"4","title":"Sancions i procediment (arts. 80 i 82 LTSV)"},{"n":"5","title":"Immobilització i retirada de vehicles (arts. 104-106 LTSV)"},{"n":"6","title":"Taxes d''alcohol i proves (RGC arts. 20 i 21)"},{"n":"7","title":"Velocitat (RGC art. 50)"},{"n":"8","title":"Agents de circulació i senyals (RGC art. 133)"}]'::jsonb, '["Art. 7 RDL 6/2015: «a) La regulación, ordenación, gestión, vigilancia y disciplina, por medio de agentes propios, del tráfico en las vías urbanas de su titularidad»","Art. 7.b RDL 6/2015: «b) La regulación mediante ordenanza municipal de circulación, de los usos de las vías urbanas»","Art. 14 RDL 6/2015: «En ningún caso el conductor menor de edad podrá circular por las vías con una tasa de alcohol en sangre superior a 0 gramos por litro o de alcohol en aire espirado superior a 0 miligramos por litro.»","Art. 20 Reglament general de circulació: «con una tasa de alcohol en sangre superior a 0,5 gramos por litro, o de alcohol en aire espirado superior a 0,25 miligramos por litro.»","Art. 20 Reglament general de circulació: «Los conductores de cualquier vehículo no podrán superar la tasa de alcohol en sangre de 0,3 gramos por litro ni de alcohol en aire espirado de 0,15 miligramos por litro durante los dos años siguientes a la obtención del permiso o licencia que les habilita para conducir.»","Art. 21 Reglament general de circulació: «a) A cualquier usuario de la vía o conductor de vehículo implicado directamente como posible responsable en un accidente de circulación.»","Art. 50 Reglament general de circulació: «b) 30 km/h en vías de un único carril por sentido de circulación.»","Art. 50.3 Reglament general de circulació: «3. Excepcionalmente, la Autoridad Municipal podrá aumentar la velocidad en vías de un único carril por sentido hasta una velocidad máxima de 50 km/h, previa señalización específica.»","Art. 133 Reglament general de circulació: «a) Señales y órdenes de los agentes de la autoridad encargados de la vigilancia del tráfico en el ejercicio de las funciones que tengan encomendadas.»","Art. 133.2 Reglament general de circulació: «prevalecerá la preferente, según el orden a que se refiere el apartado anterior, o la más restrictiva, si se trata de señales del mismo tipo.»","Art. 65 RDL 6/2015: «1. Transcurridos dos años sin haber sido sancionados en firme en vía administrativa por la comisión de infracciones que lleven aparejada la pérdida de puntos»","Art. 80 RDL 6/2015: «1. Las infracciones leves serán sancionadas con multa de hasta 100 euros; las graves, con multa de 200 euros, y las muy graves, con multa de 500 euros.»","Art. 82 RDL 6/2015: «responderán solidariamente con él de la multa impuesta sus padres, tutores, acogedores y guardadores legales o de hecho, por este orden»","Art. 104 RDL 6/2015: «e) El vehículo carezca de seguro obligatorio.»","Art. 105 RDL 6/2015: «a) Siempre que constituya peligro, cause graves perturbaciones a la circulación de vehículos o peatones o deteriore algún servicio o patrimonio público.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[{"n":"1","title":"Àmbit de la Llei de trànsit i competències dels municipis","blocks":[{"text":"El text refós de la Llei sobre trànsit, circulació de vehicles de motor i seguretat viària (TRLTSV, aprovat pel Reial decret legislatiu 6/2015) s''aplica a tot el territori de l''Estat. Obliga els titulars i els usuaris de les vies i terrenys públics aptes per circular, tant urbans com interurbans, els de les vies i terrenys que, sense tenir aquesta aptitud, són d''ús comú i, a falta d''altres normes, els titulars de vies i terrenys privats utilitzats per una col·lectivitat indeterminada d''usuaris (art. 2 TRLTSV).","refs":[{"ref":"Art. 2 TRLTSV","law":"RDL 6/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11722","quote":"Los preceptos de esta ley son aplicables en todo el territorio nacional y obligan a los titulares y usuarios de las vías y terrenos públicos aptos para la circulación, tanto urbanos como interurbanos, a los de las vías y terrenos que, sin tener tal aptitud, sean de uso común y, en defecto de otras normas, a los titulares de las vías y terrenos privados que sean utilizados por una colectividad indeterminada de usuarios."}]},{"text":"L''article 7 TRLTSV és el fonament de la policia local en matèria de trànsit. Correspon als municipis la regulació, l''ordenació, la gestió, la vigilància i la disciplina, per mitjà d''agents propis, del trànsit a les vies urbanes de la seva titularitat, i també la denúncia de les infraccions que s''hi cometin i la seva sanció quan no estigui atribuïda expressament a una altra administració (art. 7.a). Per ordenança municipal de circulació poden regular els usos de les vies urbanes, fer compatible una distribució equitativa dels aparcaments amb la fluïdesa del trànsit i l''ús dels vianants, i establir estacionament limitat per garantir la rotació, amb una atenció especial a les persones amb discapacitat i mobilitat reduïda (art. 7.b).","refs":[{"ref":"Art. 7.a TRLTSV","law":"RDL 6/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11722","quote":"a) La regulación, ordenación, gestión, vigilancia y disciplina, por medio de agentes propios, del tráfico en las vías urbanas de su titularidad, así como la denuncia de las infracciones que se cometan en dichas vías y la sanción de las mismas cuando no esté expresamente atribuida a otra Administración."},{"ref":"Art. 7.b TRLTSV","law":"RDL 6/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11722","quote":"b) La regulación mediante ordenanza municipal de circulación, de los usos de las vías urbanas, haciendo compatible la equitativa distribución de los aparcamientos entre todos los usuarios con la necesaria fluidez del tráfico rodado y con el uso peatonal de las calles, así como el establecimiento de medidas de estacionamiento limitado, con el fin de garantizar la rotación de los aparcamientos"}]},{"text":"Els municipis també poden immobilitzar vehicles en zones d''estacionament limitat quan no tenen títol o n''excedeixen l''autorització, fins que s''identifica el conductor, i retirar i dipositar els que obstaculitzen, dificulten o posen en perill la circulació. Les bicicletes només es poden retirar si estan abandonades o si, lligades, dificulten la circulació o danyen el mobiliari urbà. A més, autoritzen les proves esportives que transcorren només pel nucli urbà (excepte travesseres), tanquen vies urbanes quan cal i poden restringir-hi la circulació per motius mediambientals (art. 7.c a g).","refs":[{"ref":"Art. 7.c TRLTSV","law":"RDL 6/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11722","quote":"Las bicicletas sólo podrán ser retiradas y llevadas al correspondiente depósito si están abandonadas o si, estando amarradas, dificultan la circulación de vehículos o personas o dañan el mobiliario urbano."},{"ref":"Art. 7.d a g TRLTSV","law":"RDL 6/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11722","quote":"d) La autorización de pruebas deportivas cuando discurran íntegra y exclusivamente por el casco urbano, exceptuadas las travesías. […] f) El cierre de vías urbanas cuando sea necesario. g) La restricción de la circulación a determinados vehículos en vías urbanas por motivos medioambientales."}]}]},{"n":"2","title":"Normes de comportament: alcohol i drogues (art. 14 TRLTSV)","blocks":[{"text":"No pot circular cap conductor amb taxes d''alcohol superiors a les que fixa el reglament. El conductor menor d''edat té taxa zero: en cap cas no pot circular amb una taxa d''alcohol en sang superior a 0 g/l ni en aire espirat superior a 0 mg/l. Tampoc no pot circular cap conductor amb presència de drogues a l''organisme, excepte les substàncies preses amb prescripció facultativa i finalitat terapèutica, sempre que estigui en condicions d''utilitzar el vehicle amb diligència (art. 14.1 TRLTSV).","refs":[{"ref":"Art. 14.1 TRLTSV","law":"RDL 6/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11722","quote":"En ningún caso el conductor menor de edad podrá circular por las vías con una tasa de alcohol en sangre superior a 0 gramos por litro o de alcohol en aire espirado superior a 0 miligramos por litro."},{"ref":"Art. 14.1 TRLTSV","law":"RDL 6/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11722","quote":"Tampoco puede hacerlo el conductor de cualquier vehículo con presencia de drogas en el organismo, de las que se excluyen aquellas sustancias que se utilicen bajo prescripción facultativa y con una finalidad terapéutica"}]},{"text":"El conductor està obligat a sotmetre''s a les proves de detecció d''alcohol o de drogues que practiquen els agents encarregats de la vigilància del trànsit; també hi estan obligats els altres usuaris de la via implicats en un accident o que hagin comès una infracció (art. 14.2). La prova d''alcohol consisteix a verificar l''aire espirat amb dispositius autoritzats; la de drogues, en una prova salival i una anàlisi posterior d''una mostra salival suficient. Si hi ha raons justificades que impedeixen fer-les, es pot ordenar un reconeixement mèdic o anàlisis clíniques (art. 14.3). A petició de l''interessat, les proves es poden repetir per contrast, preferentment amb anàlisi de sang, i si el contrast dona positiu el paga l''interessat (art. 14.5).","refs":[{"ref":"Art. 14.2 TRLTSV","law":"RDL 6/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11722","quote":"El conductor de un vehículo está obligado a someterse a las pruebas para la detección de alcohol o de la presencia de drogas en el organismo, que se practicarán por los agentes de la autoridad encargados de la vigilancia del tráfico"},{"ref":"Art. 14.3 i 14.5 TRLTSV","law":"RDL 6/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11722","quote":"Las pruebas para la detección de alcohol consistirán en la verificación del aire espirado mediante dispositivos autorizados, y para la detección de la presencia de drogas en el organismo, en una prueba salival mediante un dispositivo autorizado y en un posterior análisis de una muestra salival en cantidad suficiente. […] Cuando la prueba de contraste arroje un resultado positivo será abonada por el interesado."}]}]},{"n":"3","title":"Taxes d''alcohol (art. 20 RGC)","blocks":[{"text":"El Reglament general de circulació (RGC, Reial decret 1428/2003) fixa la taxa general: ni els conductors de vehicles ni els de bicicletes no poden circular amb més de 0,5 g/l d''alcohol en sang o 0,25 mg/l en aire espirat (art. 20 RGC).","refs":[{"ref":"Art. 20 RGC","law":"Reglament general de circulació","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-23514","quote":"No podrán circular por las vías objeto de la legislación sobre tráfico, circulación de vehículos a motor y seguridad vial los conductores de vehículos ni los conductores de bicicletas con una tasa de alcohol en sangre superior a 0,5 gramos por litro, o de alcohol en aire espirado superior a 0,25 miligramos por litro."}]},{"text":"Hi ha una taxa reduïda de 0,3 g/l en sang o 0,15 mg/l en aire espirat per a dos grups. El primer és professional: conductors de vehicles de mercaderies de més de 3.500 kg de massa màxima autoritzada, de viatgers de més de nou places, de servei públic, de transport escolar i de menors, de mercaderies perilloses, de servei d''urgència o de transports especials, sigui quina sigui l''antiguitat del permís. El segon són els conductors novells: qualsevol conductor durant els dos anys següents a l''obtenció del permís o la llicència. Per a la llicència, només compta l''antiguitat quan es condueixen vehicles per als quals n''hi ha prou amb la llicència (art. 20 RGC).","refs":[{"ref":"Art. 20 RGC","law":"Reglament general de circulació","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-23514","quote":"Cuando se trate de vehículos destinados al transporte de mercancías con una masa máxima autorizada superior a 3.500 kilogramos, vehículos destinados al transporte de viajeros de más de nueve plazas, o de servicio público, al transporte escolar y de menores, al de mercancías peligrosas o de servicio de urgencia o transportes especiales, los conductores no podrán hacerlo con una tasa de alcohol en sangre superior a 0,3 gramos por litro, o de alcohol en aire espirado superior a 0,15 miligramos por litro."},{"ref":"Art. 20 RGC","law":"Reglament general de circulació","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-23514","quote":"Los conductores de cualquier vehículo no podrán superar la tasa de alcohol en sangre de 0,3 gramos por litro ni de alcohol en aire espirado de 0,15 miligramos por litro durante los dos años siguientes a la obtención del permiso o licencia que les habilita para conducir."}]}]},{"n":"4","title":"Proves d''alcoholèmia: persones obligades i pràctica (arts. 21-23 RGC)","blocks":[{"text":"Tots els conductors de vehicles i de bicicletes estan obligats a sotmetre''s a les proves, i també els altres usuaris de la via implicats en un accident de circulació. Els agents poden sotmetre a les proves: a) qualsevol usuari o conductor implicat directament com a possible responsable en un accident; b) qui condueixi amb símptomes evidents, manifestacions o fets que facin presumir raonablement que ho fa sota la influència de begudes alcohòliques; c) els conductors denunciats per alguna infracció del reglament; i d) els requerits dins dels programes de controls preventius ordenats per l''autoritat (art. 21 RGC). Un vianant no implicat en cap accident no hi entra.","refs":[{"ref":"Art. 21 RGC","law":"Reglament general de circulació","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-23514","quote":"Todos los conductores de vehículos y de bicicletas quedan obligados a someterse a las pruebas que se establezcan para la detección de las posibles intoxicaciones por alcohol. Igualmente quedan obligados los demás usuarios de la vía cuando se hallen implicados en algún accidente de circulación"},{"ref":"Art. 21 RGC","law":"Reglament general de circulació","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-23514","quote":"a) A cualquier usuario de la vía o conductor de vehículo implicado directamente como posible responsable en un accidente de circulación. b) A quienes conduzcan cualquier vehículo con síntomas evidentes, manifestaciones que denoten o hechos que permitan razonablemente presumir que lo hacen bajo la influencia de bebidas alcohólicas. c) A los conductores que sean denunciados por la comisión de alguna de las infracciones a las normas contenidas en este reglamento. d) A los que, con ocasión de conducir un vehículo, sean requeridos al efecto por la autoridad o sus agentes dentro de los programas de controles preventivos de alcoholemia ordenados por dicha autoridad."}]},{"text":"La prova consisteix normalment a verificar l''aire espirat amb etilòmetres oficialment autoritzats (art. 22.1 RGC). Si el resultat supera la taxa aplicable o, sense superar-la, la persona presenta símptomes evidents, l''agent fa una segona prova de contrast amb un procediment similar, després d''informar-ne l''interessat; entre la primera i la segona hi ha d''haver un temps mínim de 10 minuts, que l''interessat pot controlar (art. 23.1 i 23.2 RGC). També té dret a formular al·legacions i a contrastar el resultat amb anàlisis de sang, orina o similars; l''import s''ha de dipositar prèviament i el paga l''interessat si el resultat és positiu (art. 23.3 i 23.4 RGC).","refs":[{"ref":"Art. 22.1 RGC","law":"Reglament general de circulació","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-23514","quote":"consistirán, normalmente, en la verificación del aire espirado mediante etilómetros que, oficialmente autorizados, determinarán de forma cuantitativa el grado de impregnación alcohólica de los interesados."},{"ref":"Art. 23.2 RGC","law":"Reglament general de circulació","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-23514","quote":"De la misma forma advertirá a la persona sometida a examen del derecho que tiene a controlar, por sí o por cualquiera de sus acompañantes o testigos presentes, que entre la realización de la primera y de la segunda prueba medie un tiempo mínimo de 10 minutos."},{"ref":"Art. 23.4 RGC","law":"Reglament general de circulació","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-23514","quote":"El importe de dichos análisis deberá ser previamente depositado por el interesado y con él se atenderá al pago cuando el resultado de la prueba de contraste sea positivo"}]}]},{"n":"5","title":"Velocitat en vies urbanes i travesseres (art. 50 RGC)","blocks":[{"text":"Des de la reforma del Reial decret 970/2020 (en vigor l''11 de maig de 2021), el límit genèric en vies urbanes depèn del nombre de carrils: 20 km/h en vies de plataforma única de calçada i vorera; 30 km/h en vies d''un únic carril per sentit; i 50 km/h en vies de dos o més carrils per sentit. Els carrils reservats a determinats usuaris o al transport públic no es compten (art. 50.1 RGC).","refs":[{"ref":"Art. 50.1 RGC","law":"Reglament general de circulació","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-23514","quote":"a) 20 km/h en vías que dispongan de plataforma única de calzada y acera. b) 30 km/h en vías de un único carril por sentido de circulación. c) 50 km/h en vías de dos o más carriles por sentido de circulación."},{"ref":"Art. 50.1 RGC","law":"Reglament general de circulació","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-23514","quote":"A estos efectos, los carriles reservados para la circulación de determinados usuarios o uso exclusivo de transporte público no serán contabilizados."}]},{"text":"L''autoritat municipal pot rebaixar aquests límits amb senyalització específica prèvia (art. 50.2) i, excepcionalment, augmentar fins a 50 km/h com a màxim la velocitat de les vies d''un únic carril per sentit, també amb senyalització específica (art. 50.3). Els vehicles de mercaderies perilloses circulen com a màxim a 40 km/h en vies de dos o més carrils i en travesseres (art. 50.4). A les travesseres el límit genèric és de 50 km/h per a tots els vehicles (art. 50.5). Les infraccions d''aquest article són greus o, segons l''excés, molt greus (art. 50.8).","refs":[{"ref":"Art. 50.2 i 50.3 RGC","law":"Reglament general de circulació","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-23514","quote":"2. Las velocidades genéricas establecidas podrán ser rebajadas previa señalización específica, por la Autoridad municipal. 3. Excepcionalmente, la Autoridad Municipal podrá aumentar la velocidad en vías de un único carril por sentido hasta una velocidad máxima de 50 km/h, previa señalización específica."},{"ref":"Art. 50.4 i 50.5 RGC","law":"Reglament general de circulació","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-23514","quote":"los vehículos que transporten mercancías peligrosas circularán como máximo a 40 km/h. 5. El límite genérico de velocidad en travesías es de 50 km/h para todo tipo de vehículos."}]}]},{"n":"6","title":"Senyals i ordres dels agents: ordre de preferència (art. 133 RGC)","blocks":[{"text":"L''article 133.1 RGC estableix l''ordre de preferència entre senyals: a) primer, els senyals i les ordres dels agents de l''autoritat encarregats de la vigilància del trànsit; b) després, la senyalització i l''abalisament circumstancial que modifica el règim normal d''ús de la via, els dispositius delimitadors i els senyals d''abalisament; c) els semàfors; d) els senyals verticals; i e) les marques vials. Per això l''ordre d''un agent preval fins i tot sobre un semàfor.","refs":[{"ref":"Art. 133.1 RGC","law":"Reglament general de circulació","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-23514","quote":"a) Señales y órdenes de los agentes de la autoridad encargados de la vigilancia del tráfico en el ejercicio de las funciones que tengan encomendadas. b) Señalización y balizamiento circunstancial que modifique el régimen normal de utilización de la vía, dispositivos delimitadores y señales de balizamiento. c) Semáforos. d) Señales verticales de circulación. e) Marcas viales."}]},{"text":"Si diversos senyals semblen contradictoris, preval el preferent segons aquest ordre; i si són del mateix tipus, preval el més restrictiu (art. 133.2 RGC). No respectar els senyals o les ordres de l''autoritat o dels seus agents és una infracció greu (art. 76.j TRLTSV).","refs":[{"ref":"Art. 133.2 RGC","law":"Reglament general de circulació","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-23514","quote":"prevalecerá la preferente, según el orden a que se refiere el apartado anterior, o la más restrictiva, si se trata de señales del mismo tipo."},{"ref":"Art. 76.j TRLTSV","law":"RDL 6/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11722","quote":"j) No respetar las señales o las órdenes de la autoridad encargada de la regulación, ordenación, gestión, vigilancia y disciplina del tráfico, o de sus agentes."}]}]},{"n":"7","title":"Permís de conducció i permís per punts","blocks":[{"text":"Per conduir vehicles de motor i ciclomotors cal haver obtingut abans el permís o la llicència de conducció, que són d''atorgament i contingut reglats i depenen de la verificació de l''aptitud psicofísica i dels coneixements i les habilitats del conductor (art. 1 del Reglament general de conductors, RGCond). Ningú no pot ser titular de més d''un permís expedit per un estat de la Unió Europea o de l''Espai Econòmic Europeu (art. 1.4 RGCond). Atenció: l''article 1 RGCond encara remet a l''antic text articulat (RDL 339/1990), avui substituït pel TRLTSV de 2015.","refs":[{"ref":"Art. 1.1 i 1.2 RGCond","law":"Reglament general de conductors","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2009-9481","quote":"exigirá haber obtenido previamente el permiso o la licencia de conducción […] Los permisos y licencias de conducción son de otorgamiento y contenido reglados"},{"ref":"Art. 1.4 RGCond","law":"Reglament general de conductors","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2009-9481","quote":"Ninguna persona podrá ser titular de más de un permiso o de una licencia de conducción expedido por un Estado miembro de la Unión Europea o por un Estado parte del Acuerdo sobre el Espacio Económico Europeo."}]},{"text":"Les edats mínimes més preguntades (art. 4.2 RGCond) són: AM (ciclomotors i quadricicles lleugers), 15 anys; A1 (motocicletes fins a 125 cm3 i 11 kW), 16 anys; A2 i B, 18 anys; A, 20 anys; C i D1, 21 anys; i D, 24 anys, amb excepcions per als titulars del certificat d''aptitud professional (CAP).","refs":[{"ref":"Art. 4.2 RGCond","law":"Reglament general de conductors","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2009-9481","quote":"AM | 1. Ciclomotores de dos o tres ruedas y cuatriciclos ligeros."},{"ref":"Art. 4.2 RGCond","law":"Reglament general de conductors","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2009-9481","quote":"A | Motocicletas y triciclos de motor. | 20 |"}]},{"text":"Pel que fa als punts, el titular d''un permís rep un crèdit inicial de dotze punts, però en té vuit si té una antiguitat no superior a tres anys o si recupera el permís després d''haver-los perdut tots (art. 63 TRLTSV). Qui passa dos anys sense ser sancionat en ferm en via administrativa per infraccions que comporten pèrdua de punts recupera la totalitat dels dotze punts (art. 65.1). També es poden recuperar fins a sis punts, una vegada cada dos anys, amb un curs de sensibilització i reeducació viària (art. 65.4).","refs":[{"ref":"Art. 63.1 TRLTSV","law":"RDL 6/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11722","quote":"Al titular de un permiso o licencia de conducción se le asignará un crédito inicial de doce puntos."},{"ref":"Art. 65.1 TRLTSV","law":"RDL 6/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11722","quote":"1. Transcurridos dos años sin haber sido sancionados en firme en vía administrativa por la comisión de infracciones que lleven aparejada la pérdida de puntos, el titular de un permiso o licencia de conducción afectado por la pérdida parcial de puntos recuperará la totalidad del crédito inicial de doce puntos."},{"ref":"Art. 65.4 TRLTSV","law":"RDL 6/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11722","quote":"podrá optar a su recuperación parcial, hasta un máximo de seis puntos, por una sola vez cada dos años, realizando y superando con aprovechamiento un curso de sensibilización y reeducación vial"}]}]},{"n":"8","title":"Infraccions: lleus, greus i molt greus (arts. 74-77 TRLTSV)","blocks":[{"text":"Les accions i omissions contràries a la llei són infraccions administratives i es classifiquen en lleus, greus i molt greus; si poden ser delicte, s''aplica l''article 85 (art. 74). Són lleus, per exemple, circular en bicicleta sense enllumenat reglamentari o sense prendes reflectants, i les infraccions no qualificades expressament com a greus o molt greus (art. 75). Són greus, entre d''altres, saltar-se la llum vermella d''un semàfor, l''estop o el cediu el pas, o fer servir el mòbil subjectant-lo amb la mà (art. 76).","refs":[{"ref":"Art. 74.3 TRLTSV","law":"RDL 6/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11722","quote":"3. Las infracciones se clasifican en leves, graves y muy graves."},{"ref":"Art. 75.a TRLTSV","law":"RDL 6/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11722","quote":"a) Circular en una bicicleta sin hacer uso del alumbrado reglamentario."},{"ref":"Art. 76.k i 76.l TRLTSV","law":"RDL 6/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11722","quote":"k) No respetar la luz roja de un semáforo. l) No respetar la señal de stop o la señal de ceda el paso."}]},{"text":"Són molt greus, entre d''altres, conduir amb taxes d''alcohol superiors a les reglamentàries o amb presència de drogues; negar-se a les proves de detecció; la conducció temerària; circular en sentit contrari; participar en curses no autoritzades; conduir sense el permís corresponent; i no identificar verament el conductor responsable quan el titular és requerit (art. 77).","refs":[{"ref":"Art. 77.c a 77.f TRLTSV","law":"RDL 6/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11722","quote":"c) Conducir con tasas de alcohol superiores a las que reglamentariamente se establezcan, o con presencia en el organismo de drogas. d) Incumplir la obligación de todos los conductores de vehículos, y de los demás usuarios de la vía cuando se hallen implicados en algún accidente de tráfico o hayan cometido una infracción, de someterse a las pruebas que se establezcan para la detección de alcohol o de la presencia de drogas en el organismo. e) Conducción temeraria. f) Circular en sentido contrario al establecido."}]}]},{"n":"9","title":"Sancions, responsables i procediment sancionador","blocks":[{"text":"Amb caràcter general, les infraccions lleus se sancionen amb multa de fins a 100 euros; les greus, amb 200 euros; i les molt greus, amb 500 euros. Els excessos de velocitat segueixen l''annex IV (art. 80.1 TRLTSV). L''alcohol i la negativa a les proves (art. 77.c i d) comporten 1.000 euros; en el cas de l''alcohol, només per a qui ja va ser sancionat l''any anterior per excedir la taxa o per a qui supera el doble de la permesa (art. 80.2.a).","refs":[{"ref":"Art. 80.1 TRLTSV","law":"RDL 6/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11722","quote":"1. Las infracciones leves serán sancionadas con multa de hasta 100 euros; las graves, con multa de 200 euros, y las muy graves, con multa de 500 euros."},{"ref":"Art. 80.2.a TRLTSV","law":"RDL 6/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11722","quote":"a) Las infracciones previstas en el artículo 77. c) y d) serán sancionadas con multa de 1.000 euros. En el supuesto de conducción con tasas de alcohol superiores a las que reglamentariamente se establezcan, esta sanción únicamente se impondrá al conductor que ya hubiera sido sancionado en el año inmediatamente anterior por exceder la tasa de alcohol permitida, así como al que circule con una tasa que supere el doble de la permitida."}]},{"text":"La responsabilitat recau directament en l''autor del fet (art. 82 TRLTSV). Si l''autor és menor de divuit anys, de la multa responen solidàriament amb ell els pares, tutors, acollidors i guardadors legals o de fet, per aquest ordre (art. 82.b).","refs":[{"ref":"Art. 82 TRLTSV","law":"RDL 6/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11722","quote":"La responsabilidad por las infracciones a lo dispuesto en esta ley recaerá directamente en el autor del hecho en que consista la infracción."},{"ref":"Art. 82.b TRLTSV","law":"RDL 6/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11722","quote":"b) Cuando la autoría de los hechos cometidos corresponda a un menor de dieciocho años, responderán solidariamente con él de la multa impuesta sus padres, tutores, acogedores y guardadores legales o de hecho, por este orden"}]},{"text":"La sanció de les infraccions de circulació comeses en vies urbanes correspon a l''alcalde, que la pot delegar; en queden excloses les del títol IV, com les condicions tècniques dels vehicles i l''assegurança obligatòria (art. 84.4). Els agents han de denunciar les infraccions que observin (art. 87.1). Si es paga voluntàriament, en l''acte o dins dels vint dies naturals següents a la notificació, la multa es redueix un 50 per cent i el procediment s''acaba (art. 94).","refs":[{"ref":"Art. 84.4 TRLTSV","law":"RDL 6/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11722","quote":"4. La sanción por infracción a normas de circulación cometidas en vías urbanas corresponderá a los respectivos Alcaldes, los cuales podrán delegar esta competencia de acuerdo con la normativa aplicable."},{"ref":"Art. 87.1 TRLTSV","law":"RDL 6/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11722","quote":"1. Los agentes de la autoridad encargados de la vigilancia del tráfico en el ejercicio de las funciones que tienen encomendadas deberán denunciar las infracciones que observen cuando ejerzan funciones de esa naturaleza."},{"ref":"Art. 94 TRLTSV","law":"RDL 6/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11722","quote":"Una vez realizado el pago voluntario de la multa, ya sea en el acto de entrega de la denuncia o dentro del plazo de veinte días naturales contados desde el día siguiente al de su notificación, concluirá el procedimiento sancionador con las siguientes consecuencias: a) La reducción del 50 por ciento del importe de la sanción."}]}]},{"n":"10","title":"Immobilització, retirada i tractament residual del vehicle (arts. 104-106 TRLTSV)","blocks":[{"text":"Els agents poden immobilitzar el vehicle per presumptes infraccions, entre altres casos, quan no té autorització per circular; presenta deficiències que són un risc especialment greu; el conductor o el passatger no fan servir el casc o els sistemes de retenció infantil obligatoris (mesura que no s''aplica als ciclistes); hi ha negativa a les proves d''alcohol o drogues o donen positiu; o el vehicle no té l''assegurança obligatòria (art. 104.1). La immobilització s''aixeca quan cessa la causa (art. 104.2) i es fa al lloc que indiquen els agents (art. 104.5).","refs":[{"ref":"Art. 104.1 TRLTSV","law":"RDL 6/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11722","quote":"c) El conductor o el pasajero no hagan uso del casco de protección o de los dispositivos de retención infantil, en los casos en que fuera obligatorio. Esta medida no se aplicará a los ciclistas. d) Se produzca la negativa a efectuar las pruebas a que se refiere el artículo 14.2 y 3, o cuando éstas arrojen un resultado positivo. e) El vehículo carezca de seguro obligatorio."},{"ref":"Art. 104.2 TRLTSV","law":"RDL 6/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11722","quote":"2. La inmovilización se levantará en el momento en que cese la causa que la motivó."}]},{"text":"L''autoritat encarregada de la gestió del trànsit pot retirar el vehicle i dipositar-lo, si l''obligat no ho fa, entre d''altres casos: quan constitueix un perill, causa pertorbacions greus a la circulació de vehicles o vianants o deteriora algun servei o patrimoni públic; en cas d''accident que n''impedeixi la marxa; quan està en una plaça reservada a persones amb discapacitat sense distintiu; en zones de càrrega i descàrrega; o quan se supera el triple del temps abonat en zona d''estacionament limitat (art. 105.1). La retirada s''ha de comunicar al titular en el termini de vint-i-quatre hores (art. 105.3).","refs":[{"ref":"Art. 105.1 TRLTSV","law":"RDL 6/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11722","quote":"a) Siempre que constituya peligro, cause graves perturbaciones a la circulación de vehículos o peatones o deteriore algún servicio o patrimonio público. b) En caso de accidente que impida continuar su marcha."},{"ref":"Art. 105.3 TRLTSV","law":"RDL 6/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11722","quote":"3. La Administración deberá comunicar la retirada y depósito del vehículo al titular en el plazo de veinticuatro horas."}]},{"text":"L''Administració pot ordenar el trasllat a un centre autoritzat de tractament per destruir-lo i descontaminar-lo quan fa més de dos mesos que el vehicle està dipositat sense al·legacions del titular; quan fa més d''un mes que està estacionat al mateix lloc i té desperfectes que n''impedeixen el desplaçament o li falten les plaques; o quan, recollit en un recinte privat per avaria o accident, el titular no el retira en dos mesos. Abans, s''ha de requerir el titular perquè el retiri en el termini d''un mes (art. 106.1).","refs":[{"ref":"Art. 106.1 TRLTSV","law":"RDL 6/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11722","quote":"a) Cuando hayan transcurrido más de dos meses desde que el vehículo fuera inmovilizado o retirado de la vía pública y depositado por la Administración y su titular no hubiera formulado alegaciones. b) Cuando permanezca estacionado por un período superior a un mes en el mismo lugar y presente desperfectos que hagan imposible su desplazamiento por sus propios medios o le falten las placas de matrícula."},{"ref":"Art. 106.1 TRLTSV","law":"RDL 6/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11722","quote":"Con anterioridad a la orden de traslado del vehículo, la Administración requerirá al titular del mismo advirtiéndole que, de no proceder a su retirada en el plazo de un mes, se procederá a su traslado al Centro Autorizado de Tratamiento."}]}]},{"n":"R","title":"Recorda per a l''examen","blocks":[{"text":"Taxa d''alcohol general: 0,5 g/l en sang o 0,25 mg/l en aire espirat, també per als ciclistes.","refs":[{"ref":"Art. 20 RGC","law":"Reglament general de circulació","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-23514","quote":"con una tasa de alcohol en sangre superior a 0,5 gramos por litro, o de alcohol en aire espirado superior a 0,25 miligramos por litro."}]},{"text":"Taxa reduïda (0,3 g/l o 0,15 mg/l): professionals (transport escolar, mercaderies perilloses, urgències…) i novells durant dos anys; menors d''edat, taxa zero.","refs":[{"ref":"Art. 20 RGC","law":"Reglament general de circulació","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-23514","quote":"durante los dos años siguientes a la obtención del permiso o licencia que les habilita para conducir."}]},{"text":"Entre la primera i la segona prova d''aire espirat hi ha d''haver un mínim de 10 minuts.","refs":[{"ref":"Art. 23.2 RGC","law":"Reglament general de circulació","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-23514","quote":"medie un tiempo mínimo de 10 minutos."}]},{"text":"Velocitat urbana: 20 km/h (plataforma única), 30 km/h (un carril per sentit), 50 km/h (dos o més carrils); el municipi pot pujar excepcionalment a 50 km/h les vies d''un carril per sentit.","refs":[{"ref":"Art. 50.1 RGC","law":"Reglament general de circulació","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-23514","quote":"b) 30 km/h en vías de un único carril por sentido de circulación."}]},{"text":"Ordre dels senyals: agents, senyalització circumstancial, semàfors, senyals verticals i marques vials; entre senyals del mateix tipus, el més restrictiu.","refs":[{"ref":"Art. 133.2 RGC","law":"Reglament general de circulació","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-23514","quote":"o la más restrictiva, si se trata de señales del mismo tipo."}]},{"text":"Multes: lleus fins a 100 euros, greus 200 euros i molt greus 500 euros; pagament voluntari en vint dies naturals amb un 50 per cent de reducció.","refs":[{"ref":"Art. 80.1 TRLTSV","law":"RDL 6/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11722","quote":"las graves, con multa de 200 euros, y las muy graves, con multa de 500 euros."}]},{"text":"Infractor menor de divuit anys: responen solidàriament pares, tutors, acollidors i guardadors, per aquest ordre.","refs":[{"ref":"Art. 82.b TRLTSV","law":"RDL 6/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11722","quote":"sus padres, tutores, acogedores y guardadores legales o de hecho, por este orden"}]},{"text":"La immobilització per no dur casc o retenció infantil no s''aplica als ciclistes; també s''immobilitza el vehicle sense assegurança obligatòria.","refs":[{"ref":"Art. 104.1.c TRLTSV","law":"RDL 6/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11722","quote":"Esta medida no se aplicará a los ciclistas."}]},{"text":"Recuperació total dels dotze punts: dos anys sense sancions fermes que comportin pèrdua de punts.","refs":[{"ref":"Art. 65.1 TRLTSV","law":"RDL 6/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11722","quote":"recuperará la totalidad del crédito inicial de doce puntos."}]},{"text":"Tractament residual: més d''un mes estacionat al mateix lloc amb desperfectes o sense plaques, o més de dos mesos dipositat sense al·legacions.","refs":[{"ref":"Art. 106.1.b TRLTSV","law":"RDL 6/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11722","quote":"Cuando permanezca estacionado por un período superior a un mes en el mismo lugar"}]}]}]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11722'), 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11722', null, null, null, 'Otras normas citadas: Reglament general de circulació (https://www.boe.es/buscar/act.php?id=BOE-A-2003-23514)'
  from public.topics t where t.slug = 'plcat-t20-transit-seguretat-viaria'
