insert into public.sources (title, url, kind, publisher, published_on) values ('Ley 11/2009, de 6 de julio, de regulación administrativa de los espectáculos públicos y las actividades recreativas (Cataluña) (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-2009-12856', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('plcat-t21-espectacles-publics', 'Tema 21. La Llei 11/2009 d''espectacles públics i activitats recreatives: competències, control i règim sancionador') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('policia-local') and t.slug = 'plcat-t21-espectacles-publics' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, lessons, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"Objecte i àmbit de la Llei 11/2009"},{"n":"2","title":"Competències de la Generalitat i dels ajuntaments"},{"n":"3","title":"Llicències i comunicacions prèvies"},{"n":"4","title":"Control i inspecció: funcions dels agents"},{"n":"5","title":"Mesures provisionals"},{"n":"6","title":"Infraccions, sancions i prescripció"}]'::jsonb, '["Art. 1 Llei 11/2009: «El objeto de la presente ley es establecer el régimen jurídico de los espectáculos públicos, las actividades recreativas, así como los establecimientos y los espacios abiertos al público donde se llevan a cabo dichas actividades, y regular su intervención administrativa.»","Art. 3 Llei 11/2009: «b) Actividades recreativas: actividades musicales que congregan a un público con el objetivo principal de hacerle participar en la actividad o de ofrecerle el consumo de productos o servicios con finalidades de ocio, entretenimiento o diversión.»","Art. 9 Llei 11/2009: «especialmente la relativa a la prohibición de venta y suministro de bebidas alcohólicas»","Art. 10 Llei 11/2009: «El ejercicio del derecho de admisión no puede conllevar, en ningún caso, discriminación por razón de nacimiento, raza, sexo, religión, opinión, discapacidad, orientación sexual, identidad de género o cualquier otra condición»","Art. 13 Llei 11/2009: «a) Aprobar ordenanzas, en el marco establecido por esta ley.»","Art. 24 Llei 11/2009: «Este personal debe asistir a cursos de formación impartidos por un centro debidamente habilitado y superar las pruebas de selección que convoque la dirección general competente en materia de espectáculos públicos y actividades recreativas.»","Art. 44 Llei 11/2009: «Pueden realizar inspecciones los miembros de cuerpos y fuerzas de seguridad u otros servicios de inspección, los cuales, en el ejercicio de sus funciones, tienen el carácter de agentes de la autoridad»","Art. 44.3 Llei 11/2009: «3. Como resultado de la inspección, los agentes actuantes deben extender un acta, en la cual los interesados pueden hacer constar su disconformidad y observaciones.»","Art. 47 Llei 11/2009: «c) Exceder el aforo permitido, si supone un riesgo para la seguridad de las personas.»","Art. 48 Llei 11/2009: «f) Exceder el aforo permitido, si no supone un riesgo para la seguridad de las personas.»","Art. 50 Llei 11/2009: «a) Una multa de 10.001 a 100.000 euros y, en caso de reincidencia en la comisión de faltas muy graves, de hasta 200.000 euros.»","Art. 52 Llei 11/2009: «b) Si los infractores son espectadores o usuarios, una multa de 50 a 150 euros y, en caso de reincidencia en la comisión de faltas leves, de hasta 300 euros.»","Art. 57 Llei 11/2009: «1. Las faltas muy graves prescriben al cabo de tres años; las faltas graves, al cabo de dos años, y las faltas leves, al cabo de seis meses.»","Art. 57.2 Llei 11/2009: «En el caso de infracciones derivadas de una actividad continuada, la fecha inicial del cómputo es la de la finalización de la actividad o el último acto con el que la infracción se consuma.»","Art. 62 Llei 11/2009: «En tal caso, el órgano que acuerda la medida provisional debe comunicarlo a la autoridad judicial dentro de las cuarenta y ocho horas siguientes.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[{"n":"1","title":"Objecte, finalitats i principis de la Llei 11/2009","blocks":[{"text":"La Llei 11/2009, del 6 de juliol, de regulació administrativa dels espectacles públics i les activitats recreatives, té per objecte establir el règim jurídic dels espectacles públics, de les activitats recreatives i dels establiments i espais oberts al públic on es fan, i regular-ne la intervenció administrativa (art. 1). Els textos d''aquests apunts citen la versió consolidada en castellà publicada al BOE.","refs":[{"ref":"Art. 1 Llei 11/2009","law":"Llei 11/2009","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2009-12856","quote":"El objeto de la presente ley es establecer el régimen jurídico de los espectáculos públicos, las actividades recreativas, así como los establecimientos y los espacios abiertos al público donde se llevan a cabo dichas actividades, y regular su intervención administrativa."}]},{"text":"La Generalitat i els ajuntaments, cadascun en les seves competències, han de facilitar que aquestes activitats es facin adequadament (art. 2.1). Els principis que inspiren la llei són la convivència entre la ciutadania, la seguretat, la no-discriminació, la preservació de la dignitat de dones i homes, la llibertat i la indemnitat sexuals, la no-transmissió d''estereotips sexistes i la qualitat dels establiments (art. 2.2). Per això, autoritats i responsables han de garantir la convivència pacífica (especialment amb el veïnat), la seguretat i la salut del públic i del personal, i la qualitat, la comoditat i la sostenibilitat ambiental (art. 2.3).","refs":[{"ref":"Art. 2.2 Llei 11/2009","law":"Llei 11/2009","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2009-12856","quote":"Los principios generales y las finalidades últimas que inspiran esta ley, y que han de regir su desarrollo y aplicación son la convivencia entre los ciudadanos, la seguridad, la no discriminación, la preservación de la dignidad de las mujeres y de los hombres, la libertad y la indemnidad sexuales, la no transmisión de estereotipos sexistas y la calidad de los establecimientos."}]}]},{"n":"2","title":"Conceptes bàsics (art. 3)","blocks":[{"text":"La llei distingeix dues menes d''activitat. Les activitats d''espectacles públics són activitats de lleure o entreteniment que consisteixen en representacions, actuacions, exhibicions, projeccions o similars, ofertes per un titular, explotador o organitzador i fetes per actors, artistes o altres executants, que congreguen un públic que hi acudeix per contemplar-les (art. 3.1.a). Les activitats recreatives són activitats musicals que congreguen un públic amb l''objectiu principal de fer-lo participar en l''activitat o d''oferir-li el consum de productes o serveis amb finalitats d''oci, entreteniment o diversió (art. 3.1.b). La clau és, doncs, contemplar (espectacle) o participar i consumir (activitat recreativa).","refs":[{"ref":"Art. 3.1.a Llei 11/2009","law":"Llei 11/2009","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2009-12856","quote":"a) Actividades de espectáculos públicos: actividades orientadas al tiempo libre o al entretenimiento, consistentes en representaciones, actuaciones, exhibiciones, proyecciones, o similares, que son ofrecidas por un titular, explotador u organizador y realizadas por actores, artistas u otros ejecutantes, y que congregan a un público que acude a las mismas para contemplarlas."},{"ref":"Art. 3.1.b Llei 11/2009","law":"Llei 11/2009","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2009-12856","quote":"b) Actividades recreativas: actividades musicales que congregan a un público con el objetivo principal de hacerle participar en la actividad o de ofrecerle el consumo de productos o servicios con finalidades de ocio, entretenimiento o diversión."}]},{"text":"Totes dues poden ser ordinàries, si es fan habitualment en establiments que tenen autorització, llicència o comunicació prèvia per a aquella activitat, o extraordinàries, si es fan en establiments habilitats per a una altra activitat, en espais oberts al públic o en altres establiments no regulats per la llei (art. 3.1). Els establiments oberts al públic són locals, instal·lacions o recintes dedicats a aquestes activitats; en canvi, els espais oberts al públic són llocs de domini públic, inclosa la via pública, o de propietat privada on es fan ocasionalment, sense infraestructures fixes (art. 3.1.c i d). Els titulars són, llevat que es disposi el contrari, els organitzadors de les activitats del seu establiment (art. 3.1.g).","refs":[{"ref":"Art. 3.1.d Llei 11/2009","law":"Llei 11/2009","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2009-12856","quote":"d) Espacios abiertos al público: los lugares de dominio público, incluida la vía pública, o de propiedad privada donde ocasionalmente se llevan a cabo espectáculos públicos o actividades recreativas, y que no disponen de infraestructuras ni instalaciones fijas para hacerlo."},{"ref":"Art. 3.1 Llei 11/2009","law":"Llei 11/2009","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2009-12856","quote":"– Extraordinarias: Actividades que se realizan en establecimientos abiertos al público que disponen de autorización, licencia o comunicación previa para una actividad distinta a la que se quiere llevar a cabo o en espacios abiertos al público o en otros establecimientos no regulados por la presente ley."}]}]},{"n":"3","title":"Àmbit d''aplicació i exclusions (art. 4)","blocks":[{"text":"La llei s''aplica a tota mena d''espectacles, activitats recreatives i establiments oberts al públic, tant si l''organitzador o el titular és públic com privat, si hi ha afany de lucre o no, i si l''activitat és esporàdica o habitual (art. 4.1). En queden excloses: les celebracions privades o familiars fora d''establiments oberts al públic que no comportin risc; les activitats fetes en exercici dels drets fonamentals de reunió i manifestació; els actes veïnals o associatius d''aforament baix o mitjà que no comportin risc greu; i les manifestacions festives del Catàleg del patrimoni festiu de Catalunya (art. 4.5).","refs":[{"ref":"Art. 4.1 Llei 11/2009","law":"Llei 11/2009","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2009-12856","quote":"con independencia del carácter público o privado de sus organizadores, de la titularidad pública o privada del establecimiento o el espacio abierto al público en que se desarrollan, de su finalidad lucrativa o no lucrativa y de su carácter esporádico o habitual."},{"ref":"Art. 4.5.b i 4.5.d Llei 11/2009","law":"Llei 11/2009","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2009-12856","quote":"b) Las actividades efectuadas en ejercicio de los derechos fundamentales de reunión y de manifestación. […] d) Todas las manifestaciones festivas que constan en el Catálogo del patrimonio festivo de Cataluña"}]}]},{"n":"4","title":"Protecció dels menors i dret d''admissió (arts. 9 i 10)","blocks":[{"text":"L''accés dels menors a determinats establiments i activitats es regula per reglament (art. 9.1). Els establiments i espais on poden entrar menors han de complir la normativa de protecció de menors, especialment la prohibició de vendre''ls i subministrar-los begudes alcohòliques; la de vendre, subministrar i consumir tabac i drogues; la de jugar amb màquines recreatives amb premi o d''atzar o que incitin a la violència; la protecció de la seva integritat física, psíquica i moral; i la limitació d''horaris (art. 9.2). En activitats extraordinàries sense reglamentació específica, l''òrgan que les autoritza pot prohibir-hi l''assistència de menors (art. 9.3).","refs":[{"ref":"Art. 9.2 Llei 11/2009","law":"Llei 11/2009","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2009-12856","quote":"especialmente la relativa a la prohibición de venta y suministro de bebidas alcohólicas; a la prohibición de venta, suministro y consumo de tabaco y de todo tipo de drogas o sustancias estupefacientes; a la prohibición de jugar con máquinas recreativas con premio o de azar o que inciten a la violencia"}]},{"text":"El dret d''admissió no pot comportar en cap cas discriminació per raó de naixement, raça, sexe, religió, opinió, discapacitat, orientació sexual, identitat de gènere o qualsevol altra condició o circumstància personal o social, ni en l''accés, ni en la permanència, ni en l''ús dels serveis (art. 10). Incomplir aquesta prohibició és una falta molt greu (art. 47.i), mentre que exercir el dret d''admissió sense haver-lo comunicat a l''autoritat és una falta lleu (art. 49.1.d).","refs":[{"ref":"Art. 10 Llei 11/2009","law":"Llei 11/2009","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2009-12856","quote":"El ejercicio del derecho de admisión no puede conllevar, en ningún caso, discriminación por razón de nacimiento, raza, sexo, religión, opinión, discapacidad, orientación sexual, identidad de género o cualquier otra condición o circunstancia personal o social"},{"ref":"Art. 47.i i 49.1.d Llei 11/2009","law":"Llei 11/2009","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2009-12856","quote":"i) Incumplir la prohibición de discriminación establecida por el artículo 10. […] d) Ejercer el derecho de admisión sin haberlo comunicado a la autoridad competente."}]}]},{"n":"5","title":"Competències de la Generalitat i dels ajuntaments (arts. 11-13)","blocks":[{"text":"La Generalitat dicta el desplegament reglamentari, planifica territorialment els establiments, autoritza els establiments de règim especial i les activitats extraordinàries que no són municipals, i inspecciona i sanciona el que ha autoritzat i també el que han autoritzat els ajuntaments quan aquests no han assumit aquesta competència (art. 11.1). Pot delegar en els ajuntaments que ho sol·licitin i acreditin capacitat de gestió les competències d''autorització d''establiments de règim especial i les sancionadores corresponents (art. 12).","refs":[{"ref":"Art. 11.1.a i 11.1.e Llei 11/2009","law":"Llei 11/2009","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2009-12856","quote":"a) Dictar las normas que sean necesarias para el desarrollo reglamentario de esta ley. […] e) Inspeccionar y sancionar los establecimientos abiertos al público, espectáculos públicos y actividades recreativas autorizados por los ayuntamientos cuando estos no hayan acordado asumir el ejercicio de dicha competencia"}]},{"text":"Als ajuntaments els correspon: aprovar ordenances en el marc de la llei; adoptar mesures de planificació urbanística; atorgar les llicències d''establiments permanents i no permanents desmuntables, les d''activitats extraordinàries (en tot cas, amb motiu de revetlles i festes populars) i les d''activitats en espais oberts al públic; inspeccionar i sancionar el que està sotmès a llicència municipal si ho acorda el ple; ser titulars o organitzadors d''activitats; i exercir totes les potestats que la llei no atribueix a altres administracions (art. 13.1). L''òrgan sancionador municipal és l''alcalde o alcaldessa, que pot delegar (art. 59.2).","refs":[{"ref":"Art. 13.1.a Llei 11/2009","law":"Llei 11/2009","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2009-12856","quote":"a) Aprobar ordenanzas, en el marco establecido por esta ley."},{"ref":"Art. 13.1.d Llei 11/2009","law":"Llei 11/2009","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2009-12856","quote":"d) Inspeccionar y sancionar los establecimientos abiertos al público, espectáculos públicos y actividades recreativas sometidos a licencia municipal, en los supuestos de que, mediante un acuerdo del pleno municipal, se haya acordado asumir conjuntamente el ejercicio de estas competencias"},{"ref":"Art. 59.2 Llei 11/2009","law":"Llei 11/2009","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2009-12856","quote":"2. El órgano municipal competente para ejercer las potestades sancionadoras que la presente ley atribuye a los ayuntamientos es el alcalde o alcaldesa, que puede delegar la competencia de acuerdo con el régimen establecido por la legislación de régimen local."}]}]},{"n":"6","title":"Horaris, control d''accés i vigilància (arts. 20, 24 i 25)","blocks":[{"text":"L''horari general el fixa una ordre del conseller o consellera competent, un cop escoltat el Consell Assessor d''Espectacles Públics i Activitats Recreatives; els òrgans de la Generalitat o dels municipis poden acordar, sempre de manera motivada, ampliacions o reduccions (art. 20). El personal responsable del control d''accés i d''aforament ha de complir els requisits professionals i d''idoneïtat, assistir a cursos de formació en un centre degudament habilitat i superar les proves de selecció de la direcció general competent (art. 24.2).","refs":[{"ref":"Art. 20.2 Llei 11/2009","law":"Llei 11/2009","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2009-12856","quote":"los órganos competentes de la Generalidad o de los municipios pueden acordar, siempre de forma motivada, ampliaciones o reducciones del horario general."},{"ref":"Art. 24.2 Llei 11/2009","law":"Llei 11/2009","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2009-12856","quote":"2. El personal responsable del control de acceso y de aforos de los establecimientos abiertos al público debe cumplir los requisitos profesionales y de idoneidad necesarios. Este personal debe asistir a cursos de formación impartidos por un centro debidamente habilitado y superar las pruebas de selección que convoque la dirección general competente en materia de espectáculos públicos y actividades recreativas."}]},{"text":"Quan el comportament del públic pot provocar problemes greus de seguretat i d''ordre públic i el personal de vigilància no pot afrontar la situació, aquest personal ha de sol·licitar l''auxili dels cossos i forces de seguretat perquè adoptin les mesures oportunes (art. 25.4).","refs":[{"ref":"Art. 25.4 Llei 11/2009","law":"Llei 11/2009","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2009-12856","quote":"debe solicitar el auxilio de los cuerpos y fuerzas de seguridad para que adopten las medidas oportunas."}]}]},{"n":"7","title":"Llicències, autoritzacions i comunicació prèvia (art. 29)","blocks":[{"text":"Obrir un establiment o organitzar espectacles i activitats requereix obtenir abans la llicència o autorització corresponent, que només és eficaç en les condicions i per a les activitats que estableix (art. 29.1 i 29.2). Cada establiment ha de tenir una única llicència o autorització, i qualsevol modificació (reforma, ampliació, canvi d''emplaçament…) també hi està sotmesa (art. 29.4 i 29.5). Quan la legislació de control ambiental no exigeix llicència, els reglaments o les ordenances poden substituir l''autorització per una comunicació prèvia, amb les mateixes condicions generals (art. 29.6). Llevat que l''ordenança digui el contrari, no necessiten llicència municipal, entre d''altres, els establiments de titularitat de l''ajuntament i les activitats extraordinàries que organitza el municipi amb motiu de festes i revetlles populars (art. 29.7).","refs":[{"ref":"Art. 29.1 Llei 11/2009","law":"Llei 11/2009","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2009-12856","quote":"requieren la obtención previa de las licencias o autorizaciones establecidas por la presente ley."},{"ref":"Art. 29.6 Llei 11/2009","law":"Llei 11/2009","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2009-12856","quote":"los reglamentos de la Generalidad o las ordenanzas municipales pueden sustituir el régimen de autorización por el de comunicación previa a la Administración"},{"ref":"Art. 29.7 Llei 11/2009","law":"Llei 11/2009","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2009-12856","quote":"a) Los establecimientos abiertos al público que son de titularidad del propio ayuntamiento. b) Los espectáculos públicos y actividades recreativas de carácter extraordinario organizados por los municipios con motivo de fiestas y verbenas populares"}]}]},{"n":"8","title":"Inspecció: funcions dels agents (art. 44)","blocks":[{"text":"Titulars i organitzadors han de permetre i facilitar les inspeccions. El personal d''inspecció pot accedir a qualsevol lloc, instal·lació o dependència, pública o privada, amb el límit constitucional de l''entrada en domicili (art. 44.1). Poden fer inspeccions els membres dels cossos i forces de seguretat i altres serveis d''inspecció, que en l''exercici de les seves funcions tenen el caràcter d''agents de l''autoritat (art. 44.2).","refs":[{"ref":"Art. 44.1 Llei 11/2009","law":"Llei 11/2009","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2009-12856","quote":"El personal de inspección puede acceder a cualquier lugar, instalación o dependencia, de titularidad pública o privada, con el límite constitucional de la entrada en domicilio."},{"ref":"Art. 44.2 Llei 11/2009","law":"Llei 11/2009","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2009-12856","quote":"Pueden realizar inspecciones los miembros de cuerpos y fuerzas de seguridad u otros servicios de inspección, los cuales, en el ejercicio de sus funciones, tienen el carácter de agentes de la autoridad"}]},{"text":"Com a resultat de la inspecció, els agents han d''estendre una acta, en què els interessats poden fer constar la seva disconformitat i observacions; l''acta s''ha de notificar als interessats i a l''òrgan competent (art. 44.3). Si es constaten irregularitats, l''òrgan competent pot requerir les esmenes en un termini o obrir directament l''expedient sancionador (art. 44.4). No permetre l''accés als agents o impedir-los la feina és una falta molt greu (art. 47.f).","refs":[{"ref":"Art. 44.3 Llei 11/2009","law":"Llei 11/2009","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2009-12856","quote":"3. Como resultado de la inspección, los agentes actuantes deben extender un acta, en la cual los interesados pueden hacer constar su disconformidad y observaciones. El acta debe notificarse a los interesados y al órgano administrativo competente."},{"ref":"Art. 47.f Llei 11/2009","law":"Llei 11/2009","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2009-12856","quote":"f) No permitir el acceso a los agentes de la autoridad en el ejercicio de sus funciones"}]}]},{"n":"9","title":"Infraccions: faltes molt greus, greus i lleus (arts. 46-49)","blocks":[{"text":"Les infraccions es classifiquen en faltes molt greus, greus i lleus; la contaminació acústica es regeix per la seva normativa específica (art. 46). Són molt greus, entre d''altres: obrir o fer activitats sense llicència o comunicació quan comporta risc greu; tolerar de manera evident el consum il·legal i generalitzat de drogues o tolerar-ne el tràfic; excedir l''aforament si suposa un risc per a la seguretat de les persones; incomplir greument i reiteradament els horaris (com a mínim tres vegades en sis mesos); admetre menors de manera reiterada on tenen prohibida l''entrada; i trencar precintes (art. 47).","refs":[{"ref":"Art. 47.b Llei 11/2009","law":"Llei 11/2009","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2009-12856","quote":"b) Tolerar de manera evidente, los titulares, explotadores u organizadores de las actividades de espectáculos públicos y de las actividades recreativas, el consumo ilegal y generalizado de drogas tóxicas, estupefacientes o sustancias psicotrópicas o tolerar el tráfico de las mismas."},{"ref":"Art. 47.c Llei 11/2009","law":"Llei 11/2009","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2009-12856","quote":"c) Exceder el aforo permitido, si supone un riesgo para la seguridad de las personas."}]},{"text":"Són greus, entre d''altres: les mateixes conductes sense risc greu; excedir l''aforament si no suposa risc per a la seguretat; incomplir els horaris; admetre menors on tenen prohibida l''entrada; permetre l''accés de persones amb símbols que incitin a la violència, el racisme o la xenofòbia; i, en el cas dels espectadors, causar situacions de perill o assistir-hi amb objectes que es puguin fer servir com a armes (art. 48). Són lleus no col·locar els rètols obligatoris, no tenir fulls de reclamació, la revenda d''entrades i exercir el dret d''admissió sense comunicar-lo (art. 49).","refs":[{"ref":"Art. 48.f Llei 11/2009","law":"Llei 11/2009","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2009-12856","quote":"f) Exceder el aforo permitido, si no supone un riesgo para la seguridad de las personas."},{"ref":"Art. 48.p Llei 11/2009","law":"Llei 11/2009","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2009-12856","quote":"p) Asistir a espectáculos públicos o actividades recreativas con objetos que puedan ser utilizados como armas."}]}]},{"n":"10","title":"Sancions, responsables i prescripció (arts. 50-57)","blocks":[{"text":"Les faltes molt greus se sancionen amb multa de 10.001 a 100.000 euros (fins a 200.000 si hi ha reincidència en faltes molt greus) i, acumulativament o alternativament, amb tancament de sis a divuit mesos, suspensió de la llicència, revocació, inhabilitació o decomís (art. 50). Les greus, amb multa de 1.001 a 10.000 euros (fins a 20.000 per reincidència); si l''infractor és espectador o usuari, de 151 a 500 euros (art. 51). Les lleus, amb multa de 300 a 1.000 euros (fins a 2.000) i, si l''infractor és espectador o usuari, de 50 a 150 euros (fins a 300 per reincidència) (art. 52).","refs":[{"ref":"Art. 50.a Llei 11/2009","law":"Llei 11/2009","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2009-12856","quote":"a) Una multa de 10.001 a 100.000 euros y, en caso de reincidencia en la comisión de faltas muy graves, de hasta 200.000 euros."},{"ref":"Art. 51.a Llei 11/2009","law":"Llei 11/2009","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2009-12856","quote":"a) Una multa de 1.001 a 10.000 euros y, en caso de reincidencia en la comisión de faltas graves, de hasta 20.000 euros."},{"ref":"Art. 52.b Llei 11/2009","law":"Llei 11/2009","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2009-12856","quote":"b) Si los infractores son espectadores o usuarios, una multa de 50 a 150 euros y, en caso de reincidencia en la comisión de faltas leves, de hasta 300 euros."}]},{"text":"Responen de les infraccions les persones físiques o jurídiques que hi incorren; si és una persona jurídica, en responen solidàriament els administradors o directius que hi hagin participat o no hagin fet tot el possible per evitar-la (art. 56). Les faltes molt greus prescriuen als tres anys, les greus als dos anys i les lleus als sis mesos (art. 57.1). El termini compta des de la comissió o des que l''Administració en té coneixement i, en activitats continuades, des de la finalització de l''activitat o l''últim acte amb què es consuma la infracció (art. 57.2). El procediment s''ha de resoldre en nou mesos com a màxim (art. 57.5).","refs":[{"ref":"Art. 57.1 Llei 11/2009","law":"Llei 11/2009","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2009-12856","quote":"1. Las faltas muy graves prescriben al cabo de tres años; las faltas graves, al cabo de dos años, y las faltas leves, al cabo de seis meses."},{"ref":"Art. 57.2 Llei 11/2009","law":"Llei 11/2009","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2009-12856","quote":"En el caso de infracciones derivadas de una actividad continuada, la fecha inicial del cómputo es la de la finalización de la actividad o el último acto con el que la infracción se consuma."},{"ref":"Art. 57.5 Llei 11/2009","law":"Llei 11/2009","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2009-12856","quote":"El procedimiento sancionador debe ser resuelto y notificada su resolución en el plazo máximo de nueve meses desde su apertura"}]}]},{"n":"11","title":"Mesures provisionals prèvies i immediates (arts. 62-65)","blocks":[{"text":"Abans d''obrir l''expedient, l''òrgan sancionador pot impedir o suspendre espectacles o activitats si hi ha indicis clars de delicte (i ho ha de comunicar a l''autoritat judicial dins de les quaranta-vuit hores següents), alteracions de l''ordre públic amb perill, risc greu per a la seguretat, tolerància negligent del consum d''estupefaents, falta de llicència o incompliments reiterats d''horaris o d''admissió de menors (art. 62). Les mesures poden ser la suspensió de la llicència o de l''activitat, el tancament provisional amb precinte, el decomís o la prestació de fiances (art. 63), i s''han de confirmar en l''acord d''iniciació dins de quinze dies (art. 64.c).","refs":[{"ref":"Art. 62.a Llei 11/2009","law":"Llei 11/2009","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2009-12856","quote":"a) Si existen indicios claros de que pueden ser constitutivos de delito. En tal caso, el órgano que acuerda la medida provisional debe comunicarlo a la autoridad judicial dentro de las cuarenta y ocho horas siguientes."},{"ref":"Art. 64.c Llei 11/2009","law":"Llei 11/2009","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2009-12856","quote":"que debe efectuarse en el plazo máximo de quince días desde la adopción de las medidas provisionales."}]},{"text":"Els agents dels cossos i forces de seguretat poden adoptar mesures provisionals immediates en casos d''urgència absoluta, davant espectacles o activitats que comportin un risc immediat d''afectar greument la seguretat de les persones i els béns o la convivència (art. 65.1). Poden suspendre immediatament les activitats i precintar establiments, instal·lacions o instruments si hi pot haver problemes greus de seguretat; desallotjar-los si hi ha un perill greu, concret i manifest; o adoptar altres mesures menys restrictives i proporcionades (art. 65.3). Ho han de comunicar dins de les quaranta-vuit hores següents a l''òrgan competent, que les ha de confirmar, modificar o revocar en cinc dies a comptar del primer dia hàbil següent; si no es compleixen els terminis, les mesures s''aixequen automàticament (art. 65.2). També poden decomissar o precintar béns i entrades de revenda (art. 65.5).","refs":[{"ref":"Art. 65.1 Llei 11/2009","law":"Llei 11/2009","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2009-12856","quote":"en casos de urgencia absoluta, ante espectáculos públicos y actividades recreativas que conlleven un riesgo inmediato de afectar gravemente a la seguridad de las personas y los bienes o la convivencia entre los ciudadanos."},{"ref":"Art. 65.2 Llei 11/2009","law":"Llei 11/2009","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2009-12856","quote":"los agentes de policía deben comunicarlo, dentro de las cuarenta y ocho horas siguientes, al órgano competente para adoptar las medidas provisionales previas pertinentes, el cual debe confirmarlas, modificarlas o revocarlas en el plazo de cinco días, a contar desde el primer día hábil siguiente al de la comunicación. El incumplimiento de dichos plazos conlleva automáticamente el levantamiento de las medidas provisionales inmediatas adoptadas."},{"ref":"Art. 65.3.a Llei 11/2009","law":"Llei 11/2009","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2009-12856","quote":"a) La suspensión inmediata de las actividades y el precinto de los establecimientos, de las instalaciones o de los instrumentos, en el caso de que puedan producirse graves problemas de seguridad."}]}]},{"n":"R","title":"Recorda per a l''examen","blocks":[{"text":"Activitat recreativa: activitat musical per fer participar el públic o oferir-li consum d''oci; espectacle públic: el públic hi va a contemplar.","refs":[{"ref":"Art. 3.1.b Llei 11/2009","law":"Llei 11/2009","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2009-12856","quote":"actividades musicales que congregan a un público con el objetivo principal de hacerle participar en la actividad"}]},{"text":"Als ajuntaments els correspon, entre altres coses, aprovar ordenances en el marc de la llei; l''alcalde és l''òrgan sancionador municipal.","refs":[{"ref":"Art. 13.1.a Llei 11/2009","law":"Llei 11/2009","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2009-12856","quote":"a) Aprobar ordenanzas, en el marco establecido por esta ley."}]},{"text":"Els policies que inspeccionen són agents de l''autoritat i l''acta ha de recollir la disconformitat i les observacions dels interessats.","refs":[{"ref":"Art. 44.3 Llei 11/2009","law":"Llei 11/2009","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2009-12856","quote":"en la cual los interesados pueden hacer constar su disconformidad y observaciones."}]},{"text":"Excés d''aforament: molt greu si hi ha risc per a la seguretat de les persones; greu si no n''hi ha.","refs":[{"ref":"Art. 48.f Llei 11/2009","law":"Llei 11/2009","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2009-12856","quote":"f) Exceder el aforo permitido, si no supone un riesgo para la seguridad de las personas."}]},{"text":"Multes: molt greus de 10.001 a 100.000 euros (200.000 per reincidència); lleus d''espectadors o usuaris de 50 a 150 euros (300 per reincidència).","refs":[{"ref":"Art. 50.a Llei 11/2009","law":"Llei 11/2009","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2009-12856","quote":"de hasta 200.000 euros."}]},{"text":"Prescripció de les faltes: tres anys (molt greus), dos anys (greus) i sis mesos (lleus).","refs":[{"ref":"Art. 57.1 Llei 11/2009","law":"Llei 11/2009","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2009-12856","quote":"y las faltas leves, al cabo de seis meses."}]},{"text":"Mesura prèvia per indicis de delicte: comunicació a l''autoritat judicial en quaranta-vuit hores.","refs":[{"ref":"Art. 62.a Llei 11/2009","law":"Llei 11/2009","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2009-12856","quote":"debe comunicarlo a la autoridad judicial dentro de las cuarenta y ocho horas siguientes."}]},{"text":"Mesures immediates dels agents: comunicació en quaranta-vuit hores i confirmació, modificació o revocació en cinc dies; si no, s''aixequen automàticament.","refs":[{"ref":"Art. 65.2 Llei 11/2009","law":"Llei 11/2009","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2009-12856","quote":"en el plazo de cinco días, a contar desde el primer día hábil siguiente al de la comunicación."}]}]}]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2009-12856'), 'https://www.boe.es/buscar/act.php?id=BOE-A-2009-12856', null, null, null, null
  from public.topics t where t.slug = 'plcat-t21-espectacles-publics'
on conflict (topic_id, locale) do update
   set outline = excluded.outline, key_ideas = excluded.key_ideas, glossary = excluded.glossary,
       amendments = excluded.amendments, lessons = excluded.lessons, source_id = excluded.source_id, source_url = excluded.source_url,
       page_from = excluded.page_from, page_to = excluded.page_to, key_ideas_page = excluded.key_ideas_page
