       is distinct from (excluded.outline, excluded.key_ideas, excluded.glossary, excluded.amendments, excluded.lessons);
insert into public.sources (title, url, kind, publisher, published_on) values ('Acord GOV/25/2015, de 24 de febrer, pel qual s''aprova el Codi d''ètica de la Policia de Catalunya (DOGC núm. 6821, 26/02/2015)', 'https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=685656', 'diario_autonomico'::public.source_kind, 'Generalitat de Catalunya · Portal Jurídic de Catalunya', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('plcat-t22-etica-policial', 'Tema 22. Ètica i deontologia policial: Codi d''ètica de la Policia de Catalunya i Comitè d''Ètica') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('policia-local') and t.slug = 'plcat-t22-etica-policial' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, lessons, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"Comitè d''Ètica de la Policia de Catalunya: naturalesa i funcions (Decret 222/2013)"},{"n":"2","title":"Composició, nomenament i funcionament"},{"n":"3","title":"Codi d''ètica de la Policia de Catalunya: finalitat"},{"n":"4","title":"Valors: dignitat, servei, integritat i professionalitat"},{"n":"5","title":"Principis d''actuació: legalitat, imparcialitat, proporcionalitat"},{"n":"6","title":"Ús de la força i tracte a les persones detingudes"}]'::jsonb, '["Art. 1 Decret 222/2013: «1.1 El Comitè d''Ètica de la Policia de Catalunya és l’òrgan de caràcter consultiu i interdisciplinari en matèria d’ètica policial de les institucions pròpies de Catalunya»","Art. 3 Decret 222/2013: «3.1 El Comitè d''Ètica de la Policia de Catalunya està integrat per deu membres»","Art. 3.2 Decret 222/2013: «c) Dos entre els membres dels cossos de policia local de Catalunya, a proposta de les entitats municipalistes més representatives, amb una antiguitat mínima de deu anys com a policia local»","Art. 3.3 Decret 222/2013: «3.3 Els membres del Comitè són nomenats per un únic període de quatre anys.»","Art. 6 Decret 222/2013: «El Comitè s''ha de reunir almenys un cop cada quadrimestre.»","Art. 2.1.b Decret 222/2013: «b) Informar i, si s’escau, donar resposta a les qüestions que li adrecin la persona titular del departament amb competències en matèria de seguretat pública i els alcaldes com a responsables de la seguretat en els municipis respectius»","Codi d''ètica, cap. I Codi d''ètica de la Policia de Catalunya: «Es concreten en tres: a. Garantir els drets i les llibertats de totes les persones, b. Actuar amb integritat, proporcionalitat, congruència i oportunitat, i c. Actuar amb absoluta neutralitat política i imparciali»","Codi d''ètica, Proximitat Codi d''ètica de la Policia de Catalunya: «Per proximitat s’entén que l’agent de policia ha de ser accessible al ciutadà i ha d’exercir la funció que li correspon amb amabilitat i empatia per tal de fer-se proper a tota persona.»","Codi d''ètica, Temprança Codi d''ètica de la Policia de Catalunya: «La temprança és aquella qualitat humana que predisposa a l''autodomini mental, al control emocional i a l’autoconsciència»","Codi d''ètica, Professionalitat Codi d''ètica de la Policia de Catalunya: «La professionalitat implica el domini de coneixements (saber) i d''habilitats (saber fer) i unes actituds adequades (saber estar).»","Codi d''ètica, Integritat Codi d''ètica de la Policia de Catalunya: «també s’hi ha d’incloure l’obligació de denunciar i de perseguir tot acte de corrupció o qualsevol proposta que signifiqui un afavoriment indegut, injustificat o il·legal.»","Codi d''ètica, punt 7 Codi d''ètica de la Policia de Catalunya: «els agents de la Policia de Catalunya no poden acceptar ni oferir tracte de favor, contraprestacions ni regals per haver desenvolupat o per desenvolupar el servei públic que els correspon»","Codi d''ètica, punt 8 Codi d''ètica de la Policia de Catalunya: «els agents de policia s’han d’abstenir d’expressar públicament les seves legítimes opcions polítiques o religioses»","Codi d''ètica, punt 17 Codi d''ètica de la Policia de Catalunya: «Els agents de policia han d’actuar d’acord amb el principi de jerarquia. Però, en cap cas, l’obediència deguda pot emparar ordres o actes contraris a l’ordenament legal.»","Codi d''ètica, punt 13 Codi d''ètica de la Policia de Catalunya: «Les relacions entre els membres de la Policia de Catalunya han d’estar regides per l’esperit de cooperació, col·laboració, coordinació, complementarietat i auxili mutu.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[{"n":"1","title":"El Comitè d''Ètica de la Policia de Catalunya: naturalesa (Decret 222/2013)","blocks":[{"text":"L''ètica i la deontologia policial tenen dos instruments propis a Catalunya: el Comitè d''Ètica de la Policia de Catalunya, regulat pel Decret 222/2013, del 3 de setembre, i el Codi d''ètica de la Policia de Catalunya, aprovat per l''Acord GOV/25/2015, del 24 de febrer. El Comitè es va crear pel Decret 230/2007, que el Decret 222/2013 deroga i substitueix per redefinir-ne les funcions i la composició.","refs":[{"ref":"Preàmbul i disposició derogatòria D222/2013","law":"Decret 222/2013","url":"https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=643826","quote":"Pel Decret 230/2007, de 16 d''octubre, la Generalitat de Catalunya va crear el Comitè d''Ètica de la Policia de Catalunya, com a òrgan consultiu en matèria deontològica policial […] Es deroga el Decret 230/2007, de 16 d''octubre, pel qual es crea el Comitè d''Ètica de la Policia de Catalunya."}]},{"text":"El Comitè és l''òrgan de caràcter consultiu i interdisciplinari en matèria d''ètica policial de les institucions pròpies de Catalunya. La seva finalitat és ajudar a millorar la qualitat del servei policial i ser un espai de reflexió per al debat ètic en el camp de la seguretat pública (art. 1.1). Està adscrit al departament competent en seguretat pública, que li assigna els mitjans personals i materials (art. 1.2). No és, per tant, un òrgan disciplinari, sinó d''assessorament.","refs":[{"ref":"Art. 1.1 D222/2013","law":"Decret 222/2013","url":"https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=643826","quote":"1.1 El Comitè d''Ètica de la Policia de Catalunya és l’òrgan de caràcter consultiu i interdisciplinari en matèria d’ètica policial de les institucions pròpies de Catalunya, per coadjuvar a la millora de la qualitat del servei policial i ser espai de reflexió per al debat ètic en el camp de la seguretat pública."},{"ref":"Art. 1.2 D222/2013","law":"Decret 222/2013","url":"https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=643826","quote":"1.2 El Comitè d''Ètica de la Policia de Catalunya s''adscriu al departament competent en matèria de seguretat pública"}]}]},{"n":"2","title":"Funcions del Comitè (art. 2)","blocks":[{"text":"Les funcions del Comitè són, entre d''altres: assessorar els òrgans i les autoritats sobre mesures per millorar el comportament, la imatge pública i la qualitat del servei policial (art. 2.1.a); informar i respondre les qüestions que li adrecin la persona titular del departament competent en seguretat pública i els alcaldes, com a responsables de la seguretat als seus municipis, i dictaminar, a petició d''aquests, sobre l''adequació de determinades conductes als principis ètics policials (art. 2.1.b); i impulsar l''elaboració i l''actualització de la normativa deontològica, inclòs un codi d''ètica (art. 2.1.c). Precisament en exercici d''aquesta funció el Comitè va elaborar la proposta del Codi aprovat el 2015.","refs":[{"ref":"Art. 2.1.b D222/2013","law":"Decret 222/2013","url":"https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=643826","quote":"b) Informar i, si s’escau, donar resposta a les qüestions que li adrecin la persona titular del departament amb competències en matèria de seguretat pública i els alcaldes com a responsables de la seguretat en els municipis respectius, així com dictaminar, a petició d’aquests, sobre l’adequació de determinades conductes als principis ètics policials."},{"ref":"Art. 2.1.c D222/2013","law":"Decret 222/2013","url":"https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=643826","quote":"c) Contribuir a l’impuls de les propostes oportunes per a l’elaboració i l’actualització de la normativa deontològica policial i, si s’escau, la seva codificació, mitjançant l’elaboració i l’actualització d’un codi d’ètica de la policia de Catalunya."}]},{"text":"També ha de difondre la doctrina judicial rellevant, conscienciar sobre ètica i drets humans, col·laborar en els continguts ètics de la formació policial (amb perspectiva de gènere i atenció a la violència sobre les dones i als col·lectius vulnerables) i vetllar per l''adequació de la normativa policial (art. 2.1.d a h). Pot demanar documentació als cossos de policia, sempre a través de les autoritats de qui depenen, i els agents tenen un deure general de col·laboració amb el Comitè (art. 2.2). Els seus membres actuen amb independència, objectivitat, imparcialitat i integritat personal (art. 2.3).","refs":[{"ref":"Art. 2.2 D222/2013","law":"Decret 222/2013","url":"https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=643826","quote":"Els membres dels cossos de policia de Catalunya tenen un deure general de col·laboració amb el Comitè en l''exercici de les seves funcions."},{"ref":"Art. 2.3 D222/2013","law":"Decret 222/2013","url":"https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=643826","quote":"els seus membres actuen d''acord amb els principis d’independència, objectivitat, imparcialitat i integritat personal."}]}]},{"n":"3","title":"Composició i nomenament (art. 3)","blocks":[{"text":"El Comitè està integrat per deu membres, nomenats per la persona titular del departament competent en seguretat pública, que també designa qui en té la presidència; els nomenaments es comuniquen al Consell de Seguretat de Catalunya (art. 3.1). Els deu membres es reparteixen així (art. 3.2): cinc persones dels àmbits acadèmic o professional amb solvència en dret, sociologia, psicologia, ètica, seguretat i policia; tres membres de la Policia de la Generalitat – Mossos d''Esquadra amb una antiguitat mínima de deu anys al cos; i dos membres de les policies locals, a proposta de les entitats municipalistes més representatives, amb una antiguitat mínima de deu anys com a policia local. Els agents han d''haver destacat per la seva trajectòria i prestigi professionals.","refs":[{"ref":"Art. 3.1 D222/2013","law":"Decret 222/2013","url":"https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=643826","quote":"3.1 El Comitè d''Ètica de la Policia de Catalunya està integrat per deu membres, nomenats per la persona titular del departament amb competències en matèria de seguretat pública"},{"ref":"Art. 3.2 D222/2013","law":"Decret 222/2013","url":"https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=643826","quote":"a) Cinc entre persones dels àmbits acadèmic o professional […] b) Tres entre els membres de la Policia de la Generalitat – Mossos d''Esquadra, que tinguin una antiguitat mínima de deu anys en el cos […] c) Dos entre els membres dels cossos de policia local de Catalunya, a proposta de les entitats municipalistes més representatives, amb una antiguitat mínima de deu anys com a policia local"}]},{"text":"Els membres són nomenats per un únic període de quatre anys (art. 3.3). El càrrec no és retribuït, tot i que els qui no són personal de les administracions tenen dret a indemnitzacions per assistència (art. 3.4). Poden assistir a les sessions, amb veu però sense vot i amb la invitació prèvia del president, experts, assessors, entitats de defensa dels drets humans i policies de prestigi (art. 3.5). En la composició s''ha de procurar respectar la paritat de gènere (art. 3.6).","refs":[{"ref":"Art. 3.3 D222/2013","law":"Decret 222/2013","url":"https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=643826","quote":"3.3 Els membres del Comitè són nomenats per un únic període de quatre anys."},{"ref":"Art. 3.4 i 3.6 D222/2013","law":"Decret 222/2013","url":"https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=643826","quote":"3.4 El càrrec de membre del Comitè no és retribuït. […] s’ha de procurar respectar el principi de paritat de gènere."}]}]},{"n":"4","title":"Presidència, secretaria i funcionament (arts. 4-7)","blocks":[{"text":"La presidència representa el Comitè, convoca i presideix les sessions i en fixa l''ordre del dia; en cas d''absència, malaltia o vacant la substitueix el membre de més edat (art. 4). La secretaria l''exerceix una persona funcionària del departament, designada pel conseller o consellera amb l''informe previ del Comitè, que fa les convocatòries, redacta les actes i custodia la documentació (art. 5).","refs":[{"ref":"Art. 4.2 D222/2013","law":"Decret 222/2013","url":"https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=643826","quote":"4.2 En els supòsits d’absència, malaltia o vacant, el president o presidenta del Comitè és substituït per la persona membre de més edat."}]},{"text":"La convocatòria correspon a la presidència, per iniciativa pròpia o de la majoria dels membres, i el Comitè s''ha de reunir almenys un cop cada quadrimestre (art. 6.1). L''ordre del dia s''envia amb una antelació mínima de cinc dies, llevat d''urgència (art. 6.2). El quòrum és la majoria absoluta dels membres, inclòs el president o qui el substitueixi (art. 6.3), i els informes s''emeten per majoria dels vots dels assistents, amb vot de qualitat de la presidència (art. 6.4). El Comitè elabora el seu reglament intern i pot crear comissions i grups de treball (art. 7).","refs":[{"ref":"Art. 6.1 D222/2013","law":"Decret 222/2013","url":"https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=643826","quote":"El Comitè s''ha de reunir almenys un cop cada quadrimestre."},{"ref":"Art. 6.3 i 6.4 D222/2013","law":"Decret 222/2013","url":"https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=643826","quote":"6.3 El quòrum de constitució del Comitè és el de l''assistència de la majoria absoluta dels membres […] i la presidència té vot de qualitat."}]}]},{"n":"5","title":"El Codi d''ètica: naturalesa i finalitat","blocks":[{"text":"El Codi d''ètica de la Policia de Catalunya s''aplica a tots els cossos de policia de les institucions pròpies de Catalunya (Mossos d''Esquadra i policies locals). Vol ser una eina pedagògica i inspiradora: no regula protocols concrets, sinó que identifica principis, valors i competències compartits i exposa els deures i compromisos que el cos assumeix davant la ciutadania, preservant l''autonomia professional i la responsabilitat individual. També serveix com a marc de referència per als vigilants municipals.","refs":[{"ref":"Preàmbul del Codi","law":"Codi d''ètica de la Policia de Catalunya","url":"https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=685656","quote":"En aquest Codi s’entén per Policia de Catalunya tots els cossos de la policia de les institucions pròpies de Catalunya."},{"ref":"Preàmbul del Codi","law":"Codi d''ètica de la Policia de Catalunya","url":"https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=685656","quote":"La seva funció és, doncs, essencialment pedagògica i inspiradora."}]},{"text":"S''inspira en la Declaració universal dels drets humans, el Conveni europeu de drets humans, el Pacte internacional de drets civils i polítics i el Codi europeu d''ètica de la policia del 2001, i s''ha de revisar periòdicament. L''epíleg encarrega al Comitè d''Ètica vetllar perquè s''actualitzi i al Departament d''Interior decidir-ne el seguiment.","refs":[{"ref":"Preàmbul del Codi","law":"Codi d''ètica de la Policia de Catalunya","url":"https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=685656","quote":"i en el Codi europeu d’ètica de la policia (2001) del Consell d’Europa, haurà de ser revisat periòdicament i modificat, si cal, per respondre a les necessitats de cada temps."},{"ref":"Epíleg, punt 61","law":"Codi d''ètica de la Policia de Catalunya","url":"https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=685656","quote":"El Comitè d''Ètica de la Policia de Catalunya ha de vetllar perquè aquesta eina sigui actualitzada quan convingui."}]}]},{"n":"6","title":"Principis i àrees de valors (capítol I)","blocks":[{"text":"El Codi defineix els principis com les bases que en cap cas un policia no pot deixar de respectar, i en fixa tres: garantir els drets i les llibertats de totes les persones; actuar amb integritat, proporcionalitat, congruència i oportunitat; i actuar amb absoluta neutralitat política i imparcialitat. Els valors, en canvi, són horitzons de referència que mouen a obrar amb excel·lència, i la funció policial exigeix a més competències, és a dir, habilitats i destreses pròpies de la professió.","refs":[{"ref":"Cap. I del Codi","law":"Codi d''ètica de la Policia de Catalunya","url":"https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=685656","quote":"S’entén per principis aquelles bases que en cap cas un policia no pot deixar de respectar en la seva actuació. Es concreten en tres: a. Garantir els drets i les llibertats de totes les persones, b. Actuar amb integritat, proporcionalitat, congruència i oportunitat, i c. Actuar amb absoluta neutralitat política i imparcialitat."}]},{"text":"Els valors, les actituds i les competències s''agrupen en cinc àrees: A) la funció pública, B) la professió, C) l''orientació a les persones, D) les relacions institucionals i E) l''entorn.","refs":[{"ref":"Cap. I del Codi","law":"Codi d''ètica de la Policia de Catalunya","url":"https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=685656","quote":"Els valors, les actituds i les competències s’agrupen en cinc àrees: la funció pública, la professió, l’orientació a les persones, les relacions institucionals i l’entorn."}]}]},{"n":"7","title":"Valors de la funció pública i de la professió","blocks":[{"text":"A la funció pública corresponen la voluntat de servei (actitud d''atenció i ajuda, al servei de l''interès general i no de cap grup de poder) i la transparència (retre comptes i facilitar l''accés a la informació d''interès per als drets de les persones). A la professió pertanyen la proximitat, la professionalitat, l''exemplaritat, el seny, la temprança, la responsabilitat, el coratge i el coneixement.","refs":[{"ref":"Cap. I.A del Codi","law":"Codi d''ètica de la Policia de Catalunya","url":"https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=685656","quote":"La Policia de Catalunya té com a fita l’interès general, entès com el bé consensuat i no pas com la suma dels interessos particulars."}]},{"text":"Per proximitat s''entén que l''agent ha de ser accessible al ciutadà i exercir la funció amb amabilitat i empatia per fer-se proper a tothom; és un tret característic de la Policia de Catalunya. La professionalitat implica el domini de coneixements (saber), d''habilitats (saber fer) i d''actituds adequades (saber estar), amb una doble competència tècnica i ètica.","refs":[{"ref":"Cap. I.B del Codi, Proximitat","law":"Codi d''ètica de la Policia de Catalunya","url":"https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=685656","quote":"Per proximitat s’entén que l’agent de policia ha de ser accessible al ciutadà i ha d’exercir la funció que li correspon amb amabilitat i empatia per tal de fer-se proper a tota persona."},{"ref":"Cap. I.B del Codi, Professionalitat","law":"Codi d''ètica de la Policia de Catalunya","url":"https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=685656","quote":"La professionalitat implica el domini de coneixements (saber) i d''habilitats (saber fer) i unes actituds adequades (saber estar)."}]},{"text":"El seny és la qualitat que mou al discerniment abans de prendre decisions, avaluant-ne les conseqüències. La temprança predisposa a l''autodomini mental, al control emocional i a l''autoconsciència, sobretot en circumstàncies de gran pressió i tensió. El coratge predisposa l''agent a confiar en les pròpies forces i en les dels companys per afrontar situacions difícils.","refs":[{"ref":"Cap. I.B del Codi, Seny","law":"Codi d''ètica de la Policia de Catalunya","url":"https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=685656","quote":"El seny és aquella qualitat humana que mou a la pràctica del discerniment abans d’emprendre les decisions."},{"ref":"Cap. I.B del Codi, Temprança","law":"Codi d''ètica de la Policia de Catalunya","url":"https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=685656","quote":"La temprança és aquella qualitat humana que predisposa a l''autodomini mental, al control emocional i a l’autoconsciència, a una gestió intel·ligent i adequada de les emocions, sobretot en circumstàncies de gran pressió i tensió."}]}]},{"n":"8","title":"Orientació a les persones, relacions institucionals i entorn","blocks":[{"text":"L''orientació a les persones inclou el respecte als drets i llibertats, la seguretat, la imparcialitat (oposar-se a tota discriminació o prejudici i a qualsevol favoritisme), el respecte i la integritat. Ser íntegre vol dir refusar qualsevol acte de corrupció i no acceptar ni oferir regals o favors que condicionin les actuacions; les bones pràctiques inclouen, a més, l''obligació de denunciar i perseguir tot acte de corrupció o qualsevol proposta d''afavoriment indegut, injustificat o il·legal.","refs":[{"ref":"Cap. I.C del Codi, Integritat","law":"Codi d''ètica de la Policia de Catalunya","url":"https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=685656","quote":"Ser íntegre vol dir refusar qualsevol acte de corrupció"},{"ref":"Cap. I.C del Codi, Integritat","law":"Codi d''ètica de la Policia de Catalunya","url":"https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=685656","quote":"també s’hi ha d’incloure l’obligació de denunciar i de perseguir tot acte de corrupció o qualsevol proposta que signifiqui un afavoriment indegut, injustificat o il·legal."}]},{"text":"Les relacions institucionals comprenen el sentiment de pertinença, expressat amb lleialtat al cos (que mai no pot servir per ocultar males pràctiques), i la cooperació entre cossos. L''entorn demana sensibilitat social, especialment amb els entorns vulnerables, i mediambiental.","refs":[{"ref":"Cap. I.D del Codi","law":"Codi d''ètica de la Policia de Catalunya","url":"https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=685656","quote":"No ha de ser, en cap cas, un pretext per ocultar mancances, limitacions o males pràctiques."}]}]},{"n":"9","title":"Una professió al servei de les persones (punts 1-12)","blocks":[{"text":"La missió dels cossos de seguretat és protegir el lliure exercici dels drets i llibertats i garantir la seguretat ciutadana. Entre les funcions primordials hi ha defensar les llibertats i els drets, protegir persones i béns, defensar els grups vulnerables, garantir l''ordre i la pau social, prevenir infraccions, resoldre conflictes i fer respectar la llei (punt 1). Els agents tenen drets propis, com ser tractats amb dignitat, la seguretat en la professió, la formació i l''associació (punts 2 i 3), i han de comunicar al superior si no estan en condicions de fer la seva funció (punt 5).","refs":[{"ref":"Punt 1 del Codi","law":"Codi d''ètica de la Policia de Catalunya","url":"https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=685656","quote":"La missió dels cossos i forces de seguretat és protegir el lliure exercici dels drets i llibertats i garantir la seguretat ciutadana."}]},{"text":"Pel que fa als deures: els agents no poden acceptar ni oferir tracte de favor, contraprestacions ni regals per haver fet o per fer el servei públic que els correspon (punt 7); en l''exercici de les funcions s''han d''abstenir d''expressar públicament les seves legítimes opcions polítiques o religioses i han de tractar tothom amb equitat, imparcialitat i neutralitat (punt 8); i han d''actuar amb exemplaritat tant en la feina com en la vida social (punt 10). Han de ser especialment atents amb les persones i grups vulnerables i col·laborar amb els serveis comunitaris (punts 11 i 12).","refs":[{"ref":"Punt 7 del Codi","law":"Codi d''ètica de la Policia de Catalunya","url":"https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=685656","quote":"els agents de la Policia de Catalunya no poden acceptar ni oferir tracte de favor, contraprestacions ni regals per haver desenvolupat o per desenvolupar el servei públic que els correspon"},{"ref":"Punt 8 del Codi","law":"Codi d''ètica de la Policia de Catalunya","url":"https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=685656","quote":"En l’exercici de les seves funcions, els agents de policia s’han d’abstenir d’expressar públicament les seves legítimes opcions polítiques o religioses"}]}]},{"n":"10","title":"Cossos policials: principis rectors (punts 13-37)","blocks":[{"text":"Les relacions entre els membres de la Policia de Catalunya han d''estar regides per l''esperit de cooperació, col·laboració, coordinació, complementarietat i auxili mutu (punt 13), fonamentades en l''equitat i el respecte (punt 14). Les pràctiques que vulnerin la llei dins d''un cos s''han de denunciar per les vies establertes (punt 15). Els agents actuen d''acord amb el principi de jerarquia, però en cap cas l''obediència deguda no pot emparar ordres o actes contraris a l''ordenament legal (punt 17). Tenen el deure de preservar el secret professional (punt 20).","refs":[{"ref":"Punt 13 del Codi","law":"Codi d''ètica de la Policia de Catalunya","url":"https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=685656","quote":"Les relacions entre els membres de la Policia de Catalunya han d’estar regides per l’esperit de cooperació, col·laboració, coordinació, complementarietat i auxili mutu."},{"ref":"Punt 17 del Codi","law":"Codi d''ètica de la Policia de Catalunya","url":"https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=685656","quote":"Els agents de policia han d’actuar d’acord amb el principi de jerarquia. Però, en cap cas, l’obediència deguda pot emparar ordres o actes contraris a l’ordenament legal."}]},{"text":"Els comandaments responen de les ordres que donen, de la seva execució i de les seves conseqüències (punt 28). Davant les autoritats polítiques, la Policia és una organització jeràrquica a disposició de les autoritats elegides democràticament i sotmesa al control del Parlament, i els agents han d''actuar amb professionalitat sigui quina sigui la seva afinitat ideològica amb el govern (punts 31 i 32). Entre cossos (catalans, espanyols, europeus i de la resta del món) hi ha d''haver respecte, lleialtat institucional, cooperació, intercanvi d''informació i respecte a l''autonomia de cadascun (punts 34-36).","refs":[{"ref":"Punt 28 del Codi","law":"Codi d''ètica de la Policia de Catalunya","url":"https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=685656","quote":"Els comandaments són responsables de les ordres que donen, de la seva correcta execució i de les seves conseqüències."},{"ref":"Punt 34 del Codi","law":"Codi d''ètica de la Policia de Catalunya","url":"https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=685656","quote":"han d’estar presidides pel respecte, per la lleialtat institucional, per la mútua cooperació i per la bona coordinació"}]}]},{"n":"11","title":"Actuació policial: conflictes, ús de la força, detenció, víctimes i informació (punts 38-59)","blocks":[{"text":"Sempre que sigui possible, els conflictes s''han de resoldre amb la mediació, el diàleg i altres mètodes que no impliquin necessàriament la força; només quan s''han exhaurit o no es poden aplicar, es pot fer servir la força, i només si és estrictament necessari (punt 38). Llavors cal emprar els mitjans menys lesius seguint tres principis (punt 39): oportunitat (actuar en el moment i l''espai propicis perquè no es causi un mal més greu del que es vol evitar), congruència (utilitzar el mitjà més idoni per a cada situació) i proporcionalitat (modelar, adequar i aplicar gradualment la força segons el tipus i la gravetat de l''agressió).","refs":[{"ref":"Punt 38 del Codi","law":"Codi d''ètica de la Policia de Catalunya","url":"https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=685656","quote":"la Policia de Catalunya ha de tractar de resoldre les situacions de conflicte a través de la mediació, del diàleg i d’altres mètodes de resolució que no impliquin necessàriament l’ús de la força."},{"ref":"Punt 39 del Codi","law":"Codi d''ètica de la Policia de Catalunya","url":"https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=685656","quote":"Per congruència s’entén la necessitat d’utilitzar el mitjà més idoni, que més convé o que més s’ajusti a cadascuna de les situacions que se li plantegen a l’agent de policia. Per proporcionalitat s’entén la necessitat de modelar, adequar i aplicar de forma gradual l’ús de la força o del mitjà de defensa en funció del tipus i la gravetat de l’agressió que es vol neutralitzar."}]},{"text":"La investigació s''ha de fonamentar en sospites raonables, mantenint la presumpció d''innocència, i fer-se de manera confidencial (punts 40 i 41). A qui és privat de llibertat se l''ha d''informar immediatament i de manera comprensible dels seus drets, i se li ha de dispensar un tracte correcte, vetllant per la seva integritat, la seva dignitat i imatge, les necessitats mèdiques i el dret de defensa (punts 42 i 43). La Policia ha de protegir les víctimes i els testimonis (punts 45-47), col·laborar amb l''Administració de justícia i acatar-ne les decisions (punts 52 i 53), i gestionar la informació amb objectivitat, veracitat, claredat i transparència (punt 54).","refs":[{"ref":"Punt 40 del Codi","law":"Codi d''ètica de la Policia de Catalunya","url":"https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=685656","quote":"La investigació policial cal que es fonamenti en sospites raonables tot mantenint la presumpció d’innocència de les persones investigades."},{"ref":"Punt 42 del Codi","law":"Codi d''ètica de la Policia de Catalunya","url":"https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=685656","quote":"Quan es privi de llibertat una persona, se l’haurà d’informar immediatament i de manera comprensible dels seus drets i garantir que aquests drets es compleixin."},{"ref":"Punt 54 del Codi","law":"Codi d''ètica de la Policia de Catalunya","url":"https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=685656","quote":"La gestió de la informació, tant interna com externa, es fonamenta en l''objectivitat, en la veracitat, en la claredat i en la transparència."}]}]},{"n":"R","title":"Recorda per a l''examen","blocks":[{"text":"El Comitè d''Ètica és un òrgan consultiu i interdisciplinari, adscrit al departament de seguretat pública.","refs":[{"ref":"Art. 1.1 D222/2013","law":"Decret 222/2013","url":"https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=643826","quote":"és l’òrgan de caràcter consultiu i interdisciplinari en matèria d’ètica policial"}]},{"text":"Deu membres: cinc experts, tres mossos i dos policies locals (aquests, amb deu anys d''antiguitat i a proposta de les entitats municipalistes).","refs":[{"ref":"Art. 3.1 D222/2013","law":"Decret 222/2013","url":"https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=643826","quote":"està integrat per deu membres"}]},{"text":"Mandat únic de quatre anys i reunió almenys un cop cada quadrimestre.","refs":[{"ref":"Art. 3.3 D222/2013","law":"Decret 222/2013","url":"https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=643826","quote":"nomenats per un únic període de quatre anys."}]},{"text":"Poden demanar-li dictàmens el titular del departament de seguretat i els alcaldes.","refs":[{"ref":"Art. 2.1.b D222/2013","law":"Decret 222/2013","url":"https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=643826","quote":"així com dictaminar, a petició d’aquests, sobre l’adequació de determinades conductes als principis ètics policials."}]},{"text":"Tres principis del Codi: drets i llibertats; integritat, proporcionalitat, congruència i oportunitat; neutralitat política i imparcialitat. Cinc àrees de valors.","refs":[{"ref":"Cap. I del Codi","law":"Codi d''ètica de la Policia de Catalunya","url":"https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=685656","quote":"Garantir els drets i les llibertats de totes les persones"}]},{"text":"Proximitat = accessibilitat, amabilitat i empatia; temprança = autodomini i control emocional; professionalitat = saber, saber fer i saber estar.","refs":[{"ref":"Cap. I.B del Codi","law":"Codi d''ètica de la Policia de Catalunya","url":"https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=685656","quote":"coneixements (saber) i d''habilitats (saber fer) i unes actituds adequades (saber estar)."}]},{"text":"Ni regals ni tracte de favor (punt 7); cap obediència deguda a ordres il·legals (punt 17).","refs":[{"ref":"Punt 17 del Codi","law":"Codi d''ètica de la Policia de Catalunya","url":"https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=685656","quote":"en cap cas, l’obediència deguda pot emparar ordres o actes contraris a l’ordenament legal."}]},{"text":"Ús de la força: primer mediació i diàleg; després, oportunitat, congruència i proporcionalitat.","refs":[{"ref":"Punt 39 del Codi","law":"Codi d''ètica de la Policia de Catalunya","url":"https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=685656","quote":"l’oportunitat, la congruència i la proporcionalitat."}]}]}]'::jsonb, (select id from public.sources where url = 'https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=685656'), 'https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=685656', null, null, null, 'Otras normas citadas: Decret 222/2013 (https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=643826)'
  from public.topics t where t.slug = 'plcat-t22-etica-policial'
on conflict (topic_id, locale) do update
   set outline = excluded.outline, key_ideas = excluded.key_ideas, glossary = excluded.glossary,
       amendments = excluded.amendments, lessons = excluded.lessons, source_id = excluded.source_id, source_url = excluded.source_url,
       page_from = excluded.page_from, page_to = excluded.page_to, key_ideas_page = excluded.key_ideas_page
 where (n.outline, n.key_ideas, n.glossary, n.amendments, n.lessons)
       is distinct from (excluded.outline, excluded.key_ideas, excluded.glossary, excluded.amendments, excluded.lessons);
insert into public.sources (title, url, kind, publisher, published_on) values ('Ley 17/2015, de 21 de julio, de igualdad efectiva de mujeres y hombres (Cataluña) (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-9676', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('plcat-t23-igualtat-no-discriminacio', 'Tema 23. Igualtat efectiva de dones i homes (Llei 17/2015) i igualtat de tracte i no-discriminació (Llei 19/2020)') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('policia-local') and t.slug = 'plcat-t23-igualtat-no-discriminacio' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, lessons, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"Llei 17/2015: objecte i finalitats (art. 1)"},{"n":"2","title":"Definicions: representació paritària, discriminació directa, indirecta i múltiple, assetjament (art. 2)"},{"n":"3","title":"Organització administrativa: Institut Català de les Dones (art. 7)"},{"n":"4","title":"Plans d''igualtat i funció pública (arts. 15 i 16)"},{"n":"5","title":"Seguretat i perspectiva de gènere (art. 55)"},{"n":"6","title":"Síndic de Greuges i règim sancionador (arts. 57, 59 i 63)"},{"n":"7","title":"Llei 19/2020: objecte, motius de discriminació i deure de comunicació (arts. 1 i 3)"},{"n":"8","title":"Definicions de la Llei 19/2020 (art. 4)"},{"n":"9","title":"Cossos de seguretat: prohibició de criteris racials (art. 21)"},{"n":"10","title":"Organisme de Protecció i Promoció de la Igualtat de Tracte (art. 33)"},{"n":"11","title":"Infraccions, sancions i prescripció (arts. 43, 45 i 48)"}]'::jsonb, '["Art. 2.i Llei 17/2015: «ningún sexo supera el 60% del conjunto de personas a que se refiere ni es inferior al 40%, y que debe tender a alcanzar el 50% de personas de cada sexo»","Art. 2.k Llei 17/2015: «Discriminación directa: la situación en que se encuentra una persona que es, ha sido o puede ser tratada, por razón de sexo o de circunstancias directamente relacionadas con su condición biológica, de un modo menos favorable que otra en una situación análoga.»","Art. 2.l Llei 17/2015: «Discriminación indirecta: la situación discriminatoria creada por una disposición, criterio, interpretación o práctica supuestamente neutros que pueden causar un perjuicio mayor a las personas de uno de los sexos»","Art. 2.m Llei 17/2015: «Discriminación múltiple: la situación en que una mujer, por el hecho de pertenecer a otros grupos que también suelen ser discriminados, padece formas agravadas y específicas de discriminación.»","Art. 2.p Llei 17/2015: «Acoso sexual: cualquier comportamiento verbal, no verbal o físico, de naturaleza sexual, que se ejerce con el propósito o efecto de atentar contra la dignidad de una persona»","Art. 7.1 Llei 17/2015: «El Instituto Catalán de las Mujeres, que queda adscrito al departamento competente en materia de igualdad y feminismos.»","Art. 16.3 Llei 17/2015: «Los temarios para el acceso al empleo público deben incluir los contenidos relativos a la normativa sobre igualdad efectiva de mujeres y hombres y sobre violencia machista»","Art. 15.2 Llei 17/2015: «Los entes locales que tienen órganos específicos de representación del personal a su servicio deben aprobar un plan de igualdad de mujeres y hombres, que debe estar definido en el convenio colectivo o en el pacto o acuerdo de condiciones de trabajo.»","Art. 1.3 Llei 19/2020: «h) Condición social o económica, situación administrativa, profesión o condición de privación de libertad, y cualquier manifestación de aporofobia o de odio a las personas sin hogar.»","Art. 4.d Llei 19/2020: «Aporofobia: El rechazo, el desprecio o el odio hacia las personas pobres, sin techo o sin hogar.»","Art. 4.o Llei 19/2020: «Discriminación por asociación: La discriminación que se produce cuando una persona o el grupo al que se le asocia es objeto de discriminación, real o atribuida, como consecuencia de su relación con una persona o un grupo»","Art. 21.4 Llei 19/2020: «El uso de criterios raciales, basados en el aspecto físico del individuo, como el color de piel, las facciones, la pertenencia a un grupo racial o étnico o cualquier otra característica similar, en las detenciones, los interrogatorios, los registros, los controles de identidad»","Art. 3.2 Llei 19/2020: «si tienen conocimiento de una situación de riesgo o una sospecha fundada de discriminación o violencia, tienen el deber de comunicarlo a los cuerpos y fuerzas de seguridad y al órgano competente»","Art. 45.1 Llei 19/2020: «b) Infracciones graves, entre 10.001 y 40.000 euros.»","Art. 48.1 Llei 19/2020: «Las infracciones leves prescriben al cabo de doce meses; las graves, al cabo de tres años, y las muy graves, al cabo de cuatro años.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[{"n":"1","title":"Llei 17/2015: objecte, finalitats i principis","blocks":[{"text":"La Llei 17/2015, del 21 de juliol, d''igualtat efectiva de dones i homes, té per objecte establir i regular els mecanismes i recursos per fer efectiu el dret a la igualtat i a la no-discriminació per raó de sexe en tots els àmbits, etapes i circumstàncies de la vida (art. 1.1). Entre les seves finalitats hi ha eliminar les discriminacions que històricament han patit les dones, reconèixer el treball domèstic i de cura, afavorir la corresponsabilitat i abordar, prevenir i erradicar tota violència masclista (art. 1.2). Els apunts citen la versió consolidada en castellà del BOE.","refs":[{"ref":"Art. 1.1 Llei 17/2015","law":"Llei 17/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-9676","quote":"El objeto de la presente ley es establecer y regular los mecanismos y recursos para hacer efectivo el derecho a la igualdad y a la no discriminación por razón de sexo en todos los ámbitos, etapas y circunstancias de la vida."},{"ref":"Art. 1.2.f Llei 17/2015","law":"Llei 17/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-9676","quote":"f) Abordar, prevenir y erradicar, de acuerdo con lo dispuesto por la normativa vigente en la materia, todo tipo de violencia machista contra mujeres y niños."}]},{"text":"Els poders públics s''han de regir per vuit principis (art. 3): transversalitat de la perspectiva de gènere; equilibri entre treball de mercat i treball domèstic i corresponsabilitat; erradicació de la violència masclista; apoderament de les dones; democràcia paritària; perspectiva de les dones; justícia social i redistribució de la riquesa; i ús no sexista ni estereotipat del llenguatge.","refs":[{"ref":"Art. 3 Llei 17/2015","law":"Llei 17/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-9676","quote":"Primero.–Transversalidad de la perspectiva de género y de las políticas de igualdad de género […] Tercero.–Erradicación de la violencia machista […] Octavo.–Uso no sexista ni estereotipado del lenguaje"}]}]},{"n":"2","title":"Definicions de la Llei 17/2015 (art. 2)","blocks":[{"text":"Hi ha representació paritària quan cap sexe supera el 60% del conjunt de persones de què es tracta ni és inferior al 40%, i s''ha de tendir al 50% de cada sexe (art. 2.i). És diferent de la representació equilibrada, que garanteix una presència de dones en una proporció adequada a cada circumstància (art. 2.h).","refs":[{"ref":"Art. 2.i Llei 17/2015","law":"Llei 17/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-9676","quote":"i) Representación paritaria: la situación que garantiza una presencia de mujeres y hombres según la cual ningún sexo supera el 60% del conjunto de personas a que se refiere ni es inferior al 40%, y que debe tender a alcanzar el 50% de personas de cada sexo."}]},{"text":"La discriminació directa és la situació d''una persona que és, ha estat o pot ser tractada, per raó de sexe o de circumstàncies relacionades amb la seva condició biològica, de manera menys favorable que una altra en una situació anàloga; no ho són les mesures amb justificació objectiva i raonable, com l''acció positiva (art. 2.k). La discriminació indirecta la crea una disposició, criteri, interpretació o pràctica suposadament neutres que poden perjudicar més les persones d''un sexe, llevat que siguin adequats, necessaris i justificables amb criteris objectius aliens al gènere (art. 2.l). La discriminació múltiple és la que pateix una dona, de manera agreujada i específica, pel fet de pertànyer també a altres grups discriminats (art. 2.m).","refs":[{"ref":"Art. 2.k Llei 17/2015","law":"Llei 17/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-9676","quote":"k) Discriminación directa: la situación en que se encuentra una persona que es, ha sido o puede ser tratada, por razón de sexo o de circunstancias directamente relacionadas con su condición biológica, de un modo menos favorable que otra en una situación análoga."},{"ref":"Art. 2.l Llei 17/2015","law":"Llei 17/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-9676","quote":"l) Discriminación indirecta: la situación discriminatoria creada por una disposición, criterio, interpretación o práctica supuestamente neutros que pueden causar un perjuicio mayor a las personas de uno de los sexos, salvo si resultan adecuados y necesarios y pueden justificarse con criterios objetivos sin relación alguna con cuestiones de género."},{"ref":"Art. 2.m Llei 17/2015","law":"Llei 17/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-9676","quote":"m) Discriminación múltiple: la situación en que una mujer, por el hecho de pertenecer a otros grupos que también suelen ser discriminados, padece formas agravadas y específicas de discriminación."}]},{"text":"L''assetjament sexual és qualsevol comportament verbal, no verbal o físic de naturalesa sexual amb el propòsit o l''efecte d''atemptar contra la dignitat d''una persona, especialment si li crea un entorn intimidatori, hostil, degradant, humiliant o ofensiu (art. 2.p). L''assetjament per raó de sexe és el comportament que, per motiu del sexe, atempta contra la dignitat o la integritat o crea aquest entorn (art. 2.o).","refs":[{"ref":"Art. 2.p Llei 17/2015","law":"Llei 17/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-9676","quote":"p) Acoso sexual: cualquier comportamiento verbal, no verbal o físico, de naturaleza sexual, que se ejerce con el propósito o efecto de atentar contra la dignidad de una persona, especialmente si le crea un entorno intimidatorio, hostil, degradante, humillante u ofensivo"}]}]},{"n":"3","title":"Competències i organització administrativa (arts. 6 i 7)","blocks":[{"text":"Als municipis els correspon, entre altres funcions, sensibilitzar sobre les causes de la violència masclista i impulsar campanyes de prevenció, atendre i orientar les dones, i elaborar, aprovar, executar i avaluar els plans d''igualdat per al personal al seu servei (art. 6.1). La Generalitat exerceix les competències de la llei per mitjà de l''Institut Català de les Dones, adscrit al departament competent en igualtat i feminismes, i dels òrgans que designi cada departament (art. 7.1). Són òrgans consultius el Consell Nacional de les Dones de Catalunya i la Comissió Nacional per a una Intervenció Coordinada contra la Violència Masclista (art. 7.2).","refs":[{"ref":"Art. 6.1.b Llei 17/2015","law":"Llei 17/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-9676","quote":"b) Sensibilizar a la población sobre las causas de la violencia machista y, en el marco de la normativa vigente, impulsar actuaciones y campañas de prevención"},{"ref":"Art. 7.1.a Llei 17/2015","law":"Llei 17/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-9676","quote":"a) El Instituto Catalán de las Mujeres, que queda adscrito al departamento competente en materia de igualdad y feminismos."}]}]},{"n":"4","title":"Mecanismes d''igualtat en el sector públic (capítol III, arts. 10-15)","blocks":[{"text":"El capítol III recull els mecanismes per garantir la igualtat al sector públic: clàusules socials en la contractació (art. 10); denegació d''ajuts a empreses sancionades per discriminació per raó de sexe (art. 11); representació paritària en els òrgans col·legiats (art. 12); i plans d''igualtat (art. 13). Els ens locals que tenen òrgans específics de representació del personal han d''aprovar un pla d''igualtat de dones i homes, definit en el conveni col·lectiu o en el pacte o acord de condicions de treball (art. 15.2). Aquests plans han d''incloure mesures específiques per a col·lectius com els cossos i forces de seguretat i s''han d''avaluar cada quatre anys (art. 15.4).","refs":[{"ref":"Art. 12.1 Llei 17/2015","law":"Llei 17/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-9676","quote":"Las administraciones públicas deben atenerse al principio de representación paritaria de mujeres y hombres en los nombramientos y designaciones para la composición de todo tipo de órganos colegiados"},{"ref":"Art. 15.2 Llei 17/2015","law":"Llei 17/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-9676","quote":"2. Los entes locales que tienen órganos específicos de representación del personal a su servicio deben aprobar un plan de igualdad de mujeres y hombres, que debe estar definido en el convenio colectivo o en el pacto o acuerdo de condiciones de trabajo."},{"ref":"Art. 15.4.c i 15.4.e Llei 17/2015","law":"Llei 17/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-9676","quote":"así como de bomberos, agentes rurales y cuerpos y fuerzas de seguridad. […] e) Regular en el articulado la propia evaluación, que debe ser cuatrienal."}]}]},{"n":"5","title":"Igualtat en la funció pública (art. 16)","blocks":[{"text":"El departament de funció pública, amb l''Institut Català de les Dones, fixa els criteris d''igualtat per a les bases de les convocatòries (art. 16.1), i les administracions han d''impulsar la representació paritària en els tribunals de selecció (art. 16.2). Els temaris d''accés a l''ocupació pública han d''incloure continguts sobre la normativa d''igualtat efectiva de dones i homes i sobre violència masclista: per això aquest tema forma part del temari d''agent de policia local (art. 16.3). També cal una formació bàsica, progressiva i permanent en igualtat per a tot el personal (art. 16.4).","refs":[{"ref":"Art. 16.3 Llei 17/2015","law":"Llei 17/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-9676","quote":"3. Los temarios para el acceso al empleo público deben incluir los contenidos relativos a la normativa sobre igualdad efectiva de mujeres y hombres y sobre violencia machista"},{"ref":"Art. 16.2 Llei 17/2015","law":"Llei 17/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-9676","quote":"2. Las administraciones públicas de Cataluña deben impulsar la representación paritaria de mujeres y hombres en la composición de los tribunales u órganos técnicos de selección."}]}]},{"n":"6","title":"Polítiques públiques: seguretat i perspectiva de gènere (art. 55)","blocks":[{"text":"Dins de les polítiques públiques del capítol IV, l''article 55 obliga el departament competent en seguretat a tenir en compte la diferent percepció de la seguretat de dones i homes i a incloure la perspectiva de gènere en les enquestes de victimització, en l''anàlisi de la seguretat, en les diagnosis de seguretat dels espais públics i en les polítiques de prevenció i protecció (art. 55.1.a). També ha d''adoptar mesures per erradicar la violència masclista a nivell comunitari i promoure el treball amb els homes perquè no n''exerceixin (art. 55.1.b i c). El departament d''urbanisme ha d''evitar entorns que generin inseguretat per a les dones, amb visibilitat, il·luminació i recorreguts alternatius (art. 55.2).","refs":[{"ref":"Art. 55.1.a Llei 17/2015","law":"Llei 17/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-9676","quote":"a) Tener en cuenta la distinta percepción de la seguridad de mujeres y hombres e incluir la perspectiva de género en las encuestas de victimización, en el análisis de la realidad de la seguridad en Cataluña, en las diagnosis de seguridad de los espacios públicos"},{"ref":"Art. 55.1.c Llei 17/2015","law":"Llei 17/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-9676","quote":"c) Promover el trabajo con los hombres a fin de que no ejerzan ningún tipo de violencia machista."}]}]},{"n":"7","title":"Síndic de Greuges i règim sancionador de la Llei 17/2015 (arts. 57-63)","blocks":[{"text":"El Síndic de Greuges és l''òrgan encarregat de defensar els drets i les llibertats en matèria de no-discriminació per raó de gènere: investiga, fa recomanacions, assessora la ciutadania i vetlla pel compliment de la llei (art. 57.1). L''Observatori de la Igualtat de Gènere, adscrit a l''Institut Català de les Dones, s''ocupa de les dades i la recerca (art. 58).","refs":[{"ref":"Art. 57.1 Llei 17/2015","law":"Llei 17/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-9676","quote":"El Síndic de Greuges, de acuerdo con las atribuciones que le asignan el Estatuto de autonomía y la Ley 24/2009, de 23 de diciembre, es el órgano encargado de la defensa de los derechos y libertades en materia de no discriminación por razón de género"}]},{"text":"Les infraccions són lleus, greus i molt greus (art. 59.1). Són molt greus, entre d''altres, qualsevol comportament que atempti intencionadament contra la dignitat d''una persona per raó del seu sexe, qualsevol tracte desfavorable a les dones relacionat amb l''embaràs o la maternitat i les represàlies per haver denunciat una discriminació (art. 59.4). Les infraccions lleus prescriuen als sis mesos, les greus als dotze i les molt greus als divuit mesos (art. 63.1). Sobre la vigència: el BOE recull que el Tribunal Constitucional va suspendre els arts. 59 a 64 el 2016 en admetre un recurs d''inconstitucionalitat, però el va desestimar per la Sentència 159/2016; per tant, són aplicables.","refs":[{"ref":"Art. 59.4.b Llei 17/2015","law":"Llei 17/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-9676","quote":"b) Ejercer cualquier trato desfavorable a las mujeres relacionado con su embarazo o maternidad."},{"ref":"Art. 63.1 Llei 17/2015","law":"Llei 17/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-9676","quote":"1. Las infracciones tipificadas como leves por la presente ley prescriben a los seis meses; las tipificadas como graves, al cabo de doce meses, y las tipificadas como muy graves, al cabo de dieciocho meses."},{"ref":"Nota del BOE als arts. 59-64","law":"Llei 17/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-9676","quote":"Se declara la desestimación en el recurso de inconstitucionalidad 2257/2016, por Sentencia del TC 159/2016, de 22 de septiembre."}]}]},{"n":"8","title":"Llei 19/2020: objecte, motius de discriminació i deure de comunicar","blocks":[{"text":"La Llei 19/2020, del 30 de desembre, d''igualtat de tracte i no-discriminació, vol garantir aquest dret i erradicar qualsevol actuació que atempti contra la dignitat de les persones (art. 1.1). Atenció: el text consolidat del BOE disponible a les fonts està marcat com a «Desactualizado» (última actualització recollida, 2022), de manera que convé contrastar-lo amb el Portal Jurídic de Catalunya.","refs":[{"ref":"Art. 1.1 Llei 19/2020","law":"Llei 19/2020","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2021-1663","quote":"El objeto de la presente ley es garantizar el derecho a la igualdad de trato y a la no discriminación y erradicar cualquier actuación o comportamiento que puedan atentar contra la dignidad de las personas"}]},{"text":"La llei vol evitar les discriminacions per origen territorial o nacional i xenofòbia; sexe o gènere, orientació o identitat sexual i LGBTI-fòbia; edat; raça, origen ètnic o color de pell, inclòs l''antisemitisme i l''antigitanisme; llengua; ideologia; conviccions religioses; condició social o econòmica, situació administrativa, professió o privació de llibertat, inclosa l''aporofòbia o l''odi a les persones sense llar; discapacitat; salut; aspecte físic o indumentària; i qualsevol altra condició humana reconeguda internacionalment (art. 1.3). S''aplica a tothom a Catalunya, també a les xarxes socials (art. 2).","refs":[{"ref":"Art. 1.3.h Llei 19/2020","law":"Llei 19/2020","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2021-1663","quote":"h) Condición social o económica, situación administrativa, profesión o condición de privación de libertad, y cualquier manifestación de aporofobia o de odio a las personas sin hogar."}]},{"text":"Els professionals de les administracions i dels serveis públics que fan tasques de prevenció, detecció o atenció (entre d''altres, els dels cossos de seguretat), si tenen coneixement d''una situació de risc o una sospita fonamentada de discriminació o violència, tenen el deure de comunicar-ho als cossos i forces de seguretat i a l''òrgan competent (art. 3.2).","refs":[{"ref":"Art. 3.2 Llei 19/2020","law":"Llei 19/2020","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2021-1663","quote":"si tienen conocimiento de una situación de riesgo o una sospecha fundada de discriminación o violencia, tienen el deber de comunicarlo a los cuerpos y fuerzas de seguridad y al órgano competente."}]}]},{"n":"9","title":"Definicions de la Llei 19/2020 (art. 4)","blocks":[{"text":"Algunes definicions clau: l''aporofòbia és el rebuig, el menyspreu o l''odi cap a les persones pobres, sense sostre o sense llar (art. 4.d); l''assetjament discriminatori és el comportament basat en algun dels motius de l''article 1 que atempta contra la dignitat i crea un entorn hostil (art. 4.e); i la discriminació directa es produeix quan una persona és tractada de manera menys favorable que una altra en situació anàloga per algun d''aquests motius (art. 4.l).","refs":[{"ref":"Art. 4.d Llei 19/2020","law":"Llei 19/2020","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2021-1663","quote":"d) Aporofobia: El rechazo, el desprecio o el odio hacia las personas pobres, sin techo o sin hogar."},{"ref":"Art. 4.l Llei 19/2020","law":"Llei 19/2020","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2021-1663","quote":"l) Discriminación directa: La discriminación que se produce cuando una persona es tratada de una forma menos favorable que otra en situación análoga por alguno de los motivos a los que se refiere el artículo 1."}]},{"text":"Hi ha discriminació per associació quan una persona o el grup a què se l''associa és discriminat per la seva relació amb una persona o un grup protegit (per exemple, la parella d''una persona d''origen ètnic minoritari) (art. 4.o), i discriminació per error quan se li atribueix erròniament una característica (art. 4.p). La discriminació múltiple és la forma agreujada que resulta de la concurrència de diversos motius (art. 4.n).","refs":[{"ref":"Art. 4.o Llei 19/2020","law":"Llei 19/2020","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2021-1663","quote":"o) Discriminación por asociación: La discriminación que se produce cuando una persona o el grupo al que se le asocia es objeto de discriminación, real o atribuida, como consecuencia de su relación con una persona o un grupo por alguno de los motivos a los que se refiere el artículo 1."},{"ref":"Art. 4.n Llei 19/2020","law":"Llei 19/2020","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2021-1663","quote":"n) Discriminación múltiple: La discriminación que se produce cuando una persona sufre una forma agravada y específica de discriminación como consecuencia de la concurrencia o la interacción de diversos motivos de discriminación."}]}]},{"n":"10","title":"Cossos de seguretat (art. 21) i defensa del dret (arts. 22-32)","blocks":[{"text":"Els Mossos d''Esquadra, la policia local i el personal de seguretat privada han de respectar la igualtat de tracte i evitar tot abús o discriminació (art. 21.1). Els funcionaris han de protegir les víctimes, garantint-los la investigació de les denúncies, la informació dels seus drets i l''accés a la justícia (art. 21.3). Queda prohibit l''ús de criteris racials basats en l''aspecte físic (color de pell, faccions, pertinença a un grup ètnic…) en detencions, interrogatoris, escorcolls, controls d''identitat i, en general, en la vigilància, així com el tracte discriminatori en les detencions, deportacions i expulsions (art. 21.4).","refs":[{"ref":"Art. 21.1 Llei 19/2020","law":"Llei 19/2020","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2021-1663","quote":"El Cuerpo de Mossos d''Esquadra, la policía local y también los trabajadores de empresas de seguridad privada deben respetar el derecho a la igualdad de trato en sus actuaciones"},{"ref":"Art. 21.4.a Llei 19/2020","law":"Llei 19/2020","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2021-1663","quote":"a) El uso de criterios raciales, basados en el aspecto físico del individuo, como el color de piel, las facciones, la pertenencia a un grupo racial o étnico o cualquier otra característica similar, en las detenciones, los interrogatorios, los registros, los controles de identidad"}]},{"text":"Les administracions han de detectar les situacions discriminatòries, protegir les víctimes i fer-les cessar (art. 22.1). Si qui al·lega discriminació aporta indicis racionals i fonamentats, s''inverteix la càrrega de la prova i és l''altra part qui ha de provar que no ha discriminat (art. 22.4). Qui discrimina ha de respondre del dany causat, inclòs el moral (art. 25). La formació en igualtat de tracte és obligatòria, amb atenció especial als cossos i forces de seguretat (art. 32.2).","refs":[{"ref":"Art. 22.4 Llei 19/2020","law":"Llei 19/2020","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2021-1663","quote":"se debe aplicar la inversión de la carga de la prueba sobre cuya base corresponde a la parte que ha infligido la discriminación probar que su comportamiento no ha sido discriminatorio."},{"ref":"Art. 32.2 Llei 19/2020","law":"Llei 19/2020","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2021-1663","quote":"con especial atención a la magistratura, el personal de los centros penitenciarios, los cuerpos y fuerzas de seguridad"}]}]},{"n":"11","title":"Organisme de Protecció i règim sancionador de la Llei 19/2020 (arts. 33-48)","blocks":[{"text":"L''Organisme de Protecció i Promoció de la Igualtat de Tracte i la No-Discriminació vetlla pel compliment de la llei tant en el sector públic com en el privat (art. 33.1). S''adscriu al departament competent per raó de la matèria i ha de retre comptes davant el Parlament; el Govern en designa el titular (art. 33.2 i 33.3).","refs":[{"ref":"Art. 33.2 Llei 19/2020","law":"Llei 19/2020","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2021-1663","quote":"2. El Organismo de Protección y Promoción de la Igualdad de Trato y la No Discriminación se adscribe al departamento competente por razón de la materia y debe rendir cuentas ante el Parlamento."}]},{"text":"És infracció tota conducta discriminatòria basada en algun motiu de l''article 1, i les infraccions són lleus, greus o molt greus (art. 43). Són lleus, per exemple, els insults o gestos vexatoris a l''espai públic; greus, la discriminació directa, indirecta, per associació o per error; i molt greus, la discriminació múltiple, l''assetjament discriminatori, les represàlies o abstenir-se d''intervenir qui té el deure de fer-ho. Les multes són de 300 a 10.000 euros (lleus), de 10.001 a 40.000 (greus) i de 40.001 a 500.000 (molt greus) (art. 45.1). Les infraccions lleus prescriuen als dotze mesos, les greus als tres anys i les molt greus als quatre anys (art. 48.1).","refs":[{"ref":"Art. 43.5.a i 43.6.j Llei 19/2020","law":"Llei 19/2020","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2021-1663","quote":"a) Los actos u omisiones que constituyan una discriminación, directa o indirecta, por asociación o por error […] j) Abstenerse de intervenir, las personas que tengan atribuido el deber de intervención, ante cualquier forma de discriminación."},{"ref":"Art. 45.1 Llei 19/2020","law":"Llei 19/2020","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2021-1663","quote":"a) Infracciones leves, entre 300 y 10.000 euros. b) Infracciones graves, entre 10.001 y 40.000 euros. c) Infracciones muy graves, entre 40.001 y 500.000 euros."},{"ref":"Art. 48.1 Llei 19/2020","law":"Llei 19/2020","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2021-1663","quote":"1. Las infracciones leves prescriben al cabo de doce meses; las graves, al cabo de tres años, y las muy graves, al cabo de cuatro años."}]}]},{"n":"R","title":"Recorda per a l''examen","blocks":[{"text":"Representació paritària: cap sexe per sobre del 60% ni per sota del 40%.","refs":[{"ref":"Art. 2.i Llei 17/2015","law":"Llei 17/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-9676","quote":"ningún sexo supera el 60% del conjunto de personas a que se refiere ni es inferior al 40%"}]},{"text":"Discriminació múltiple (Llei 17/2015): la dona que pateix formes agreujades per pertànyer també a altres grups discriminats.","refs":[{"ref":"Art. 2.m Llei 17/2015","law":"Llei 17/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-9676","quote":"padece formas agravadas y específicas de discriminación."}]},{"text":"L''Institut Català de les Dones és l''organisme principal de la Generalitat per aplicar la Llei 17/2015.","refs":[{"ref":"Art. 7.1.a Llei 17/2015","law":"Llei 17/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-9676","quote":"El Instituto Catalán de las Mujeres"}]},{"text":"El Síndic de Greuges defensa la no-discriminació per raó de gènere; les infraccions molt greus de la Llei 17/2015 prescriuen als divuit mesos.","refs":[{"ref":"Art. 63.1 Llei 17/2015","law":"Llei 17/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-9676","quote":"y las tipificadas como muy graves, al cabo de dieciocho meses."}]},{"text":"Aporofòbia: rebuig o odi a les persones pobres o sense llar; s''inclou en el motiu de condició social o econòmica.","refs":[{"ref":"Art. 4.d Llei 19/2020","law":"Llei 19/2020","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2021-1663","quote":"Aporofobia: El rechazo, el desprecio o el odio hacia las personas pobres, sin techo o sin hogar."}]},{"text":"Prohibits els criteris racials basats en l''aspecte físic en els controls d''identitat.","refs":[{"ref":"Art. 21.4.a Llei 19/2020","law":"Llei 19/2020","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2021-1663","quote":"en las detenciones, los interrogatorios, los registros, los controles de identidad"}]},{"text":"Llei 19/2020: multes greus de 10.001 a 40.000 euros; infraccions greus prescriuen als tres anys.","refs":[{"ref":"Art. 45.1.b Llei 19/2020","law":"Llei 19/2020","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2021-1663","quote":"b) Infracciones graves, entre 10.001 y 40.000 euros."}]},{"text":"L''Organisme de Protecció s''adscriu al departament competent i ret comptes davant el Parlament.","refs":[{"ref":"Art. 33.2 Llei 19/2020","law":"Llei 19/2020","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2021-1663","quote":"debe rendir cuentas ante el Parlamento."}]}]}]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-9676'), 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-9676', null, null, null, 'Otras normas citadas: Llei 19/2020 (https://www.boe.es/buscar/act.php?id=BOE-A-2021-1663)'
  from public.topics t where t.slug = 'plcat-t23-igualtat-no-discriminacio'
on conflict (topic_id, locale) do update
   set outline = excluded.outline, key_ideas = excluded.key_ideas, glossary = excluded.glossary,
       amendments = excluded.amendments, lessons = excluded.lessons, source_id = excluded.source_id, source_url = excluded.source_url,
       page_from = excluded.page_from, page_to = excluded.page_to, key_ideas_page = excluded.key_ideas_page
 where (n.outline, n.key_ideas, n.glossary, n.amendments, n.lessons)
       is distinct from (excluded.outline, excluded.key_ideas, excluded.glossary, excluded.amendments, excluded.lessons);

do $$
declare
  v_owner uuid;
  v_slug text;
  v_n int := 0;
begin
  select id into v_owner from public.profiles
   where role = 'owner' and status = 'active' order by created_at limit 1;
  if v_owner is null then
    raise notice 'No hay persona titular: no se publica nada.';
    return;
  end if;
  perform set_config('request.jwt.claims',
    json_build_object('sub', v_owner, 'role', 'authenticated')::text, true);

  for v_slug in select t.slug from public.topics t
                  join public.topic_notes n on n.topic_id = t.id
                 where t.slug like 'plcat-%' and n.status <> 'published'
                 order by t.slug loop
    perform public.review_topic_notes(v_slug, 'approved');
    v_n := v_n + public.review_topic_notes(v_slug, 'published');
  end loop;

  perform public.log_admin_action('content.publish_notes', 'exam_bodies',
    'policia-local',
    jsonb_build_object('notes', v_n,
                       'motivo', 'Petición expresa de joel en el hilo del proyecto (10/11/2026: apuntes completos por tema)'));
  perform set_config('request.jwt.claims', '', true);
  raise notice 'Policía local de Cataluña: % fichas con apuntes publicadas', v_n;
end $$;

commit;
